typedef struct {
    int32_t  *code;
    int32_t  *linhas;      /* linha do fonte de cada palavra do code (ou NULL) */
    int32_t  *colunas;     /* coluna do fonte de cada palavra (ou NULL) */
    int       ncode;
    Value    *consts;
    int       nconsts;
    int       nlocals;
    int       nparams;
    int       ndefaults;   /* quantos parâmetros finais têm valor padrão */
    char    **param_nomes; /* nome de cada parâmetro — só pra argumento nomeado */
    /* Tipo declarado de cada parâmetro (`funct f(str nome)`). NULL no vetor =
     * nenhum parâmetro tem tipo; NULL numa posição = aquele não tem. A VM só
     * CHECA — argumento de tipo errado é erro, nunca conversão. */
    char    **param_tipos;
    char     *nome;        /* nome da action — usado na mensagem de erro */
    char     *arquivo;     /* arquivo-fonte deste proto — pro traceback (ou NULL) */
    int       eh_gerador;  /* chamar cria gerador em vez de empilhar frame */
    int       eh_async;    /* `async action` — chamar cria fibra+future */
    int       eh_static;   /* `@static` — chamável na Entity sem instância */
    /* Variáveis de fora capturadas (closure). NULL na quase totalidade dos
     * protos: só action DECLARADA DENTRO de outra tem. */
    PSUpval  *upvals;
    int       nupvals;
    char    **upval_nomes;  /* nome de cada upvalue — só pra mensagem de erro */
    /* Variáveis locais com a faixa de bytecode em que valem. Só o debugger lê:
     * é o que permite dizer QUAL nome mora no slot com o frame parado num `ip`,
     * já que os slots são reaproveitados entre blocos. */
    PSVarDbg *vars;
    int       nvars;
} Proto;

typedef struct {
    int proto;
    int ip;
    int locals_base;
    int stack_base;
    int nargs;          /* quantos argumentos a chamada REALMENTE passou */
    /* Chamada de Entity: o valor da expressão é a INSTÂNCIA, não o que o
     * `__init__` retornar (ele devolve Null). Sem esta marca, o RETURN
     * sobrescrevia o objeto recém-criado com Null. */
    int devolve_self;
    /* Closure em execução, se a action captura algo. É por aqui que o
     * LOAD_UPVAL acha as células. NULL numa action comum. */
    PSClosure *cl;
} Frame;

/* ── estado do depurador ──────────────────────────────────────────────────
 * Existe só com `pool --debug`. Fora disso o campo fica zerado e o laço da VM
 * paga um `if` previsível por instrução — nada mais.
 *
 * `ult_linha`/`ult_proto` são o que impede o passo de parar várias vezes na
 * MESMA linha: uma linha vira várias instruções, e sem essa memória o "próximo
 * passo" andaria de opcode em opcode em vez de de linha em linha, que é o que
 * quem depura espera ver. */
#define DBG_SOLTO      0   /* rodando até bater breakpoint */
#define DBG_PASSO_DENTRO 1 /* para na próxima linha, entrando em chamada */
#define DBG_PASSO_SOBRE  2 /* para na próxima linha do mesmo frame ou acima */
#define DBG_PASSO_FORA   3 /* para quando voltar pro frame de cima */
#define DBG_PAUSAR       4 /* para na próxima LINHA com fonte, seja em que frame
                            * for — o mesmo grão dos passos (`ult_linha`) */

typedef struct {
    int      ativo;
    int      fd_in, fd_out;
    int      configurado;     /* o editor já mandou `configurationDone` */
    int      parar_entrada;   /* `stopOnEntry` do launch */
    int      desconectou;
    int      modo;            /* DBG_* */
    int      passo_prof;      /* profundidade de frame de referência do passo */
    int      ult_linha;
    int      ult_proto;
    int      seq;             /* numeração das mensagens que o motor envia */
    struct { char *arquivo; int32_t linha; } *bps;
    int      nbps;
    /* Rastro da execução, pro gráfico: cada aresta é um salto de (proto,linha)
     * pra outro (proto,linha). Guardado como lista circular pra não crescer sem
     * limite num laço de milhões de voltas. */
    struct { int32_t de_proto, de_linha, para_proto, para_linha; int64_t vezes; } *arestas;
    int      narestas, cap_arestas;
    int32_t  quebrou_proto, quebrou_linha;   /* onde o erro estourou (-1 = não estourou) */
} Debug;

/* Tamanhos modestos por padrão: antes eram 1<<20 slots cada, o que reservava
 * 33,5 MB por execução mesmo pra um `post(1)` — medido com RSS. Estes valores
 * cobrem recursão profunda de sobra (65k frames) a 1/16 do custo.
 * Estouro é ERRO EXPLÍCITO, nunca escrita fora do array. */
#define MAX_FRAMES  65536
#define STACK_SIZE  (1 << 16)
#define LOCALS_SIZE (1 << 18)
#define GC_INICIAL  (1024 * 1024)

/* Cópia do descritor de classe — o PSPrograma é liberado antes da execução,
 * então a VM precisa ser dona destes dados (mesma lição do param_nomes). */
typedef struct {
    char    *nome;
    char   **met_nomes;
    int32_t *met_protos;
    int32_t  nmetodos;
    int32_t  npais;
    char   **priv_nomes;   /* membros `private` (copiado do PSClassDef) */
    int32_t  npriv;
    int32_t  classe_privada;   /* `private class` — não exportada no import */
} PSClassDefC;

/* Troca de contexto de fibra em ASSEMBLY (x86-64): salva só os registradores
 * callee-saved + rsp, ZERO syscall — ao contrário do swapcontext do glibc, que
 * faz sigprocmask a cada troca. Outras arquiteturas usam ucontext. */
#if defined(__x86_64__)
typedef void *PS_CTX;
extern void ps_fctx_swap(PS_CTX *from, PS_CTX *to);
__asm__(
".text\n"
".globl ps_fctx_swap\n"
".type ps_fctx_swap,@function\n"
"ps_fctx_swap:\n"
"    pushq %rbp\n    pushq %rbx\n    pushq %r12\n"
"    pushq %r13\n    pushq %r14\n    pushq %r15\n"
"    movq %rsp, (%rdi)\n"
"    movq (%rsi), %rsp\n"
"    popq %r15\n    popq %r14\n    popq %r13\n"
"    popq %r12\n    popq %rbx\n    popq %rbp\n"
"    ret\n"
".size ps_fctx_swap, .-ps_fctx_swap\n"
);
static inline void ps_ctx_swap(PS_CTX *from, PS_CTX *to) { ps_fctx_swap(from, to); }
static inline void ps_ctx_make(PS_CTX *ctx, void *stack, size_t size, void (*entry)(void)) {
    uintptr_t top = ((uintptr_t)stack + size) & ~(uintptr_t)0xFULL;
    void **sp = (void **)(top - 64);
    for (int i = 0; i < 6; i++) sp[i] = 0;   /* rbp,rbx,r12-r15 (garbage inicial) */
    sp[6] = (void *)entry;                    /* alvo do `ret`: rsp fica em top-8 */
    *ctx = (void *)sp;
}
#else
typedef ucontext_t PS_CTX;
static inline void ps_ctx_swap(PS_CTX *from, PS_CTX *to) { swapcontext(from, to); }
static inline void ps_ctx_make(PS_CTX *ctx, void *stack, size_t size, void (*entry)(void)) {
    getcontext(ctx); ctx->uc_stack.ss_sp = stack; ctx->uc_stack.ss_size = size;
    ctx->uc_link = NULL; makecontext(ctx, entry, 0);
}
#endif

struct VM_ {
    Proto  *protos;
    int     nprotos;
    PSClassDefC *classes;
    int          nclasses;
    /* descritores de model — copiados do programa, mesma lição do classes */
    PSModelCampo **model_campos;
    int32_t       *model_ncampos;
    char         **model_nomes;
    int            nmodels;
    /* descritores de enum — nome do enum, nomes dos membros e flag auto/expl */
    char         **enum_nomes;
    char        ***enum_membro_nomes;
    int8_t       **enum_auto;
    int32_t       *enum_nmembros;
    int            nenums;
    Value  *globals;
    int     nglobals;
    Value  *stack;
    Value  *locals;
    Frame  *frames;

    /* estado exposto pro GC enxergar as raízes vivas */
    int     sp;
    int     locals_top;
    /* Primeiro frame LIVRE. Publicado junto com sp/locals_top antes de
     * chamar builtin, pra um `vm_executa_base` aninhado saber onde começar
     * sem sobrescrever o frame de quem chamou. */
    int     frame_topo;
    /* Publicado no ponto seguro do GC: quantos frames estão vivos e qual o
     * closure do frame corrente. Só o coletor lê. */
    int        gc_fp;
    PSClosure *gc_cl;

    /* Teto de cada pool de execução. Normalmente = STACK_SIZE/LOCALS_SIZE/
     * MAX_FRAMES (a execução principal usa os arrays cheios). Uma FIBRA de
     * handler roda em arrays PRÓPRIOS menores e reaponta esses tetos pro
     * tamanho dela — as checagens de estouro passam a respeitar o array da
     * fibra em vez do global (senão a fibra escreveria fora do próprio array).*/
    int     stack_teto;
    int     locals_teto;
    /* Conexões WebSocket de CLIENTE abertas. O `sleep()` percorre esta lista
     * pra entregar o `on_message` enquanto o script espera — sem isso um
     * processo que só escuta (o caso clássico de dois terminais) nunca recebe
     * nada: a mensagem chegava no socket e ficava lá até o próximo `send` ou
     * `close`. Ponteiro fraco: o finalizador tira a entrada. */
    struct PSWsConn_ *ws_vivos[64];
    int     n_ws_vivos;
    int     frames_teto;

    /* ── fibras (green-threads do jinker) ────────────────────────────────
     * `fib_atual` != NULL quando um handler está rodando numa fibra: nesse
     * caso os campos stack/locals/frames/sp/... acima descrevem o contexto da
     * FIBRA, e o contexto da execução principal (o poll loop dentro de
     * app.run()) fica salvo nos `m_*`. `sched_ctx` é a pilha-C do escalonador
     * (o poll loop), pra onde a fibra volta ao ceder ou terminar. */
    struct Fiber *fib_atual;
    PS_CTX        sched_ctx;
    Value  *m_stack;  Value *m_locals;  Frame *m_frames;
    int     m_sp, m_locals_top, m_frame_topo;
    int     m_stack_teto, m_locals_teto, m_frames_teto;
    Value   m_jk_req;

    /* Módulos `.ps` já carregados, pra `import` duas vezes não reexecutar. */
    struct { char *nome; Value valor; } *mods_ps;
    int      nmods_ps;
    int      cap_mods_ps;
    /* Diretório do ENTRY point — raiz do projeto, base do import absoluto
     * (`from pkg.mod import x`). Constante durante toda a execução. */
    char     dir_script[512];
    /* Diretório do arquivo cujo corpo está rodando AGORA — base do import
     * RELATIVO (`from .mod import x`). Muda ao entrar/sair de cada módulo. */
    char     dir_modulo[512];
    /* Argumentos do usuário: `pool arquivo.ps a b` -> {"a","b"}. */
    char   **argv_user;
    int      argc_user;
    /* Caminho do script, ou "__main__" quando não veio de arquivo. É o que
     * `__name__` responde. */
    char     nome_script[512];

    /* Transporte da retomada de gerador. Não é estado durável: vale só entre
     * `ger_retoma` e o YIELD/RETURN que devolve o controle. */
    int      ger_ativo;
    int      ger_cedeu;    /* 1 = parou num yield; 0 = a action terminou */
    int32_t  ger_ip;
    int32_t  ger_npilha;
    Value   *ger_locais;
    Value   *ger_pilha;
    struct Handler_ *ger_handlers;   /* onde o YIELD despeja os `try` abertos */
    int      ger_nh;
    int      ger_cap_h;

    /* coletor */
    Obj    *objetos;
    size_t  alocado;
    size_t  proximo_gc;
    long    ciclos_gc;
    long    objetos_liberados;

    /* Pilha cinza da marcação. Sem ela, marcar uma lista que contém listas
     * exigiria recursão em C — e uma estrutura profunda o bastante derrubaria
     * o processo por stack overflow dentro do coletor, que é o pior lugar
     * possível pra isso acontecer. */
    Obj   **cinzas;
    int     ncinzas;
    int     cap_cinzas;

    /* ── jinker ─────────────────────────────────────────────────────────
     * Singletons e a requisição corrente são RAÍZES do GC: vivem aqui (e não
     * em estático C) porque o coletor não varre a pilha do C. `nomes_globais`
     * é a tabela de nomes do programa — o Jinker() usa pra achar os slots
     * `request`/`channel` e pré-ligá-los no escopo do handler. */
    Value    jk_cors;      /* singleton de cors — V_UNSET até o 1º uso */
    Value    jk_proxy;     /* singleton do `request` */
    Value    jk_req;       /* requisição corrente (V_NULL fora de handler) */
    Value    jk_app;       /* o app servindo agora (pra emit/socket) */
    char   **nomes_globais;
    int      n_nomes_globais;   /* só as do script principal — nglobals cresce
                                 * com import de .ps, esta tabela não */

    Debug   dbg;             /* só com `pool --debug`; zerado no resto */

    char    erro[256];
    char    erro_tipo[64];   /* nome do tipo, pra casar `catch (Tipo e)` */
    /* Traceback do erro não-capturado: do <module> (mais externo) ao frame que
     * falhou (mais interno). */
    struct { int proto; int linha; int col; } tb[64];
    int     ntb;
    /* Traceback preservado de um import que estourou DENTRO do módulo: sem isto
     * o erro_runtime externo reconstruiria o tb só com o frame do `import` e a
     * linha de dentro do módulo (onde o erro está de verdade) se perderia. */
    struct { int proto; int linha; int col; } tb_mod[64];
    int     ntb_mod;
    int     import_falhou;   /* 1 = o erro atual veio de dentro de um módulo importado */
    int     importando;      /* >0 = rodando o corpo de um módulo importado (o guard pula) */
    /* Módulo que NÃO COMPILOU. O `tb` acima guarda índice de proto, e um
     * módulo que nem compilou não tem proto nenhum — então o erro saía como
     * "SyntaxError: random: expressao invalida / em d.ps, linha 1", apontando
     * a linha do `import` de quem importou. O defeito está DENTRO da lib e o
     * usuário não tinha como saber onde. Estes três campos carregam o arquivo
     * e a posição reais até o quadro final do traceback. */
    char    mod_erro_arquivo[1024];   /* mesmo tamanho do `abspath` que o alimenta */
    int     mod_erro_linha, mod_erro_col;
};

/* Handler de `try`: onde saltar e qual estado restaurar. Guardar fp/sp/
 * locals_top é o que permite capturar um erro levantado VÁRIOS frames
 * abaixo — o desenrolamento volta a máquina ao ponto do `try`. */
typedef struct Handler_ {
    int ip;
    int fp;
    int sp;
    int locals_top;
    /* O protótipo e a base de locais CORRENTES no momento do `try`.
     * `frames[fp]` guarda o estado do CHAMADOR, não o do frame ativo — sem
     * gravar estes dois, o catch retomava no protótipo errado quando o erro
     * vinha de uma função chamada dentro do try. */
    int proto;
    int lbase;
} Handler;
#define MAX_HANDLERS 256
typedef struct VM_ VM;

/* ── alocação e coleta ──────────────────────────────────────────────────── */

/* SEMENTE DO HASH, sorteada uma vez por processo.
 *
 * Sem ela, o FNV-1a com as constantes públicas é totalmente pré-computável:
 * quem quiser monta offline um conjunto de N chaves que colidem em 32 bits, e
 * como o dict resolve colisão por sondagem linear, inserir as N custa O(N²).
 *
 * Isso importa porque este runtime SERVE HTTP: header, query, formulário e
 * JSON do cliente viram dict. É o ataque de 2011 (n.runs SA-2011.004), que
 * rendeu CVE em vários runtimes com dict de hash — e a resposta de todos
 * eles foi randomizar a semente por processo. Custa uma leitura de
 * /dev/urandom no boot.
 *
 * `PS_HASH_SEED=<n>` fixa a semente. Existe pro caso em que a saída precisa
 * ser reproduzível entre execuções (depurar ordem de dict, comparar despejo);
 * o padrão é sorteada. */
static uint32_t ps_hash_seed = 2166136261u;

static void ps_hash_semeia(void)
{
    const char *fixa = getenv("PS_HASH_SEED");
    if (fixa && fixa[0]) { ps_hash_seed = (uint32_t)strtoul(fixa, NULL, 10); return; }
    unsigned char b[4];
    if (ps_random_bytes(b, sizeof b) == 0)
        ps_hash_seed = ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16)
                     | ((uint32_t)b[2] << 8)  |  (uint32_t)b[3];
    /* sem entropia, fica a constante do FNV: pior que sorteada, melhor que
     * abortar o interpretador inteiro por causa disso */
}

static uint32_t hash_str(const char *chars, int len)
{
    /* FNV-1a com a semente do processo no estado inicial (é onde ela tem
     * efeito: o FNV depende do sufixo, então semear no fim não adiantaria) */
    uint32_t h = ps_hash_seed;
    for (int i = 0; i < len; i++) {
        h ^= (unsigned char)chars[i];
        h *= 16777619u;
    }
    return h;
}

static PSString *nova_string(VM *vm, const char *chars, int len)
{
    PSString *s = malloc(sizeof(PSString) + (size_t)len + 1);
    if (!s) return NULL;
    s->obj.type   = OBJ_STRING;
    s->obj.marked = 0;
    s->obj.next   = vm->objetos;
    vm->objetos   = (Obj *)s;
    s->len  = len;
    memcpy(s->chars, chars, (size_t)len);
    s->chars[len] = '\0';
    s->hash = hash_str(chars, len);
    vm->alocado += sizeof(PSString) + (size_t)len + 1;
    return s;
}

/* ── bignum (GMP) ───────────────────────────────────────────────────────── */
static PSBigInt *novo_bigint(VM *vm)
{
    PSBigInt *b = calloc(1, sizeof(PSBigInt));
    if (!b) return NULL;
    b->obj.type = OBJ_BIGINT; b->obj.marked = 0;
    b->obj.next = vm->objetos; vm->objetos = (Obj *)b;
    mpz_init(b->v);
    vm->alocado += sizeof(PSBigInt);
    return b;
}

/* Resultado de uma conta: rebaixa pra V_INT se couber em int64,
 * senão embrulha num bignum. */
static Value mk_from_mpz(VM *vm, mpz_srcptr z)
{
    if (mpz_fits_slong_p(z)) return MK_INT((int64_t)mpz_get_si(z));
    PSBigInt *b = novo_bigint(vm);
    if (!b) return MK_NULL();
    mpz_set(b->v, z);
    return MK_OBJ(b);
}

/* Carrega um Value inteiro (V_INT ou bignum) num mpz já inicializado. */
static void mpz_de_val(mpz_t z, Value v)
{
    if (EH_BIGINT(v)) mpz_set(z, COMO_BIGINT(v)->v);
    else              mpz_set_si(z, (long)v.as.i);   /* V_INT (bool já virou int) */
}

/* v é inteiro (int64 ou bignum)? / inteiro como double (pra misturar com float) */
#define EH_INTEIRO(v) ((v).t == V_INT || EH_BIGINT(v))
static double int_como_double(Value v)
{
    return EH_BIGINT(v) ? mpz_get_d(COMO_BIGINT(v)->v) : (double)v.as.i;
}

/* Dígitos decimais de um bignum, em buffer malloc (o chamador dá free). */
static char *bigint_str(mpz_srcptr z)
{
    char *s = malloc(mpz_sizeinbase(z, 10) + 2);   /* + sinal + '\0' */
    if (s) mpz_get_str(s, 10, z);
    return s;
}

/* a OP b entre inteiros (int64 e/ou bignum). Caminho rápido em int64; se
 * estourar, PROMOVE pra bignum. op = '+' '-' '*'. Pode alocar — o chamador
 * publica vm->sp antes. */
static Value int_arit(VM *vm, Value a, Value b, char op)
{
    if (a.t == V_INT && b.t == V_INT) {
        int64_t r;
        int of = (op == '+') ? __builtin_add_overflow(a.as.i, b.as.i, &r)
               : (op == '-') ? __builtin_sub_overflow(a.as.i, b.as.i, &r)
               :               __builtin_mul_overflow(a.as.i, b.as.i, &r);
        if (!of) return MK_INT(r);
    }
    mpz_t za, zb, zr;
    mpz_init(za); mpz_init(zb); mpz_init(zr);
    mpz_de_val(za, a); mpz_de_val(zb, b);
    if (op == '+')      mpz_add(zr, za, zb);
    else if (op == '-') mpz_sub(zr, za, zb);
    else                mpz_mul(zr, za, zb);
    Value out = mk_from_mpz(vm, zr);
    mpz_clear(za); mpz_clear(zb); mpz_clear(zr);
    return out;
}

static PSList *nova_seq(VM *vm, int cap, ObjType tipo)
{
    PSList *l = calloc(1, sizeof(PSList));
    if (!l) return NULL;
    l->obj.type = tipo;
    l->obj.marked = 0;
    l->obj.next = vm->objetos;
    vm->objetos = (Obj *)l;
    l->len = 0;
    l->cap = cap > 0 ? cap : 0;
    l->itens = NULL;
    if (l->cap > 0) {
        l->itens = malloc(sizeof(Value) * (size_t)l->cap);
        if (!l->itens) { l->cap = 0; return NULL; }
    }
    vm->alocado += sizeof(PSList) + sizeof(Value) * (size_t)l->cap;
    return l;
}

static PSDict *novo_dict(VM *vm, int cap)
{
    PSDict *d = calloc(1, sizeof(PSDict));
    if (!d) return NULL;
    d->obj.type = OBJ_DICT;
    d->obj.marked = 0;
    d->obj.next = vm->objetos;
    vm->objetos = (Obj *)d;
    d->count = 0;
    d->usados = 0;
    d->cap = 0;
    d->icap = 0;
    d->entradas = NULL;
    d->indices = NULL;
    if (cap > 0) {
        int c = 8;
        while (c < cap) c *= 2;
        int ic = 8;
        while (ic < c * 2) ic *= 2;
        d->entradas = malloc(sizeof(Entrada) * (size_t)c);
        if (!d->entradas) return NULL;
        d->indices = malloc(sizeof(int32_t) * (size_t)ic);
        if (!d->indices) return NULL;
        for (int i = 0; i < ic; i++) d->indices[i] = DICT_VAZIO;
        d->cap = c;
        d->icap = ic;
    }
    vm->alocado += sizeof(PSDict) + sizeof(Entrada) * (size_t)d->cap
                 + sizeof(int32_t) * (size_t)d->icap;
    return d;
}

/* ── hash e igualdade de chaves ─────────────────────────────────────────── */
static int val_iguais(const Value *a, const Value *b);
static int model_valida(const PSModel *m, const Value *v);
static int utf8_conta(const char *s, int len);
static int utf8_le(const char *s, int len, int i, uint32_t *cp);
static int utf8_byte_de(const char *s, int len, int64_t cp);

static uint32_t hash_valor(const Value *v)
{
    switch (v->t) {
        case V_NULL:  return 0u;
        /* bool hasheia como o int equivalente (true->1, false->0), pra
         * `d[1]`/`d[true]` e `d[0]`/`d[false]` serem a MESMA chave — bool é
         * subtipo de int, igual ao interpretador. */
        case V_BOOL:  return (uint32_t)((uint64_t)(v->as.b ? 1 : 0) * 2654435761u);
        case V_INT:   return (uint32_t)((uint64_t)v->as.i * 2654435761u);
        case V_FLOAT: {
            /* inteiro guardado como float precisa colidir com o int
             * equivalente, senão d[1] e d[1.0] viram chaves diferentes */
            if (v->as.d == (double)(int64_t)v->as.d)
                return (uint32_t)((uint64_t)(int64_t)v->as.d * 2654435761u);
            uint64_t bits;
            memcpy(&bits, &v->as.d, sizeof(bits));
            return (uint32_t)(bits ^ (bits >> 32));
        }
        case V_TIPO:  return 0x7ed0u ^ (uint32_t)v->as.i;
        case V_OBJ:
            if (v->as.obj->type == OBJ_STRING || v->as.obj->type == OBJ_BYTES)
                return ((PSString *)v->as.obj)->hash;
            if (v->as.obj->type == OBJ_BIGINT) {
                char *s = bigint_str(((PSBigInt *)v->as.obj)->v);
                uint32_t h = s ? hash_str(s, (int)strlen(s)) : 0;
                free(s);
                return h;
            }
            return (uint32_t)(uintptr_t)v->as.obj;
        default:
            return (uint32_t)(uintptr_t)v->as.obj;
    }
}

/* Slot da tabela de índices onde `chave` está, ou onde ela caberia.
 * Devolve o índice na tabela; o chamador olha `indices[slot]` pra saber se
 * achou (>= 0), se é vazio, ou se é lápide.
 *
 * Lápide é reaproveitada só se a chave não existir adiante — por isso a
 * primeira vista fica guardada, mas a sondagem continua. */
static int acha_slot(const PSDict *d, const Value *chave)
{
    uint32_t i = hash_valor(chave) & (uint32_t)(d->icap - 1);
    int lapide = -1;
    for (;;) {
        int32_t pos = d->indices[i];
        if (pos == DICT_VAZIO) return lapide >= 0 ? lapide : (int)i;
        if (pos == DICT_LAPIDE) { if (lapide < 0) lapide = (int)i; }
        else if (val_iguais(&d->entradas[pos].chave, chave)) return (int)i;
        i = (i + 1) & (uint32_t)(d->icap - 1);
    }
}

/* Recompacta o denso (some com os removidos) e reconstrói os índices. */
static int dict_cresce(VM *vm, PSDict *d)
{
    int novo_cap  = d->cap < 8 ? 8 : d->cap * 2;
    int novo_icap = 8;
    while (novo_icap < novo_cap * 2) novo_icap *= 2;

    Entrada *novas = malloc(sizeof(Entrada) * (size_t)novo_cap);
    if (!novas) return -1;
    int32_t *novos_idx = malloc(sizeof(int32_t) * (size_t)novo_icap);
    if (!novos_idx) { free(novas); return -1; }
    for (int i = 0; i < novo_icap; i++) novos_idx[i] = DICT_VAZIO;

    int n = 0;
    for (int i = 0; i < d->usados; i++) {
        if (d->entradas[i].estado != 1) continue;
        novas[n++] = d->entradas[i];
    }

    vm->alocado -= sizeof(Entrada) * (size_t)d->cap + sizeof(int32_t) * (size_t)d->icap;
    vm->alocado += sizeof(Entrada) * (size_t)novo_cap + sizeof(int32_t) * (size_t)novo_icap;
    free(d->entradas);
    free(d->indices);
    d->entradas = novas;
    d->indices  = novos_idx;
    d->cap      = novo_cap;
    d->icap     = novo_icap;
    d->count    = n;
    d->usados   = n;

    for (int i = 0; i < n; i++)
        d->indices[acha_slot(d, &d->entradas[i].chave)] = i;
    return 0;
}

/* Chave de dict tem que ser IMUTÁVEL. A VM aceitava lista/dict como chave e
 * ainda deduplicava por valor — se a lista fosse mutada depois, a chave ficava
 * pendurada e o dict inconsistente. O interpretador recusa; agora os dois. */
static int chave_hashavel(VM *vm, const Value *k)
{
    if (k->t != V_OBJ) return 0;
    if (k->as.obj->type == OBJ_LIST || k->as.obj->type == OBJ_DICT) {
        snprintf(vm->erro, sizeof(vm->erro),
                 "unhashable type: '%s'",
                 k->as.obj->type == OBJ_LIST ? "list" : "dict");
        snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
        return -1;
    }
    return 0;
}

static int dict_set(VM *vm, PSDict *d, const Value *chave, const Value *valor)
{
    if (chave_hashavel(vm, chave) != 0) return -1;
    if (d->usados + 1 > d->cap * 3 / 4 || d->icap == 0) {
        if (dict_cresce(vm, d) != 0) return -1;
    }
    int slot = acha_slot(d, chave);
    int32_t pos = d->indices[slot];
    if (pos >= 0) {                      /* já existe: só troca o valor,
                                          * a posição na ordem não muda */
        d->entradas[pos].valor = *valor;
        return 0;
    }
    pos = d->usados++;
    d->entradas[pos].chave  = *chave;
    d->entradas[pos].valor  = *valor;
    d->entradas[pos].estado = 1;
    d->indices[slot] = pos;
    d->count++;
    return 0;
}

/* Remove a chave. Deixa lápide no índice e buraco no denso: a ordem de
 * inserção das outras não pode mudar, e a cadeia de sondagem de quem entrou
 * depois não pode ser cortada. */
static int dict_del(PSDict *d, const Value *chave, Value *out)
{
    if (d->icap == 0) return -1;
    int slot = acha_slot(d, chave);
    int32_t pos = d->indices[slot];
    if (pos < 0) return -1;
    if (out) *out = d->entradas[pos].valor;
    d->entradas[pos].estado = 0;
    d->indices[slot] = DICT_LAPIDE;
    d->count--;
    return 0;
}

static int dict_get(PSDict *d, const Value *chave, Value *out)
{
    if (d->icap == 0) return -1;
    int32_t pos = d->indices[acha_slot(d, chave)];
    if (pos < 0) return -1;
    *out = d->entradas[pos].valor;
    return 0;
}

/* ── marcação com pilha cinza (sem recursão em C) ───────────────────────── */
static void empilha_cinza(VM *vm, Obj *o)
{
    if (vm->ncinzas + 1 > vm->cap_cinzas) {
        int novo = vm->cap_cinzas < 64 ? 64 : vm->cap_cinzas * 2;
        Obj **p = realloc(vm->cinzas, sizeof(Obj *) * (size_t)novo);
        if (!p) return;   /* sem memória pra crescer: o objeto fica marcado,
                           * apenas não é varrido em busca de filhos nesta
                           * passada — conservador, nunca libera algo vivo */
        vm->cinzas = p;
        vm->cap_cinzas = novo;
    }
    vm->cinzas[vm->ncinzas++] = o;
}

static void marca_obj(VM *vm, Obj *o)
{
    if (!o || o->marked) return;
    /* `type` fora da tabela é ponteiro que não aponta pra objeto: raiz podre,
     * uso após liberar, ou campo lido de memória já devolvida. Sem isto, o
     * `GC_INFO[o->type]` logo adiante indexa fora do vetor e o efeito só
     * aparece bem longe daqui. */
    PS_ASSERT_MSG(o->type >= 0 && o->type < OBJ__COUNT,
                  "ObjType=%d fora da tabela (objeto %p)", (int)o->type, (void *)o);
    o->marked = 1;
    if (o->type != OBJ_STRING) empilha_cinza(vm, o);  /* string é folha */
}

static void marca_valor(VM *vm, const Value *v)
{
    if (v->t == V_OBJ) marca_obj(vm, v->as.obj);
}

/* ── GC: cada tipo DECLARA como marca seus filhos ─────────────────────────
 * Em vez de um `else if` gigante (fácil de esquecer um tipo novo => vaza como
 * use-after-free silencioso), cada ObjType tem uma entrada em GC_INFO:
 *   GC_LEAF  = sem filho Value/Obj
 *   GC_ONE   = um único Value, no offset dado
 *   GC_FN    = tracer próprio (arrays/múltiplos campos)
 * GC_UNSET (=0) é "não declarado": o check de boot (gc_valida_tabela) ABORTA
 * se qualquer tipo ficar assim. Assim, adicionar um ObjType obriga a declarar. */
typedef enum { GC_UNSET = 0, GC_LEAF, GC_ONE, GC_FN } GcKind;
/* `fn`  = tracer (marca os filhos).
 * `tam` = tamanho FIXO do objeto, descontado de vm->alocado no sweep (0 quando o
 *         tamanho é variável — aí o `fin` faz a conta).
 * `fin` = finalizer: libera os buffers C do objeto (e, se `tam`==0, também faz o
 *         `vm->alocado -=`). Centraliza o cleanup que antes era um `if/else`
 *         gigante em libera_obj (os "garis" espalhados). NULL = nada a liberar. */
typedef struct { GcKind kind; size_t off; void (*fn)(VM *, Obj *);
                 size_t tam; void (*fin)(VM *, Obj *); } GcInfo;

/* Caixa de uma variável capturada. Quem declara e quem captura apontam pra
 * MESMA célula, então uma escrita de dentro da action aninhada é vista de fora
 * (e vice-versa) — é o que separa closure de cópia. */
typedef struct { Obj obj; Value v; } PSCelula;

/* Uma action que captura: o proto mais o vetor de células. Continua sendo
 * "uma função" pra todo o resto da VM — os pontos de chamada aceitam os dois. */
struct PSClosure_ {
    Obj        obj;
    int32_t    proto;
    int32_t    nups;
    PSCelula **ups;
};

/* `async action` — resultado pendente. A fibra que o produz vive no pool de
 * fibras (marcada por fib_marca_gc enquanto `usada`); aqui marcamos só o valor
 * final. */
typedef struct PSFuturo {
    Obj    obj;
    struct Fiber *fib;      /* fibra que roda a action (NULL após concluir) */
    int    done;
    int    erro;           /* 1 = a action levantou */
    char   erro_msg[256];
    char   erro_tipo[64];
    Value  valor;          /* resultado quando done */
} PSFuturo;

static void gct_closure(VM *vm, Obj *o) {
    PSClosure *cl = (PSClosure *)o;
    for (int32_t i = 0; i < cl->nups; i++)
        if (cl->ups[i]) marca_obj(vm, (Obj *)cl->ups[i]);
}
static void fin_closure(VM *vm, Obj *o) {
    PSClosure *cl = (PSClosure *)o;
    vm->alocado -= sizeof(PSCelula *) * (size_t)cl->nups;
    free(cl->ups);
}
static void gct_celula(VM *vm, Obj *o) { marca_valor(vm, &((PSCelula *)o)->v); }

static void gct_seq(VM *vm, Obj *o) {
    PSList *l = (PSList *)o;
    for (int i = 0; i < l->len; i++) marca_valor(vm, &l->itens[i]);
}
static void gct_futuro(VM *vm, Obj *o) {
    marca_valor(vm, &((PSFuturo *)o)->valor);
}
static void gct_dict(VM *vm, Obj *o) {
    PSDict *d = (PSDict *)o;
    for (int i = 0; i < d->usados; i++) {
        if (d->entradas[i].estado != 1) continue;
        marca_valor(vm, &d->entradas[i].chave);
        marca_valor(vm, &d->entradas[i].valor);
    }
}
static void gct_gerador(VM *vm, Obj *o) {
    PSGerador *g = (PSGerador *)o;
    for (int32_t i = 0; i < g->nlocais; i++) marca_valor(vm, &g->locais[i]);
    for (int32_t i = 0; i < g->npilha; i++)  marca_valor(vm, &g->pilha[i]);
    if (g->cl) marca_obj(vm, (Obj *)g->cl);   /* células que a geradora capturou */
}
static void gct_response(VM *vm, Obj *o) {
    PSResponse *rp = (PSResponse *)o;
    marca_valor(vm, &rp->headers); marca_valor(vm, &rp->url); marca_valor(vm, &rp->corpo);
}
static void gct_instance(VM *vm, Obj *o) {
    PSInstance *inst = (PSInstance *)o;
    if (inst->classe) marca_obj(vm, (Obj *)inst->classe);
    if (inst->campos) marca_obj(vm, (Obj *)inst->campos);
}
/* Campo `static` de uma classe, procurando nela e depois nos pais, na ordem
 * declarada. 0 = achou (em `out`), -1 = não existe. */
static int classe_estatico(PSClass *cl, const Value *nomev, Value *out)
{
    if (!cl) return -1;
    if (EH_DICT(cl->estaticos) && dict_get(COMO_DICT(cl->estaticos), nomev, out) == 0)
        return 0;
    for (int32_t i = 0; i < cl->npais; i++)
        if (classe_estatico(cl->pais[i], nomev, out) == 0) return 0;
    return -1;
}

static void gct_class(VM *vm, Obj *o) {
    PSClass *cl = (PSClass *)o;
    for (int32_t i = 0; i < cl->npais; i++)
        if (cl->pais[i]) marca_obj(vm, (Obj *)cl->pais[i]);
    marca_valor(vm, &cl->estaticos);
}
static void gct_enum(VM *vm, Obj *o) {
    PSEnum *e = (PSEnum *)o;
    for (int32_t i = 0; i < e->n; i++) marca_valor(vm, &e->valores[i]);
}
static void gct_jinker(VM *vm, Obj *o) {
    PSJinker *j = (PSJinker *)o;
    for (int i = 0; i < j->nrotas; i++) {
        marca_valor(vm, &j->rotas[i].handler);
        marca_valor(vm, &j->rotas[i].middleware);
        marca_valor(vm, &j->rotas[i].model);
    }
    for (int i = 0; i < j->nsocks; i++) marca_valor(vm, &j->socks[i].handler);
    for (int i = 0; i < j->nws; i++)    marca_valor(vm, &j->ws[i].params);
    marca_valor(vm, &j->mw_handler);
    marca_valor(vm, &j->ch_status);
}
static void gct_jreg(VM *vm, Obj *o) {
    PSJReg *r = (PSJReg *)o; marca_valor(vm, &r->app); marca_valor(vm, &r->middleware);
    marca_valor(vm, &r->model);
}
static void gct_jresp(VM *vm, Obj *o) {
    PSJResp *r = (PSJResp *)o; marca_valor(vm, &r->corpo); marca_valor(vm, &r->headers);
    marca_valor(vm, &r->cookies);
}
static void gct_jreq(VM *vm, Obj *o) {
    PSJReq *r = (PSJReq *)o;
    marca_valor(vm, &r->headers); marca_valor(vm, &r->corpo); marca_valor(vm, &r->query);
    marca_valor(vm, &r->params);  marca_valor(vm, &r->ws_msg);
}

/* ── finalizers (Fase 1: migração do `if/else` de libera_obj pra tabela) ────
 * Cada um libera os buffers C do objeto. Quando o tamanho é VARIÁVEL (string,
 * list, dict, gerador), o finalizer também faz o `vm->alocado -=` (a entrada põe
 * tam=0); quando é fixo, o `tam` da tabela cuida da conta e o finalizer só
 * libera os buffers internos. */
static void fin_str(VM *vm, Obj *o) {        /* STRING e BYTES (tam variável) */
    PSString *s = (PSString *)o;
    vm->alocado -= sizeof(PSString) + (size_t)s->len + 1;
}
static void fin_seq(VM *vm, Obj *o) {        /* LIST e TUPLE (tam variável) */
    PSList *l = (PSList *)o;
    vm->alocado -= sizeof(PSList) + sizeof(Value) * (size_t)l->cap;
    free(l->itens);
}
static void fin_dict(VM *vm, Obj *o) {       /* DICT (tam variável) */
    PSDict *d = (PSDict *)o;
    vm->alocado -= sizeof(PSDict) + sizeof(Entrada) * (size_t)d->cap
                 + sizeof(int32_t) * (size_t)d->icap;
    free(d->entradas);
    free(d->indices);
}
static void fin_gerador(VM *vm, Obj *o) {    /* GERADOR (tam variável) */
    PSGerador *g = (PSGerador *)o;
    vm->alocado -= sizeof(PSGerador) + sizeof(Value) * (size_t)(g->nlocais + g->npilha);
    free(g->locais);
    free(g->pilha);
    free(g->handlers);
}
static void fin_class(VM *vm, Obj *o) {      /* CLASS (tam fixo; só buffers) */
    (void)vm;
    PSClass *cl = (PSClass *)o;
    free(cl->nome);
    for (int32_t i = 0; i < cl->nmetodos; i++) free(cl->met_nomes[i]);
    free(cl->met_nomes);
    free(cl->met_protos);
    for (int32_t i = 0; i < cl->npriv; i++) free(cl->priv_nomes[i]);
    free(cl->priv_nomes);
    free(cl->pais);
}
static void fin_enum(VM *vm, Obj *o) {       /* nome/nomes são do descritor; só valores é por-instância */
    (void)vm;
    free(((PSEnum *)o)->valores);
}
static void fin_moduleps(VM *vm, Obj *o) {
    (void)vm;
    PSModuloPS *m = (PSModuloPS *)o;
    for (int32_t i = 0; i < m->n; i++) free(m->nomes[i]);
    free(m->nomes);
    free(m->priv);
    free(m->nome);
    free(m->caminho);
}
static void fin_bigint(VM *vm, Obj *o) {
    (void)vm;
    mpz_clear(((PSBigInt *)o)->v);
}
static void fin_poolfile(VM *vm, Obj *o) {
    (void)vm;
    PSPoolFile *f = (PSPoolFile *)o;
    free(f->caminho); free(f->nome); free(f->ext);
}
static void fin_socket(VM *vm, Obj *o) {   /* fecha o que o usuário esqueceu */
    (void)vm;
    PSSocket *s = (PSSocket *)o;
    if (s->fd >= 0) close(s->fd);
}

static void fin_regex(VM *vm, Obj *o) {
    (void)vm;
    PSRegexObj *r = (PSRegexObj *)o;
    if (r->rx) ps_regex_free(r->rx);
    free(r->pat);
}

/* Finalizers de lib/servidor (lote 2): DEFINIDOS mais abaixo, junto do
 * libera_obj, porque usam tipos/funções de lib que só existem lá. Aqui só o
 * forward-declare pra a GC_INFO poder referenciá-los. Cada um faz o
 * `vm->alocado -=` (a entrada põe tam=0) + libera os buffers. */
static void fin_arquivo(VM *, Obj *);   static void fin_sqlcur(VM *, Obj *);
static void fin_sqlconn(VM *, Obj *);   static void fin_mailsrv(VM *, Obj *);
static void fin_mailrd(VM *, Obj *);    static void fin_response(VM *, Obj *);
static void fin_qrfile(VM *, Obj *);    static void fin_manpu_res(VM *, Obj *);
static void fin_dbconn(VM *, Obj *);    static void fin_dbcur(VM *, Obj *);
static void fin_mongoconn(VM *, Obj *); static void fin_mongocol(VM *, Obj *);
static void fin_mailmsg(VM *, Obj *);   static void fin_jinker(VM *, Obj *);
static void fin_jcors(VM *, Obj *);     static void fin_jreg(VM *, Obj *);
static void fin_jresp(VM *, Obj *);     static void fin_jreq(VM *, Obj *);
static void fin_jproxy(VM *, Obj *);    static void fin_jupload(VM *, Obj *);
static void fin_jsockns(VM *, Obj *);   static void fin_jemit(VM *, Obj *);
static void fin_jchan(VM *, Obj *);     static void fin_jchst(VM *, Obj *);
static void fin_wsconn(VM *, Obj *);    static void fin_qrbuild(VM *, Obj *);
static void fin_qrimage(VM *, Obj *);   static void fin_manpu_file(VM *, Obj *);

/* A tabela: TODO tipo aparece aqui. Esquecer um => GC_UNSET => aborta no boot. */
static const GcInfo GC_INFO[OBJ__COUNT] = {
    [OBJ_CELULA]     = { GC_FN,   0, gct_celula, sizeof(PSCelula), NULL },
    [OBJ_CLOSURE]    = { GC_FN,   0, gct_closure, sizeof(PSClosure), fin_closure },
    [OBJ_STRING]     = { GC_LEAF, 0, NULL, 0, fin_str },
    [OBJ_LIST]       = { GC_FN,   0, gct_seq, 0, fin_seq },
    [OBJ_TUPLE]      = { GC_FN,   0, gct_seq, 0, fin_seq },
    [OBJ_DICT]       = { GC_FN,   0, gct_dict, 0, fin_dict },
    [OBJ_CLASS]      = { GC_FN,   0, gct_class, sizeof(PSClass), fin_class },
    [OBJ_INSTANCE]   = { GC_FN,   0, gct_instance, sizeof(PSInstance), NULL },
    [OBJ_BOUND]      = { GC_ONE,  offsetof(PSBound, instancia), NULL, sizeof(PSBound), NULL },
    [OBJ_METODO_NAT] = { GC_ONE,  offsetof(PSMetodoNat, alvo), NULL, sizeof(PSMetodoNat), NULL },
    [OBJ_MODULO]     = { GC_LEAF, 0, NULL, sizeof(PSModulo), NULL },
    [OBJ_NATIVA]     = { GC_LEAF, 0, NULL, sizeof(PSNativa), NULL },
    [OBJ_MODEL]      = { GC_LEAF, 0, NULL, sizeof(PSModel), NULL },
    [OBJ_ENUM]       = { GC_FN,   0, gct_enum, sizeof(PSEnum), fin_enum },
    [OBJ_GERADOR]    = { GC_FN,   0, gct_gerador, 0, fin_gerador },
    [OBJ_FUTURO]     = { GC_FN,   0, gct_futuro, sizeof(PSFuturo), NULL },   /* o libera_obj ANTIGO esquecia o alocado-= do futuro (leak de conta); agora conta */
    [OBJ_SOCKET]     = { GC_LEAF, 0, NULL, sizeof(PSSocket), fin_socket },
    [OBJ_REGEX]      = { GC_LEAF, 0, NULL, sizeof(PSRegexObj), fin_regex },
    [OBJ_ARQUIVO]    = { GC_LEAF, 0, NULL, 0, fin_arquivo },   /* globais vivem em vm->globals (raiz) */
    [OBJ_MODULO_PS]  = { GC_LEAF, 0, NULL, sizeof(PSModuloPS), fin_moduleps },
    [OBJ_BYTES]      = { GC_LEAF, 0, NULL, 0, fin_str },
    [OBJ_SQLCONN]    = { GC_LEAF, 0, NULL, 0, fin_sqlconn },
    [OBJ_SQLCUR]     = { GC_ONE,  offsetof(PSSqlCur, conn), NULL, 0, fin_sqlcur },
    [OBJ_MAILSRV]    = { GC_LEAF, 0, NULL, 0, fin_mailsrv },
    [OBJ_MAILMSG]    = { GC_LEAF, 0, NULL, 0, fin_mailmsg },
    [OBJ_MAILRD]     = { GC_LEAF, 0, NULL, 0, fin_mailrd },
    [OBJ_RESPONSE]   = { GC_FN,   0, gct_response, 0, fin_response },
    [OBJ_QRFILE]     = { GC_ONE,  offsetof(PSQRFile, conteudo), NULL, 0, fin_qrfile },
    [OBJ_MANPU_RES]  = { GC_LEAF, 0, NULL, 0, fin_manpu_res },
    [OBJ_DBCONN]     = { GC_LEAF, 0, NULL, 0, fin_dbconn },
    [OBJ_DBCUR]      = { GC_ONE,  offsetof(PSDbCursor, conexao), NULL, 0, fin_dbcur },
    [OBJ_MONGOCONN]  = { GC_LEAF, 0, NULL, 0, fin_mongoconn },
    [OBJ_MONGOCOL]   = { GC_ONE,  offsetof(PSMongoCol, conexao), NULL, 0, fin_mongocol },
    [OBJ_POOLFILE]   = { GC_ONE,  offsetof(PSPoolFile, conteudo), NULL, sizeof(PSPoolFile), fin_poolfile },
    [OBJ_JINKER]     = { GC_FN,   0, gct_jinker, 0, fin_jinker },
    [OBJ_JCORS]      = { GC_LEAF, 0, NULL, 0, fin_jcors },
    [OBJ_JREG]       = { GC_FN,   0, gct_jreg, 0, fin_jreg },
    [OBJ_JRESP]      = { GC_FN,   0, gct_jresp, 0, fin_jresp },
    [OBJ_JREQ]       = { GC_FN,   0, gct_jreq, 0, fin_jreq },
    [OBJ_JPROXY]     = { GC_LEAF, 0, NULL, 0, fin_jproxy },
    [OBJ_JUPLOAD]    = { GC_ONE,  offsetof(PSJUpload, dados), NULL, 0, fin_jupload },
    [OBJ_JSOCKNS]    = { GC_ONE,  offsetof(PSJSockNs, app), NULL, 0, fin_jsockns },
    [OBJ_JEMIT]      = { GC_ONE,  offsetof(PSJEmit, app), NULL, 0, fin_jemit },
    [OBJ_JCHAN]      = { GC_ONE,  offsetof(PSJChan, app), NULL, 0, fin_jchan },
    [OBJ_JCHST]      = { GC_LEAF, 0, NULL, 0, fin_jchst },
    [OBJ_WSCONN]     = { GC_ONE,  offsetof(PSWsConn, on_msg), NULL, 0, fin_wsconn },
    [OBJ_QRBUILD]    = { GC_LEAF, 0, NULL, 0, fin_qrbuild },
    [OBJ_QRIMAGE]    = { GC_LEAF, 0, NULL, 0, fin_qrimage },
    [OBJ_MANPU_FILE] = { GC_LEAF, 0, NULL, 0, fin_manpu_file },
    [OBJ_BIGINT]     = { GC_LEAF, 0, NULL, sizeof(PSBigInt), fin_bigint },
};

/* Boot: recusa qualquer ObjType que não declarou seu tracer (GC_UNSET).
 * É a rede de segurança: tipo novo sem entrada em GC_INFO aborta AQUI, alto e
 * claro, em vez de virar use-after-free silencioso lá na frente. */
static void gc_valida_tabela(void) {
    static int checado = 0;
    if (checado) return;
    checado = 1;
    for (int t = 0; t < OBJ__COUNT; t++) {
        if (GC_INFO[t].kind == GC_UNSET) {
            fprintf(stderr, "ERRO FATAL: ObjType %d sem tracer de GC declarado "
                            "(adicione em GC_INFO[])\n", t);
            abort();
        }
        /* O sweep é table-driven: cada tipo tem que dizer como libera — `tam`
         * (tamanho fixo) OU `fin` (finalizer). Sem nenhum dos dois, o objeto
         * vazaria os buffers e a conta de vm->alocado desanda. Aborta no boot,
         * igual ao tracer — um ObjType novo é obrigado a declarar o cleanup. */
        if (GC_INFO[t].tam == 0 && GC_INFO[t].fin == NULL) {
            fprintf(stderr, "ERRO FATAL: ObjType %d sem finalizer/tam de GC "
                            "(adicione tam ou fin em GC_INFO[])\n", t);
            abort();
        }
    }
}

static void percorre_cinzas(VM *vm)
{
    while (vm->ncinzas > 0) {
        Obj *o = vm->cinzas[--vm->ncinzas];
        const GcInfo *gi = &GC_INFO[o->type];
        if (gi->kind == GC_FN)       gi->fn(vm, o);
        else if (gi->kind == GC_ONE) marca_valor(vm, (Value *)((char *)o + gi->off));
        /* GC_LEAF: sem filho a marcar */
    }
}

/* ── finalizers de lib/servidor (Fase 1, lote 2) ────────────────────────────
 * Definidos aqui (e não junto de fin_str) porque usam tipos/funções de lib que
 * só existem a esta altura do arquivo. Cada um faz o `vm->alocado -=` (a entrada
 * na tabela põe tam=0) + libera os buffers internos. */
static void fin_arquivo(VM *vm, Obj *o) {
    PSArquivo *a = (PSArquivo *)o;
    if (!a->fechado && a->f) fclose(a->f);   /* fecha o que o usuário esqueceu */
    vm->alocado -= sizeof(PSArquivo);
}
static void fin_sqlcur(VM *vm, Obj *o) {
    PSSqlCur *cu = (PSSqlCur *)o;
    if (cu->stmt) sqlite3_finalize(cu->stmt);
    vm->alocado -= sizeof(PSSqlCur);
}
static void fin_sqlconn(VM *vm, Obj *o) {
    PSSqlConn *cn = (PSSqlConn *)o;
    if (!cn->fechado && cn->db) sqlite3_close_v2(cn->db);   /* v2 tolera stmt vivo */
    vm->alocado -= sizeof(PSSqlConn);
}
static void fin_mailsrv(VM *vm, Obj *o) {
    PSMailSrv *m = (PSMailSrv *)o;
    if (m->conn) ps_mail_solta(m->conn);   /* socket órfão: só fecha */
    free(m->user);
    vm->alocado -= sizeof(PSMailSrv);
}
static void fin_mailrd(VM *vm, Obj *o) {
    PSMailMsg_reader *m = (PSMailMsg_reader *)o;
    if (m->conn) ps_mail_solta(m->conn);
    vm->alocado -= sizeof(PSMailMsg_reader);
}
static void fin_response(VM *vm, Obj *o) {
    PSResponse *r = (PSResponse *)o;
    /* o arquivo do corpo é do motor quando ele mesmo o criou: some junto com a
     * resposta. O que o usuário pediu com `save=` é dele e fica. */
    if (r->arquivo) {
        if (r->temporario && r->dono == getpid()) unlink(r->arquivo);
        free(r->arquivo);
        r->arquivo = NULL;
    }
    vm->alocado -= sizeof(PSResponse);
}
static void fin_qrfile(VM *vm, Obj *o) {
    PSQRFile *q = (PSQRFile *)o;
    free(q->nome); free(q->ext);
    vm->alocado -= sizeof(PSQRFile);
}
static void fin_manpu_res(VM *vm, Obj *o) {
    free(((PSManpuRes *)o)->status);
    vm->alocado -= sizeof(PSManpuRes);
}
static void fin_dbconn(VM *vm, Obj *o) {
    PSDbConexao *cn = (PSDbConexao *)o;
    if (!cn->fechado && cn->conn) ps_db_solta(cn->conn);
    else free(cn->conn);
    vm->alocado -= sizeof(PSDbConexao);
}
static void fin_dbcur(VM *vm, Obj *o) {
    ps_db_res_libera(&((PSDbCursor *)o)->res);
    vm->alocado -= sizeof(PSDbCursor);
}
static void fin_mongoconn(VM *vm, Obj *o) {
    PSMongoConn *cn = (PSMongoConn *)o;
    if (!cn->fechado && cn->m) ps_mongo_fecha(cn->m);
    vm->alocado -= sizeof(PSMongoConn);
}
static void fin_mongocol(VM *vm, Obj *o) {
    free(((PSMongoCol *)o)->nome);
    vm->alocado -= sizeof(PSMongoCol);
}
static void fin_mailmsg(VM *vm, Obj *o) {
    PSMailMsg *m = (PSMailMsg *)o;
    for (int k = 0; k < m->ncabs; k++) { free(m->cabs[k].nome); free(m->cabs[k].valor); }
    free(m->cabs);
    for (int k = 0; k < m->npartes; k++) { free(m->partes[k].ct); free(m->partes[k].dados); }
    free(m->partes);
    vm->alocado -= sizeof(PSMailMsg);
}
static void fin_jinker(VM *vm, Obj *o) {
    PSJinker *j = (PSJinker *)o;
    for (int i = 0; i < j->nrotas; i++) {
        free(j->rotas[i].path);
        for (int k = 0; k < j->rotas[i].nmetodos; k++) free(j->rotas[i].metodos[k]);
        free(j->rotas[i].metodos);
        for (int k = 0; k < j->rotas[i].nauth; k++) free(j->rotas[i].auth[k]);
        free(j->rotas[i].auth);
    }
    free(j->rotas);
    for (int i = 0; i < j->nsocks; i++) free(j->socks[i].path);
    free(j->socks);
    for (int i = 0; i < j->nws; i++) free(j->ws[i].sala);
    free(j->ws);
    for (int i = 0; i < j->nhits; i++) free(j->hits[i].ts);
    free(j->hits);
    free(j->bans);
    free(j->nome); free(j->static_folder); free(j->static_url); free(j->route_prefix); free(j->cert); free(j->key);
    vm->alocado -= sizeof(PSJinker);
}
static void fin_jcors(VM *vm, Obj *o) {
    PSJCors *c = (PSJCors *)o;
    for (int i = 0; i < c->nmetodos; i++) free(c->metodos[i]);
    free(c->metodos);
    for (int i = 0; i < c->norigens; i++) free(c->origens[i]);
    free(c->origens);
    vm->alocado -= sizeof(PSJCors);
}
static void fin_jreg(VM *vm, Obj *o) {
    PSJReg *r = (PSJReg *)o;
    free(r->path);
    for (int i = 0; i < r->nmetodos; i++) free(r->metodos[i]);
    free(r->metodos);
    for (int i = 0; i < r->nauth; i++) free(r->auth[i]);
    free(r->auth);
    vm->alocado -= sizeof(PSJReg);
}
static void fin_jresp(VM *vm, Obj *o) { (void)o; vm->alocado -= sizeof(PSJResp); }
static void fin_jreq(VM *vm, Obj *o) {
    free(((PSJReq *)o)->path);
    vm->alocado -= sizeof(PSJReq);
}
static void fin_jproxy(VM *vm, Obj *o) { (void)o; vm->alocado -= sizeof(PSJProxy); }
static void fin_jupload(VM *vm, Obj *o) {
    PSJUpload *u = (PSJUpload *)o;
    free(u->nome); free(u->ctype); free(u->ext);
    vm->alocado -= sizeof(PSJUpload);
}
static void fin_jsockns(VM *vm, Obj *o) { (void)o; vm->alocado -= sizeof(PSJSockNs); }
static void fin_jemit(VM *vm, Obj *o) { (void)o; vm->alocado -= sizeof(PSJEmit); }
static void fin_jchan(VM *vm, Obj *o) { (void)o; vm->alocado -= sizeof(PSJChan); }
static void fin_jchst(VM *vm, Obj *o) { (void)o; vm->alocado -= sizeof(PSJChSt); }
static void fin_wsconn(VM *vm, Obj *o) {
    PSWsConn *w = (PSWsConn *)o;
    if (w->conn) ps_jk_close(w->conn);
    free(w->url);
    /* tira da lista do `sleep()`. Enquanto está nela é RAIZ do GC (ver
     * gc_coleta), então só chega aqui quem já foi fechado por `.close()` ou
     * quem está morrendo com a VM. */
    for (int i = 0; i < vm->n_ws_vivos; i++)
        if (vm->ws_vivos[i] == w) {
            vm->ws_vivos[i] = vm->ws_vivos[--vm->n_ws_vivos];
            break;
        }
    vm->alocado -= sizeof(PSWsConn);
}
static void fin_qrbuild(VM *vm, Obj *o) {
    free(((PSQRBuild *)o)->dados);
    vm->alocado -= sizeof(PSQRBuild);
}
static void fin_qrimage(VM *vm, Obj *o) {
    PSQRImage *q = (PSQRImage *)o;
    free(q->dados); free(q->cor); free(q->fundo); free(q->nome);
    vm->alocado -= sizeof(PSQRImage);
}
static void fin_manpu_file(VM *vm, Obj *o) {
    PSManpuFile *m = (PSManpuFile *)o;
    free(m->caminho); free(m->texto);
    ps_grade_libera(&m->grade);
    vm->alocado -= sizeof(PSManpuFile);
}

/* Sweep 100%% table-driven: `tam` desconta o tamanho fixo (0 quando variável) e
 * `fin` libera os buffers internos (e faz a conta do variável). O antigo
 * `if/else` gigante por tipo virou os finalizers acima. */
static void libera_obj(VM *vm, Obj *o)
{
    const GcInfo *gi = &GC_INFO[o->type];
    vm->alocado -= gi->tam;
    if (gi->fin) gi->fin(vm, o);
    free(o);
}

static void fib_marca_gc(VM *vm);   /* marca contextos de fibra (def. junto do jinker) */

static void gc_coleta(VM *vm)
{
    gc_valida_tabela();   /* rede de segurança: aborta se algum tipo não declarou tracer */

    /* O GC lê `sp` e `locals_top` como TAMANHO das raízes. Se algum caminho os
     * deixou fora de faixa, a varredura lê lixo e marca objeto que não existe
     * — e o efeito aparece muito depois, num free de ponteiro inventado. Aqui
     * é o ponto exato em que dá pra dizer que estava errado. */
    PS_ASSERT_MSG(vm->sp >= 0 && vm->sp <= vm->stack_teto,
                  "sp=%d fora de [0, %d]", vm->sp, vm->stack_teto);
    PS_ASSERT_MSG(vm->locals_top >= 0 && vm->locals_top <= vm->locals_teto,
                  "locals_top=%d fora de [0, %d]", vm->locals_top, vm->locals_teto);
    PS_ASSERT_MSG(vm->gc_fp >= 0, "gc_fp=%d negativo", vm->gc_fp);

    vm->ncinzas = 0;

    /* raízes: globais, pilha viva, locais vivos e constantes dos protótipos */
    for (int i = 0; i < vm->nglobals; i++)   marca_valor(vm, &vm->globals[i]);
    /* singletons e requisição corrente do jinker também são raízes */
    marca_valor(vm, &vm->jk_cors);
    marca_valor(vm, &vm->jk_proxy);
    marca_valor(vm, &vm->jk_req);
    marca_valor(vm, &vm->jk_app);
    /* módulos `.ps` importados vivem no cache mods_ps pro programa inteiro
     * — são RAÍZES, senão o GC coleta um módulo
     * ainda em uso e depois libera de novo -> double free -> segfault. */
    for (int i = 0; i < vm->nmods_ps; i++)   marca_valor(vm, &vm->mods_ps[i].valor);
    /* Conexão WebSocket ABERTA é raiz até o `.close()`. `ws_vivos` era só
     * ponteiro fraco: `request.ws_connect(u).on_message(f)` sem variável, ou
     * com a variável reatribuída, deixava o objeto sem raiz; o `sleep()` o
     * drenava, o callback disparava o GC, o objeto morria, e o laço da
     * drenagem voltava a ler `w->conn` de memória liberada. `fin_wsconn` tira
     * da lista o que foi fechado, então nada fica enraizado além da vida. */
    for (int i = 0; i < vm->n_ws_vivos; i++)  marca_obj(vm, (Obj *)vm->ws_vivos[i]);
    for (int i = 0; i < vm->sp; i++)         marca_valor(vm, &vm->stack[i]);
    for (int i = 0; i < vm->locals_top; i++) marca_valor(vm, &vm->locals[i]);
    /* closures dos frames em execução (não aparecem na pilha de valores) */
    if (vm->gc_cl) marca_obj(vm, (Obj *)vm->gc_cl);
    for (int i = 0; i < vm->gc_fp && i < vm->frames_teto; i++)
        if (vm->frames[i].cl) marca_obj(vm, (Obj *)vm->frames[i].cl);
    fib_marca_gc(vm);   /* MAIN salvo + fibras suspensas (contextos fora de vm->) */
    for (int i = 0; i < vm->nprotos; i++)
        for (int k = 0; k < vm->protos[i].nconsts; k++)
            marca_valor(vm, &vm->protos[i].consts[k]);

    percorre_cinzas(vm);

    /* varre: libera o que não foi marcado, desmarca o resto */
    Obj **elo = &vm->objetos;
    while (*elo) {
        Obj *o = *elo;
        if (o->marked) {
            o->marked = 0;
            elo = &o->next;
        } else {
            *elo = o->next;
            libera_obj(vm, o);
            vm->objetos_liberados++;
        }
    }

    vm->ciclos_gc++;
    vm->proximo_gc = vm->alocado * 2;
    if (vm->proximo_gc < GC_INICIAL) vm->proximo_gc = GC_INICIAL;
}

static void libera_objetos(VM *vm)
{
    Obj *o = vm->objetos;
    while (o) {
        Obj *prox = o->next;
        libera_obj(vm, o);      /* precisa liberar itens/entradas, não só o cabeçalho */
        o = prox;
    }
    vm->objetos = NULL;
    free(vm->cinzas);
    vm->cinzas = NULL;
    vm->cap_cinzas = 0;
    vm->ncinzas = 0;
}

/* ── Entity ─────────────────────────────────────────────────────────────── */
static PSInstance *nova_instancia(VM *vm, PSClass *cl)
{
    PSInstance *o = calloc(1, sizeof(PSInstance));
    if (!o) return NULL;
    o->obj.type = OBJ_INSTANCE; o->obj.marked = 0;
    o->obj.next = vm->objetos; vm->objetos = (Obj *)o;
    o->classe = cl;
    o->campos = NULL;
    vm->alocado += sizeof(PSInstance);
    return o;
}

static PSBound *novo_bound(VM *vm, Value inst, int32_t proto)
{
    PSBound *b = calloc(1, sizeof(PSBound));
    if (!b) return NULL;
    b->obj.type = OBJ_BOUND; b->obj.marked = 0;
    b->obj.next = vm->objetos; vm->objetos = (Obj *)b;
    b->instancia = inst;
    b->proto = proto;
    vm->alocado += sizeof(PSBound);
    return b;
}

/* MRO simples: a própria classe, depois os pais da esquerda pra direita —
 * é o `find_method` do interpretador. */
static int32_t acha_metodo(PSClass *cl, const char *nome)
{
    if (!cl || !cl->met_nomes) return -1;
    for (int32_t i = 0; i < cl->nmetodos; i++)
        /* `met_nomes[i]` NULL não pode derrubar a busca: quem monta a classe já
         * mantém o contador coerente, mas esta função é chamada de todo lugar
         * e é barato não confiar. */
        if (cl->met_nomes[i] && strcmp(cl->met_nomes[i], nome) == 0) return cl->met_protos[i];
    for (int32_t i = 0; i < cl->npais; i++) {
        int32_t r = acha_metodo(cl->pais[i], nome);
        if (r >= 0) return r;
    }
    return -1;
}

/* Nome do global de índice `arg`, pra mensagem de erro. Primeiro o script
 * principal (nomes_globais); se não achar, procura nos módulos `.ps` já
 * carregados (cada um cobre a faixa [base, base+n)). "?" só se nada bater. */
static const char *nome_do_global(VM *vm, int32_t arg)
{
    if (arg >= 0 && arg < vm->n_nomes_globais && vm->nomes_globais && vm->nomes_globais[arg])
        return vm->nomes_globais[arg];
    for (int i = 0; i < vm->nmods_ps; i++) {
        Value v = vm->mods_ps[i].valor;
        if (v.t != V_OBJ || v.as.obj->type != OBJ_MODULO_PS) continue;
        PSModuloPS *m = (PSModuloPS *)v.as.obj;
        if (arg >= m->base && arg < m->base + m->n && m->nomes && m->nomes[arg - m->base])
            return m->nomes[arg - m->base];
    }
    return "?";
}

/* Encapsulamento: 1 se `nome` é membro `private` de `cl` (ou de um ancestral)
 * E o protótipo em execução (`proto_atual`) NÃO é um método da classe que o
 * declara — isto é, acesso de FORA. 0 = liberado (público, ou private acessado
 * de dentro de um método da própria classe). */
/* Regra: um `private` é visível DENTRO da classe que o declara.
 *
 * A versão antiga parava na PRIMEIRA classe da hierarquia que declarasse o
 * nome — em geral a filha — e, se o método em execução não fosse dela,
 * barrava. Com `Entity P` declarando `private s` e `Entity F(P)` também,
 * o `self.s` DENTRO de `P.mostra` era negado: o método é de P, que declara o
 * campo, e ainda assim a checagem só olhava F. Agora a hierarquia inteira é
 * varrida e a pergunta é outra: o proto que está rodando pertence a ALGUMA
 * classe que declara este nome como private? Se pertence, passa. */
static int priv_barrado(PSClass *cl, const char *nome, int32_t proto_atual)
{
    PSClass *pilha[64]; int np = 0;
    int achou = 0;
    if (cl) pilha[np++] = cl;
    while (np > 0) {
        PSClass *c = pilha[--np];
        for (int32_t i = 0; i < c->npriv; i++) {
            if (strcmp(c->priv_nomes[i], nome) == 0) {
                achou = 1;
                for (int32_t k = 0; k < c->nmetodos; k++)
                    if (c->met_protos[k] == proto_atual) return 0;  /* de dentro */
                break;
            }
        }
        for (int32_t i = 0; i < c->npais && np < 64; i++)
            if (c->pais[i]) pilha[np++] = c->pais[i];
    }
    return achou;   /* private em algum ponto da hierarquia e não é de dentro */
}

/* ── conversões com a extensão de teste diferencial ─────────────────────── */

#ifdef PS_MODULO_PYTHON
/* Entrada de dados: só converte o que a VM representa nativamente. Nenhum
 * objeto da extensão entra na VM — se o tipo não tem forma nativa, é erro
 * explícito, porque guardar um objeto de fora aqui reintroduziria a
 * dependência que esta etapa existe pra eliminar. */
static int py_para_value(VM *vm, PyObject *o, Value *out)
{
    if (o == Py_None)  { *out = MK_NULL(); return 0; }
    if (PyBool_Check(o)) { *out = MK_BOOL(o == Py_True); return 0; }
    if (PyLong_Check(o)) {
        int overflow = 0;
        long long v = PyLong_AsLongLongAndOverflow(o, &overflow);
        if (overflow) return -1;
        *out = MK_INT((int64_t)v);
        return 0;
    }
    if (PyFloat_Check(o)) { *out = MK_FLOAT(PyFloat_AsDouble(o)); return 0; }
    if (PyUnicode_Check(o)) {
        Py_ssize_t n = 0;
        const char *utf8 = PyUnicode_AsUTF8AndSize(o, &n);
        if (!utf8) return -1;
        PSString *s = nova_string(vm, utf8, (int)n);
        if (!s) return -1;
        *out = MK_OBJ(s);
        return 0;
    }
    return -1;
}

static PyObject *value_para_py(const Value *v)
{
    switch (v->t) {
        case V_NULL:   Py_RETURN_NONE;
        case V_BOOL:   return PyBool_FromLong(v->as.b);
        case V_INT:    return PyLong_FromLongLong((long long)v->as.i);
        case V_FLOAT:  return PyFloat_FromDouble(v->as.d);
        case V_FUNC:   return PyUnicode_FromFormat("<funct #%d>", v->as.proto);
        case V_NATIVE: return PyUnicode_FromString("<builtin>");
        case V_TIPO:   return PyUnicode_FromString(tipo_nome(v->as.i));
        case V_UNSET:  Py_RETURN_NONE;
        case V_OBJ:
            if (v->as.obj->type == OBJ_BIGINT) {
                char *s = bigint_str(((PSBigInt *)v->as.obj)->v);
                PyObject *py = s ? PyLong_FromString(s, NULL, 10) : NULL;
                free(s);
                return py;
            }
            if (v->as.obj->type == OBJ_STRING) {
                PSString *s = (PSString *)v->as.obj;
                return PyUnicode_FromStringAndSize(s->chars, s->len);
            }
            if (v->as.obj->type == OBJ_LIST || v->as.obj->type == OBJ_TUPLE) {
                PSList *l = (PSList *)v->as.obj;
                PyObject *py = PyList_New(l->len);
                if (!py) return NULL;
                for (int i = 0; i < l->len; i++) {
                    PyObject *item = value_para_py(&l->itens[i]);
                    if (!item) { Py_DECREF(py); return NULL; }
                    PyList_SET_ITEM(py, i, item);
                }
                return py;
            }
            if (v->as.obj->type == OBJ_DICT) {
                PSDict *d = (PSDict *)v->as.obj;
                PyObject *py = PyDict_New();
                if (!py) return NULL;
                for (int i = 0; i < d->usados; i++) {
                    if (d->entradas[i].estado != 1) continue;
                    PyObject *k = value_para_py(&d->entradas[i].chave);
                    PyObject *val = value_para_py(&d->entradas[i].valor);
                    if (!k || !val) { Py_XDECREF(k); Py_XDECREF(val); Py_DECREF(py); return NULL; }
                    int rc = PyDict_SetItem(py, k, val);
                    Py_DECREF(k); Py_DECREF(val);
                    if (rc != 0) { Py_DECREF(py); return NULL; }
                }
                return py;
            }
            Py_RETURN_NONE;
    }
    Py_RETURN_NONE;
}
#endif /* PS_MODULO_PYTHON */

static int val_truthy(const Value *v)
{
    switch (v->t) {
        case V_NULL:   return 0;
        case V_BOOL:   return v->as.b;
        case V_INT:    return v->as.i != 0;
        case V_FLOAT:  return v->as.d != 0.0;
        case V_FUNC:   return 1;
        case V_NATIVE: return 1;
        case V_TIPO:   return 1;
        case V_UNSET:  return 0;
        case V_OBJ:
            if (v->as.obj->type == OBJ_STRING || v->as.obj->type == OBJ_BYTES)
                return ((PSString *)v->as.obj)->len != 0;
            if (v->as.obj->type == OBJ_LIST || v->as.obj->type == OBJ_TUPLE)
                return ((PSList *)v->as.obj)->len != 0;
            if (v->as.obj->type == OBJ_DICT)   return ((PSDict *)v->as.obj)->count != 0;
            if (v->as.obj->type == OBJ_MANPU_RES) return ((PSManpuRes *)v->as.obj)->sucesso;
            /* ChannelStatus: `if send.status_send()` responde o sucesso */
            if (v->as.obj->type == OBJ_JCHST) return ((PSJChSt *)v->as.obj)->sucesso;
            return 1;   /* todo outro objeto (Entity, instância, método…) é verdadeiro */
    }
    return 0;
}

static int strings_iguais(const PSString *a, const PSString *b)
{
    if (a == b) return 1;
    if (a->len != b->len || a->hash != b->hash) return 0;   /* descarte barato */
    return memcmp(a->chars, b->chars, (size_t)a->len) == 0;
}

/* regra do spec: Null == 0 é True */
/* Profundidade da comparação: estruturas MUTUAMENTE recursivas (a contém b,
 * b contém a) faziam val_iguais descer pra sempre — segfault. O teto devolve
 * "diferente" em vez de derrubar o processo; comparação legítima nunca chega
 * perto de 256 níveis. */
#define PS_CMP_MAX 256
static int ps_prof_cmp = 0;

static int val_iguais(const Value *a, const Value *b)
{
    if (ps_prof_cmp > PS_CMP_MAX) return 0;
    /* Null só é igual a Null.
     *
     * Até 28/08 `null == 0`, `null == 0.0` e `null == false` eram TRUE, e o
     * comentário aqui defendia isso pela transitividade interna. O custo real
     * era outro: `if x == 0` entrava com `x` valendo Null, e todo teste escrito
     * como `if os.cmd(...) != 0` virava falso verde permanente — porque
     * `Null != 0` era False e a condição nunca disparava. Isso já escondeu
     * defeito na própria suíte deste repositório.
     *
     * `V_UNSET` (slot declarado e nunca escrito) conta como Null, que é o que o
     * `type()` já dizia. */
    int a_nulo = (a->t == V_NULL || a->t == V_UNSET);
    int b_nulo = (b->t == V_NULL || b->t == V_UNSET);
    if (a_nulo || b_nulo) return a_nulo && b_nulo;
    if (EH_STRING(*a) && EH_STRING(*b))
        return strings_iguais(COMO_STRING(*a), COMO_STRING(*b));
    /* bytes só é igual a bytes: `"ab" == "ab".encode()` é falso
     * — são conteúdos iguais de tipos diferentes. */
    if (EH_BYTES(*a) && EH_BYTES(*b))
        return strings_iguais(COMO_BYTES(*a), COMO_BYTES(*b));
    if (a->t == V_INT && b->t == V_INT)   return a->as.i == b->as.i;
    if (a->t == V_BOOL && b->t == V_BOOL) return a->as.b == b->as.b;
    if (EH_BIGINT(*a) || EH_BIGINT(*b)) {
        if (EH_BIGINT(*a) && EH_BIGINT(*b))
            return mpz_cmp(COMO_BIGINT(*a)->v, COMO_BIGINT(*b)->v) == 0;
        if (a->t == V_FLOAT || b->t == V_FLOAT)   /* bignum vs float: aproximado */
            return int_como_double(EH_BIGINT(*a) ? *a : *b)
                   == (a->t == V_FLOAT ? a->as.d : b->as.d);
        return 0;   /* bignum vs int64/bool: nunca igual (fora do alcance do int64) */
    }
    /* ManpuResult == true/false compara o sucesso; == "texto" compara status */
    if (EH_MANPURES(*a) || EH_MANPURES(*b)) {
        const Value *mr = EH_MANPURES(*a) ? a : b, *o = EH_MANPURES(*a) ? b : a;
        PSManpuRes *r = COMO_MANPURES(*mr);
        if (o->t == V_BOOL) return r->sucesso == o->as.b;
        if (EH_STRING(*o)) return strcmp(r->status, COMO_STRING(*o)->chars) == 0;
        return 0;
    }
    /* ChannelStatus do jinker: `== "Success"` / `== "Error"` — só esses dois
     * textos respondem algo; o resto é False, como o __eq__ do wrapper. */
    if (EH_JCHST(*a) || EH_JCHST(*b)) {
        const Value *cs = EH_JCHST(*a) ? a : b, *o = EH_JCHST(*a) ? b : a;
        PSJChSt *st = COMO_JCHST(*cs);
        if (EH_STRING(*o)) {
            if (strcmp(COMO_STRING(*o)->chars, "Success") == 0) return st->sucesso;
            if (strcmp(COMO_STRING(*o)->chars, "Error") == 0)   return !st->sucesso;
            return 0;
        }
        if (EH_JCHST(*o)) return st->sucesso == COMO_JCHST(*o)->sucesso;
        return 0;
    }
    /* `data == Usuario` valida o dict contra o model, dos dois lados */
    if (EH_MODEL(*b)) return model_valida(COMO_MODEL(*b), a);
    if (EH_MODEL(*a)) return model_valida(COMO_MODEL(*a), b);
    /* duas referências ao mesmo tipo são o mesmo valor — `str == str` */
    if (a->t == V_TIPO && b->t == V_TIPO) return a->as.i == b->as.i;
    /* `type(x)` devolve o NOME do tipo em texto, e a referência de tipo IMPRIME
     * esse mesmo nome. Sem esta ponte, `type(200) == int` seria falso enquanto
     * os dois lados escrevem "int" na tela — mentira calada, do tipo que faz o
     * `if` inteiro nunca entrar sem dar erro nenhum. Aqui os dois se encontram
     * pelo nome. (A forma canônica de testar tipo continua sendo `x is int`.) */
    if (a->t == V_TIPO && EH_STRING(*b)) {
        PSString *s = COMO_STRING(*b);
        return strcmp(s->chars, tipo_nome(a->as.i)) == 0;
    }
    if (b->t == V_TIPO && EH_STRING(*a)) {
        PSString *s = COMO_STRING(*a);
        return strcmp(s->chars, tipo_nome(b->as.i)) == 0;
    }
    if (a->t == V_TIPO || b->t == V_TIPO) return 0;
    /* int/float/bool se comparam por valor numérico — bool é subtipo de int
     * (true==1, false==0), como no interpretador. int==int e bool==bool já
     * saíram acima; aqui é sempre mistura. */
    if ((a->t == V_INT || a->t == V_FLOAT || a->t == V_BOOL) &&
        (b->t == V_INT || b->t == V_FLOAT || b->t == V_BOOL)) {
        double x = (a->t == V_FLOAT) ? a->as.d : (double)(a->t == V_BOOL ? a->as.b : a->as.i);
        double y = (b->t == V_FLOAT) ? b->as.d : (double)(b->t == V_BOOL ? b->as.b : b->as.i);
        return x == y;
    }
    if (EH_SEQ(*a) && EH_SEQ(*b) && a->as.obj->type == b->as.obj->type) {
        PSList *x = COMO_LIST(*a), *y = COMO_LIST(*b);
        if (x == y) return 1;
        if (x->len != y->len) return 0;
        for (int i = 0; i < x->len; i++) {
            ps_prof_cmp++;
            int ig = val_iguais(&x->itens[i], &y->itens[i]);
            ps_prof_cmp--;
            if (!ig) return 0;
        }
        return 1;
    }
    /* dicts: igualdade ESTRUTURAL, como as listas acima e como o interp —
     * mesmas chaves com mesmos valores, independente da ordem de inserção. */
    if (EH_DICT(*a) && EH_DICT(*b)) {
        PSDict *x = COMO_DICT(*a), *y = COMO_DICT(*b);
        if (x == y) return 1;
        if (x->count != y->count) return 0;
        for (int k = 0; k < x->usados; k++) {
            if (x->entradas[k].estado != 1) continue;
            Value vy;
            if (dict_get(y, &x->entradas[k].chave, &vy) != 0) return 0;   /* chave só em x */
            ps_prof_cmp++;
            { int ig = val_iguais(&x->entradas[k].valor, &vy);
              ps_prof_cmp--;
              if (!ig) return 0; }
        }
        return 1;
    }
    /* Funct é igual a si mesma. `V_FUNC` e `V_NATIVE` não são `V_OBJ` — o
     * valor carrega o índice do proto/builtin, não um ponteiro — então os dois
     * caíam no `return 0` lá embaixo e `f == f` respondia False. Comparar por
     * identidade é o mesmo critério do objeto: `f = nom` e `g = nom` apontam
     * pra mesma funct, logo são iguais; duas lambdas escritas separadas não.
     * (`hash_valor` já lê os mesmos bits, então funct como chave de dict
     * continua batendo com a igualdade.) */
    if (a->t == V_FUNC   && b->t == V_FUNC)   return a->as.proto  == b->as.proto;
    if (a->t == V_NATIVE && b->t == V_NATIVE) return a->as.nativa == b->as.nativa;
    if (a->t == V_OBJ && b->t == V_OBJ) return a->as.obj == b->as.obj;
    return 0;
}

/* ── impressão nativa ───────────────────────────────────────────────────── */
/* Float: a MENOR representação que volta ao mesmo
 * double. `%.17g` sempre roundtrippa mas escreve lixo — 1/3 vira
 * "0.33333333333333331" em vez de "0.3333333333333333".
 *
 * Depois, a regra do `repr`: se o resultado não tem '.' nem expoente, cola
 * ".0". É o que faz `4.0` não virar `4` e distingue float de int na saída. */
static int float_para_texto(char *buf, size_t cap, double d)
{
    if (isnan(d)) return snprintf(buf, cap, "nan");
    if (isinf(d)) return snprintf(buf, cap, d < 0 ? "-inf" : "inf");

    /* 1) menor quantidade de dígitos significativos que volta ao mesmo
     *    double. `%e` (não `%g`) porque aqui só interessa contar dígitos. */
    int p;
    for (p = 1; p <= 17; p++) {
        snprintf(buf, cap, "%.*e", p - 1, d);
        if (strtod(buf, NULL) == d) break;
    }
    if (p > 17) p = 17;

    /* 2) fixo ou exponencial — pelo EXPOENTE, não pela precisão.
     *    `%g` decide por precisão, e por isso 150.0 virava "1.5e+02": com 2
     *    dígitos significativos ele já acha que o número é grande. Aqui a
     *    exponencial só entra fora de [-4, 16). */
    const char *e = strchr(buf, 'e');
    int expo = e ? atoi(e + 1) : 0;
    int n;
    if (expo < -4 || expo >= 16) {
        n = snprintf(buf, cap, "%.*e", p - 1, d);
    } else {
        int casas = p - 1 - expo;
        if (casas < 0) casas = 0;
        n = snprintf(buf, cap, "%.*f", casas, d);
    }

    /* 3) regra do repr: sem '.' nem expoente, cola ".0" — é o que faz `4.0`
     *    não virar `4` e distingue float de int na saída. */
    for (const char *q = buf; *q; q++)
        if (*q == '.' || *q == 'e' || *q == 'E') return n;
    if ((size_t)n + 3 <= cap) { buf[n++] = '.'; buf[n++] = '0'; buf[n] = '\0'; }
    return n;
}

/* `eh_valor` = o membro é resolvido no ACESSO, não na chamada: `sys.argv` é
 * uma lista e `sys.stdout` é um namespace, não funções que devolvem isso. */
/* `params` lista os nomes dos parâmetros, separados por vírgula, na ordem —
 * é o que permite `regex.sub(..., count=2)`. NULL quer dizer "não aceita
 * nome", que é o certo pra membro só posicional. */
typedef struct { const char *nome; FnNativa fn; int eh_valor; const char *params; } MembroMod;
typedef struct { const char *nome; const MembroMod *membros; int n; } ModuloNat;

/* Tamanho do NOME dentro de um segmento de `params`. A string aceita
 * `nome=default` ("timeout=30") pra o motor ser a fonte da assinatura
 * completa — o casamento de argumento nomeado tem que parar no '='. */
static size_t par_nome_tam(const char *seg, size_t tam)
{
    for (size_t i = 0; i < tam; i++) if (seg[i] == '=') return i;
    return tam;
}

static const ModuloNat MODULOS[];

/* A VM em execução. Existe só pra `escreve_valor` conseguir o NOME do
 * protótipo ao imprimir um gerador — a assinatura dele não recebe a VM, e
 * mudá-la mexeria em dezenas de chamadas por causa de um caso. Único
 * escritor, execução single-threaded. */
static VM *vm_corrente = NULL;

/* Estrutura que se contém (`l.append(l)`) fazia a recursão descer até estourar
 * a pilha do C — SEGFAULT, sem mensagem nenhuma. O container que já está sendo
 * impresso vira `[...]`.
 *
 * O CICLO SOZINHO NÃO BASTA, e a versão anterior deste comentário dizia
 * escolher detectá-lo "em vez de um teto de profundidade". Isso deixava dois
 * alçapões, os dois com repro:
 *
 *   1. profundidade sem ciclo — `x = [x]` cem mil vezes e `str(x)` mata o
 *      processo. Não há ciclo pra detectar: a estrutura é uma corrente;
 *   2. ciclo que fecha ACIMA de 256 — o vetor só registra os 256 primeiros
 *      níveis (`if (ps_prof_texto < PS_CICLO_MAX)`), mas o contador continua
 *      subindo. Um ciclo fechando na profundidade 300 simplesmente não existe
 *      para o detector.
 *
 * Os dois somem com o TETO no mesmo lugar: passou de `PS_CICLO_MAX` níveis,
 * para de descer e imprime `[...]`, exatamente como faria num ciclo. Como os
 * três pontos de recursão já consultavam esta função antes de descer, o teto
 * vale em todos sem tocar em nenhum.
 *
 * CONTAR NÍVEL NÃO MEDE PILHA, e isto aqui é a prova: com `-O0 --coverage` o
 * quadro de `escreve_valor` fica várias vezes maior que no `-O2`, e a MESMA
 * profundidade de 300 que sobra folgada no binário de release estourava a
 * pilha da fibra no binário instrumentado — o servidor morria e a medição de
 * cobertura ficava travada em 14,9% sem ninguém entender por quê.
 *
 * Um número fixo ou está apertado demais pra um build ou frouxo demais pro
 * outro. O que decide é a FOLGA QUE SOBRA, então é isso que se mede:
 * `ps_pilha_apertada()` compara o endereço de um local com a base registrada
 * na entrada (`ps_pilha_marca`) e para quando falta menos que a margem.
 *
 * O vetor de visitados continua existindo pelo que ele faz de verdade —
 * detectar CICLO (`l.append(l)` vira `[...]`). Ele não é mais
 * teto: um ciclo que fecha acima de `PS_CICLO_MAX` níveis é pego pela folga de
 * pilha, não por uma contagem que responde "é ciclo" pra estrutura que não é.
 *
 * Estrutura legítima de 300, 1000 ou 5000 níveis agora IMPRIME. */
#define PS_CICLO_MAX 256
static const void *ps_pilha_texto[PS_CICLO_MAX];
static int ps_prof_texto = 0;

/* 1 = PARE de descer aqui: ou este objeto já está no caminho (CICLO), ou a
 * pilha está no fim. Quem chama imprime `[...]` nos dois casos. */
static int ps_em_ciclo(const void *o)
{
    if (ps_pilha_apertada()) return 1;
    int n = ps_prof_texto < PS_CICLO_MAX ? ps_prof_texto : PS_CICLO_MAX;
    for (int i = 0; i < n; i++) if (ps_pilha_texto[i] == o) return 1;
    return 0;
}


/* Descrição de UMA LINHA dos objetos "opacos" (os que não têm conteúdo
 * navegável: arquivo, conexão, servidor, socket, registrar...).
 *
 * Existe pra `post(x)` e `str(x)` não divergirem. Eram dois caminhos
 * independentes — `escreve_valor` (que imprime) e `valor_para_texto` (que
 * monta string) — e o segundo não conhecia 33 dos tipos: `post(conn)` mostrava
 * `<sqlite3.Connection>` e `str(conn)` devolvia STRING VAZIA. Agora os dois
 * leem daqui, então não tem como um saber e o outro não.
 *
 * Devolve 1 se escreveu em `buf`, 0 se o tipo não é destes. */
static int descreve_obj(const Value *v, char *buf, size_t cap)
{
    if (v->t != V_OBJ) return 0;
    switch (v->as.obj->type) {
        case OBJ_GERADOR:
            snprintf(buf, cap, "<generator %s>",
                     vm_corrente && ((PSGerador *)v->as.obj)->proto < vm_corrente->nprotos
                     ? vm_corrente->protos[((PSGerador *)v->as.obj)->proto].nome : "?");
            return 1;
        case OBJ_ARQUIVO:
            /* o caminho pode ser longo: %.200s pra não estourar o buffer */
            snprintf(buf, cap, "<arquivo %.200s>", ((PSArquivo *)v->as.obj)->caminho);
            return 1;
        case OBJ_SQLCONN:   snprintf(buf, cap, "<sqlite3.Connection>"); return 1;
        case OBJ_SQLCUR:    snprintf(buf, cap, "<sqlite3.Cursor>");     return 1;
        case OBJ_MAILSRV:   snprintf(buf, cap, "<MailServer>");         return 1;
        case OBJ_MAILRD:    snprintf(buf, cap, "<MailReader>");         return 1;
        case OBJ_MAILMSG:   snprintf(buf, cap, "<MailMessage>");        return 1;
        case OBJ_JCORS:     snprintf(buf, cap, "<CorsConfig>");         return 1;
        case OBJ_JPROXY:    snprintf(buf, cap, "<jinker.request>");     return 1;
        case OBJ_NATIVA:    snprintf(buf, cap, "<builtin>");            return 1;
        case OBJ_METODO_NAT:snprintf(buf, cap, "<metodo>");             return 1;
        case OBJ_MONGOCONN: snprintf(buf, cap, "<db.connection [mongo]>"); return 1;
        case OBJ_MANPU_RES:
            snprintf(buf, cap, "%s", ((PSManpuRes *)v->as.obj)->status);
            return 1;
        case OBJ_JCHST:
            snprintf(buf, cap, "%s", ((PSJChSt *)v->as.obj)->sucesso ? "Success" : "Error");
            return 1;
        case OBJ_JINKER:
            snprintf(buf, cap, "<Jinker '%s'>", ((PSJinker *)v->as.obj)->nome);
            return 1;
        case OBJ_QRIMAGE:
            snprintf(buf, cap, "<QRImage '%s'>", ((PSQRImage *)v->as.obj)->nome);
            return 1;
        case OBJ_QRFILE: {
            PSQRFile *q = (PSQRFile *)v->as.obj;
            snprintf(buf, cap, "<QRCode '%s' %lld bytes>", q->nome, (long long)q->tamanho);
            return 1;
        }
        case OBJ_DBCONN: {
            static const char *DN[] = { "sqlite", "postgres", "mysql", "mssql" };
            snprintf(buf, cap, "<db.connection [%s]>", DN[((PSDbConexao *)v->as.obj)->drv]);
            return 1;
        }
        case OBJ_SOCKET: {
            PSSocket *sk = (PSSocket *)v->as.obj;
            if (sk->fd < 0) snprintf(buf, cap, "<socket fechado>");
            else snprintf(buf, cap, "<socket family=%d type=%d proto=%d fd=%d>",
                          sk->familia, sk->tipo, sk->proto, sk->fd);
            return 1;
        }
        case OBJ_JSOCKNS: {
            PSJSockNs *ns = (PSJSockNs *)v->as.obj;
            snprintf(buf, cap, "<SocketNamespace %s>",
                     EH_JINKER(ns->app) ? COMO_JINKER(ns->app)->nome : "?");
            return 1;
        }
        default: return 0;
    }
}

static void escreve_valor(const Value *v, int dentro);
static int fut_resolve(VM *vm, PSFuturo *fu);   /* async: resolve o future (def. junto do jinker) */

/* Repr de string ANINHADA (dentro de list/dict/tup):
 * aspas simples, `"` quando o texto tem `'` e não tem `"`, e controle escapado
 * (`\n`, `\t`, `\\`, `\xNN`). Antes o caractere de controle saía CRU, e um
 * `["a\tb"]` imprimia com uma tabulação de verdade no meio — o certo é
 * `['a\tb']`. Texto de topo (`post("a\tb")`) continua cru.
 *
 * UTF-8 passa inteiro: só ASCII de controle (< 0x20 e 0x7f) vira escape.
 * Devolve buffer malloc'd (NUL-terminado) ou NULL sem memória. */
static char *repr_str_dup(const char *s, int len)
{
    int tem_simples = 0, tem_duplas = 0;
    for (int i = 0; i < len; i++) {
        if (s[i] == '\'') tem_simples = 1;
        else if (s[i] == '"') tem_duplas = 1;
    }
    char aspa = (tem_simples && !tem_duplas) ? '"' : '\'';
    /* pior caso: todo byte vira \xNN (4) + as duas aspas + NUL */
    char *out = malloc((size_t)len * 4 + 3);
    if (!out) return NULL;
    int n = 0;
    out[n++] = aspa;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        if (c == (unsigned char)aspa || c == '\\') { out[n++] = '\\'; out[n++] = (char)c; }
        else if (c == '\n') { out[n++] = '\\'; out[n++] = 'n'; }
        else if (c == '\t') { out[n++] = '\\'; out[n++] = 't'; }
        else if (c == '\r') { out[n++] = '\\'; out[n++] = 'r'; }
        else if (c < 0x20 || c == 0x7f) n += sprintf(out + n, "\\x%02x", c);
        else out[n++] = (char)c;
    }
    out[n++] = aspa;
    out[n] = '\0';
    return out;
}

/* O repr de `bytes`: `b'...'`, com `\xNN` pra tudo que
 * não é ASCII imprimível.
 *
 * ESTAVA EM TRÊS CÓPIAS (escreve_valor, valor_para_texto e o ramo de dentro),
 * e as três erravam a mesma coisa: a aspa troca quando o conteúdo tem
 * `'` e não tem `"` — `b"a'b"`, não `b'a\'b'`. O repr de STRING deste mesmo
 * arquivo já fazia a regra certa (`repr_str_dup`, logo acima); o de bytes não,
 * e ninguém tinha percebido porque o gerador de oráculo pulava toda expressão
 * com `.encode()` alegando que "o repr de bytes difere por design". Não
 * difere: divergia por defeito.
 *
 * Uma cópia só, e o chamador libera. */
static char *repr_bytes_dup(const char *s, int len)
{
    int tem_simples = 0, tem_duplas = 0;
    for (int i = 0; i < len; i++) {
        if (s[i] == '\'') tem_simples = 1;
        else if (s[i] == '"') tem_duplas = 1;
    }
    char aspa = (tem_simples && !tem_duplas) ? '"' : '\'';
    /* pior caso: todo byte vira \xNN (4) + `b` + as duas aspas + NUL */
    char *out = malloc((size_t)len * 4 + 4);
    if (!out) return NULL;
    int n = 0;
    out[n++] = 'b';
    out[n++] = aspa;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        if (c == (unsigned char)aspa || c == '\\') { out[n++] = '\\'; out[n++] = (char)c; }
        else if (c == '\n') { out[n++] = '\\'; out[n++] = 'n'; }
        else if (c == '\r') { out[n++] = '\\'; out[n++] = 'r'; }
        else if (c == '\t') { out[n++] = '\\'; out[n++] = 't'; }
        else if (c >= 32 && c < 127) out[n++] = (char)c;
        else n += sprintf(out + n, "\\x%02x", c);
    }
    out[n++] = aspa;
    out[n] = '\0';
    return out;
}

static void escreve_valor(const Value *v, int dentro)
{
    {   /* objetos opacos: mesma descrição que o `str()` usa */
        char d[256];
        if (descreve_obj(v, d, sizeof(d))) { fputs(d, stdout); return; }
    }
    /* Mesma guarda de ciclo do valor_para_texto: `l.append(l)` descia até
     * estourar a pilha do C (segfault sem mensagem). Container que já está
     * sendo escrito vira `[...]`. */
    if (v->t == V_OBJ && (v->as.obj->type == OBJ_LIST || v->as.obj->type == OBJ_TUPLE
                          || v->as.obj->type == OBJ_DICT)) {
        if (ps_em_ciclo(v->as.obj)) {
            fputs(v->as.obj->type == OBJ_TUPLE ? "(...)"
                  : v->as.obj->type == OBJ_DICT ? "{...}" : "[...]", stdout);
            return;
        }
        if (ps_prof_texto < PS_CICLO_MAX) ps_pilha_texto[ps_prof_texto] = v->as.obj;
    }
    switch (v->t) {
        /* I22: `Null` com inicial maiuscula, como `True` e `False`. O
         * literal ja se escrevia assim e a impressao discordava dele. NAO
         * vale pro JSON: la `null` minusculo e a especificacao do formato,
         * e o serializador tem o caminho dele. */
        case V_NULL:   fputs("Null", stdout); break;
        case V_BOOL:   fputs(v->as.b ? "True" : "False", stdout); break;
        case V_INT:    printf("%lld", (long long)v->as.i); break;
        case V_FLOAT: {
            char fb[40];
            float_para_texto(fb, sizeof(fb), v->as.d);
            fputs(fb, stdout);
            break;
        }
        case V_FUNC:   printf("<funct #%d>", v->as.proto); break;
        case V_NATIVE: fputs("<builtin>", stdout); break;
        case V_TIPO:   fputs(tipo_nome(v->as.i), stdout); break;
        case V_UNSET:  fputs("Null", stdout); break;
        case V_OBJ:
            if (v->as.obj->type == OBJ_STRING) {
                PSString *s = (PSString *)v->as.obj;
                if (dentro) {
                    char *r = repr_str_dup(s->chars, s->len);
                    if (r) { fputs(r, stdout); free(r); }
                    else { putchar('\''); fwrite(s->chars, 1, (size_t)s->len, stdout); putchar('\''); }
                } else {
                    fwrite(s->chars, 1, (size_t)s->len, stdout);
                }
            } else if (v->as.obj->type == OBJ_BIGINT) {
                char *bs = bigint_str(((PSBigInt *)v->as.obj)->v);
                if (bs) { fputs(bs, stdout); free(bs); }
            } else if (v->as.obj->type == OBJ_LIST || v->as.obj->type == OBJ_TUPLE) {
                PSList *l = (PSList *)v->as.obj;
                int tupla = (v->as.obj->type == OBJ_TUPLE);
                putchar(tupla ? '(' : '[');
                for (int i = 0; i < l->len; i++) {
                    if (i) fputs(", ", stdout);
                    ps_prof_texto++; escreve_valor(&l->itens[i], 1); ps_prof_texto--;
                }
                /* tupla de 1 elemento imprime `(x,)` */
                if (tupla && l->len == 1) putchar(',');
                putchar(tupla ? ')' : ']');
            } else if (v->as.obj->type == OBJ_CLASS) {
                printf("<Entity %s>", ((PSClass *)v->as.obj)->nome);
            } else if (v->as.obj->type == OBJ_INSTANCE) {
                /* <Nome {campos}> — igual ao interp (campos como dict) */
                PSInstance *inst = (PSInstance *)v->as.obj;
                printf("<%s ", inst->classe->nome);
                if (inst->campos) {
                    Value dv = MK_OBJ((Obj *)inst->campos);
                    ps_prof_texto++; escreve_valor(&dv, 1); ps_prof_texto--;
                } else {
                    fputs("{}", stdout);
                }
                putchar('>');
            } else if (v->as.obj->type == OBJ_GERADOR) {
                printf("<generator %s>",
                       vm_corrente && ((PSGerador *)v->as.obj)->proto < vm_corrente->nprotos
                       ? vm_corrente->protos[((PSGerador *)v->as.obj)->proto].nome : "?");
            } else if (v->as.obj->type == OBJ_POOLFILE) {
                PSPoolFile *f = (PSPoolFile *)v->as.obj;
                printf("<PoolFile '%s' (%lld bytes)>", f->nome, (long long)f->tamanho);
            } else if (v->as.obj->type == OBJ_SQLCONN) {
                fputs("<sqlite3.Connection>", stdout);
            } else if (v->as.obj->type == OBJ_SQLCUR) {
                fputs("<sqlite3.Cursor>", stdout);
            } else if (v->as.obj->type == OBJ_MAILSRV) {
                fputs("<MailServer>", stdout);
            } else if (v->as.obj->type == OBJ_MAILMSG) {
                fputs("<MailMessage>", stdout);
            } else if (v->as.obj->type == OBJ_MAILRD) {
                fputs("<MailReader>", stdout);
            } else if (v->as.obj->type == OBJ_RESPONSE) {
                PSResponse *rp = (PSResponse *)v->as.obj;
                printf("<Response status=%ld url='%s' (%zu bytes)>", rp->status,
                       EH_STRING(rp->url) ? COMO_STRING(rp->url)->chars : "",
                       rp->nbytes);   /* o tamanho, sem trazer o corpo pra memória */
            } else if (v->as.obj->type == OBJ_QRFILE) {
                PSQRFile *q = (PSQRFile *)v->as.obj;
                printf("<QRCode '%s' %lld bytes>", q->nome, (long long)q->tamanho);
            } else if (v->as.obj->type == OBJ_MANPU_RES) {
                fputs(((PSManpuRes *)v->as.obj)->status, stdout);
            } else if (v->as.obj->type == OBJ_JINKER) {
                printf("<Jinker '%s'>", ((PSJinker *)v->as.obj)->nome);
            } else if (v->as.obj->type == OBJ_JCORS) {
                fputs("<CorsConfig>", stdout);
            } else if (v->as.obj->type == OBJ_JREG) {
                PSJReg *rg = (PSJReg *)v->as.obj;
                if (rg->kind == JREG_MIDDLEWARE) fputs("<MiddlewareRegistrar>", stdout);
                else if (rg->kind == JREG_SOCKET) printf("<SocketRegistrar %s>", rg->path);
                else {
                    /* mesmo formato do repr do wrapper: lista de métodos */
                    fputs("<RouteRegistrar [", stdout);
                    for (int i = 0; i < rg->nmetodos; i++)
                        printf("%s'%s'", i ? ", " : "", rg->metodos[i]);
                    printf("] %s>", rg->path);
                }
            } else if (v->as.obj->type == OBJ_JRESP) {
                fputs("<JinkerResponse>", stdout);
            } else if (v->as.obj->type == OBJ_JPROXY) {
                fputs("<jinker.request>", stdout);
            } else if (v->as.obj->type == OBJ_JUPLOAD) {
                PSJUpload *up = (PSJUpload *)v->as.obj;
                printf("<PoolFileUpload '%s' (%d bytes)>", up->nome,
                       EH_BYTES(up->dados) ? COMO_BYTES(up->dados)->len : 0);
            } else if (v->as.obj->type == OBJ_JSOCKNS) {
                PSJSockNs *ns = (PSJSockNs *)v->as.obj;
                printf("<SocketNamespace %s>",
                       EH_JINKER(ns->app) ? COMO_JINKER(ns->app)->nome : "?");
            } else if (v->as.obj->type == OBJ_JEMIT) {
                PSJEmit *em = (PSJEmit *)v->as.obj;
                printf("<SocketEmitter %s>",
                       EH_JINKER(em->app) ? COMO_JINKER(em->app)->nome : "?");
            } else if (v->as.obj->type == OBJ_JCHAN) {
                PSJChan *ch = (PSJChan *)v->as.obj;
                if (EH_JINKER(ch->app)) {
                    PSJinker *jk = COMO_JINKER(ch->app);
                    int salas = 0;
                    for (int i = 0; i < jk->nws; i++) {
                        if (!jk->ws[i].sala) continue;
                        int visto = 0;
                        for (int q = 0; q < i; q++)
                            if (jk->ws[q].sala && strcmp(jk->ws[q].sala, jk->ws[i].sala) == 0) { visto = 1; break; }
                        if (!visto) salas++;
                    }
                    printf("<Channel connections=%d rooms=%d>", jk->nws, salas);
                } else fputs("<Channel connections=0 rooms=0>", stdout);
            } else if (v->as.obj->type == OBJ_JCHST) {
                fputs(((PSJChSt *)v->as.obj)->sucesso ? "Success" : "Error", stdout);
            } else if (v->as.obj->type == OBJ_WSCONN) {
                PSWsConn *w = (PSWsConn *)v->as.obj;
                printf("<WsConnection %s [%s]>", w->url,
                       w->conn ? "conectado" : "desconectado");
            } else if (v->as.obj->type == OBJ_SOCKET) {
                PSSocket *sk = (PSSocket *)v->as.obj;
                if (sk->fd < 0) fputs("<socket fechado>", stdout);
                else printf("<socket family=%d type=%d proto=%d fd=%d>",
                            sk->familia, sk->tipo, sk->proto, sk->fd);
            } else if (v->as.obj->type == OBJ_QRBUILD) {
                fputs("<PoolQRCode>", stdout);
            } else if (v->as.obj->type == OBJ_QRIMAGE) {
                printf("<QRImage '%s'>", ((PSQRImage *)v->as.obj)->nome);
            } else if (v->as.obj->type == OBJ_MANPU_FILE) {
                const char *cam = ((PSManpuFile *)v->as.obj)->caminho;
                const char *barra = strrchr(cam, '/');
                printf("<ManpuFile %s>", barra ? barra + 1 : cam);
            } else if (v->as.obj->type == OBJ_DBCONN) {
                static const char *DN[]={"sqlite","postgres","mysql","mssql"};
                printf("<db.connection [%s]>", DN[((PSDbConexao *)v->as.obj)->drv]);
            } else if (v->as.obj->type == OBJ_DBCUR) {
                static const char *DN[]={"sqlite","postgres","mysql","mssql"};
                printf("<db.cursor [%s]>", DN[((PSDbCursor *)v->as.obj)->drv]);
            } else if (v->as.obj->type == OBJ_MONGOCONN) {
                fputs("<db.connection [mongo]>", stdout);
            } else if (v->as.obj->type == OBJ_MONGOCOL) {
                printf("<db.collection [%s]>", ((PSMongoCol *)v->as.obj)->nome);
            } else if (v->as.obj->type == OBJ_BYTES) {
                PSString *b = (PSString *)v->as.obj;
                char *r = repr_bytes_dup(b->chars, b->len);
                if (r) { fputs(r, stdout); free(r); }
            } else if (v->as.obj->type == OBJ_MODULO_PS) {
                printf("<modulo %s>", ((PSModuloPS *)v->as.obj)->nome);
            } else if (v->as.obj->type == OBJ_ARQUIVO) {
                printf("<arquivo %s>", ((PSArquivo *)v->as.obj)->caminho);
            } else if (v->as.obj->type == OBJ_MODEL) {
                printf("<model %s>", ((PSModel *)v->as.obj)->nome);
            } else if (v->as.obj->type == OBJ_ENUM) {
                printf("<enum %s>", ((PSEnum *)v->as.obj)->nome);
            } else if (v->as.obj->type == OBJ_MODULO) {
                {
                    /* módulo oculto sai sem o `_` de registro: o usuário
                     * escreveu `Parsing`, não `_Parsing` */
                    const char *nm = MODULOS[((PSModulo *)v->as.obj)->idx].nome;
                    if (nm[0] == '_') printf("<%s>", nm + 1);
                    else              printf("<modulo %s>", nm);
                }
            } else if (v->as.obj->type == OBJ_NATIVA) {
                fputs("<builtin>", stdout);
            } else if (v->as.obj->type == OBJ_FUTURO) {
                /* Future não resolvido: sem este ramo ele caía no fim da
                 * cadeia e imprimia NADA — `post([f1, f2])` saía `[, ]`. */
                fputs("<future>", stdout);
            } else if (v->as.obj->type == OBJ_BOUND
                    || v->as.obj->type == OBJ_METODO_NAT) {
                fputs("<metodo>", stdout);
            } else if (v->as.obj->type == OBJ_DICT) {
                PSDict *d = (PSDict *)v->as.obj;
                putchar('{');
                int n = 0;
                for (int i = 0; i < d->usados; i++) {
                    if (d->entradas[i].estado != 1) continue;
                    if (n++) fputs(", ", stdout);
                    ps_prof_texto++; escreve_valor(&d->entradas[i].chave, 1); ps_prof_texto--;
                    fputs(": ", stdout);
                    ps_prof_texto++; escreve_valor(&d->entradas[i].valor, 1); ps_prof_texto--;
                }
                putchar('}');
            }
            break;
    }
}

/* ── valor → texto (para interpolação) ──────────────────────────────────── */
/* Reusa exatamente as regras do `post` — null vira "null", 4.0 mantém o
 * ".0", string aninhada ganha aspas. Duplicar essa lógica faria a
 * interpolação divergir da impressão sem ninguém notar. */
typedef struct { char *b; int n; int cap; } TxtBuf;

/* TxtBuf TEMPORÁRIO com liberação automática na saída do escopo — mesma regra
 * do SBUF_AUTO (ver o comentário lá): só pra buffer local cuja posse nunca sai
 * da função; se transferir, zere t.b logo após. */
static void txt_solta_auto(TxtBuf *t) { free(t->b); }
#define TXTBUF_AUTO __attribute__((cleanup(txt_solta_auto))) TxtBuf

static int txt_put(TxtBuf *t, const char *s, int n)
{
    if (t->n + n + 1 > t->cap) {
        int novo = t->cap < 64 ? 64 : t->cap;
        while (t->n + n + 1 > novo) novo *= 2;
        char *p = realloc(t->b, (size_t)novo);
        if (!p) return -1;
        t->b = p; t->cap = novo;
    }
    memcpy(t->b + t->n, s, (size_t)n);
    t->n += n;
    t->b[t->n] = '\0';
    return 0;
}

static int valor_para_texto(TxtBuf *t, const Value *v, int dentro)
{
    {   /* objetos opacos: a MESMA descrição que o `post()` imprime. Sem isto,
         * `str(conn)` devolvia string vazia enquanto `post(conn)` mostrava
         * `<sqlite3.Connection>` — 33 tipos caíam nesse silêncio. */
        char d[256];
        if (descreve_obj(v, d, sizeof(d))) return txt_put(t, d, (int)strlen(d));
    }
    char tmp[64];
    if (!dentro) ps_prof_texto = 0;   /* topo: zera a pilha de ciclo */
    switch (v->t) {
        case V_NULL:   return txt_put(t, "Null", 4);
        case V_BOOL:   return v->as.b ? txt_put(t, "True", 4) : txt_put(t, "False", 5);
        case V_INT:    return txt_put(t, tmp, snprintf(tmp, sizeof(tmp), "%lld", (long long)v->as.i));
        case V_FLOAT:
            return txt_put(t, tmp, float_para_texto(tmp, sizeof(tmp), v->as.d));
        case V_FUNC:   return txt_put(t, tmp, snprintf(tmp, sizeof(tmp), "<funct #%d>", v->as.proto));
        case V_NATIVE: return txt_put(t, "<builtin>", 9);
        case V_TIPO:   return txt_put(t, tipo_nome(v->as.i), (int)strlen(tipo_nome(v->as.i)));
        case V_UNSET:  return txt_put(t, "Null", 4);
        case V_OBJ:
            if (v->as.obj->type == OBJ_BIGINT) {
                char *bs = bigint_str(((PSBigInt *)v->as.obj)->v);
                if (!bs) return -1;
                int rc = txt_put(t, bs, (int)strlen(bs));
                free(bs);
                return rc;
            }
            if (v->as.obj->type == OBJ_BYTES) {
                /* mesmo repr do `escreve_valor`; sem isto `str(b)` saía vazio */
                PSString *b = (PSString *)v->as.obj;
                char *r = repr_bytes_dup(b->chars, b->len);
                if (!r) return -1;
                int rc = txt_put(t, r, (int)strlen(r));
                free(r);
                return rc;
            }
            if (v->as.obj->type == OBJ_STRING) {
                PSString *st = (PSString *)v->as.obj;
                if (!dentro) return txt_put(t, st->chars, st->len);
                char *r = repr_str_dup(st->chars, st->len);
                if (!r) return -1;
                int rc = txt_put(t, r, (int)strlen(r));
                free(r);
                return rc;
            }
            if (v->as.obj->type == OBJ_LIST || v->as.obj->type == OBJ_TUPLE) {
                PSList *l = (PSList *)v->as.obj;
                int tup = (v->as.obj->type == OBJ_TUPLE);
                /* já estou imprimindo este container -> ciclo */
                if (ps_em_ciclo(v->as.obj))
                    return txt_put(t, tup ? "(...)" : "[...]", 5);
                if (ps_prof_texto < PS_CICLO_MAX) ps_pilha_texto[ps_prof_texto] = v->as.obj;
                if (txt_put(t, tup ? "(" : "[", 1) != 0) return -1;
                for (int i = 0; i < l->len; i++) {
                    if (i && txt_put(t, ", ", 2) != 0) return -1;
                    ps_prof_texto++;
                    { int rc_i = valor_para_texto(t, &l->itens[i], 1);
                      ps_prof_texto--;
                      if (rc_i != 0) return -1; }
                }
                if (tup && l->len == 1 && txt_put(t, ",", 1) != 0) return -1;
                return txt_put(t, tup ? ")" : "]", 1);
            }
            if (v->as.obj->type == OBJ_CLASS)
                return txt_put(t, tmp, snprintf(tmp, sizeof(tmp), "<Entity %s>",
                                                ((PSClass *)v->as.obj)->nome));
            if (v->as.obj->type == OBJ_INSTANCE) {
                /* <Nome {campos}> — igual ao interp */
                PSInstance *inst = (PSInstance *)v->as.obj;
                if (txt_put(t, "<", 1) != 0) return -1;
                if (txt_put(t, inst->classe->nome, (int)strlen(inst->classe->nome)) != 0) return -1;
                if (txt_put(t, " ", 1) != 0) return -1;
                if (inst->campos) {
                    Value dv = MK_OBJ((Obj *)inst->campos);
                    ps_prof_texto++;
                    { int rc_i = valor_para_texto(t, &dv, 1);
                      ps_prof_texto--;
                      if (rc_i != 0) return -1; }
                } else {
                    if (txt_put(t, "{}", 2) != 0) return -1;
                }
                return txt_put(t, ">", 1);
            }
            if (v->as.obj->type == OBJ_FUTURO) return txt_put(t, "<future>", 8);
            if (v->as.obj->type == OBJ_BOUND) return txt_put(t, "<metodo>", 8);
            if (v->as.obj->type == OBJ_BYTES) {
                /* mesmo repr do `escreve_valor`; sem isto `str(b)` saía vazio */
                PSString *b = (PSString *)v->as.obj;
                char *r = repr_bytes_dup(b->chars, b->len);
                if (!r) return -1;
                int rc = txt_put(t, r, (int)strlen(r));
                free(r);
                return rc;
            }
            if (v->as.obj->type == OBJ_DICT) {
                PSDict *d = (PSDict *)v->as.obj;
                if (ps_em_ciclo(v->as.obj)) return txt_put(t, "{...}", 5);
                if (ps_prof_texto < PS_CICLO_MAX) ps_pilha_texto[ps_prof_texto] = v->as.obj;
                if (txt_put(t, "{", 1) != 0) return -1;
                int k = 0;
                for (int i = 0; i < d->usados; i++) {
                    if (d->entradas[i].estado != 1) continue;
                    if (k++ && txt_put(t, ", ", 2) != 0) return -1;
                    ps_prof_texto++;
                    { int rc_k = valor_para_texto(t, &d->entradas[i].chave, 1);
                      ps_prof_texto--;
                      if (rc_k != 0) return -1; }
                    if (txt_put(t, ": ", 2) != 0) return -1;
                    ps_prof_texto++;
                    { int rc_v = valor_para_texto(t, &d->entradas[i].valor, 1);
                      ps_prof_texto--;
                      if (rc_v != 0) return -1; }
                }
                return txt_put(t, "}", 1);
            }
            /* ChannelStatus vira "Success"/"Error" também em str()/f-string */
            if (v->as.obj->type == OBJ_JCHST) {
                const char *st = ((PSJChSt *)v->as.obj)->sucesso ? "Success" : "Error";
                return txt_put(t, st, (int)strlen(st));
            }
            if (v->as.obj->type == OBJ_JPROXY)
                return txt_put(t, "<jinker.request>", 16);
            if (v->as.obj->type == OBJ_ENUM) {
                char buf[300];
                const char *nm = ((PSEnum *)v->as.obj)->nome;
                int nn = snprintf(buf, sizeof(buf), "<enum %s>", nm ? nm : "?");
                /* o retorno é o que TERIA cabido: com nome gigante, o txt_put
                 * leria além do buf */
                if (nn < 0) nn = 0;
                if (nn >= (int)sizeof(buf)) nn = (int)sizeof(buf) - 1;
                return txt_put(t, buf, nn);
            }
            return 0;
    }
    return 0;
}

/* ── builtins nativos ───────────────────────────────────────────────────── */
static int nativa_post(VM *vm, Value *args, int n, Value *out)
{
    /* `post()` sem argumento nenhum não imprime nada — nem a quebra de linha.
     * Quem quer linha em branco escreve `post("")`. */
    if (n == 0) { *out = MK_NULL(); return 0; }
    for (int i = 0; i < n; i++) {
        if (i) putchar(' ');
        Value v = args[i];
        if (EH_FUTURO(v)) {   /* async: resolve e mostra o VALOR (paridade com o interp) */
            PSFuturo *fu = COMO_FUTURO(v);
            if (fut_resolve(vm, fu) != 0) return -1;
            v = fu->valor;
        }
        /* Começa SEMPRE do zero: a pilha de ciclo é global e um resto de
         * chamada anterior fazia um container inocente casar com endereço
         * velho e sair impresso como `[...]`. */
        ps_prof_texto = 0;
        escreve_valor(&v, 0);
        ps_prof_texto = 0;
    }
    putchar('\n');
    *out = MK_NULL();
    return 0;
}

/* definido adiante; vários builtins acima dele montam mensagem com o tipo */
static const char *nome_do_tipo_valor(Value v);

/* definido adiante; o len é o primeiro builtin e já precisa dele */
static int erro_aridade(VM *vm, const char *nome, int minimo, int maximo, int n);

static int nativa_len(VM *vm, Value *args, int n, Value *out)
{
    /* mesma redação de todo mundo agora — o `erro_aridade` produz exatamente
     * este texto, então não há motivo pra este sítio ter cópia própria */
    if (n != 1) return erro_aridade(vm, "len", 1, 1, n);
    Value v = args[0];
    if (v.t == V_NULL) { *out = MK_INT(0); return 0; }   /* len(null) = 0, como o interp */
    /* string conta CARACTERES (codepoints), como o método s.len() e o
     * interpretador — contar bytes fazia len("olá") responder 4 */
    if (EH_STRING(v)) { *out = MK_INT(utf8_conta(COMO_STRING(v)->chars, COMO_STRING(v)->len)); return 0; }
    if (EH_BYTES(v))  { *out = MK_INT(COMO_BYTES(v)->len); return 0; }
    if (EH_SEQ(v))    { *out = MK_INT(COMO_LIST(v)->len);   return 0; }
    if (EH_DICT(v))   { *out = MK_INT(COMO_DICT(v)->count); return 0; }
    snprintf(vm->erro, sizeof(vm->erro), "object of type '%s' has no len()",
             nome_do_tipo_valor(v));
    snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
    return -1;
}


/* AS MENSAGENS DE `sem memoria` FICAM EM PORTUGUÊS, E É DE PROPÓSITO.
 *
 * A regra desta base é usar a frase padrão em inglês de cada erro. O
 * `MemoryError` é a exceção, e a razão é simples: a frase padrão dele é vazia —
 * `MemoryError:` e mais nada. As 79 daqui dizem ONDE a memória acabou
 * (`sem memoria em sorted()`, `sem memoria na concatenacao`), e num processo
 * que morreu de memória essa é a única pista que sobra.
 *
 * Deixar vazio aqui trocaria informação real por uma linha vazia. Se uma
 * varredura futura apontar estas 79 como "ainda em português", ela está
 * medindo a coisa errada — a pergunta não é se o texto segue o padrão, é
 * se ele ajuda quem lê.
 */

/* Argumento POSICIONAL onde o método só aceita nomeado. Frase padrão pra
 * parâmetro keyword-only. */
#define ERRO_ARIDADE_POS(vm, nome, n) do { \
    snprintf((vm)->erro, sizeof((vm)->erro), \
             "%s() takes 0 positional arguments but %d %s given", \
             (nome), (n), (n) == 1 ? "was" : "were"); \
    snprintf((vm)->erro_tipo, sizeof((vm)->erro_tipo), "TypeError"); \
    return -1; \
} while (0)

/* Erro de builtin: mensagem + tipo, no mesmo formato do resto da VM. */
#define BERRO(vm, tipo, ...) do { \
    snprintf((vm)->erro, sizeof((vm)->erro), __VA_ARGS__); \
    snprintf((vm)->erro_tipo, sizeof((vm)->erro_tipo), "%s", (tipo)); \
    return -1; \
} while (0)

/* Falha de SISTEMA (errno) → o par (tipo, mensagem).
 *
 * A taxonomia: cada errno frequente tem a SUA subclasse de
 * OSError e o resto cai no OSError puro. A mensagem é
 * `[Errno N] strerror: 'caminho'`, e `'a' -> 'b'` quando a
 * chamada tem dois caminhos (rename). `strerror` sai em inglês porque a VM
 * não chama setlocale(LC_MESSAGES).
 *
 * Antes TODO erro de sistema do módulo `os` saía como `TypeError` com texto em
 * português: `nao consegui criar '/tmp/x'`. Ninguém escreve
 * `catch (TypeError)` pra pasta já existente — e quem escrevesse pegava junto
 * `1 + "a"`, `len(5)` e aridade errada. */
/* ── HIERARQUIA DE EXCEÇÕES: a única lista ────────────────────────────────
 *
 * O tipo de uma exceção era uma string solta, digitada à mão em cada um dos
 * ~1000 sítios de erro, e o `catch` comparava os dois nomes por IGUALDADE
 * LITERAL. Duas consequências medidas no binário:
 *
 *   catch (Exception e)  não pegava NADA — nem erro de arquivo, nem
 *                        `1 + "a"`, nem um `raise ValueError` explícito
 *   catch (OSError e)    não pegava FileNotFoundError
 *
 * e o motor gera esses nomes de subclasse DE PROPÓSITO: `tipo_do_errno`
 * logo abaixo devolve `FileNotFoundError`, `PermissionError`,
 * `IsADirectoryError`. Nomes que só fazem sentido se o pai os pegasse.
 *
 * Aqui cada exceção é UMA LINHA: o nome e o PAI. `Exception` é a raiz e tem
 * pai NULL. Quem pergunta "este catch pega este erro?" chama `excecao_eh()`,
 * que sobe a cadeia — não existe um segundo lugar com a mesma resposta.
 *
 * Tipo levantado que NÃO estiver nesta tabela continua sendo pego pelo
 * `catch` do próprio nome e pelo `catch (e)` sem tipo: ninguém perde captura
 * que já tinha. A tabela só ACRESCENTA os pais que faltavam. */
typedef struct { const char *nome; const char *pai; } ExcLinha;

static const ExcLinha EXCECOES[] = {
    { "Exception",            NULL },

    /* erro de sistema — os nomes que `tipo_do_errno` já emitia */
    { "OSError",              "Exception" },
    { "FileExistsError",      "OSError" },
    { "FileNotFoundError",    "OSError" },
    { "IsADirectoryError",    "OSError" },
    { "NotADirectoryError",   "OSError" },
    { "PermissionError",      "OSError" },
    { "NetworkError",         "OSError" },
    /* `IOError` fica IRMÃO de OSError, não pai nem filho: a doc do `open()`
     * promete, com teste, que `catch (IOError e)` NÃO pega FileNotFoundError.
     * Pendurar um no outro mudaria comportamento documentado. */
    { "IOError",              "Exception" },

    { "LookupError",          "Exception" },
    { "IndexError",           "LookupError" },
    { "KeyError",             "LookupError" },

    { "ArithmeticError",      "Exception" },
    { "ZeroDivisionError",    "ArithmeticError" },
    { "OverflowError",        "ArithmeticError" },

    { "ValueError",           "Exception" },
    { "UnicodeError",         "ValueError" },
    { "UnicodeDecodeError",   "UnicodeError" },
    { "UnicodeEncodeError",   "UnicodeError" },
    { "AttributedValueError", "ValueError" },
    { "ConversionError",      "ValueError" },

    { "RuntimeError",         "Exception" },
    { "RecursionError",       "RuntimeError" },

    { "TypeError",            "Exception" },
    { "AttributeError",       "Exception" },
    { "NameError",            "Exception" },
    { "ImportError",          "Exception" },
    { "MemoryError",          "Exception" },
    { "AssertionError",       "Exception" },
    { "SyntaxError",          "Exception" },
    { "NotImplementedError",  "RuntimeError" },
    { "TimeoutError",         "OSError" },
    { "DatabaseError",        "Exception" },
};
#define N_EXCECOES ((int64_t)(sizeof(EXCECOES) / sizeof(EXCECOES[0])))

static int tipo_eh_excecao(int64_t t)
{
    return t >= TIPO_EXC_BASE && t < TIPO_EXC_BASE + N_EXCECOES;
}

/* posição do nome em EXCECOES[], ou -1: é o que liga o global `ValueError` */
static int64_t excecao_indice(const char *nome)
{
    for (int64_t k = 0; k < N_EXCECOES; k++)
        if (strcmp(EXCECOES[k].nome, nome) == 0) return k;
    return -1;
}

static const char *excecao_pai(const char *nome)
{
    if (!nome) return NULL;
    for (size_t i = 0; i < sizeof(EXCECOES) / sizeof(EXCECOES[0]); i++)
        if (strcmp(EXCECOES[i].nome, nome) == 0) return EXCECOES[i].pai;
    /* Os 251 nomes de erro do postgres vivem na tabela SQLSTATE de
     * `ps_pgerr.h` e todos são `DatabaseError`. Perguntar a ela é o que evita
     * uma segunda cópia da lista aqui — e sem esta linha `catch (DatabaseError
     * e)` não pegava `UniqueViolation`, enquanto a MESMA violação de UNIQUE no
     * sqlite já dava `DatabaseError`: o tipo mudava conforme o driver. */
    if (ps_db_eh_nome_erro(nome)) return "DatabaseError";
    return NULL;   /* fora da tabela: só casa pelo próprio nome */
}

/* `catch (pedido e)` pega um erro do tipo `levantado`? Sobe a cadeia de pais.
 * O limite de voltas é a própria tabela: ciclo escrito por engano para, em vez
 * de pendurar a VM. */
static int excecao_eh(const char *levantado, const char *pedido)
{
    if (!levantado || !pedido) return 0;
    size_t teto = sizeof(EXCECOES) / sizeof(EXCECOES[0]) + 1;
    for (const char *t = levantado; t && teto--; t = excecao_pai(t))
        if (strcmp(t, pedido) == 0) return 1;
    return 0;
}

static const char *tipo_do_errno(int e)
{
    switch (e) {
        case EEXIST:  return "FileExistsError";
        case ENOENT:  return "FileNotFoundError";
        case EISDIR:  return "IsADirectoryError";
        case ENOTDIR: return "NotADirectoryError";
        case EACCES:
        case EPERM:   return "PermissionError";
        default:      return "OSError";
    }
}

static int erro_sistema(VM *vm, int e, const char *cam, const char *cam2)
{
    /* As precisoes cabem no `erro[256]` junto com o prefixo `[Errno N] ` e o
     * `strerror` — sem elas o gcc avisa truncamento e o caminho sairia cortado
     * no meio, que e justamente a parte que o usuario precisa ler. */
    if (cam && cam2)
        snprintf(vm->erro, sizeof(vm->erro), "[Errno %d] %s: '%.90s' -> '%.90s'",
                 e, strerror(e), cam, cam2);
    else if (cam)
        snprintf(vm->erro, sizeof(vm->erro), "[Errno %d] %s: '%.190s'",
                 e, strerror(e), cam);
    else
        snprintf(vm->erro, sizeof(vm->erro), "[Errno %d] %s", e, strerror(e));
    snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "%s", tipo_do_errno(e));
    return -1;
}

/* Os parâmetros obrigatórios que ficaram sem valor:
 * `'x'`, depois `'x' and 'y'`, depois `'x', 'y', and 'z'`.
 *
 * A mensagem antiga citava só o PRIMEIRO que faltou. Quem esquecia três
 * argumentos consertava um, rodava de novo, descobria o segundo, rodava de
 * novo — três viagens pra uma informação que já estava toda aqui.
 *
 * `marcado` é opcional: sem ele, todos de `de` a `ate` contam como faltantes;
 * com ele (caminho de argumento nomeado), só os que ninguém preencheu.
 */
static const char *lista_faltantes(const Proto *pr, int de, int ate,
                                   const int *marcado)
{
    static char buf[256];
    buf[0] = '\0';
    int quantos = 0;
    for (int k = de; k < ate; k++)
        if (!marcado || !marcado[k]) quantos++;
    int escritos = 0;
    for (int k = de; k < ate; k++) {
        if (marcado && marcado[k]) continue;
        const char *nm = (pr->param_nomes && pr->param_nomes[k])
                         ? pr->param_nomes[k] : "?";
        const char *sep = "";
        if (escritos > 0)
            sep = (escritos == quantos - 1)
                  ? (quantos == 2 ? " and " : ", and ") : ", ";
        size_t u = strlen(buf);
        if (u >= sizeof(buf) - 8) break;
        snprintf(buf + u, sizeof(buf) - u, "%s'%s'", sep, nm);
        escritos++;
    }
    return buf;
}

static int conta_faltantes(int de, int ate, const int *marcado)
{
    int q = 0;
    for (int k = de; k < ate; k++)
        if (!marcado || !marcado[k]) q++;
    return q;
}

/* Aridade:
 *
 *     len() takes exactly one argument (2 given)
 *     upper() takes no arguments (1 given)
 *     round() takes at most 2 arguments (3 given)
 *     find() takes at least 1 argument (0 given)
 *
 * O que faltava nas ~120 mensagens daqui era o `(N given)`. "espera 1 ou 2
 * argumentos" obriga quem lê a contar os argumentos na mão pra descobrir se
 * passou de mais ou de menos — e é justamente isso que a pessoa acabou de
 * errar.
 *
 * POR QUE ESTA FAMÍLIA, e não a outra: existem DUAS redações correntes pra
 * isto. Esta (`takes … (N given)`) e a outra (`expected …, got N`). Medi qual
 * é qual pra cada nome que esta linguagem tem: 97 usam esta, 34 usam a
 * outra. A primeira versão daqui escolheu a MINORITÁRIA e errava 74% dos
 * casos.
 *
 * Não reproduzo a divisão nome a nome, e é de propósito: ela não separa
 * nada — é só um acidente de implementação. Copiar isso seria manter uma
 * tabela de 131 nomes à toa. Aqui a redação é uma só, a da maioria
 * esmagadora.
 */
static int erro_aridade(VM *vm, const char *nome, int minimo, int maximo, int n)
{
    char quanto[64];
    if (maximo == 0)
        snprintf(quanto, sizeof(quanto), "no arguments");
    else if (minimo == maximo)
        snprintf(quanto, sizeof(quanto),
                 minimo == 1 ? "exactly one argument" : "exactly %d arguments", minimo);
    else if (n < minimo)
        snprintf(quanto, sizeof(quanto), "at least %d argument%s",
                 minimo, minimo == 1 ? "" : "s");
    else
        snprintf(quanto, sizeof(quanto), "at most %d argument%s",
                 maximo, maximo == 1 ? "" : "s");
    snprintf(vm->erro, sizeof(vm->erro), "%s() takes %s (%d given)",
             nome, quanto, n);
    snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
    return -1;
}

/* Tipo do argumento 1, numa frase só pra toda nativa que exige list/tup ou
 * dict. Antes cada sítio tinha a própria cópia, e a maioria dizia "'str'
 * object is not iterable" sobre tipos que o motor ITERA (str, bytes, dict):
 * a frase negava uma capacidade da linguagem em vez de dizer o que a função
 * pede. Nenhuma conversão: str continua recusado onde entra list. */
static int arg_exige_seq(VM *vm, Value v, const char *quem)
{
    if (EH_SEQ(v)) return 0;
    snprintf(vm->erro, sizeof(vm->erro), "%s() argument 1 must be list or tup, not %s",
             quem, nome_do_tipo_valor(v));
    snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
    return -1;
}

static int arg_exige_dict(VM *vm, Value v, const char *quem)
{
    if (EH_DICT(v)) return 0;
    snprintf(vm->erro, sizeof(vm->erro), "%s() argument 1 must be dict, not %s",
             quem, nome_do_tipo_valor(v));
    snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
    return -1;
}

#define EXIGE_ARGS(vm, nome, quant) do { \
    if (n != (quant)) return erro_aridade(vm, (nome), (quant), (quant), n); \
} while (0)

/* Constrói uma PSString a partir de um buffer C. Centraliza o "sem memória",
 * que todo builtin que devolve texto precisaria repetir. */
static int devolve_texto(VM *vm, Value *out, const char *buf, int len)
{
    PSString *s = nova_string(vm, buf, len);
    if (!s) BERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(s);
    return 0;
}

static int nativa_str(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "str", 1);
    TXTBUF_AUTO t = {0};
    if (valor_para_texto(&t, &args[0], 0) != 0) { BERRO(vm, "MemoryError", "sem memoria em str()"); }
    int r = devolve_texto(vm, out, t.b ? t.b : "", t.n);
    return r;
}

/* Texto → int, com as regras do `int()`: espaço em volta é
 * ignorado, sinal opcional, só dígitos decimais. "0x1f" é erro. */
static int texto_para_int(const char *s, int len, int64_t *out)
{
    int i = 0, j = len;
    while (i < j && isspace((unsigned char)s[i])) i++;
    while (j > i && isspace((unsigned char)s[j - 1])) j--;
    if (i >= j) return -1;
    int neg = 0;
    if (s[i] == '+' || s[i] == '-') { neg = (s[i] == '-'); i++; }
    if (i >= j) return -1;
    int64_t v = 0;
    for (; i < j; i++) {
        if (!isdigit((unsigned char)s[i])) return -1;
        /* passou do int64: quem chama decide (o `int()` vai pro bignum). Antes
         * o valor dava a volta em silêncio — `int("<32 dígitos>")` virava
         * lixo negativo sem erro nenhum. */
        if (v > (INT64_MAX - (s[i] - '0')) / 10) return 1;   /* 1 = estourou */
        v = v * 10 + (s[i] - '0');
    }
    *out = neg ? -v : v;
    return 0;
}

static int nativa_int(VM *vm, Value *args, int n, Value *out)
{
    if (n == 0) { *out = MK_INT(0); return 0; }   /* int() -> 0, como o interp */
    EXIGE_ARGS(vm, "int", 1);
    Value v = args[0];
    if (v.t == V_INT)   { *out = v; return 0; }
    if (EH_BIGINT(v))   { *out = v; return 0; }   /* bignum já é int */
    if (v.t == V_BOOL)  { *out = MK_INT(v.as.b ? 1 : 0); return 0; }
    /* trunca para zero — não arredonda */
    if (v.t == V_FLOAT) {
        /* inf/NaN não têm inteiro correspondente: o cast em C é comportamento
         * indefinido e devolvia INT64_MIN calado. Agora é erro. */
        if (isnan(v.as.d))
            BERRO(vm, "ValueError", "cannot convert flo NaN to integer");
        if (isinf(v.as.d))
            BERRO(vm, "OverflowError", "cannot convert flo infinity to integer");
        /* Fora da faixa do int64 o cast também é UB: vai de bignum. */
        if (v.as.d >= 9223372036854775808.0 || v.as.d <= -9223372036854775809.0) {
            mpz_t z; mpz_init(z);
            mpz_set_d(z, trunc(v.as.d));
            *out = mk_from_mpz(vm, z);
            mpz_clear(z);
            return 0;
        }
        *out = MK_INT((int64_t)v.as.d);
        return 0;
    }
    if (EH_STRING(v)) {
        PSString *s = COMO_STRING(v);
        int64_t r;
        int rc = texto_para_int(s->chars, s->len, &r);
        if (rc == 1) {   /* não cabe no int64 -> bignum, como o interpretador */
            char buf[512];
            int len = s->len < (int)sizeof(buf) - 1 ? s->len : (int)sizeof(buf) - 1;
            memcpy(buf, s->chars, (size_t)len); buf[len] = '\0';
            mpz_t z; mpz_init(z);
            if (mpz_set_str(z, buf, 10) != 0) {
                mpz_clear(z);
                BERRO(vm, "ValueError",
                      "invalid literal for int() with base 10: '%s'", s->chars);
            }
            *out = mk_from_mpz(vm, z);
            mpz_clear(z);
            return 0;
        }
        if (rc != 0)
            BERRO(vm, "ValueError",
                      "invalid literal for int() with base 10: '%s'", s->chars);
        *out = MK_INT(r);
        return 0;
    }
    BERRO(vm, "TypeError",
          "int() argument must be a string, a bytes-like object"
          " or a real number, not '%s'", nome_do_tipo_valor(v));
}

/* Texto -> double, com espaço em volta permitido e lixo no fim recusado.
 * `-1` se não converte. */
static int texto_para_flo(const char *s, int len, double *out)
{
    char buf[64];
    if (len <= 0 || len >= (int)sizeof(buf)) return -1;
    memcpy(buf, s, (size_t)len);
    buf[len] = '\0';
    char *fim = NULL;
    double d = strtod(buf, &fim);
    while (fim && *fim && isspace((unsigned char)*fim)) fim++;
    if (!fim || fim == buf || *fim) return -1;
    *out = d;
    return 0;
}

static int nativa_flo(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "flo", 1);
    Value v = args[0];
    if (v.t == V_FLOAT) { *out = v; return 0; }
    if (v.t == V_INT)   { *out = MK_FLOAT((double)v.as.i); return 0; }
    if (EH_BIGINT(v))   { *out = MK_FLOAT(mpz_get_d(COMO_BIGINT(v)->v)); return 0; }
    if (v.t == V_BOOL)  { *out = MK_FLOAT(v.as.b ? 1.0 : 0.0); return 0; }
    if (EH_STRING(v)) {
        PSString *s = COMO_STRING(v);
        char *fim = NULL;
        double d = strtod(s->chars, &fim);
        /* strtod para no primeiro caractere inválido; só aceita se o resto
         * for espaço, senão "1.5abc" viraria 1.5 em silêncio. */
        while (fim && *fim && isspace((unsigned char)*fim)) fim++;
        if (!fim || fim == s->chars || *fim)
            BERRO(vm, "ValueError",
                  "could not convert string to flo: '%s'", s->chars);
        *out = MK_FLOAT(d);
        return 0;
    }
    BERRO(vm, "TypeError",
          "flo() argument must be a string or a real number, not '%s'",
          nome_do_tipo_valor(v));
}

static int nativa_bool(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "bool", 1);
    *out = MK_BOOL(val_truthy(&args[0]));
    return 0;
}

/* Nome do tipo de um Value, como o type() mostra — usado também em erro de
 * runtime pra DIZER qual tipo travou (ex: "tipo nao indexavel: Response"). */
/* O nome do tipo NA MENSAGEM tem que ser o que o usuário escreveu.
 *
 * A aritmética coage `bool` pra `int` antes de operar — está certo, bool vale
 * 0/1 aqui. O problema é que a coerção acontece ANTES do erro:
 * `true - "a"` respondia "'-' entre tipos incompativeis: int - str", acusando
 * um `int` que não existe em lugar nenhum do código do usuário. Guardar a tag
 * original antes da coerção custa um registrador e devolve a verdade.
 */
#define TIPO0(v, t0)  ((t0) == V_BOOL ? "bool" : nome_do_tipo_valor(v))

static const char *nome_do_tipo_valor(Value v)
{
    const char *t = "object";
    switch (v.t) {
        case V_NULL: case V_UNSET: t = "Null";   break;
        case V_BOOL:               t = "bool";   break;
        case V_INT:                t = "int";    break;
        case V_FLOAT:              t = "flo";    break;
        case V_FUNC: case V_NATIVE:t = "funct"; break;
        case V_TIPO:               t = "type";  break;
        case V_OBJ:
            switch (v.as.obj->type) {
                case OBJ_BIGINT:   t = "int";    break;
                case OBJ_FUTURO:   t = "future"; break;
                case OBJ_STRING:   t = "str";    break;
                case OBJ_LIST:     t = "list";   break;
                case OBJ_TUPLE:    t = "tup";    break;
                case OBJ_DICT:     t = "dict";   break;
                case OBJ_CLASS:    t = "Entity"; break;
                case OBJ_INSTANCE: t = COMO_INST(v)->classe->nome; break;
                case OBJ_CELULA:   /* nunca escapa pro usuário; só pra tabela ficar completa */
                case OBJ_CLOSURE:
                case OBJ_BOUND:
                case OBJ_NATIVA:
                case OBJ_METODO_NAT: t = "funct"; break;
                case OBJ_MODULO:     t = "module"; break;
                case OBJ_MODEL:      t = "PoolModel"; break;
                case OBJ_ENUM:       t = "enum";   break;
                case OBJ_GERADOR:    t = "generator"; break;
                case OBJ_ARQUIVO:    t = "PoolFile"; break;   /* todo arquivo é PoolFile */
                case OBJ_MODULO_PS:  t = "module"; break;
                case OBJ_BYTES:      t = "bytes";  break;
                case OBJ_POOLFILE:   t = "PoolFile"; break;
                case OBJ_SQLCONN:    t = "PoolConnection"; break;
                case OBJ_SQLCUR:     t = "PoolCursor"; break;
                case OBJ_MAILSRV:    t = "MailServer"; break;
                case OBJ_MAILMSG:    t = "MailMessage"; break;
                case OBJ_MAILRD:     t = "MailReader"; break;
                case OBJ_RESPONSE:   t = "Response"; break;
                case OBJ_QRFILE:     t = "QRPoolFile"; break;
                case OBJ_MANPU_RES:  t = "ManpuResult"; break;
                case OBJ_DBCONN:     t = "DbConnection"; break;
                case OBJ_DBCUR:      t = "DbCursor"; break;
                case OBJ_MONGOCONN:  t = "MongoConnection"; break;
                case OBJ_MONGOCOL:   t = "MongoCollection"; break;
                case OBJ_JINKER:     t = "Jinker"; break;
                case OBJ_JCORS:      t = "CorsConfig"; break;
                case OBJ_JREG: {
                    PSJReg *rg = (PSJReg *)v.as.obj;
                    t = rg->kind == JREG_MIDDLEWARE ? "MiddlewareRegistrar"
                      : rg->kind == JREG_SOCKET    ? "_SocketRegistrar"
                                                   : "_RouteRegistrar";
                    break;
                }
                case OBJ_JRESP:      t = "JinkerResponse"; break;
                case OBJ_JREQ:       t = "JinkerRequest"; break;
                case OBJ_JPROXY:     t = "RequestProxy"; break;
                case OBJ_JUPLOAD:    t = "PoolFileUpload"; break;
                case OBJ_JSOCKNS:    t = "SocketNamespace"; break;
                case OBJ_JEMIT:      t = "SocketEmitter"; break;
                case OBJ_JCHAN:      t = "ChannelManager"; break;
                case OBJ_JCHST:      t = "ChannelStatus"; break;
                case OBJ_WSCONN:     t = "WsConnection"; break;
                case OBJ_QRBUILD:    t = "PoolQRCode"; break;
                case OBJ_QRIMAGE:    t = "QRImage"; break;
                case OBJ_MANPU_FILE: t = "ManpuFile"; break;
                case OBJ_SOCKET:     t = "socket"; break;
                case OBJ_REGEX:      t = "Pattern"; break;
                case OBJ__COUNT:     break;   /* sentinela: nunca ocorre */
            }
            break;
    }
    return t;
}

static int nativa_type(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "type", 1);
    const char *t = nome_do_tipo_valor(args[0]);
    return devolve_texto(vm, out, t, (int)strlen(t));
}

static int nativa_abs(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "abs", 1);
    Value v = args[0];
    /* `-INT64_MIN` não cabe no int64: `abs(-9223372036854775808)` devolvia o
     * MESMO número negativo. Vai pro bignum, como o interpretador. */
    if (v.t == V_INT && v.as.i == INT64_MIN) {
        mpz_t z; mpz_init(z);
        mpz_set_si(z, (long)v.as.i);
        mpz_neg(z, z);
        *out = mk_from_mpz(vm, z);
        mpz_clear(z);
        return 0;
    }
    if (v.t == V_INT)   { *out = MK_INT(v.as.i < 0 ? -v.as.i : v.as.i); return 0; }
    if (v.t == V_BOOL)  { *out = MK_INT(v.as.b ? 1 : 0); return 0; }
    if (EH_BIGINT(v)) {   /* bignum é `int` pro type(): abs tem que aceitar */
        mpz_t z; mpz_init(z);
        mpz_set(z, COMO_BIGINT(v)->v);
        if (mpz_sgn(z) < 0) mpz_neg(z, z);
        *out = mk_from_mpz(vm, z);
        mpz_clear(z);
        return 0;
    }
    if (v.t == V_FLOAT) { *out = MK_FLOAT(v.as.d < 0 ? -v.as.d : v.as.d); return 0; }
    BERRO(vm, "TypeError", "bad operand type for abs(): '%s'",
          nome_do_tipo_valor(v));
}


/* `pow(base, expo)` e `pow(base, expo, mod)` — I11.
 *
 * O de dois argumentos e o MESMO caminho do `**` (o compilador emite OP_POW),
 * entao este builtin so existe pra quem escreve `pow(...)` por costume e pro
 * terceiro argumento, que o operador nao tem: `pow(b, e, m)` calcula
 * `(b ** e) % m` SEM materializar a potencia inteira, que e o unico jeito de
 * fazer isso com expoente grande.
 */
static int nativa_pow(VM *vm, Value *args, int n, Value *out)
{
    if (n < 2 || n > 3) return erro_aridade(vm, "pow", 2, 3, n);
    Value a = args[0], b = args[1];
    if (a.t == V_BOOL) { a.t = V_INT; a.as.i = a.as.b ? 1 : 0; }
    if (b.t == V_BOOL) { b.t = V_INT; b.as.i = b.as.b ? 1 : 0; }

    if (n == 3) {
        Value m = args[2];
        if (m.t == V_BOOL) { m.t = V_INT; m.as.i = m.as.b ? 1 : 0; }
        if (!EH_INTEIRO(a) || !EH_INTEIRO(b) || !EH_INTEIRO(m))
            BERRO(vm, "TypeError",
                  "pow() 3rd argument not allowed unless all arguments are integers");
        int bneg = (b.t == V_INT) ? (b.as.i < 0) : (mpz_sgn(COMO_BIGINT(b)->v) < 0);
        if (bneg)
            BERRO(vm, "ValueError",
                  "pow() 2nd argument cannot be negative when 3rd argument specified");
        mpz_t za, zb, zm, zr;
        mpz_init(za); mpz_init(zb); mpz_init(zm); mpz_init(zr);
        mpz_de_val(za, a); mpz_de_val(zb, b); mpz_de_val(zm, m);
        if (mpz_cmp_si(zm, 0) == 0) {
            mpz_clear(za); mpz_clear(zb); mpz_clear(zm); mpz_clear(zr);
            BERRO(vm, "ValueError", "pow() 3rd argument cannot be 0");
        }
        mpz_powm(zr, za, zb, zm);
        /* mpz_powm devolve no intervalo [0, |m|); aqui o resultado segue o
         * SINAL do modulo, como o `%` da linguagem. */
        if (mpz_sgn(zm) < 0 && mpz_sgn(zr) != 0) mpz_add(zr, zr, zm);
        *out = mk_from_mpz(vm, zr);
        mpz_clear(za); mpz_clear(zb); mpz_clear(zm); mpz_clear(zr);
        return 0;
    }

    if (EH_INTEIRO(a) && EH_INTEIRO(b)) {
        int neg = (b.t == V_INT) ? (b.as.i < 0) : (mpz_sgn(COMO_BIGINT(b)->v) < 0);
        if (neg) {
            double base = int_como_double(a);
            if (base == 0.0)
                BERRO(vm, "ZeroDivisionError",
                      "0.0 cannot be raised to a negative power");
            *out = MK_FLOAT(pow(base, int_como_double(b)));
            return 0;
        }
        if (b.t != V_INT || b.as.i > 1000000)
            BERRO(vm, "MemoryError", "expoente grande demais em pow()");
        mpz_t za, zr; mpz_init(za); mpz_init(zr);
        mpz_de_val(za, a);
        mpz_pow_ui(zr, za, (unsigned long)b.as.i);
        *out = mk_from_mpz(vm, zr);
        mpz_clear(za); mpz_clear(zr);
        return 0;
    }
    if ((EH_INTEIRO(a) || a.t == V_FLOAT) && (EH_INTEIRO(b) || b.t == V_FLOAT)) {
        double x = (a.t == V_FLOAT) ? a.as.d : int_como_double(a);
        double y = (b.t == V_FLOAT) ? b.as.d : int_como_double(b);
        if (x == 0.0 && y < 0.0)
            BERRO(vm, "ZeroDivisionError", "0.0 cannot be raised to a negative power");
        *out = MK_FLOAT(pow(x, y));
        return 0;
    }
    BERRO(vm, "TypeError",
          "unsupported operand type(s) for ** or pow(): '%s' and '%s'",
          nome_do_tipo_valor(args[0]), nome_do_tipo_valor(args[1]));
}

static int nativa_round(VM *vm, Value *args, int n, Value *out)
{
    if (n != 1 && n != 2) return erro_aridade(vm, "round", 1, 2, n);
    /* As casas sao conferidas ANTES do atalho de int: `round(1, "a")` devolvia
     * 1 em silencio porque o `return 0` do inteiro vinha primeiro. */
    if (n == 2 && args[1].t != V_INT && args[1].t != V_BOOL)
        BERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
              nome_do_tipo_valor(args[1]));
    Value v = args[0];
    if (v.t == V_INT || v.t == V_BOOL) {
        /* int já está arredondado; com casas, continua int */
        *out = MK_INT(v.t == V_BOOL ? (v.as.b ? 1 : 0) : v.as.i);
        return 0;
    }
    if (EH_BIGINT(v)) { *out = v; return 0; }   /* já é inteiro */
    if (v.t != V_FLOAT)
        BERRO(vm, "TypeError", "type %s doesn't define __round__ method",
              nome_do_tipo_valor(v));
    if (n == 1) {
        if (isnan(v.as.d))
            BERRO(vm, "ValueError", "cannot convert flo NaN to integer");
        if (isinf(v.as.d))
            BERRO(vm, "OverflowError", "cannot convert flo infinity to integer");
        double r = nearbyint(v.as.d);
        if (r >= 9223372036854775808.0 || r <= -9223372036854775809.0) {
            mpz_t z; mpz_init(z);
            mpz_set_d(z, r);
            *out = mk_from_mpz(vm, z);
            mpz_clear(z);
            return 0;
        }
        /* nearbyint no modo padrão = meio-para-o-par:
         * round(2.5) dá 2, não 3. */
        *out = MK_INT((int64_t)r);
        return 0;
    }
    /* As casas já foram conferidas na entrada (int ou bool); esta era uma
     * segunda cópia da decisão, e recusava bool que a primeira aceitava. */
    int64_t casas = (args[1].t == V_BOOL) ? (args[1].as.b ? 1 : 0) : args[1].as.i;
    if (casas < 0)  casas = 0;
    if (casas > 30) casas = 30;
    /* Formata e relê: o printf arredonda sobre o valor binário exato
     * (por isso 2.675 → 2.67). */
    char buf[64];
    snprintf(buf, sizeof(buf), "%.*f", (int)casas, v.as.d);
    *out = MK_FLOAT(strtod(buf, NULL));
    return 0;
}

/* hex/bin/oct: o sinal vem antes do prefixo (`-0xff`). */
static int base_para_texto(VM *vm, Value *args, int n, Value *out,
                           const char *nome, const char *prefixo, int base)
{
    EXIGE_ARGS(vm, nome, 1);
    Value v = args[0];
    /* Inteiro grande é `int` pro type() e entra em | ^ & << >>; aqui era
     * recusado com "'int' object cannot be interpreted as an integer". O
     * sinal vai antes do prefixo, como no caminho de 64 bits abaixo. */
    if (EH_BIGINT(v)) {
        char *dig = mpz_get_str(NULL, base, COMO_BIGINT(v)->v);
        if (!dig) BERRO(vm, "MemoryError", "sem memoria em %s()", nome);
        size_t nd = strlen(dig);
        char *buf = malloc(nd + 3);
        if (!buf) { free(dig); BERRO(vm, "MemoryError", "sem memoria em %s()", nome); }
        int j = 0;
        const char *d = dig;
        if (*d == '-') { buf[j++] = '-'; d++; }
        buf[j++] = prefixo[0]; buf[j++] = prefixo[1];
        memcpy(buf + j, d, strlen(d));
        j += (int)strlen(d);
        int rc = devolve_texto(vm, out, buf, j);
        free(buf); free(dig);
        return rc;
    }
    if (v.t != V_INT && v.t != V_BOOL)
        BERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
              nome_do_tipo_valor(v));
    int64_t x = (v.t == V_BOOL) ? (v.as.b ? 1 : 0) : v.as.i;
    int neg = x < 0;
    uint64_t u = neg ? (uint64_t)(-(x + 1)) + 1 : (uint64_t)x;   /* sem estourar em INT64_MIN */
    char digitos[70];
    int k = 0;
    if (u == 0) digitos[k++] = '0';
    while (u) { digitos[k++] = "0123456789abcdef"[u % (unsigned)base]; u /= (unsigned)base; }
    char buf[80];
    int j = 0;
    if (neg) buf[j++] = '-';
    buf[j++] = prefixo[0]; buf[j++] = prefixo[1];
    while (k) buf[j++] = digitos[--k];
    return devolve_texto(vm, out, buf, j);
}

static int nativa_hex(VM *vm, Value *a, int n, Value *o) { return base_para_texto(vm, a, n, o, "hex", "0x", 16); }
static int nativa_bin(VM *vm, Value *a, int n, Value *o) { return base_para_texto(vm, a, n, o, "bin", "0b", 2); }
static int nativa_oct(VM *vm, Value *a, int n, Value *o) { return base_para_texto(vm, a, n, o, "oct", "0o", 8); }

/* ord/chr trabalham em CODEPOINT, não em byte: `ord("ç")` é 231, e a string
 * tem 2 bytes em UTF-8. Sem decodificar, daria 195 (o primeiro byte). */
static int nativa_ord(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "ord", 1);
    if (!EH_STRING(args[0]))
        BERRO(vm, "TypeError", "ord() expected string of length 1, but %s found",
              nome_do_tipo_valor(args[0]));
    PSString *s = COMO_STRING(args[0]);
    const unsigned char *b = (const unsigned char *)s->chars;
    int len = s->len, usados = 0;
    int64_t cp = 0;
    if (len >= 1 && b[0] < 0x80)                        { cp = b[0];               usados = 1; }
    else if (len >= 2 && (b[0] & 0xE0) == 0xC0)         { cp = b[0] & 0x1F;        usados = 2; }
    else if (len >= 3 && (b[0] & 0xF0) == 0xE0)         { cp = b[0] & 0x0F;        usados = 3; }
    else if (len >= 4 && (b[0] & 0xF8) == 0xF0)         { cp = b[0] & 0x07;        usados = 4; }
    else BERRO(vm, "TypeError",
               "ord() expected a character, but string of length %d found",
               (int)utf8_conta(s->chars, s->len));
    for (int i = 1; i < usados; i++) {
        if ((b[i] & 0xC0) != 0x80) BERRO(vm, "TypeError", "ord() recebeu UTF-8 invalido");
        cp = (cp << 6) | (b[i] & 0x3F);
    }
    if (usados != len)
        BERRO(vm, "TypeError",
              "ord() expected a character, but string of length %d found",
              (int)utf8_conta(s->chars, s->len));
    *out = MK_INT(cp);
    return 0;
}

static int nativa_chr(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "chr", 1);
    /* aceita bool como int (true->1, false->0), como o interp */
    if (args[0].t != V_INT && args[0].t != V_BOOL)
        BERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
              nome_do_tipo_valor(args[0]));
    int64_t cp = (args[0].t == V_BOOL) ? (args[0].as.b ? 1 : 0) : args[0].as.i;
    if (cp < 0 || cp > 0x10FFFF)
        BERRO(vm, "ValueError", "chr() arg not in range(0x110000)");
    char b[4];
    int k = 0;
    if (cp < 0x80) b[k++] = (char)cp;
    else if (cp < 0x800) {
        b[k++] = (char)(0xC0 | (cp >> 6));
        b[k++] = (char)(0x80 | (cp & 0x3F));
    } else if (cp < 0x10000) {
        b[k++] = (char)(0xE0 | (cp >> 12));
        b[k++] = (char)(0x80 | ((cp >> 6) & 0x3F));
        b[k++] = (char)(0x80 | (cp & 0x3F));
    } else {
        b[k++] = (char)(0xF0 | (cp >> 18));
        b[k++] = (char)(0x80 | ((cp >> 12) & 0x3F));
        b[k++] = (char)(0x80 | ((cp >> 6) & 0x3F));
        b[k++] = (char)(0x80 | (cp & 0x3F));
    }
    return devolve_texto(vm, out, b, k);
}


/* Ordem total entre valores, para min/max/sorted. Devolve -1/0/1, ou -2 se
 * os tipos não se comparam (o chamador vira isso em erro).
 *
 * Lista contra lista é lexicográfico: `min([1,2],[3])` é
 * `[1,2]`. Sem isso, min/max com listas divergiriam do interpretador. */
/* Quando a comparação recusa (-2), quem chama precisa dizer QUAIS tipos não se
 * comparam. Num aninhado os culpados são os de DENTRO: `[1] < ["a"]` falha por
 * causa de `int` contra `str` — dizer "list e list" seria mentira, já que lista
 * com lista compara muito bem. `ma`/`mb` sobem o par exato até a mensagem, e
 * podem ser NULL pra quem só quer o veredito. */
static int compara_valores_par(const Value *a, const Value *b,
                               const Value **ma, const Value **mb)
{
    /* bignum é número: sem isto, `sorted([grande, 1])` dizia "tipos
     * incompativeis" para dois valores que o type() chama de `int`. */
    if (EH_INTEIRO(*a) && EH_INTEIRO(*b) && (EH_BIGINT(*a) || EH_BIGINT(*b))) {
        mpz_t za, zb; mpz_init(za); mpz_init(zb);
        mpz_de_val(za, *a); mpz_de_val(zb, *b);
        int c = mpz_cmp(za, zb);
        mpz_clear(za); mpz_clear(zb);
        return (c > 0) - (c < 0);
    }
    int an = (a->t == V_INT || a->t == V_FLOAT || a->t == V_BOOL || EH_BIGINT(*a));
    int bn = (b->t == V_INT || b->t == V_FLOAT || b->t == V_BOOL || EH_BIGINT(*b));
    if (an && bn) {
        if (a->t == V_INT && b->t == V_INT)
            return (a->as.i > b->as.i) - (a->as.i < b->as.i);
        double x = (a->t == V_FLOAT) ? a->as.d : (a->t == V_BOOL ? (a->as.b ? 1 : 0) : int_como_double(*a));
        double y = (b->t == V_FLOAT) ? b->as.d : (b->t == V_BOOL ? (b->as.b ? 1 : 0) : int_como_double(*b));
        return (x > y) - (x < y);
    }
    if (EH_STRING(*a) && EH_STRING(*b)) {
        PSString *x = COMO_STRING(*a), *y = COMO_STRING(*b);
        int m = x->len < y->len ? x->len : y->len;
        int c = memcmp(x->chars, y->chars, (size_t)m);
        if (c) return c < 0 ? -1 : 1;
        return (x->len > y->len) - (x->len < y->len);
    }
    /* bytes com bytes: lexicográfico POR BYTE, sem UTF-8 no meio. É o que
     * ordena hash, chave binária e resposta de protocolo — e sem isto
     * `sorted` de uma lista de bytes dizia que os tipos não se comparam. */
    if (EH_BYTES(*a) && EH_BYTES(*b)) {
        PSString *x = COMO_BYTES(*a), *y = COMO_BYTES(*b);
        int m = x->len < y->len ? x->len : y->len;
        int c = m > 0 ? memcmp(x->chars, y->chars, (size_t)m) : 0;
        if (c) return c < 0 ? -1 : 1;
        return (x->len > y->len) - (x->len < y->len);
    }
    if (EH_SEQ(*a) && EH_SEQ(*b)) {
        PSList *x = COMO_LIST(*a), *y = COMO_LIST(*b);
        int m = x->len < y->len ? x->len : y->len;
        for (int i = 0; i < m; i++) {
            int c = compara_valores_par(&x->itens[i], &y->itens[i], ma, mb);
            if (c == -2) return -2;
            if (c) return c;
        }
        return (x->len > y->len) - (x->len < y->len);
    }
    if (ma) { *ma = a; *mb = b; }
    return -2;
}


/* Aponta `itens`/`n` para o conteúdo de uma sequência. String vira sequência
 * de caracteres, dict vira sequência de chaves — mas esses dois precisam
 * materializar valores novos, então quem itera usa `iteravel_item`. */
static int iteravel_tam(const Value *v)
{
    if (EH_SEQ(*v))    return COMO_LIST(*v)->len;
    /* CODEPOINTS, não bytes: `list("ção")` tem 3 itens, não 5. Iterar por
     * byte parte o UTF-8 no meio e devolve lixo. */
    if (EH_STRING(*v)) return utf8_conta(COMO_STRING(*v)->chars, COMO_STRING(*v)->len);
    /* bytes itera em BYTES e cada item é um INTEIRO 0..255 — não um pedaço de
     * bytes de tamanho 1, e não codepoint. É o que
     * torna `for each b in dados` útil pra dado binário. */
    if (EH_BYTES(*v))  return COMO_BYTES(*v)->len;
    if (EH_DICT(*v))   return COMO_DICT(*v)->count;
    return -1;
}

/* i-ésimo item de um iterável. Para string devolve o caractere como string
 * nova, então pode alocar — o chamador precisa ter publicado vm->sp. */
/* Posição da i-ésima entrada VIVA no array denso. Sem remoções, `usados` e
 * `count` andam juntos e o índice serve direto; o laço só existe pra o dia
 * em que houver remoção de chave. */
static int dict_pos_viva(const PSDict *d, int i)
{
    if (d->count == d->usados) return i;
    for (int k = 0, vistos = 0; k < d->usados; k++) {
        if (d->entradas[k].estado != 1) continue;
        if (vistos++ == i) return k;
    }
    return -1;
}

static int iteravel_item(VM *vm, const Value *v, int i, Value *out)
{
    if (EH_SEQ(*v))  { *out = COMO_LIST(*v)->itens[i]; return 0; }
    if (EH_BYTES(*v)) { *out = MK_INT((unsigned char)COMO_BYTES(*v)->chars[i]); return 0; }
    if (EH_DICT(*v)) {
        int pos = dict_pos_viva(COMO_DICT(*v), i);
        if (pos < 0) return -1;
        *out = COMO_DICT(*v)->entradas[pos].chave;
        return 0;
    }
    if (EH_STRING(*v)) {
        /* anda até o i-ésimo CODEPOINT — o índice não é posição em bytes */
        PSString *s = COMO_STRING(*v);
        int byte = 0;
        uint32_t cp;
        int passo = 0;
        for (int k = 0; k <= i; k++) {
            passo = utf8_le(s->chars, s->len, byte, &cp);
            if (!passo) return -1;
            if (k < i) byte += passo;
        }
        PSString *c = nova_string(vm, s->chars + byte, passo);
        if (!c) return -1;
        *out = MK_OBJ(c);
        return 0;
    }
    return -1;
}

/* Lista nova já com `cap` posições. Usada por todo builtin que devolve
 * sequência — a alocação dos itens precisa da lista viva e alcançável antes,
 * senão o GC pode coletá-la no meio do preenchimento. */
static PSList *lista_com_cap(VM *vm, int cap, ObjType tipo)
{
    PSList *l = nova_seq(vm, cap > 0 ? cap : 1, tipo);
    if (l) l->len = 0;
    return l;
}

static int cresce_lista(VM *vm, PSList *l);
/* Anexa um valor no fim, crescendo a capacidade se preciso. 0/-1. */
static int lista_push(VM *vm, PSList *l, Value v)
{
    if (cresce_lista(vm, l) != 0) return -1;
    l->itens[l->len++] = v;
    return 0;
}

/* Mesmas regras de conversão do `range()`: int, bool, flo truncado e texto
 * numérico. Usado pelo `range()` e pelo laço especializado, pra os dois
 * aceitarem exatamente a mesma coisa. */
static int num_de_range(VM *vm, Value v, int64_t *out)
{
    if (v.t == V_INT)        { *out = v.as.i; return 0; }
    if (v.t == V_BOOL)       { *out = v.as.b ? 1 : 0; return 0; }
    if (v.t == V_FLOAT)      { *out = (int64_t)v.as.d; return 0; }
    if (EH_STRING(v)) {
        const char *s = COMO_STRING(v)->chars;
        while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
        char *end = NULL;
        long long val = strtoll(s, &end, 10);
        while (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r') end++;
        if (end == s || *end != '\0') {
            snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
            snprintf(vm->erro, sizeof(vm->erro),
                     "'str' object cannot be interpreted as an integer");
            return -1;
        }
        *out = (int64_t)val;
        return 0;
    }
    snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
    snprintf(vm->erro, sizeof(vm->erro),
             "'%s' object cannot be interpreted as an integer",
             nome_do_tipo_valor(v));
    return -1;
}

static int nativa_range(VM *vm, Value *args, int n, Value *out)
{
    if (n < 1 || n > 3) return erro_aridade(vm, "range", 1, 3, n);
    int64_t lim[3] = { 0, 0, 1 };
    for (int i = 0; i < n; i++) {
        if (args[i].t == V_INT)       lim[i] = args[i].as.i;
        else if (args[i].t == V_BOOL) lim[i] = args[i].as.b ? 1 : 0;
        else if (args[i].t == V_FLOAT)lim[i] = (int64_t)args[i].as.d;
        else if (EH_STRING(args[i])) {
            /* string numérica é parseada, como o interp faz (int(a)) */
            const char *s = COMO_STRING(args[i])->chars;
            while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
            char *end = NULL;
            long long val = strtoll(s, &end, 10);
            while (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r') end++;
            if (end == s || *end != '\0')
                BERRO(vm, "TypeError", "'str' object cannot be interpreted as an integer");
            lim[i] = (int64_t)val;
        }
        else BERRO(vm, "TypeError",
                   "'%s' object cannot be interpreted as an integer",
                   nome_do_tipo_valor(args[i]));
    }
    int64_t ini = (n == 1) ? 0 : lim[0];
    int64_t fim = (n == 1) ? lim[0] : lim[1];
    int64_t passo = (n == 3) ? lim[2] : 1;
    if (passo == 0) BERRO(vm, "ValueError", "range() arg 3 must not be zero");
    int64_t quant = (passo > 0)
        ? (fim > ini ? (fim - ini + passo - 1) / passo : 0)
        : (fim < ini ? (ini - fim - passo - 1) / (-passo) : 0);
    if (quant > 50000000) BERRO(vm, "MemoryError", "range() grande demais");
    PSList *l = lista_com_cap(vm, (int)quant, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria em range()");
    for (int64_t k = 0, v = ini; k < quant; k++, v += passo) l->itens[k] = MK_INT(v);
    l->len = (int)quant;
    *out = MK_OBJ(l);
    return 0;
}

static int fixa_raiz(VM *vm, Value v);
static int cresce_lista(VM *vm, PSList *l);
static int ger_retoma(VM *vm, PSGerador *g, Value *out);

/* Esvazia um gerador numa lista. Usado por `list(g)` e por todo builtin que
 * precisa do conteúdo inteiro — não dá pra perguntar o tamanho antes. */
static int drena_gerador(VM *vm, Value g, Value *out)
{
    PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) BERRO(vm, "RuntimeError", "estouro da pilha");
    for (;;) {
        Value item;
        int r = ger_retoma(vm, COMO_GER(g), &item);
        if (r < 0) { vm->sp--; return -1; }
        if (!r) break;
        if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
        l->itens[l->len++] = item;
    }
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

/* `tup(x)` — o mesmo que `list(x)`, mas o resultado é TUPLA.
 *
 * POR QUE ELE PASSOU A EXISTIR: `NOME_TIPO` declara dez tipos e `type((1,2))`
 * responde `"tup"`, mas só CINCO deles eram chamáveis como conversão (`str`,
 * `int`, `flo`, `bool`, `list`). `tup(...)` e `dict(...)` davam "variável não
 * definida" — o nome que o próprio motor imprime não existia como global.
 *
 * Achado escrevendo a LEI "lista vira tupla e volta" (`list(tup(l)) == l`) em
 * `teste/leis.ps`: enunciar a regra obrigou a nomear a conversão, e aí a falta
 * apareceu. Nenhum dos 7903 casos fixos tinha topado com isso. */
static int nativa_tup(VM *vm, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "tup", 0, 1, n);
    PSList *l;
    if (n == 0) {
        l = lista_com_cap(vm, 0, OBJ_TUPLE);
        if (!l) BERRO(vm, "MemoryError", "sem memoria em tup()");
        *out = MK_OBJ(l);
        return 0;
    }
    if (EH_GERADOR(args[0])) {
        /* dreno como lista e converto: o gerador só pode ser consumido uma vez */
        Value tmp;
        if (drena_gerador(vm, args[0], &tmp) != 0) return -1;
        PSList *src = (PSList *)tmp.as.obj;
        src->obj.type = OBJ_TUPLE;
        *out = tmp;
        return 0;
    }
    int tam = iteravel_tam(&args[0]);
    if (tam < 0) BERRO(vm, "TypeError", "'%s' object is not iterable",
              nome_do_tipo_valor(args[0]));
    l = lista_com_cap(vm, tam, OBJ_TUPLE);
    if (!l) BERRO(vm, "MemoryError", "sem memoria em tup()");
    /* no `out` ANTES do laço: se alocar um item disparar o GC, ela precisa
     * estar alcançável ou vira lixo no meio do caminho (mesma razão do list) */
    *out = MK_OBJ(l);
    for (int i = 0; i < tam; i++) {
        Value item;
        if (iteravel_item(vm, &args[0], i, &item) != 0) BERRO(vm, "MemoryError", "sem memoria em tup()");
        l->itens[i] = item;
        l->len = i + 1;
    }
    return 0;
}

/* `dict(x)` — mesma lacuna do `tup()`.
 *
 * Sem argumento: dict vazio. Com um dict: CÓPIA rasa. Com uma sequência de
 * pares (`[[k, v], ...]`): monta a partir deles. Não invento terceira forma —
 * essas três são as únicas sem ambiguidade. */
static int nativa_dict(VM *vm, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "dict", 0, 1, n);
    PSDict *d = novo_dict(vm, 8);
    if (!d) BERRO(vm, "MemoryError", "sem memoria em dict()");
    *out = MK_OBJ(d);                     /* alcançável antes de qualquer alocação */
    if (n == 0) return 0;

    if (EH_DICT(args[0])) {
        PSDict *o = COMO_DICT(args[0]);
        /* `usados` percorre o denso INTEIRO (vivas + removidas) e `estado != 1`
         * pula as removidas — é o mesmo laço do coletor (`gct_dict`). Usar
         * `count` aqui pararia cedo e a cópia sairia furada num dict que já
         * sofreu remoção. */
        for (int i = 0; i < o->usados; i++) {
            if (o->entradas[i].estado != 1) continue;
            if (dict_set(vm, d, &o->entradas[i].chave, &o->entradas[i].valor) != 0)
                BERRO(vm, "MemoryError", "sem memoria em dict()");
        }
        return 0;
    }

    int tam = iteravel_tam(&args[0]);
    if (tam < 0) BERRO(vm, "TypeError", "'%s' object is not iterable",
              nome_do_tipo_valor(args[0]));
    for (int i = 0; i < tam; i++) {
        Value par;
        if (iteravel_item(vm, &args[0], i, &par) != 0) BERRO(vm, "MemoryError", "sem memoria em dict()");
        if (!EH_SEQ(par))
            BERRO(vm, "TypeError",
                  "cannot convert dictionary update sequence element #%d"
                  " to a sequence", i);
        /* É sequência, o que não serve é o TAMANHO: a frase de cima afirmava
         * o contrário e não dizia que o motor esperava 2. */
        if (iteravel_tam(&par) != 2)
            BERRO(vm, "TypeError",
                  "dictionary update sequence element #%d has length %d; 2 is required",
                  i, iteravel_tam(&par));
        Value k, v;
        if (iteravel_item(vm, &par, 0, &k) != 0 || iteravel_item(vm, &par, 1, &v) != 0)
            BERRO(vm, "MemoryError", "sem memoria em dict()");
        if (dict_set(vm, d, &k, &v) != 0) BERRO(vm, "MemoryError", "sem memoria em dict()");
    }
    return 0;
}

static int nativa_list(VM *vm, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "list", 0, 1, n);
    if (n == 1 && EH_GERADOR(args[0])) return drena_gerador(vm, args[0], out);
    PSList *l;
    if (n == 0) {
        l = lista_com_cap(vm, 0, OBJ_LIST);
        if (!l) BERRO(vm, "MemoryError", "sem memoria em list()");
        *out = MK_OBJ(l);
        return 0;
    }
    int tam = iteravel_tam(&args[0]);
    if (tam < 0) BERRO(vm, "TypeError", "'%s' object is not iterable",
              nome_do_tipo_valor(args[0]));
    l = lista_com_cap(vm, tam, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria em list()");
    /* a lista entra no `out` antes do laço: se alocar um caractere disparar
     * o GC, ela precisa estar alcançável ou vira lixo no meio do caminho */
    *out = MK_OBJ(l);
    for (int i = 0; i < tam; i++) {
        Value item;
        if (iteravel_item(vm, &args[0], i, &item) != 0) BERRO(vm, "MemoryError", "sem memoria em list()");
        l->itens[i] = item;
        l->len = i + 1;
    }
    return 0;
}

/* Tipo (V_TIPO) usado como valor chamável -> o conversor nativo correspondente,
 * O MESMO da chamada direta `str(...)`. json/dict/tup não convertem (NULL). */
static int nativa_type(VM *vm, Value *args, int n, Value *out);
static FnNativa tipo_conversor(int32_t idx)
{
    switch (idx) {
        case TIPO_STR:  return nativa_str;
        /* `long(x)` e a MESMA conversao do `int(x)`: o `nativa_int` ja devolve
         * o bignum intacto. O que separa os dois e a DECLARACAO — `int x =`
         * promete 64 bits e recusa bignum, `long x =` nao promete. */
        case TIPO_INT:
        case TIPO_LONG: return nativa_int;
        case TIPO_FLO:  return nativa_flo;
        case TIPO_BOOL: return nativa_bool;
        case TIPO_LIST: return nativa_list;
        case TIPO_TYPE: return nativa_type;
        default:        return NULL;   /* dict, tup */
    }
}

static int nativa_sum(VM *vm, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "sum", 1, 2, n);
    if (arg_exige_seq(vm, args[0], "sum") != 0) return -1;
    PSList *l = COMO_LIST(args[0]);
    double  sd = 0;
    int flutuou = 0;
    /* Acumula em mpz: bignum é `int` pro type(), então sum() tem que somá-lo —
     * e o total de int64 também pode estourar no meio do caminho. */
    mpz_t si; mpz_init(si);
    if (n == 2) {
        Value s = args[1];
        if (s.t == V_INT)        mpz_set_si(si, (long)s.as.i);
        else if (s.t == V_BOOL)  mpz_set_si(si, s.as.b ? 1 : 0);
        else if (EH_BIGINT(s))   mpz_set(si, COMO_BIGINT(s)->v);
        else if (s.t == V_FLOAT) { sd = s.as.d; flutuou = 1; }
        else {
            mpz_clear(si);
            if (EH_STRING(s))
                BERRO(vm, "TypeError",
                      "sum() can't sum strings [use ''.join(seq) instead]");
            BERRO(vm, "TypeError", "unsupported operand type(s) for +: '%s' and 'int'",
                  nome_do_tipo_valor(s));
        }
    }
    for (int i = 0; i < l->len; i++) {
        Value v = l->itens[i];
        if (EH_INTEIRO(v) || v.t == V_BOOL) {
            mpz_t z; mpz_init(z);
            if (v.t == V_BOOL) mpz_set_si(z, v.as.b ? 1 : 0);
            else               mpz_de_val(z, v);
            mpz_add(si, si, z);
            mpz_clear(z);
        }
        else if (v.t == V_FLOAT) { sd += v.as.d; flutuou = 1; }
        else {
            mpz_clear(si);
            BERRO(vm, "TypeError", "unsupported operand type(s) for +: 'int' and '%s'",
                  nome_do_tipo_valor(v));
        }
    }
    *out = flutuou ? MK_FLOAT(sd + mpz_get_d(si)) : mk_from_mpz(vm, si);
    mpz_clear(si);
    return 0;
}

/* min/max: com um argumento itera; com vários compara os próprios. */
static int extremo(VM *vm, Value *args, int n, Value *out, const char *nome, int maior)
{
    if (n < 1) return erro_aridade(vm, nome, 1, 99, n);
    if (n == 1) {
        /* um argumento: itera. Vale string e dict, não só lista. */
        int tam = iteravel_tam(&args[0]);
        if (tam < 0)
            BERRO(vm, "TypeError", "'%s' object is not iterable",
                  nome_do_tipo_valor(args[0]));
        if (tam == 0) BERRO(vm, "ValueError", "%s() iterable argument is empty", nome);
        Value melhor;
        if (iteravel_item(vm, &args[0], 0, &melhor) != 0) BERRO(vm, "MemoryError", "sem memoria");
        for (int i = 1; i < tam; i++) {
            Value item;
            if (iteravel_item(vm, &args[0], i, &item) != 0) BERRO(vm, "MemoryError", "sem memoria");
            const Value *ma = &item, *mb = &melhor;
            int c = compara_valores_par(&item, &melhor, &ma, &mb);
            if (c == -2)
                BERRO(vm, "TypeError",
                      "'%s' not supported between instances of '%s' and '%s'",
                      maior ? ">" : "<", nome_do_tipo_valor(*ma), nome_do_tipo_valor(*mb));
            if (maior ? (c > 0) : (c < 0)) melhor = item;
        }
        *out = melhor;
        return 0;
    }
    Value melhor = args[0];
    for (int i = 1; i < n; i++) {
        const Value *ma = &args[i], *mb = &melhor;
        int c = compara_valores_par(&args[i], &melhor, &ma, &mb);
        if (c == -2)
            BERRO(vm, "TypeError",
                  "'%s' not supported between instances of '%s' and '%s'",
                  maior ? ">" : "<", nome_do_tipo_valor(*ma), nome_do_tipo_valor(*mb));
        if (maior ? (c > 0) : (c < 0)) melhor = args[i];
    }
    *out = melhor;
    return 0;
}

static int nativa_min(VM *vm, Value *a, int n, Value *o) { return extremo(vm, a, n, o, "min", 0); }
static int nativa_max(VM *vm, Value *a, int n, Value *o) { return extremo(vm, a, n, o, "max", 1); }

static int nativa_sorted(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "sorted", 1);
    int tam = iteravel_tam(&args[0]);
    if (tam < 0) BERRO(vm, "TypeError", "'%s' object is not iterable",
              nome_do_tipo_valor(args[0]));
    PSList *l = lista_com_cap(vm, tam, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria em sorted()");
    *out = MK_OBJ(l);
    for (int i = 0; i < tam; i++) {
        Value item;
        if (iteravel_item(vm, &args[0], i, &item) != 0) BERRO(vm, "MemoryError", "sem memoria em sorted()");
        l->itens[i] = item;
        l->len = i + 1;
    }
    /* Inserção: estável, e as listas aqui são
     * pequenas. Trocar por merge sort se aparecer caso grande medido. */
    for (int i = 1; i < tam; i++) {
        Value chave = l->itens[i];
        int j = i - 1;
        while (j >= 0) {
            const Value *ma = &l->itens[j], *mb = &chave;
            int c = compara_valores_par(&l->itens[j], &chave, &ma, &mb);
            if (c == -2)
                BERRO(vm, "TypeError",
                      "'<' not supported between instances of '%s' and '%s'",
                      nome_do_tipo_valor(*mb), nome_do_tipo_valor(*ma));
            if (c <= 0) break;
            l->itens[j + 1] = l->itens[j];
            j--;
        }
        l->itens[j + 1] = chave;
    }
    return 0;
}

static int nativa_reversed(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "reversed", 1);
    int tam = iteravel_tam(&args[0]);
    if (tam < 0) BERRO(vm, "TypeError", "'%s' object is not reversible",
              nome_do_tipo_valor(args[0]));
    PSList *l = lista_com_cap(vm, tam, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria em reversed()");
    *out = MK_OBJ(l);
    for (int i = 0; i < tam; i++) {
        Value item;
        if (iteravel_item(vm, &args[0], tam - 1 - i, &item) != 0) BERRO(vm, "MemoryError", "sem memoria");
        l->itens[i] = item;
        l->len = i + 1;
    }
    return 0;
}

static int nativa_enumerate(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "enumerate", 1);
    int tam = iteravel_tam(&args[0]);
    if (tam < 0) BERRO(vm, "TypeError", "'%s' object is not iterable",
              nome_do_tipo_valor(args[0]));
    PSList *l = lista_com_cap(vm, tam, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria em enumerate()");
    *out = MK_OBJ(l);
    for (int i = 0; i < tam; i++) {
        Value item;
        if (iteravel_item(vm, &args[0], i, &item) != 0) BERRO(vm, "MemoryError", "sem memoria");
        /* o par entra na lista antes do próximo malloc, pelo mesmo motivo */
        PSList *par = nova_seq(vm, 2, OBJ_TUPLE);
        if (!par) BERRO(vm, "MemoryError", "sem memoria em enumerate()");
        par->itens[0] = MK_INT(i);
        par->itens[1] = item;
        par->len = 2;
        l->itens[i] = MK_OBJ(par);
        l->len = i + 1;
    }
    return 0;
}

static int nativa_zip(VM *vm, Value *args, int n, Value *out)
{
    int menor = 0;
    for (int i = 0; i < n; i++) {
        int t = iteravel_tam(&args[i]);
        /* nomeia o argumento que NAO itera — era sempre o primeiro, mesmo
         * quando o problema estava no segundo */
        if (t < 0) BERRO(vm, "TypeError", "'%s' object is not iterable",
              nome_do_tipo_valor(args[i]));
        if (i == 0 || t < menor) menor = t;
    }
    PSList *l = lista_com_cap(vm, menor, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria em zip()");
    *out = MK_OBJ(l);
    for (int i = 0; i < menor; i++) {
        PSList *par = nova_seq(vm, n, OBJ_TUPLE);
        if (!par) BERRO(vm, "MemoryError", "sem memoria em zip()");
        par->len = 0;
        l->itens[i] = MK_OBJ(par);
        l->len = i + 1;
        for (int k = 0; k < n; k++) {
            Value item;
            if (iteravel_item(vm, &args[k], i, &item) != 0) BERRO(vm, "MemoryError", "sem memoria");
            par->itens[k] = item;
            par->len = k + 1;
        }
    }
    return 0;
}

/* ── mutação de lista in-place ─────────────────────────────────────────── */
static int cresce_lista(VM *vm, PSList *l)
{
    if (l->len < l->cap) return 0;
    int novo = l->cap ? l->cap * 2 : 4;
    Value *p = realloc(l->itens, sizeof(Value) * (size_t)novo);
    if (!p) return -1;
    l->itens = p;
    vm->alocado += sizeof(Value) * (size_t)(novo - l->cap);
    l->cap = novo;
    return 0;
}

static int nativa_add_end(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "addEnd", 2);
    if (!EH_LIST(args[0])) BERRO(vm, "TypeError", "addEnd() argument 1 must be list, not %s",
                                            nome_do_tipo_valor(args[0]));
    PSList *l = COMO_LIST(args[0]);
    if (cresce_lista(vm, l) != 0) BERRO(vm, "MemoryError", "sem memoria em addEnd()");
    l->itens[l->len++] = args[1];
    *out = MK_NULL();
    return 0;
}

static int nativa_add_start(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "addStart", 2);
    if (!EH_LIST(args[0])) BERRO(vm, "TypeError", "addStart() argument 1 must be list, not %s",
                                            nome_do_tipo_valor(args[0]));
    PSList *l = COMO_LIST(args[0]);
    if (cresce_lista(vm, l) != 0) BERRO(vm, "MemoryError", "sem memoria em addStart()");
    memmove(l->itens + 1, l->itens, sizeof(Value) * (size_t)l->len);
    l->itens[0] = args[1];
    l->len++;
    *out = MK_NULL();
    return 0;
}

static int nativa_remove_end(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "removeEnd", 1);
    if (!EH_LIST(args[0])) BERRO(vm, "TypeError", "removeEnd() argument 1 must be list, not %s",
                                            nome_do_tipo_valor(args[0]));
    PSList *l = COMO_LIST(args[0]);
    if (l->len == 0) { *out = MK_NULL(); return 0; }
    *out = l->itens[--l->len];
    return 0;
}

static int nativa_remove_start(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "removeStart", 1);
    if (!EH_LIST(args[0])) BERRO(vm, "TypeError", "removeStart() argument 1 must be list, not %s",
                                            nome_do_tipo_valor(args[0]));
    PSList *l = COMO_LIST(args[0]);
    if (l->len == 0) { *out = MK_NULL(); return 0; }
    *out = l->itens[0];
    l->len--;
    memmove(l->itens, l->itens + 1, sizeof(Value) * (size_t)l->len);
    return 0;
}


/* Definida junto do laço de execução (precisa reentrar na VM); aqui só a
 * declaração, pra `map`/`filter` poderem entrar na tabela de builtins. */
static int chama_valor(VM *vm, Value fn, Value *args, int n, Value *out);
/* objetos jinker chamáveis (app(), cors(), app.socket(), app.channel()): dá o
 * params (pra chamada nomeada) e a fn de despacho. 1 se é chamável, 0 senão. */
typedef int (*FnMetodoChamavel)(VM *, Value, Value *, int, Value *);
static int jk_obj_callable(Value alvo, const char **params, FnMetodoChamavel *fn);
static Value jk_str_val(VM *vm, const char *s);


static int fixa_raiz(VM *vm, Value v);
static int cresce_lista(VM *vm, PSList *l);

static PSMetodoNat *novo_metnat(VM *vm, Value alvo, int tabela, int idx)
{
    PSMetodoNat *m = calloc(1, sizeof(PSMetodoNat));
    if (!m) return NULL;
    m->obj.type = OBJ_METODO_NAT;
    m->obj.marked = 0;
    m->obj.next = vm->objetos;
    vm->objetos = (Obj *)m;
    m->alvo = alvo;
    m->tabela = (int16_t)tabela;
    m->idx = (int16_t)idx;
    vm->alocado += sizeof(PSMetodoNat);
    return m;
}

/* ── métodos de string ──────────────────────────────────────────────────── */
/* A string é UTF-8, então nada aqui pode assumir "1 byte = 1 caractere".
 * Índice, fatia e contagem trabalham em CODEPOINT — é o que o usuário vê e o
 * que o interpretador faz. */

/* Decodifica o codepoint que começa em `s[i]`; devolve quantos bytes usou. */
static int utf8_le(const char *s, int len, int i, uint32_t *cp)
{
    const unsigned char *b = (const unsigned char *)s;
    if (i >= len) return 0;
    if (b[i] < 0x80)                  { *cp = b[i]; return 1; }
    if ((b[i] & 0xE0) == 0xC0 && i + 1 < len) { *cp = ((uint32_t)(b[i] & 0x1F) << 6) | (b[i+1] & 0x3F); return 2; }
    if ((b[i] & 0xF0) == 0xE0 && i + 2 < len) {
        *cp = ((uint32_t)(b[i] & 0x0F) << 12) | ((uint32_t)(b[i+1] & 0x3F) << 6) | (b[i+2] & 0x3F);
        return 3;
    }
    if ((b[i] & 0xF8) == 0xF0 && i + 3 < len) {
        *cp = ((uint32_t)(b[i] & 0x07) << 18) | ((uint32_t)(b[i+1] & 0x3F) << 12)
            | ((uint32_t)(b[i+2] & 0x3F) << 6) | (b[i+3] & 0x3F);
        return 4;
    }
    *cp = b[i];                       /* byte solto: trata como Latin-1 */
    return 1;
}

static int utf8_escreve(char *dest, uint32_t cp)
{
    if (cp < 0x80)    { dest[0] = (char)cp; return 1; }
    if (cp < 0x800)   { dest[0] = (char)(0xC0 | (cp >> 6));  dest[1] = (char)(0x80 | (cp & 0x3F)); return 2; }
    if (cp < 0x10000) { dest[0] = (char)(0xE0 | (cp >> 12)); dest[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        dest[2] = (char)(0x80 | (cp & 0x3F)); return 3; }
    dest[0] = (char)(0xF0 | (cp >> 18));        dest[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
    dest[2] = (char)(0x80 | ((cp >> 6) & 0x3F));dest[3] = (char)(0x80 | (cp & 0x3F));
    return 4;
}

/* byte onde começa o codepoint `cp` (0..n); cp == n (ou além) -> len */
static int utf8_byte_de(const char *s, int len, int64_t cp)
{
    int i = 0;
    while (cp > 0 && i < len) {
        uint32_t c;
        int k = utf8_le(s, len, i, &c);
        i += k ? k : 1;
        cp--;
    }
    return i;
}

static int utf8_conta(const char *s, int len)
{
    int n = 0;
    for (int i = 0; i < len; ) { uint32_t cp; int k = utf8_le(s, len, i, &cp); if (!k) break; i += k; n++; }
    return n;
}

/* Maiúscula/minúscula cobrindo ASCII, Latin-1 Suplementar e Latin Estendido-A.
 * É a faixa que importa pro português (ç, ã, é, ô…). Fora dela o codepoint
 * passa intacto — está anotado em LIMITACOES.md. */
/* Caixa fora do Latin-1: a tabela cobria só ASCII + Latin-1/Ext-A, então
 * grego e cirílico passavam INTACTOS por lower()/upper() e `isalpha` dizia
 * False pra letra. Os blocos abaixo são contíguos e regulares, então cabem
 * em aritmética — nada de tabela de milhares de entradas. */
static uint32_t cp_maiuscula(uint32_t c)
{
    if (c >= 'a' && c <= 'z') return c - 32;
    if (c >= 0xE0 && c <= 0xFE && c != 0xF7) return c - 32;   /* à-þ, menos ÷ */
    if (c == 0xFF) return 0x178;                              /* ÿ -> Ÿ */
    if (c >= 0x100 && c <= 0x177) return (c & 1) ? c - 1 : c; /* pares Ā/ā … */
    if (c >= 0x179 && c <= 0x17E) return (c & 1) ? c : c - 1; /* Ź/ź … */
    /* grego: α-ω (0x3B1-0x3C9) -> Α-Ω (0x391-0x3A9); ς (sigma final) -> Σ */
    if (c == 0x3C2) return 0x3A3;
    if (c >= 0x3B1 && c <= 0x3C9) return c - 32;
    if (c >= 0x3AC && c <= 0x3AF) {                            /* acentuadas */
        if (c == 0x3AC) return 0x386;
        return c - 0x25;                                       /* έήί -> ΈΉΊ */
    }
    if (c == 0x3CC) return 0x38C;
    if (c == 0x3CD) return 0x38E;
    if (c == 0x3CE) return 0x38F;
    /* cirílico: а-я (0x430-0x44F) -> А-Я (0x410-0x42F); ѐ-џ -> Ѐ-Џ */
    if (c >= 0x430 && c <= 0x44F) return c - 32;
    if (c >= 0x450 && c <= 0x45F) return c - 80;
    if (c >= 0x460 && c <= 0x481) return (c & 1) ? c - 1 : c;
    if (c >= 0x48A && c <= 0x4BF) return (c & 1) ? c - 1 : c;
    if (c >= 0x4C1 && c <= 0x4CE) return (c & 1) ? c : c - 1;
    if (c >= 0x4D0 && c <= 0x52F) return (c & 1) ? c - 1 : c;
    /* İ (I com pingo) NÃO vira i sem pingo: é maiúscula, fica como está */
    return c;
}

static uint32_t cp_minuscula(uint32_t c)
{
    if (c >= 'A' && c <= 'Z') return c + 32;
    if (c >= 0xC0 && c <= 0xDE && c != 0xD7) return c + 32;
    if (c == 0x178) return 0xFF;
    if (c == 0x130) return 'i';        /* İ -> i; vem ANTES da faixa Ext-A,
                                        * senão a regra dos pares dava ı */
    if (c >= 0x100 && c <= 0x177) return (c & 1) ? c : c + 1;
    if (c >= 0x179 && c <= 0x17E) return (c & 1) ? c + 1 : c;
    if (c == 0x386) return 0x3AC;
    if (c >= 0x388 && c <= 0x38A) return c + 0x25;
    if (c == 0x38C) return 0x3CC;
    if (c == 0x38E) return 0x3CD;
    if (c == 0x38F) return 0x3CE;
    if (c >= 0x391 && c <= 0x3A9 && c != 0x3A2) return c + 32;
    if (c >= 0x410 && c <= 0x42F) return c + 32;
    if (c >= 0x400 && c <= 0x40F) return c + 80;
    if (c >= 0x460 && c <= 0x481) return (c & 1) ? c : c + 1;
    if (c >= 0x48A && c <= 0x4BF) return (c & 1) ? c : c + 1;
    if (c >= 0x4C1 && c <= 0x4CE) return (c & 1) ? c + 1 : c;
    if (c >= 0x4D0 && c <= 0x52F) return (c & 1) ? c : c + 1;
    return c;
}

/* Letras que NÃO têm par de caixa de um codepoint só. `cp_eh_minuscula` é
 * "trocar de caixa muda o caractere?" — critério que dá False pro ß (a
 * maiúscula dele é "SS", duas letras) e pro ʼn/ﬀ. Sem esta lista, `"ß".isalpha()`
 * respondia False, e `isalnum`/`islower` junto. */
static int cp_min_sem_par(uint32_t c)
{
    return c == 0x00DF        /* ß  — maiúscula é "SS" */
        || c == 0x0149        /* ŉ  */
        || c == 0x01F0        /* ǰ  */
        || c == 0x0390 || c == 0x03B0
        || (c >= 0x1E96 && c <= 0x1E9A)
        || c == 0x00B5;       /* µ (micro) */
}

static int cp_eh_maiuscula(uint32_t c) { return cp_minuscula(c) != c; }
static int cp_eh_minuscula(uint32_t c) { return cp_maiuscula(c) != c || cp_min_sem_par(c); }
static int cp_eh_letra(uint32_t c)     { return cp_eh_maiuscula(c) || cp_eh_minuscula(c); }
/* Dígito além do ASCII. `isdecimal` = dígito decimal de qualquer escrita
 * (árabe-índico ٣, devanágari ३…); `isdigit` inclui os sobrescritos (²³¹);
 * `isnumeric` inclui fração e numeral romano (½ Ⅷ). Antes tudo isso dava
 * False e só 0-9 contava. */
static int cp_eh_decimal(uint32_t c)
{
    if (c >= '0' && c <= '9') return 1;
    if (c >= 0x660 && c <= 0x669) return 1;    /* árabe-índico */
    if (c >= 0x6F0 && c <= 0x6F9) return 1;    /* árabe-índico estendido */
    if (c >= 0x966 && c <= 0x96F) return 1;    /* devanágari */
    if (c >= 0x9E6 && c <= 0x9EF) return 1;    /* bengali */
    if (c >= 0xE50 && c <= 0xE59) return 1;    /* tailandês */
    if (c >= 0xFF10 && c <= 0xFF19) return 1;  /* dígitos de largura plena */
    return 0;
}

static int cp_eh_digito(uint32_t c)
{
    if (cp_eh_decimal(c)) return 1;
    if (c == 0xB2 || c == 0xB3 || c == 0xB9) return 1;   /* ² ³ ¹ */
    if (c >= 0x2070 && c <= 0x2079) return 1;            /* ⁰-⁹ sobrescrito */
    if (c >= 0x2080 && c <= 0x2089) return 1;            /* ₀-₉ subscrito */
    return 0;
}

static int cp_eh_numerico(uint32_t c)
{
    if (cp_eh_digito(c)) return 1;
    if (c >= 0xBC && c <= 0xBE) return 1;                /* ¼ ½ ¾ */
    if (c >= 0x2150 && c <= 0x218B) return 1;            /* frações e romanos */
    return 0;
}
static int cp_eh_branco(uint32_t c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f'
        || c == 0x85 || c == 0xA0 || c == 0x2028 || c == 0x2029;
}

/* Buffer de saída dos métodos que constroem texto. */
typedef struct { char *b; int n; int cap; } SBuf;

/* SBuf TEMPORÁRIO com liberação automática na saída do escopo (Fase 2 do
 * refactor de memória): `SBUF_AUTO b = {0};` libera o .b sozinho em QUALQUER
 * saída — return, MERRO/BERRO (que retornam), goto pra fora do bloco — o que
 * elimina os `free(b.b)` espalhados por todo ramo de erro (e os leaks nos
 * ramos que esqueciam). Regras:
 *   - só pra buffer LOCAL cuja posse NUNCA sai da função (nova_string copia);
 *   - se a posse é transferida em algum ramo, zere: `b.b = NULL; b.n = 0;`
 *     logo após a transferência (free(NULL) é no-op no cleanup);
 *   - atenção: cleanup NÃO roda em longjmp (só o ps_qr.c/libpng usa, isolado). */
static void sb_solta(SBuf *s) { free(s->b); }
#define SBUF_AUTO __attribute__((cleanup(sb_solta))) SBuf

static int sb_grow(SBuf *s, int extra)
{
    if (s->n + extra <= s->cap) return 0;
    int novo = s->cap ? s->cap : 32;
    while (novo < s->n + extra) novo *= 2;
    char *p = realloc(s->b, (size_t)novo);
    if (!p) return -1;
    s->b = p; s->cap = novo;
    return 0;
}

static int sb_bytes(SBuf *s, const char *src, int n)
{
    if (n <= 0) return 0;
    if (sb_grow(s, n) != 0) return -1;
    memcpy(s->b + s->n, src, (size_t)n);
    s->n += n;
    return 0;
}

static int sb_cp(SBuf *s, uint32_t cp)
{
    if (sb_grow(s, 4) != 0) return -1;
    s->n += utf8_escreve(s->b + s->n, cp);
    return 0;
}

/* Assinatura de um método nativo: o alvo vem separado dos argumentos. */
typedef int (*FnMetodo)(VM *vm, Value alvo, Value *args, int n, Value *out);
typedef struct { const char *nome; FnMetodo fn; const char *params; } MetodoNat;

#define MERRO(vm, tipo, ...) do { \
    snprintf((vm)->erro, sizeof((vm)->erro), __VA_ARGS__); \
    snprintf((vm)->erro_tipo, sizeof((vm)->erro_tipo), "%s", (tipo)); \
    return -1; \
} while (0)

/* Re-levanta um erro cuja MENSAGEM já está em vm->erro (ex.: json_escreve
 * falhou e escreveu ali): só fixa o TIPO e sai. Evita `snprintf(vm->erro,
 * "%s", vm->erro)` — origem = destino, que é UB (e -Wrestrict). */
#define REERRO(vm, tipo) do { \
    snprintf((vm)->erro_tipo, sizeof((vm)->erro_tipo), "%s", (tipo)); \
    return -1; \
} while (0)

#define ARGS_MET(vm, nome, quant) do { \
    if (n != (quant)) return erro_aridade(vm, (nome), (quant), (quant), n); \
} while (0)

/* Entrega o SBuf como PSString, sempre liberando o buffer. */
static int devolve_sbuf(VM *vm, SBuf *s, Value *out)
{
    PSString *r = nova_string(vm, s->b ? s->b : "", s->n);
    free(s->b);
    /* ZERA após consumir: os chamadores agora usam SBUF_AUTO (cleanup libera na
     * saída do escopo) — sem zerar aqui, o cleanup daria double-free. */
    s->b = NULL; s->n = 0; s->cap = 0;
    if (!r) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(r);
    return 0;
}

static int exige_str(VM *vm, Value v, const char *quem, PSString **out)
{
    if (!EH_STRING(v))
        MERRO(vm, "TypeError", "%s() argument 1 must be str, not %s",
              quem, nome_do_tipo_valor(v));
    *out = COMO_STRING(v);
    return 0;
}

/* ── caixa ──────────────────────────────────────────────────────────────── */
static int met_caixa(VM *vm, Value alvo, int n, Value *out, const char *quem, int modo)
{
    if (n != 0) MERRO(vm, "TypeError", "%s() nao aceita argumento", quem);
    PSString *s = COMO_STRING(alvo);
    SBUF_AUTO b = {0};
    int inicio_palavra = 1;
    for (int i = 0; i < s->len; ) {
        uint32_t cp;
        int k = utf8_le(s->chars, s->len, i, &cp);
        if (!k) break;
        uint32_t r = cp;
        /* `sobe` = este caractere vai pra maiúscula neste modo. Serve pra
         * decidir a expansão do ß, que não tem maiúscula de 1 codepoint. */
        int sobe = (modo == 0) || (modo == 2 && inicio_palavra) || (modo == 3 && i == 0)
                   || (modo == 4 && !cp_eh_maiuscula(cp));
        if (cp == 0x00DF && sobe) {
            /* ß não tem maiúscula única: vira "SS" (ou "Ss" quando só a
             * inicial da palavra sobe, como no title/capitalize). */
            const char *exp = (modo == 0 || modo == 4) ? "SS" : "Ss";
            if (sb_bytes(&b, exp, 2) != 0) { MERRO(vm, "MemoryError", "sem memoria em %s()", quem); }
            inicio_palavra = 0;
            i += k;
            continue;
        }
        switch (modo) {
            case 0: r = cp_maiuscula(cp); break;                 /* upper */
            case 1: /* lower */
                r = cp_minuscula(cp);
                /* Σ no fim de palavra vira ς, não σ: depende do que vem
                 * depois, então não cabe no cp_minuscula. */
                if (cp == 0x03A3 && !inicio_palavra) {
                    uint32_t prox;
                    int k2 = utf8_le(s->chars, s->len, i + k, &prox);
                    if (!k2 || !cp_eh_letra(prox)) r = 0x03C2;
                }
                break;
            case 2: r = inicio_palavra ? cp_maiuscula(cp) : cp_minuscula(cp); break;  /* title */
            case 3: r = (i == 0) ? cp_maiuscula(cp) : cp_minuscula(cp); break;        /* capitalize */
            case 4: r = cp_eh_maiuscula(cp) ? cp_minuscula(cp) : cp_maiuscula(cp); break; /* swapcase */
            case 5:                                              /* casefold */
                /* full folding dos casos que o lower não pega: ß/ẞ viram
                 * "ss" (por isso casefold ≠ lower) e o sigma final grego
                 * normaliza. O resto cai no lower comum. */
                if (cp == 0x00DF || cp == 0x1E9E) {
                    if (sb_bytes(&b, "ss", 2) != 0) { MERRO(vm, "MemoryError", "sem memoria em %s()", quem); }
                    inicio_palavra = 0;
                    i += k;
                    continue;
                }
                r = cp == 0x03C2 ? 0x03C3 : cp_minuscula(cp);
                break;
        }
        if (sb_cp(&b, r) != 0) { MERRO(vm, "MemoryError", "sem memoria em %s()", quem); }
        inicio_palavra = !cp_eh_letra(cp);
        i += k;
    }
    return devolve_sbuf(vm, &b, out);
}

static int met_upper(VM *v, Value a, Value *g, int n, Value *o)      { (void)g; return met_caixa(v, a, n, o, "upper", 0); }
static int met_lower(VM *v, Value a, Value *g, int n, Value *o)      { (void)g; return met_caixa(v, a, n, o, "lower", 1); }
static int met_title(VM *v, Value a, Value *g, int n, Value *o)      { (void)g; return met_caixa(v, a, n, o, "title", 2); }
static int met_capitalize(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return met_caixa(v, a, n, o, "capitalize", 3); }
static int met_swapcase(VM *v, Value a, Value *g, int n, Value *o)   { (void)g; return met_caixa(v, a, n, o, "swapcase", 4); }
static int met_casefold(VM *v, Value a, Value *g, int n, Value *o)   { (void)g; return met_caixa(v, a, n, o, "casefold", 5); }

/* ── aparar ─────────────────────────────────────────────────────────────── */
/* `chars` é um CONJUNTO de caracteres, não um prefixo — `"xyx".strip("xy")`
 * come qualquer um dos dois, em qualquer ordem. */
static int no_conjunto(const char *set, int slen, uint32_t cp)
{
    for (int i = 0; i < slen; ) {
        uint32_t c;
        int k = utf8_le(set, slen, i, &c);
        if (!k) break;
        if (c == cp) return 1;
        i += k;
    }
    return 0;
}

static int met_apara(VM *vm, Value alvo, Value *args, int n, Value *out,
                     const char *quem, int esq, int dir)
{
    if (n > 1) return erro_aridade(vm, quem, 0, 1, n);
    PSString *s = COMO_STRING(alvo);
    const char *set = NULL;
    int slen = 0;
    if (n == 1 && args[0].t != V_NULL) {
        PSString *cs;
        if (exige_str(vm, args[0], quem, &cs) != 0) return -1;
        set = cs->chars; slen = cs->len;
    }
    int i = 0, j = s->len;
    if (esq) {
        while (i < j) {
            uint32_t cp;
            int k = utf8_le(s->chars, s->len, i, &cp);
            if (!k) break;
            if (set ? !no_conjunto(set, slen, cp) : !cp_eh_branco(cp)) break;
            i += k;
        }
    }
    if (dir) {
        while (j > i) {
            /* recua até o começo do codepoint anterior */
            int t = j - 1;
            while (t > i && ((unsigned char)s->chars[t] & 0xC0) == 0x80) t--;
            uint32_t cp;
            utf8_le(s->chars, s->len, t, &cp);
            if (set ? !no_conjunto(set, slen, cp) : !cp_eh_branco(cp)) break;
            j = t;
        }
    }
    PSString *r = nova_string(vm, s->chars + i, j - i);
    if (!r) MERRO(vm, "MemoryError", "sem memoria em %s()", quem);
    *out = MK_OBJ(r);
    return 0;
}

static int met_strip(VM *v, Value a, Value *g, int n, Value *o)  { return met_apara(v, a, g, n, o, "strip", 1, 1); }
static int met_lstrip(VM *v, Value a, Value *g, int n, Value *o) { return met_apara(v, a, g, n, o, "lstrip", 1, 0); }
static int met_rstrip(VM *v, Value a, Value *g, int n, Value *o) { return met_apara(v, a, g, n, o, "rstrip", 0, 1); }

/* ── busca ──────────────────────────────────────────────────────────────── */
/* Posição em BYTES de `ag` dentro de `s` a partir de `de`; -1 se não achar. */
static int acha_bytes(const char *s, int slen, const char *ag, int alen, int de)
{
    if (alen == 0) return de <= slen ? de : -1;
    for (int i = de; i + alen <= slen; i++)
        if (memcmp(s + i, ag, (size_t)alen) == 0) return i;
    return -1;
}

/* Um só teste pra `startswith`/`endswith`: o argumento pode ser uma string ou
 * uma TUPLA/LISTA de opções ("bate com qualquer uma") — antes
 * a tupla dava erro de tipo e obrigava a escrever um `or` pra cada opção. */
static int prefixo_bate(PSString *s, PSString *p, int fim)
{
    if (p->len > s->len) return 0;
    const char *base = fim ? s->chars + s->len - p->len : s->chars;
    return memcmp(base, p->chars, (size_t)p->len) == 0;
}

static int met_borda(VM *vm, Value alvo, Value *args, int n, Value *out,
                     const char *quem, int fim)
{
    ARGS_MET(vm, quem, 1);
    PSString *s = COMO_STRING(alvo), *p;
    if (EH_SEQ(args[0])) {
        PSList *l = COMO_LIST(args[0]);   /* tupla e lista têm o mesmo cabeçalho */
        for (int i = 0; i < l->len; i++) {
            if (exige_str(vm, l->itens[i], quem, &p) != 0) return -1;
            if (prefixo_bate(s, p, fim)) { *out = MK_BOOL(1); return 0; }
        }
        *out = MK_BOOL(0);
        return 0;
    }
    if (exige_str(vm, args[0], quem, &p) != 0) return -1;
    *out = MK_BOOL(prefixo_bate(s, p, fim));
    return 0;
}

static int met_startswith(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    return met_borda(vm, alvo, args, n, out, "startswith", 0);
}

static int met_endswith(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    return met_borda(vm, alvo, args, n, out, "endswith", 1);
}

static int met_contains(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "contains", 1);
    PSString *s = COMO_STRING(alvo), *sub;
    if (exige_str(vm, args[0], "contains", &sub) != 0) return -1;
    *out = MK_BOOL(acha_bytes(s->chars, s->len, sub->chars, sub->len, 0) >= 0);
    return 0;
}

/* find/index devolvem posição em CODEPOINT, não em byte. */
static int posicao_cp(const char *s, int bytes)
{
    return utf8_conta(s, bytes);
}

/* `inicio`/`fim` opcionais (args[1], args[2]) de find/rfind/index/rindex/count,
 * em CARACTERES: negativo conta do fim, limites saturam,
 * Null = ausente. Sai a faixa em BYTES [*b0, *b1); inicio além do fim da
 * string vira faixa invertida (b1 < b0) = "não acha". */
static int faixa_busca(VM *vm, PSString *s, Value *args, int n, const char *quem,
                       int *b0, int *b1)
{
    int64_t total = utf8_conta(s->chars, s->len);
    int64_t i0 = 0, i1 = total;
    if (n >= 2 && args[1].t != V_NULL) {
        if (args[1].t != V_INT)
            MERRO(vm, "TypeError",
                  "slice indices must be integers or None"
                  " or have an __index__ method");
        i0 = args[1].as.i;
        if (i0 < 0) i0 += total;
        if (i0 < 0) i0 = 0;
        if (i0 > total) { *b0 = s->len; *b1 = s->len - 1; return 0; }
    }
    if (n >= 3 && args[2].t != V_NULL) {
        if (args[2].t != V_INT)
            MERRO(vm, "TypeError",
                  "slice indices must be integers or None"
                  " or have an __index__ method");
        i1 = args[2].as.i;
        if (i1 < 0) i1 += total;
        if (i1 < 0) i1 = 0;
        if (i1 > total) i1 = total;
    }
    *b0 = utf8_byte_de(s->chars, s->len, i0);
    *b1 = utf8_byte_de(s->chars, s->len, i1);
    return 0;
}

static int met_busca(VM *vm, Value alvo, Value *args, int n, Value *out,
                     const char *quem, int reverso, int levanta)
{
    if (n < 1 || n > 3)
        return erro_aridade(vm, quem, 1, 3, n);
    PSString *s = COMO_STRING(alvo), *sub;
    if (exige_str(vm, args[0], quem, &sub) != 0) return -1;
    int b0 = 0, b1 = s->len;
    if (faixa_busca(vm, s, args, n, quem, &b0, &b1) != 0) return -1;
    int achou = -1;
    if (b1 >= b0) {
        const char *base = s->chars + b0;
        int len = b1 - b0;
        if (reverso) {
            for (int i = len - sub->len; i >= 0; i--)
                if (memcmp(base + i, sub->chars, (size_t)sub->len) == 0) { achou = i; break; }
            if (sub->len == 0) achou = len;
        } else {
            achou = acha_bytes(base, len, sub->chars, sub->len, 0);
        }
        if (achou >= 0) achou += b0;
    }
    if (achou < 0) {
        if (levanta) MERRO(vm, "ValueError", "substring not found");
        *out = MK_INT(-1);
        return 0;
    }
    *out = MK_INT(posicao_cp(s->chars, achou));
    return 0;
}

static int met_find(VM *v, Value a, Value *g, int n, Value *o)   { return met_busca(v, a, g, n, o, "find", 0, 0); }
static int met_rfind(VM *v, Value a, Value *g, int n, Value *o)  { return met_busca(v, a, g, n, o, "rfind", 1, 0); }
static int met_index(VM *v, Value a, Value *g, int n, Value *o)  { return met_busca(v, a, g, n, o, "index", 0, 1); }
static int met_rindex(VM *v, Value a, Value *g, int n, Value *o) { return met_busca(v, a, g, n, o, "rindex", 1, 1); }

static int met_count(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 1 || n > 3)
        return erro_aridade(vm, "count", 1, 3, n);
    PSString *s = COMO_STRING(alvo), *sub;
    if (exige_str(vm, args[0], "count", &sub) != 0) return -1;
    int b0 = 0, b1 = s->len;
    if (faixa_busca(vm, s, args, n, "count", &b0, &b1) != 0) return -1;
    if (b1 < b0) { *out = MK_INT(0); return 0; }
    const char *base = s->chars + b0;
    int len = b1 - b0;
    if (sub->len == 0) { *out = MK_INT(utf8_conta(base, len) + 1); return 0; }
    int64_t q = 0;
    for (int i = 0; i + sub->len <= len; )
        if (memcmp(base + i, sub->chars, (size_t)sub->len) == 0) { q++; i += sub->len; }
        else i++;
    *out = MK_INT(q);
    return 0;
}

static int met_len(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "len", 0, 0, n);
    PSString *s = COMO_STRING(alvo);
    *out = MK_INT(utf8_conta(s->chars, s->len));
    return 0;
}

/* ── testes de conteúdo ─────────────────────────────────────────────────── */
static int met_teste(VM *vm, Value alvo, int n, Value *out, const char *quem, int qual)
{
    if (n != 0) MERRO(vm, "TypeError", "%s() nao aceita argumento", quem);
    PSString *s = COMO_STRING(alvo);
    /* Vazia: `isascii`/`isprintable` são True (nada viola a regra); os
     * demais pedem "pelo menos um da classe", então dão False. */
    if (s->len == 0) { *out = MK_BOOL(qual == 6 || qual == 8); return 0; }
    int ok = 1, viu_caixa = 0, inicio_palavra = 1;
    for (int i = 0; i < s->len && ok; ) {
        uint32_t cp;
        int k = utf8_le(s->chars, s->len, i, &cp);
        if (!k) break;
        switch (qual) {
            case 0: ok = cp_eh_letra(cp); break;                                  /* isalpha */
            case 1: ok = cp_eh_digito(cp); break;                                 /* isdigit */
            case 2: ok = cp_eh_letra(cp) || cp_eh_digito(cp); break;              /* isalnum */
            case 3: ok = cp_eh_branco(cp); break;                                 /* isspace */
            case 4: if (cp_eh_minuscula(cp)) ok = 0;                              /* isupper */
                    if (cp_eh_maiuscula(cp)) viu_caixa = 1;
                    break;
            case 5: if (cp_eh_maiuscula(cp)) ok = 0;                              /* islower */
                    if (cp_eh_minuscula(cp)) viu_caixa = 1;
                    break;
            case 6: ok = cp < 128; break;                                         /* isascii */
            case 7: { /* istitle */
                int letra = cp_eh_letra(cp);
                if (letra) {
                    if (inicio_palavra) { if (!cp_eh_maiuscula(cp)) ok = 0; else viu_caixa = 1; }
                    else if (cp_eh_maiuscula(cp)) ok = 0;
                }
                inicio_palavra = !letra;
                break;
            }
            case 8: ok = cp >= 32 && cp != 127; break;                            /* isprintable */
            case 9:  ok = cp_eh_decimal(cp); break;                               /* isdecimal */
            case 10: ok = cp_eh_numerico(cp); break;                              /* isnumeric */
        }
        i += k;
    }
    /* isupper/islower/istitle exigem pelo menos um caractere com caixa */
    if ((qual == 4 || qual == 5 || qual == 7) && !viu_caixa) ok = 0;
    *out = MK_BOOL(ok);
    return 0;
}

static int met_isalpha(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "isalpha", 0); }
static int met_isdigit(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "isdigit", 1); }
static int met_isnumeric(VM *v, Value a, Value *g, int n, Value *o){ (void)g; return met_teste(v, a, n, o, "isnumeric", 10); }
static int met_isdecimal(VM *v, Value a, Value *g, int n, Value *o){ (void)g; return met_teste(v, a, n, o, "isdecimal", 9); }
static int met_isalnum(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "isalnum", 2); }
static int met_isspace(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "isspace", 3); }
static int met_isupper(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "isupper", 4); }
static int met_islower(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "islower", 5); }
static int met_isascii(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "isascii", 6); }
static int met_istitle(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; return met_teste(v, a, n, o, "istitle", 7); }
static int met_isprintable(VM *v, Value a, Value *g, int n, Value *o){ (void)g; return met_teste(v, a, n, o, "isprintable", 8); }


/* ── quebra e junção ────────────────────────────────────────────────────── */
/* `split()` sem separador quebra em QUALQUER corrida de branco e descarta as
 * bordas vazias; com separador, cada ocorrência gera um campo, inclusive
 * vazio. São regras diferentes de propósito. */
static int met_split(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 2) return erro_aridade(vm, "split", 0, 2, n);
    PSString *s = COMO_STRING(alvo);
    PSString *sep = NULL;
    if (n >= 1 && args[0].t != V_NULL) {
        if (!EH_STRING(args[0]))
            MERRO(vm, "TypeError", "must be str or None, not %s", nome_do_tipo_valor(args[0]));
        sep = COMO_STRING(args[0]);
        if (sep->len == 0) MERRO(vm, "ValueError", "empty separator");
    }
    int64_t limite = -1;
    if (n == 2) {
        if (args[1].t != V_INT)
            MERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[1]));
        limite = args[1].as.i;
    }
    PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
    if (!l) MERRO(vm, "MemoryError", "sem memoria em split()");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha em split()");

    int64_t feitos = 0;
    int i = 0;
    for (;;) {
        int ini, fim;
        if (!sep) {
            while (i < s->len) {                       /* pula branco da frente */
                uint32_t cp; int k = utf8_le(s->chars, s->len, i, &cp);
                if (!k || !cp_eh_branco(cp)) break;
                i += k;
            }
            if (i >= s->len) break;
            ini = i;
            if (limite >= 0 && feitos >= limite) { fim = s->len; i = s->len; }
            else {
                while (i < s->len) {
                    uint32_t cp; int k = utf8_le(s->chars, s->len, i, &cp);
                    if (!k || cp_eh_branco(cp)) break;
                    i += k;
                }
                fim = i;
            }
        } else {
            ini = i;
            int achou = (limite >= 0 && feitos >= limite)
                        ? -1 : acha_bytes(s->chars, s->len, sep->chars, sep->len, i);
            if (achou < 0) { fim = s->len; i = s->len; }
            else           { fim = achou;  i = achou + sep->len; }
        }
        PSString *parte = nova_string(vm, s->chars + ini, fim - ini);
        if (!parte) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria em split()"); }
        if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        l->itens[l->len++] = MK_OBJ(parte);
        feitos++;
        if (sep) { if (fim == s->len) break; }
        else if (i >= s->len) break;
    }
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

/* rsplit: sem limite é igual ao split; com limite, as divisões contam da
 * DIREITA — `"a,b,c".rsplit(",", 1)` = ["a,b", "c"]. */
static int met_rsplit(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 2) return erro_aridade(vm, "rsplit", 0, 2, n);
    int64_t limite = (n == 2 && args[1].t == V_INT) ? args[1].as.i : -1;
    /* sem limite (ou negativo) a direção não importa — delega ao split */
    if (limite < 0) return met_split(vm, alvo, args, n, out);
    if (n >= 1 && args[0].t != V_NULL && !EH_STRING(args[0]))
        MERRO(vm, "TypeError", "must be str or None, not %s", nome_do_tipo_valor(args[0]));

    PSString *s = COMO_STRING(alvo);
    PSString *sep = (n >= 1 && EH_STRING(args[0])) ? COMO_STRING(args[0]) : NULL;
    if (sep && sep->len == 0) MERRO(vm, "ValueError", "empty separator");

    /* acha os cortes da direita pra esquerda, no máximo `limite` */
    int cortes[256]; int nc = 0;
    int i = s->len;
    while (nc < limite && nc < 256) {
        int achou = -1;
        if (sep) {
            for (int p = i - sep->len; p >= 0; p--)
                if (memcmp(s->chars + p, sep->chars, (size_t)sep->len) == 0) { achou = p; break; }
            if (achou < 0) break;
            cortes[nc++] = achou;
            i = achou;
        } else {
            /* separador = branco: pula brancos à direita, depois acha o próximo */
            int p = i - 1;
            while (p >= 0) { uint32_t cp; utf8_le(s->chars, s->len, p, &cp); if (!cp_eh_branco((unsigned char)s->chars[p])) break; p--; }
            int fimtok = p + 1;
            while (p >= 0 && !cp_eh_branco((unsigned char)s->chars[p])) p--;
            if (fimtok <= 0) break;
            cortes[nc++] = p + 1;          /* início do token */
            cortes[nc++] = fimtok;         /* fim do token (par) */
            i = p + 1;
            if (nc >= limite * 2) break;
        }
    }

    PSList *l = lista_com_cap(vm, nc + 2, OBJ_LIST);
    if (!l) MERRO(vm, "MemoryError", "sem memoria em rsplit()");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");

    if (sep) {
        /* monta da esquerda: resto + cada corte */
        int ini = 0;
        for (int c = nc - 1; c >= 0; c--) {
            PSString *parte = nova_string(vm, s->chars + ini, cortes[c] - ini);
            if (!parte || lista_push(vm, l, MK_OBJ(parte)) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
            ini = cortes[c] + sep->len;
        }
        PSString *parte = nova_string(vm, s->chars + ini, s->len - ini);
        if (!parte || lista_push(vm, l, MK_OBJ(parte)) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
    } else {
        /* cortes vêm em pares (ini,fim) da direita; o "resto" vai na frente */
        int resto_fim = nc >= 2 ? cortes[nc - 2] : s->len;
        /* apara branco à direita do resto */
        while (resto_fim > 0 && cp_eh_branco((unsigned char)s->chars[resto_fim - 1])) resto_fim--;
        if (resto_fim > 0) {
            PSString *parte = nova_string(vm, s->chars, resto_fim);
            if (!parte || lista_push(vm, l, MK_OBJ(parte)) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        }
        for (int c = nc - 2; c >= 0; c -= 2) {
            PSString *parte = nova_string(vm, s->chars + cortes[c], cortes[c + 1] - cortes[c]);
            if (!parte || lista_push(vm, l, MK_OBJ(parte)) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        }
    }
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

static int met_splitlines(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "splitlines", 0, 0, n);
    PSString *s = COMO_STRING(alvo);
    PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
    if (!l) MERRO(vm, "MemoryError", "sem memoria em splitlines()");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    int i = 0;
    while (i < s->len) {
        int ini = i;
        while (i < s->len && s->chars[i] != '\n' && s->chars[i] != '\r') i++;
        int fim = i;
        if (i < s->len) {                       /* \r\n conta como uma quebra só */
            if (s->chars[i] == '\r' && i + 1 < s->len && s->chars[i + 1] == '\n') i += 2;
            else i++;
        }
        PSString *parte = nova_string(vm, s->chars + ini, fim - ini);
        if (!parte) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        l->itens[l->len++] = MK_OBJ(parte);
    }
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

static int met_join(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "join", 1);
    PSString *sep = COMO_STRING(alvo);
    if (arg_exige_seq(vm, args[0], "join") != 0) return -1;
    PSList *l = COMO_LIST(args[0]);
    SBUF_AUTO b = {0};
    for (int i = 0; i < l->len; i++) {
        if (!EH_STRING(l->itens[i])) { MERRO(vm, "TypeError",
            "sequence item %d: expected str instance, %s found",
            i, nome_do_tipo_valor(l->itens[i])); }
        if (i && sb_bytes(&b, sep->chars, sep->len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
        PSString *x = COMO_STRING(l->itens[i]);
        if (sb_bytes(&b, x->chars, x->len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    }
    return devolve_sbuf(vm, &b, out);
}

static int met_replace(VM *vm, Value alvo, Value *args, int n, Value *out);

/* `.replace([alvos], novo)` e `.replace([alvos], [novos])` — extensão da
 * PoolScript. Aplica os replaces de string em cadeia sobre o resultado
 * corrente, na ordem da lista; `novos` par a par, ou o mesmo `novo` pra
 * todos. Reusa met_replace pra cada par (mesma semântica de substring). */
static int met_replace_lista(VM *vm, Value alvo, PSList *alvos, Value novo, Value *out)
{
    int novo_lista = EH_SEQ(novo);
    PSList *novos = novo_lista ? COMO_LIST(novo) : NULL;
    Value atual = alvo;
    if (fixa_raiz(vm, atual) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    for (int i = 0; i < alvos->len; i++) {
        if (!EH_STRING(alvos->itens[i])) { vm->sp--;
            MERRO(vm, "TypeError", "replace() argument 1 must be str, not %s",
                  nome_do_tipo_valor(alvos->itens[i])); }
        Value nv;
        if (novo_lista) { if (i >= novos->len) break; nv = novos->itens[i]; }  /* zip para no menor */
        else nv = novo;
        Value par[2] = { alvos->itens[i], nv };
        Value res;
        if (met_replace(vm, atual, par, 2, &res) != 0) { vm->sp--; return -1; }
        atual = res;
        vm->stack[vm->sp - 1] = atual;   /* mantém o resultado corrente fixo */
    }
    vm->sp--;
    *out = atual;
    return 0;
}

static int met_replace(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 1 || n > 3) return erro_aridade(vm, "replace", 1, 3, n);
    /* alvo em lista: `.replace(["-", "_"], ".")` */
    if (n >= 1 && EH_SEQ(args[0]))
        return met_replace_lista(vm, alvo, COMO_LIST(args[0]), n >= 2 ? args[1] : jk_str_val(vm, ""), out);
    PSString *s = COMO_STRING(alvo), *velho, *novo = NULL;
    if (exige_str(vm, args[0], "replace", &velho) != 0) return -1;
    if (n >= 2) {
        if (!EH_STRING(args[1]))
            MERRO(vm, "TypeError", "replace() argument 2 must be str, not %s",
                  nome_do_tipo_valor(args[1]));
        novo = COMO_STRING(args[1]);
    }
    int64_t limite = -1;
    if (n == 3) {
        if (args[2].t != V_INT)
            MERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[2]));
        limite = args[2].as.i;
    }
    int64_t feitos_vazio = 0;
    SBUF_AUTO b = {0};
    if (velho->len == 0) {
        /* alvo vazio casa em toda fronteira de caractere, inclusive nas
         * pontas: `"a".replace("", "x")` é "xax". */
        for (int i = 0; i <= s->len; ) {
            if ((limite < 0 || feitos_vazio < limite) && novo
                    && sb_bytes(&b, novo->chars, novo->len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            feitos_vazio++;
            if (i == s->len) break;
            uint32_t cp;
            int k = utf8_le(s->chars, s->len, i, &cp);
            if (!k) k = 1;
            if (sb_bytes(&b, s->chars + i, k) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            i += k;
        }
        return devolve_sbuf(vm, &b, out);
    }
    int64_t feitos = 0;
    int i = 0;
    while (i < s->len) {
        if ((limite < 0 || feitos < limite) && i + velho->len <= s->len
                && memcmp(s->chars + i, velho->chars, (size_t)velho->len) == 0) {
            if (novo && sb_bytes(&b, novo->chars, novo->len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            i += velho->len;
            feitos++;
        } else {
            if (sb_bytes(&b, s->chars + i, 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            i++;
        }
    }
    return devolve_sbuf(vm, &b, out);
}

/* partition devolve sempre 3 partes: antes, separador, depois. */
static int met_particiona(VM *vm, Value alvo, Value *args, int n, Value *out,
                          const char *quem, int pelo_fim)
{
    ARGS_MET(vm, quem, 1);
    PSString *s = COMO_STRING(alvo), *sep;
    if (!EH_STRING(args[0]))
        MERRO(vm, "TypeError", "must be str, not %s", nome_do_tipo_valor(args[0]));
    sep = COMO_STRING(args[0]);
    if (sep->len == 0) MERRO(vm, "ValueError", "valor invalido: separador vazio em %s()", quem);
    int achou = -1;
    if (pelo_fim) {
        for (int i = s->len - sep->len; i >= 0; i--)
            if (memcmp(s->chars + i, sep->chars, (size_t)sep->len) == 0) { achou = i; break; }
    } else {
        achou = acha_bytes(s->chars, s->len, sep->chars, sep->len, 0);
    }
    PSList *t = nova_seq(vm, 3, OBJ_TUPLE);
    if (!t) MERRO(vm, "MemoryError", "sem memoria em %s()", quem);
    t->len = 0;
    if (fixa_raiz(vm, MK_OBJ(t)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    const char *pedaco[3];
    int tam[3];
    if (achou < 0) {
        /* sem separador: partition põe tudo na frente, rpartition no fim */
        if (pelo_fim) { pedaco[0] = ""; tam[0] = 0; pedaco[1] = ""; tam[1] = 0;
                        pedaco[2] = s->chars; tam[2] = s->len; }
        else          { pedaco[0] = s->chars; tam[0] = s->len; pedaco[1] = ""; tam[1] = 0;
                        pedaco[2] = ""; tam[2] = 0; }
    } else {
        pedaco[0] = s->chars;              tam[0] = achou;
        pedaco[1] = sep->chars;            tam[1] = sep->len;
        pedaco[2] = s->chars + achou + sep->len; tam[2] = s->len - achou - sep->len;
    }
    for (int i = 0; i < 3; i++) {
        PSString *x = nova_string(vm, pedaco[i], tam[i]);
        if (!x) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        t->itens[i] = MK_OBJ(x);
        t->len = i + 1;
    }
    vm->sp--;
    *out = MK_OBJ(t);
    return 0;
}

static int met_partition(VM *v, Value a, Value *g, int n, Value *o)  { return met_particiona(v, a, g, n, o, "partition", 0); }
static int met_rpartition(VM *v, Value a, Value *g, int n, Value *o) { return met_particiona(v, a, g, n, o, "rpartition", 1); }

static int met_remove_borda(VM *vm, Value alvo, Value *args, int n, Value *out,
                            const char *quem, int prefixo)
{
    ARGS_MET(vm, quem, 1);
    PSString *s = COMO_STRING(alvo), *b;
    if (exige_str(vm, args[0], quem, &b) != 0) return -1;
    int corta = 0;
    if (b->len > 0 && b->len <= s->len)
        corta = prefixo ? (memcmp(s->chars, b->chars, (size_t)b->len) == 0)
                        : (memcmp(s->chars + s->len - b->len, b->chars, (size_t)b->len) == 0);
    const char *ini = s->chars + (corta && prefixo ? b->len : 0);
    int tam = s->len - (corta ? b->len : 0);
    PSString *r = nova_string(vm, ini, tam);
    if (!r) MERRO(vm, "MemoryError", "sem memoria em %s()", quem);
    *out = MK_OBJ(r);
    return 0;
}

static int met_removeprefix(VM *v, Value a, Value *g, int n, Value *o) { return met_remove_borda(v, a, g, n, o, "removeprefix", 1); }
static int met_removesuffix(VM *v, Value a, Value *g, int n, Value *o) { return met_remove_borda(v, a, g, n, o, "removesuffix", 0); }

/* ── preenchimento ──────────────────────────────────────────────────────── */
/* A largura é contada em CODEPOINT: `"ção".ljust(5)` põe 2 espaços, não 0. */
/* Teto de uma string construída por LARGURA (`zfill`, `ljust`, `rjust`,
 * `center`). Sem isto, `"a".zfill(9223372036854775807)` saía alocando em laço
 * e comia a RAM até o OOM killer derrubar a SESSÃO INTEIRA — o interpretador
 * recusa na hora com MemoryError. 256 MB é maior que qualquer uso real e
 * pequeno o bastante pra não matar a máquina. */
#define PS_STR_MAX (256 * 1024 * 1024)

static int met_preenche(VM *vm, Value alvo, Value *args, int n, Value *out,
                        const char *quem, int modo)
{
    if (n < 1 || n > 2) return erro_aridade(vm, quem, 1, 2, n);
    PSString *s = COMO_STRING(alvo);
    if (args[0].t != V_INT)
            MERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[0]));
    int64_t larg = args[0].as.i;
    const char *ench = " ";
    int ench_len = 1;
    if (n == 2) {
        PSString *f;
        if (!EH_STRING(args[1]))
            MERRO(vm, "TypeError", "The fill character must be a unicode character, not %s",
                  nome_do_tipo_valor(args[1]));
        f = COMO_STRING(args[1]);
        if (utf8_conta(f->chars, f->len) != 1)
            MERRO(vm, "TypeError", "The fill character must be exactly one character long");
        ench = f->chars; ench_len = f->len;
    }
    int atual = utf8_conta(s->chars, s->len);
    if (larg > PS_STR_MAX / (ench_len > 0 ? ench_len : 1))
        MERRO(vm, "MemoryError", "memória insuficiente: %s() pediu largura %lld",
              quem, (long long)larg);
    int64_t falta = larg - atual;
    if (falta <= 0) {
        PSString *r = nova_string(vm, s->chars, s->len);
        if (!r) MERRO(vm, "MemoryError", "sem memoria");
        *out = MK_OBJ(r);
        return 0;
    }
    int64_t esq = 0, dir = 0;
    if (modo == 0) dir = falta;                        /* ljust  */
    else if (modo == 1) esq = falta;                   /* rjust  */
    else {
        /* center: a sobra ímpar vai pra ESQUERDA quando largura e folga são
         * ambas ímpares. A fórmula é `marg/2 + (marg & width & 1)`
         * — `"ab".center(5)` é "  ab ", não " ab  ". */
        esq = falta / 2 + (falta & larg & 1);
        dir = falta - esq;
    }
    SBUF_AUTO b = {0};
    for (int64_t k = 0; k < esq; k++)
        if (sb_bytes(&b, ench, ench_len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    if (sb_bytes(&b, s->chars, s->len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    for (int64_t k = 0; k < dir; k++)
        if (sb_bytes(&b, ench, ench_len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    return devolve_sbuf(vm, &b, out);
}

static int met_ljust(VM *v, Value a, Value *g, int n, Value *o)  { return met_preenche(v, a, g, n, o, "ljust", 0); }
static int met_rjust(VM *v, Value a, Value *g, int n, Value *o)  { return met_preenche(v, a, g, n, o, "rjust", 1); }
static int met_center(VM *v, Value a, Value *g, int n, Value *o) { return met_preenche(v, a, g, n, o, "center", 2); }

/* zfill põe zeros DEPOIS do sinal: "-5".zfill(4) é "-005", não "00-5". */
static int met_zfill(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "zfill", 1);
    PSString *s = COMO_STRING(alvo);
    if (args[0].t != V_INT)
            MERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[0]));
    int64_t larg = args[0].as.i;
    int atual = utf8_conta(s->chars, s->len);
    if (larg > PS_STR_MAX)
        MERRO(vm, "MemoryError", "memória insuficiente: zfill() pediu largura %lld",
              (long long)larg);
    int64_t falta = larg - atual;
    SBUF_AUTO b = {0};
    int sinal = (s->len > 0 && (s->chars[0] == '+' || s->chars[0] == '-')) ? 1 : 0;
    if (falta <= 0) {
        if (sb_bytes(&b, s->chars, s->len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
        return devolve_sbuf(vm, &b, out);
    }
    if (sinal && sb_bytes(&b, s->chars, 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    for (int64_t k = 0; k < falta; k++)
        if (sb_bytes(&b, "0", 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    if (sb_bytes(&b, s->chars + sinal, s->len - sinal) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    return devolve_sbuf(vm, &b, out);
}

static int met_expandtabs(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "expandtabs", 0, 1, n);
    PSString *s = COMO_STRING(alvo);
    int64_t passo = 8;
    if (n == 1) {
        if (args[0].t != V_INT) MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                                     nome_do_tipo_valor(args[0]));
        passo = args[0].as.i;
    }
    SBUF_AUTO b = {0};
    int coluna = 0;
    for (int i = 0; i < s->len; i++) {
        char c = s->chars[i];
        if (c == '\t') {
            int64_t ate = passo > 0 ? passo - (coluna % passo) : 0;
            for (int64_t k = 0; k < ate; k++)
                if (sb_bytes(&b, " ", 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            coluna += (int)ate;
        } else {
            if (sb_bytes(&b, &c, 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            if (c == '\n' || c == '\r') coluna = 0;
            else if (((unsigned char)c & 0xC0) != 0x80) coluna++;
        }
    }
    return devolve_sbuf(vm, &b, out);
}


/* ── format ─────────────────────────────────────────────────────────────── */
/*
 * Mini-linguagem de formato, no subconjunto que cobre o uso real:
 *
 *   {}  {0}  {nome}          posicional automático, indexado, nomeado
 *   {:[preenche][<^>][0][largura][.precisao][tipo]}
 *   {{  }}                   chave literal
 *
 * `tipo` aceita `s d f x X b o`. O que não estiver aqui é recusado com erro,
 * nunca ignorado: formatar diferente do pedido é pior que não formatar.
 */
static int formata_um(VM *vm, SBuf *saida, const Value *v, const char *spec, int nspec)
{
    /* [preenche][align] [0] [largura] [.prec] [tipo] */
    char preenche = ' ', align = 0, tipo = 0;
    int i = 0, largura = 0, prec = -1;
    if (nspec >= 2 && (spec[1] == '<' || spec[1] == '>' || spec[1] == '^')) {
        preenche = spec[0]; align = spec[1]; i = 2;
    } else if (nspec >= 1 && (spec[0] == '<' || spec[0] == '>' || spec[0] == '^')) {
        align = spec[0]; i = 1;
    }
    if (i < nspec && spec[i] == '0') { preenche = '0'; if (!align) align = '>'; i++; }
    /* COM TETO. `largura = largura * 10 + digito` transbordava o `int` em
     * silencio: `"{:99999999999d}".format(1)` dava um valor lixo, o laco de
     * preenchimento la embaixo escrevia byte a byte, e o processo TRAVAVA
     * comendo memoria ate morrer. Agora responde MemoryError.
     *
     * O teto e o mesmo limite de string do resto do motor — acima dele nao ha
     * o que produzir de qualquer forma. */
    while (i < nspec && spec[i] >= '0' && spec[i] <= '9') {
        if (largura > PS_STR_MAX / 10) {
            snprintf(vm->erro, sizeof(vm->erro), "sem memoria na largura do format");
            snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "MemoryError");
            return -1;
        }
        largura = largura * 10 + (spec[i++] - '0');
    }
    if (largura > PS_STR_MAX) {
        snprintf(vm->erro, sizeof(vm->erro), "sem memoria na largura do format");
        snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "MemoryError");
        return -1;
    }
    if (i < nspec && spec[i] == '.') {
        i++; prec = 0;
        while (i < nspec && spec[i] >= '0' && spec[i] <= '9') {
            if (prec > PS_STR_MAX / 10) {
                snprintf(vm->erro, sizeof(vm->erro), "sem memoria na precisao do format");
                snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "MemoryError");
                return -1;
            }
            prec = prec * 10 + (spec[i++] - '0');
        }
    }
    if (i < nspec) tipo = spec[i++];
    if (i != nspec) { snprintf(vm->erro, sizeof(vm->erro), "format: spec invalido"); return -1; }

    char num[128];
    const char *txt = NULL;
    int ntxt = 0;
    TXTBUF_AUTO t = {0};

    if (tipo == 'f') {
        double d = (v->t == V_INT) ? (double)v->as.i : (v->t == V_FLOAT) ? v->as.d : 0;
        if (v->t != V_INT && v->t != V_FLOAT) { snprintf(vm->erro, sizeof(vm->erro), "format: 'f' espera numero"); return -1; }
        ntxt = snprintf(num, sizeof(num), "%.*f", prec < 0 ? 6 : prec, d);
        txt = num;
    } else if (tipo == 'd' || tipo == 'x' || tipo == 'X' || tipo == 'o' || tipo == 'b') {
        if (v->t != V_INT && v->t != V_BOOL) { snprintf(vm->erro, sizeof(vm->erro), "format: '%c' espera int", tipo); return -1; }
        int64_t x = (v->t == V_BOOL) ? (v->as.b ? 1 : 0) : v->as.i;
        if (tipo == 'd')      ntxt = snprintf(num, sizeof(num), "%lld", (long long)x);
        else if (tipo == 'x') ntxt = snprintf(num, sizeof(num), "%llx", (unsigned long long)x);
        else if (tipo == 'X') ntxt = snprintf(num, sizeof(num), "%llX", (unsigned long long)x);
        else if (tipo == 'o') ntxt = snprintf(num, sizeof(num), "%llo", (unsigned long long)x);
        else {
            /* `b` não tem no printf */
            char tmp[70];
            int k = 0;
            uint64_t u = (uint64_t)(x < 0 ? -x : x);
            if (!u) tmp[k++] = '0';
            while (u) { tmp[k++] = (char)('0' + (u & 1)); u >>= 1; }
            int o = 0;
            if (x < 0) num[o++] = '-';
            while (k) num[o++] = tmp[--k];
            num[o] = '\0';
            ntxt = o;
        }
        txt = num;
    } else if (tipo == 's' || tipo == 0) {
        if (valor_para_texto(&t, v, 0) != 0) { return -1; }
        txt = t.b ? t.b : "";
        ntxt = t.n;
        if (prec >= 0 && prec < ntxt) ntxt = prec;
    } else {
        snprintf(vm->erro, sizeof(vm->erro), "format: tipo '%c' nao suportado", tipo);
        return -1;
    }

    /* sem align explícito: número alinha à direita, o resto à esquerda */
    if (!align) align = (tipo && tipo != 's') ? '>' : '<';
    int atual = utf8_conta(txt, ntxt);
    int falta = largura > atual ? largura - atual : 0;
    int esq = align == '>' ? falta : align == '^' ? falta / 2 : 0;
    int dir = falta - esq;

    int rc = 0;
    for (int k = 0; k < esq && !rc; k++) rc = sb_bytes(saida, &preenche, 1);
    if (!rc) rc = sb_bytes(saida, txt, ntxt);
    for (int k = 0; k < dir && !rc; k++) rc = sb_bytes(saida, &preenche, 1);
    return rc;
}

/* `nomes` alinha com os últimos `nkw` de `args` (o CALL_KW já reordenou),
 * ou vem de um dict no caso do `format_map`. */
static int met_format_geral(VM *vm, Value alvo, Value *args, int n, Value *out, Value mapa)
{
    PSString *s = COMO_STRING(alvo);
    SBUF_AUTO b = {0};
    int auto_idx = 0;
    for (int i = 0; i < s->len; ) {
        char c = s->chars[i];
        if (c == '{' && i + 1 < s->len && s->chars[i+1] == '{') {
            if (sb_bytes(&b, "{", 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            i += 2; continue;
        }
        if (c == '}' && i + 1 < s->len && s->chars[i+1] == '}') {
            if (sb_bytes(&b, "}", 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            i += 2; continue;
        }
        if (c != '{') {
            if (sb_bytes(&b, &c, 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            i++; continue;
        }
        /* campo: {campo[:spec]} */
        int fim = i + 1;
        while (fim < s->len && s->chars[fim] != '}') fim++;
        if (fim >= s->len) {
            /* Dois casos separados, e os dois são ValueError — o TIPO
             * do argumento está certo, quem não serve é a string de formato. */
            if (i + 1 >= s->len)
                MERRO(vm, "ValueError", "Single '{' encountered in format string");
            MERRO(vm, "ValueError", "expected '}' before end of string");
        }
        int corte = i + 1;
        while (corte < fim && s->chars[corte] != ':') corte++;
        const char *campo = s->chars + i + 1;
        int ncampo = corte - (i + 1);
        const char *spec = (corte < fim) ? s->chars + corte + 1 : "";
        int nspec = (corte < fim) ? fim - corte - 1 : 0;

        Value v = MK_NULL();
        int achou = 0;
        if (ncampo == 0) {
            if (auto_idx < n) { v = args[auto_idx++]; achou = 1; }
        } else {
            int so_digito = 1;
            for (int k = 0; k < ncampo; k++)
                if (campo[k] < '0' || campo[k] > '9') { so_digito = 0; break; }
            if (so_digito) {
                int idx = 0;
                for (int k = 0; k < ncampo; k++) idx = idx * 10 + (campo[k] - '0');
                if (idx < n) { v = args[idx]; achou = 1; }
            } else if (EH_DICT(mapa)) {
                PSString *ch = nova_string(vm, campo, ncampo);
                if (!ch) { MERRO(vm, "MemoryError", "sem memoria"); }
                Value cv = MK_OBJ(ch);
                achou = dict_get(COMO_DICT(mapa), &cv, &v) == 0;
            }
        }
        if (!achou) {
            /* Dois erros distintos: campo POSICIONAL ausente (`{}` sem argumento
             * sobrando, ou `{5}`) é IndexError com o índice; campo por NOME é
             * KeyError com o nome, e só ele. Nos dois o TIPO do argumento está
             * certo — o que falta é o VALOR —, então nenhum é TypeError. */
            int pos = 1, idx = auto_idx;
            if (ncampo > 0) {
                idx = 0;
                for (int k = 0; k < ncampo; k++) {
                    if (campo[k] < '0' || campo[k] > '9') { pos = 0; break; }
                    idx = idx * 10 + (campo[k] - '0');
                }
            }
            if (pos)
                MERRO(vm, "IndexError",
                      "Replacement index %d out of range for positional args tuple",
                      idx);
            MERRO(vm, "KeyError", "'%.*s'", ncampo, campo);
        }
        if (formata_um(vm, &b, &v, spec, nspec) != 0) {
            if (!vm->erro_tipo[0]) snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
            return -1;
        }
        i = fim + 1;
    }
    return devolve_sbuf(vm, &b, out);
}

static int met_format(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    /* Nomeado não chega aqui como nome: o CALL_KW resolve pelos parâmetros do
     * protótipo, e método nativo não tem protótipo. Por isso `{nome}` só
     * funciona via `format_map`, e `format` com nome dá erro claro. */
    return met_format_geral(vm, alvo, args, n, out, MK_NULL());
}

static int met_format_map(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "format_map", 1);
    if (!EH_DICT(args[0]))
        MERRO(vm, "TypeError", "format_map() argument 1 must be dict, not %s",
              nome_do_tipo_valor(args[0]));
    return met_format_geral(vm, alvo, NULL, 0, out, args[0]);
}

static int met_isidentifier(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "isidentifier", 0, 0, n);
    PSString *s = COMO_STRING(alvo);
    if (s->len == 0) { *out = MK_BOOL(0); return 0; }
    int ok = 1, primeiro = 1;
    for (int i = 0; i < s->len && ok; ) {
        uint32_t cp;
        int k = utf8_le(s->chars, s->len, i, &cp);
        if (!k) break;
        /* Letra ou `_`. O atalho "cp >= 128 vale" fazia `"²³".isidentifier()`
         * e `"٣٤".isidentifier()` responderem True: sobrescrito e dígito
         * árabe não são identificador em lugar nenhum. Depois do primeiro,
         * dígito DECIMAL entra (`a²` continua inválido, `a٣` vale — a
         * categoria Nd do Unicode). */
        int letra = cp_eh_letra(cp) || cp == '_';
        ok = primeiro ? letra : (letra || cp_eh_decimal(cp));
        primeiro = 0;
        i += k;
    }
    *out = MK_BOOL(ok);
    return 0;
}

/* `maketrans("ab","xy")` -> {97: 120, 98: 121}: dict de codepoint pra
 * codepoint, exatamente o que o `translate` consome. */
static int met_maketrans(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)alvo;
    ARGS_MET(vm, "maketrans", 2);
    if (!EH_STRING(args[0]) || !EH_STRING(args[1]))
        MERRO(vm, "TypeError", "maketrans() argument %d must be str, not %s",
              EH_STRING(args[0]) ? 2 : 1,
              nome_do_tipo_valor(EH_STRING(args[0]) ? args[1] : args[0]));
    PSString *de = COMO_STRING(args[0]), *para = COMO_STRING(args[1]);
    if (utf8_conta(de->chars, de->len) != utf8_conta(para->chars, para->len))
        MERRO(vm, "ValueError", "the first two maketrans arguments must have equal length");
    PSDict *d = novo_dict(vm, 8);
    if (!d) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(d);
    if (fixa_raiz(vm, *out) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    int i = 0, j = 0;
    while (i < de->len && j < para->len) {
        uint32_t a, b2;
        int ka = utf8_le(de->chars, de->len, i, &a);
        int kb = utf8_le(para->chars, para->len, j, &b2);
        if (!ka || !kb) break;
        Value ck = MK_INT((int64_t)a), cv = MK_INT((int64_t)b2);
        if (dict_set(vm, d, &ck, &cv) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        i += ka; j += kb;
    }
    vm->sp--;
    return 0;
}

static int met_translate(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "translate", 1);
    if (arg_exige_dict(vm, args[0], "translate") != 0) return -1;
    PSString *s = COMO_STRING(alvo);
    SBUF_AUTO b = {0};
    for (int i = 0; i < s->len; ) {
        uint32_t cp;
        int k = utf8_le(s->chars, s->len, i, &cp);
        if (!k) break;
        Value ch = MK_INT((int64_t)cp), destino;
        if (dict_get(COMO_DICT(args[0]), &ch, &destino) == 0) {
            /* Null na tabela REMOVE o caractere */
            if (destino.t == V_INT) {
                if (sb_cp(&b, (uint32_t)destino.as.i) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            } else if (EH_STRING(destino)) {
                PSString *d2 = COMO_STRING(destino);
                if (sb_bytes(&b, d2->chars, d2->len) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
            }
        } else {
            if (sb_bytes(&b, s->chars + i, k) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
        }
        i += k;
    }
    return devolve_sbuf(vm, &b, out);
}

/* Definidos junto do bloco de regex, mais abaixo — só a assinatura aqui, pra
 * entrarem na tabela. */
static int met_match(VM *vm, Value alvo, Value *args, int n, Value *out);
static int met_get_json(VM *vm, Value alvo, Value *args, int n, Value *out);
