/* ── métodos de list ────────────────────────────────────────────────────── */
static int met_l_append(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "append", 1);
    PSList *l = COMO_LIST(alvo);
    if (cresce_lista(vm, l) != 0) MERRO(vm, "MemoryError", "sem memoria em append()");
    l->itens[l->len++] = args[0];
    *out = MK_NULL();
    return 0;
}

static int met_l_extend(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "extend", 1);
    if (arg_exige_seq(vm, args[0], "extend") != 0) return -1;
    PSList *l = COMO_LIST(alvo), *o = COMO_LIST(args[0]);
    /* `l.extend(l)` duplica a própria lista: fixa o tamanho antes do laço,
     * senão a condição de parada anda junto e o loop não termina. */
    int quantos = o->len;
    for (int i = 0; i < quantos; i++) {
        if (cresce_lista(vm, l) != 0) MERRO(vm, "MemoryError", "sem memoria em extend()");
        l->itens[l->len++] = o->itens[i];
    }
    *out = MK_NULL();
    return 0;
}

static int met_l_insert(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "insert", 2);
    if (args[0].t != V_INT) MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                                 nome_do_tipo_valor(args[0]));
    PSList *l = COMO_LIST(alvo);
    int64_t i = args[0].as.i;
    if (i < 0) i += l->len;
    if (i < 0) i = 0;
    if (i > l->len) i = l->len;            /* fora do fim gruda no fim */
    if (cresce_lista(vm, l) != 0) MERRO(vm, "MemoryError", "sem memoria em insert()");
    memmove(l->itens + i + 1, l->itens + i, sizeof(Value) * (size_t)(l->len - i));
    l->itens[i] = args[1];
    l->len++;
    *out = MK_NULL();
    return 0;
}

static int met_l_pop(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "pop", 0, 1, n);
    PSList *l = COMO_LIST(alvo);
    if (l->len == 0) MERRO(vm, "IndexError", "pop from empty list");
    int64_t i = l->len - 1;
    if (n == 1) {
        if (args[0].t != V_INT) MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                                     nome_do_tipo_valor(args[0]));
        i = args[0].as.i;
        if (i < 0) i += l->len;
        if (i < 0 || i >= l->len) MERRO(vm, "IndexError", "pop index out of range");
    }
    *out = l->itens[i];
    memmove(l->itens + i, l->itens + i + 1, sizeof(Value) * (size_t)(l->len - i - 1));
    l->len--;
    return 0;
}

static int met_l_remove(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "remove", 1);
    PSList *l = COMO_LIST(alvo);
    for (int i = 0; i < l->len; i++) {
        if (!val_iguais(&l->itens[i], &args[0])) continue;
        memmove(l->itens + i, l->itens + i + 1, sizeof(Value) * (size_t)(l->len - i - 1));
        l->len--;
        *out = MK_NULL();
        return 0;
    }
    MERRO(vm, "ValueError", "list.remove(x): x not in list");
}

/* `index(item, inicio=0, fim=len)` — a faixa é opcional, como no `.find` de
 * string. Antes só aceitava 1 argumento. */
static int met_l_index(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 1 || n > 3)
        return erro_aridade(vm, "index", 1, 3, n);
    PSList *l = COMO_LIST(alvo);
    int64_t de = 0, ate = l->len;
    /* Sem o "or None" que o `str.find` tem: aqui a faixa não aceita Null,
     * então a frase é a mais curta. */
    if (n >= 2) {
        if (args[1].t != V_INT)
            MERRO(vm, "TypeError",
                  "slice indices must be integers"
                  " or have an __index__ method");
        de = args[1].as.i;
        if (de < 0) de += l->len;
        if (de < 0) de = 0;
    }
    if (n >= 3) {
        if (args[2].t != V_INT)
            MERRO(vm, "TypeError",
                  "slice indices must be integers"
                  " or have an __index__ method");
        ate = args[2].as.i;
        if (ate < 0) ate += l->len;
        if (ate > l->len) ate = l->len;
    }
    for (int64_t i = de; i < ate; i++)
        if (val_iguais(&l->itens[i], &args[0])) { *out = MK_INT(i); return 0; }
    /* Nao diz "nao achou o item": mostra o VALOR procurado, com
     * repr, e diz de que sequencia ele nao faz parte. Tupla e lista tem
     * frases DIFERENTES — a mesma funcao serve as duas aqui (METODOS_TUPLA
     * reusa met_l_index), entao o ramo tem que existir. O nome do tipo e o do
     * type() da PoolScript: "tup". */
    if (EH_TUPLA(alvo)) MERRO(vm, "ValueError", "tup.index(x): x not in tup");
    {
        TXTBUF_AUTO ib = {0};
        valor_para_texto(&ib, &args[0], 1);
        MERRO(vm, "ValueError", "%s is not in list", ib.b ? ib.b : "");
    }
}

static int met_l_count(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "count", 1);
    PSList *l = COMO_LIST(alvo);
    int64_t q = 0;
    for (int i = 0; i < l->len; i++) if (val_iguais(&l->itens[i], &args[0])) q++;
    *out = MK_INT(q);
    return 0;
}

static int met_l_contains(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "contains", 1);
    PSList *l = COMO_LIST(alvo);
    for (int i = 0; i < l->len; i++)
        if (val_iguais(&l->itens[i], &args[0])) { *out = MK_BOOL(1); return 0; }
    *out = MK_BOOL(0);
    return 0;
}

static int met_l_reverse(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "reverse", 0, 0, n);
    PSList *l = COMO_LIST(alvo);
    for (int i = 0, j = l->len - 1; i < j; i++, j--) {
        Value t = l->itens[i]; l->itens[i] = l->itens[j]; l->itens[j] = t;
    }
    *out = MK_NULL();
    return 0;
}

static int met_l_sort(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "sort", 0, 0, n);
    PSList *l = COMO_LIST(alvo);
    for (int i = 1; i < l->len; i++) {          /* inserção: estável, igual ao sorted() */
        Value chave = l->itens[i];
        int j = i - 1;
        while (j >= 0) {
            const Value *ma = &l->itens[j], *mb = &chave;
            int c = compara_valores_par(&l->itens[j], &chave, &ma, &mb);
            if (c == -2)
                MERRO(vm, "TypeError",
                      "'<' not supported between instances of '%s' and '%s'",
                      nome_do_tipo_valor(*mb), nome_do_tipo_valor(*ma));
            if (c <= 0) break;
            l->itens[j + 1] = l->itens[j];
            j--;
        }
        l->itens[j + 1] = chave;
    }
    *out = MK_NULL();
    return 0;
}

static int met_l_clear(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "clear", 0, 0, n);
    COMO_LIST(alvo)->len = 0;
    *out = MK_NULL();
    return 0;
}

static int met_l_copy(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "copy", 0, 0, n);
    PSList *l = COMO_LIST(alvo);
    PSList *r = lista_com_cap(vm, l->len, OBJ_LIST);
    if (!r) MERRO(vm, "MemoryError", "sem memoria em copy()");
    for (int i = 0; i < l->len; i++) r->itens[i] = l->itens[i];
    r->len = l->len;
    *out = MK_OBJ(r);
    return 0;
}

static int met_l_len(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "len", 0, 0, n);
    *out = MK_INT(COMO_LIST(alvo)->len);
    return 0;
}

/* ── métodos de dict ────────────────────────────────────────────────────── */
/* keys/values/items percorrem o array DENSO, então saem em ordem de inserção. */
static int dict_extrai(VM *vm, Value alvo, Value *out, int o_que)
{
    PSDict *d = COMO_DICT(alvo);
    PSList *l = lista_com_cap(vm, d->count, OBJ_LIST);
    if (!l) MERRO(vm, "MemoryError", "sem memoria");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    for (int i = 0; i < d->usados; i++) {
        if (d->entradas[i].estado != 1) continue;
        Value v;
        if (o_que == 0)      v = d->entradas[i].chave;
        else if (o_que == 1) v = d->entradas[i].valor;
        else {
            PSList *par = nova_seq(vm, 2, OBJ_TUPLE);
            if (!par) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
            par->itens[0] = d->entradas[i].chave;
            par->itens[1] = d->entradas[i].valor;
            par->len = 2;
            v = MK_OBJ(par);
        }
        if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        l->itens[l->len++] = v;
    }
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

static int met_d_keys(VM *v, Value a, Value *g, int n, Value *o)   { (void)g; if (n) MERRO(v,"TypeError","keys() nao aceita argumento"); return dict_extrai(v, a, o, 0); }
static int met_d_values(VM *v, Value a, Value *g, int n, Value *o) { (void)g; if (n) MERRO(v,"TypeError","values() nao aceita argumento"); return dict_extrai(v, a, o, 1); }
/* value() == values(): existe pro `in` olhar os VALORES (`x in d` testa a CHAVE) */
static int met_d_value(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; if (n) MERRO(v,"TypeError","value() nao aceita argumento"); return dict_extrai(v, a, o, 1); }
static int met_d_items(VM *v, Value a, Value *g, int n, Value *o)  { (void)g; if (n) MERRO(v,"TypeError","items() nao aceita argumento"); return dict_extrai(v, a, o, 2); }

static int met_d_get(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "get", 1, 2, n);
    if (dict_get(COMO_DICT(alvo), &args[0], out) != 0)
        *out = (n == 2) ? args[1] : MK_NULL();     /* ausente devolve Null, não erro */
    return 0;
}

static int met_d_has(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "has", 1);
    Value v;
    *out = MK_BOOL(dict_get(COMO_DICT(alvo), &args[0], &v) == 0);
    return 0;
}

static int met_d_pop(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "pop", 1, 2, n);
    if (dict_del(COMO_DICT(alvo), &args[0], out) != 0) {
        if (n == 2) { *out = args[1]; return 0; }
        /* Mesmo texto do `d["z"]` e do `d.z`: as tres respondem a mesma
         * pergunta, e ter tres redacoes pra isso era metade do I4. Hoje a
         * redacao e unica — a mensagem do KeyError e a CHAVE, e
         * so ela. */
        {
            TXTBUF_AUTO kb = {0};
            valor_para_texto(&kb, &args[0], 1);
            MERRO(vm, "KeyError", "%s", kb.b ? kb.b : "");
        }
    }
    return 0;
}

static int met_d_update(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "update", 1);
    if (arg_exige_dict(vm, args[0], "update") != 0) return -1;
    PSDict *d = COMO_DICT(alvo), *o = COMO_DICT(args[0]);
    if (d == o) { *out = MK_NULL(); return 0; }    /* `d.update(d)` é no-op */
    for (int i = 0; i < o->usados; i++) {
        if (o->entradas[i].estado != 1) continue;
        if (dict_set(vm, d, &o->entradas[i].chave, &o->entradas[i].valor) != 0)
            MERRO(vm, "MemoryError", "sem memoria em update()");
    }
    *out = MK_NULL();
    return 0;
}

static int met_d_clear(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "clear", 0, 0, n);
    PSDict *d = COMO_DICT(alvo);
    d->count = 0;
    d->usados = 0;
    for (int i = 0; i < d->icap; i++) d->indices[i] = DICT_VAZIO;
    *out = MK_NULL();
    return 0;
}

static int met_d_copy(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "copy", 0, 0, n);
    PSDict *d = COMO_DICT(alvo);
    PSDict *r = novo_dict(vm, d->count > 0 ? d->count : 1);
    if (!r) MERRO(vm, "MemoryError", "sem memoria em copy()");
    if (fixa_raiz(vm, MK_OBJ(r)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    for (int i = 0; i < d->usados; i++) {
        if (d->entradas[i].estado != 1) continue;
        if (dict_set(vm, r, &d->entradas[i].chave, &d->entradas[i].valor) != 0) {
            vm->sp--; MERRO(vm, "MemoryError", "sem memoria em copy()");
        }
    }
    vm->sp--;
    *out = MK_OBJ(r);
    return 0;
}

static int met_d_len(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "len", 0, 0, n);
    *out = MK_INT(COMO_DICT(alvo)->count);
    return 0;
}

/* ── universal ──────────────────────────────────────────────────────────── */
/* `.type()` existe em QUALQUER valor, e devolve os MESMOS nomes do builtin
 * `type(x)`. Já foram diferentes (`dict`/`tup` aqui contra `json`/`tuple` lá)
 * — duas implementações independentes que ninguém tinha comparado. */
static int met_type(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "type", 0, 0, n);
    const char *t = "object";
    switch (alvo.t) {
        case V_NULL: case V_UNSET:  t = "Null";   break;
        case V_BOOL:                t = "bool";   break;
        case V_INT:                 t = "int";    break;
        case V_FLOAT:               t = "flo";    break;
        case V_FUNC: case V_NATIVE: t = "funct"; break;
        case V_TIPO:                t = "type";  break;
        case V_OBJ:
            switch (alvo.as.obj->type) {
                case OBJ_BIGINT:      t = "int";   break;
                case OBJ_FUTURO:      t = "future";break;
                case OBJ_STRING:      t = "str";   break;
                case OBJ_LIST:        t = "list";  break;
                case OBJ_TUPLE:       t = "tup";   break;
                case OBJ_DICT:        t = "dict";  break;
                case OBJ_CLASS:       t = "Entity"; break;
                case OBJ_INSTANCE:    t = COMO_INST(alvo)->classe->nome; break;
                case OBJ_CELULA:   /* nunca escapa pro usuário; só pra tabela ficar completa */
                case OBJ_CLOSURE:
                case OBJ_BOUND:
                case OBJ_NATIVA:
                case OBJ_METODO_NAT:  t = "funct"; break;
                case OBJ_MODULO:      t = "module"; break;
                case OBJ_MODEL:       t = "PoolModel"; break;
                case OBJ_ENUM:        t = "enum";   break;
                case OBJ_GERADOR:     t = "generator"; break;
                case OBJ_ARQUIVO:     t = "PoolFile"; break;   /* todo arquivo é PoolFile */
                case OBJ_MODULO_PS:   t = "module"; break;
                case OBJ_BYTES:       t = "bytes";  break;
                case OBJ_POOLFILE:    t = "PoolFile"; break;
                case OBJ_SQLCONN:     t = "PoolConnection"; break;
                case OBJ_SQLCUR:      t = "PoolCursor"; break;
                case OBJ_MAILSRV:     t = "MailServer"; break;
                case OBJ_MAILMSG:     t = "MailMessage"; break;
                case OBJ_MAILRD:      t = "MailReader"; break;
                case OBJ_RESPONSE:    t = "Response"; break;
                case OBJ_QRFILE:      t = "QRPoolFile"; break;
                case OBJ_MANPU_RES:   t = "ManpuResult"; break;
                case OBJ_DBCONN:      t = "DbConnection"; break;
                case OBJ_DBCUR:       t = "DbCursor"; break;
                case OBJ_MONGOCONN:   t = "MongoConnection"; break;
                case OBJ_MONGOCOL:    t = "MongoCollection"; break;
                case OBJ_JINKER:      t = "Jinker"; break;
                case OBJ_JCORS:       t = "CorsConfig"; break;
                case OBJ_JREG: {
                    PSJReg *rg = (PSJReg *)alvo.as.obj;
                    t = rg->kind == JREG_MIDDLEWARE ? "MiddlewareRegistrar"
                      : rg->kind == JREG_SOCKET    ? "_SocketRegistrar"
                                                   : "_RouteRegistrar";
                    break;
                }
                case OBJ_JRESP:       t = "JinkerResponse"; break;
                case OBJ_JREQ:        t = "JinkerRequest"; break;
                case OBJ_JPROXY:      t = "RequestProxy"; break;
                case OBJ_JUPLOAD:     t = "PoolFileUpload"; break;
                case OBJ_JSOCKNS:     t = "SocketNamespace"; break;
                case OBJ_JEMIT:       t = "SocketEmitter"; break;
                case OBJ_JCHAN:       t = "ChannelManager"; break;
                case OBJ_JCHST:       t = "ChannelStatus"; break;
                case OBJ_WSCONN:      t = "WsConnection"; break;
                case OBJ_QRBUILD:     t = "PoolQRCode"; break;
                case OBJ_QRIMAGE:     t = "QRImage"; break;
                case OBJ_MANPU_FILE:  t = "ManpuFile"; break;
                case OBJ_SOCKET:      t = "socket"; break;
                case OBJ_REGEX:       t = "Pattern"; break;
                case OBJ__COUNT:      break;   /* sentinela: nunca ocorre */
            }
            break;
    }
    PSString *r = nova_string(vm, t, (int)strlen(t));
    if (!r) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(r);
    return 0;
}


/* ── arquivo ────────────────────────────────────────────────────────────── */
static int arq_exige(VM *vm, Value v, const char *quem, PSArquivo **out)
{
    if (!EH_ARQUIVO(v))
        MERRO(vm, "TypeError", "%s() argument 1 must be PoolFile, not %s",
              quem, nome_do_tipo_valor(v));
    *out = COMO_ARQ(v);
    if ((*out)->fechado) MERRO(vm, "ValueError", "I/O operation on closed file.");
    return 0;
}

static PSString *novo_bytes(VM *vm, const char *dados, int n);   /* def. abaixo */

/* Devolve o conteúdo lido como BYTES se o arquivo é binário, senão string —
 * igual ao FileHandle do interp (read() de "rb" dá bytes, de "r" dá str). */
static int devolve_leitura(VM *vm, SBuf *b, int binario, Value *out)
{
    if (!binario) return devolve_sbuf(vm, b, out);
    PSString *by = novo_bytes(vm, b->b ? b->b : "", b->n);
    free(b->b);
    b->b = NULL; b->n = 0; b->cap = 0;   /* mesma regra do devolve_sbuf (SBUF_AUTO) */
    if (!by) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(by);
    return 0;
}

static int met_a_read(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n > 1) return erro_aridade(vm, "read", 0, 1, n);
    PSArquivo *a;
    if (arq_exige(vm, alvo, "read", &a) != 0) return -1;
    long limite = -1;
    if (n == 1) {
        if (args[0].t != V_INT) MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                                     nome_do_tipo_valor(args[0]));
        limite = (long)args[0].as.i;
    }
    SBUF_AUTO b = {0};
    char pedaco[4096];
    size_t lidos;
    /* Com limite, lê EXATAMENTE o que falta: o `fread` de 4096 sugava o
     * arquivo todo e só descartava o excedente — o cursor ficava no fim e a
     * leitura seguinte vinha vazia (`f.read(3)` e depois `f.read(2)` dava ""). */
    for (;;) {
        size_t quero = sizeof(pedaco);
        if (limite >= 0) {
            long falta = limite - b.n;
            if (falta <= 0) break;
            if ((size_t)falta < quero) quero = (size_t)falta;
        }
        lidos = fread(pedaco, 1, quero, a->f);
        if (lidos == 0) break;
        if (sb_bytes(&b, pedaco, (int)lidos) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    }
    return devolve_leitura(vm, &b, a->binario, out);
}

static int met_a_readline(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "readline", 0, 0, n);
    PSArquivo *a;
    if (arq_exige(vm, alvo, "readline", &a) != 0) return -1;
    SBUF_AUTO b = {0};
    int ch;
    while ((ch = fgetc(a->f)) != EOF) {
        char c = (char)ch;
        if (sb_bytes(&b, &c, 1) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
        if (c == '\n') break;              /* a quebra fica na linha */
    }
    return devolve_leitura(vm, &b, a->binario, out);
}

static int met_a_readlines(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "readlines", 0, 0, n);
    PSArquivo *a;
    if (arq_exige(vm, alvo, "readlines", &a) != 0) return -1;
    PSList *l = lista_com_cap(vm, 8, OBJ_LIST);
    if (!l) MERRO(vm, "MemoryError", "sem memoria");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    for (;;) {
        SBUF_AUTO b = {0};
        int ch, viu = 0;
        while ((ch = fgetc(a->f)) != EOF) {
            char c = (char)ch;
            viu = 1;
            if (sb_bytes(&b, &c, 1) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
            if (c == '\n') break;
        }
        if (!viu) { break; }
        PSString *linha = a->binario ? novo_bytes(vm, b.b ? b.b : "", b.n)
                                     : nova_string(vm, b.b ? b.b : "", b.n);
        if (!linha) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; MERRO(vm, "MemoryError", "sem memoria"); }
        l->itens[l->len++] = MK_OBJ(linha);
    }
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

/* Grava e CONFERE. O `fwrite` devolve quantos itens saíram, e menor que o
 * pedido é erro; `ferror` acumula a falha do fluxo, que às vezes só aparece
 * depois. Sem estes dois, "disco cheio" virava um número menor no retorno que
 * nenhum script confere — grava, fecha, e o arquivo está truncado.
 * Devolve 0, ou -1 com o `errno` da falha em `*pe` — quem chama monta a
 * frase com `erro_sistema`, que sai `[Errno N] <strerror>`.
 * O palpite antigo ("disco cheio?") mentia: `write()` em arquivo aberto em
 * "r" da EBADF e cano quebrado da EPIPE, e os dois liam "disco cheio". */
static int arq_grava(FILE *f, const void *dados, size_t n, int *pe)
{
    if (n == 0) return 0;
    errno = 0;
    size_t w = fwrite(dados, 1, n, f);
    if (w != n || ferror(f)) {
        *pe = errno ? errno : EIO;
        return -1;
    }
    return 0;
}

static int met_a_write(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "write", 1);
    PSArquivo *a;
    if (arq_exige(vm, alvo, "write", &a) != 0) return -1;
    /* não-string vira texto, como o FileHandle do interpretador faz */
    TXTBUF_AUTO t = {0};
    int e = 0;
    if (EH_STRING(args[0])) {
        PSString *ss = COMO_STRING(args[0]);
        if (arq_grava(a->f, ss->chars, (size_t)ss->len, &e) != 0)
            return erro_sistema(vm, e, NULL, NULL);
        *out = MK_INT((int64_t)ss->len);
        return 0;
    }
    if (EH_BYTES(args[0])) {                 /* bytes crus (ex.: req.content) */
        PSString *by = COMO_BYTES(args[0]);
        if (arq_grava(a->f, by->chars, (size_t)by->len, &e) != 0)
            return erro_sistema(vm, e, NULL, NULL);
        *out = MK_INT((int64_t)by->len);
        return 0;
    }
    if (valor_para_texto(&t, &args[0], 0) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    if (arq_grava(a->f, t.b ? t.b : "", (size_t)t.n, &e) != 0)
        return erro_sistema(vm, e, NULL, NULL);
    *out = MK_INT((int64_t)t.n);
    return 0;
}

static int met_a_writelines(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "writelines", 1);
    PSArquivo *a;
    if (arq_exige(vm, alvo, "writelines", &a) != 0) return -1;
    if (arg_exige_seq(vm, args[0], "writelines") != 0) return -1;
    PSList *l = COMO_LIST(args[0]);
    for (int i = 0; i < l->len; i++) {
        /* bytes vão CRUS, como no write(): antes caíam no valor_para_texto e
         * o arquivo recebia a representação `b'a'` em vez do byte. */
        int e = 0;
        if (EH_BYTES(l->itens[i])) {
            PSString *by = COMO_BYTES(l->itens[i]);
            if (arq_grava(a->f, by->chars, (size_t)by->len, &e) != 0)
                return erro_sistema(vm, e, NULL, NULL);
            continue;
        }
        TXTBUF_AUTO t = {0};
        if (valor_para_texto(&t, &l->itens[i], 0) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
        if (arq_grava(a->f, t.b ? t.b : "", (size_t)t.n, &e) != 0)
            return erro_sistema(vm, e, NULL, NULL);
    }
    *out = MK_NULL();
    return 0;
}

static int met_a_close(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "close", 0, 0, n);
    if (!EH_ARQUIVO(alvo))
        MERRO(vm, "TypeError", "close() argument 1 must be PoolFile, not %s",
              nome_do_tipo_valor(alvo));
    PSArquivo *a = COMO_ARQ(alvo);
    /* O `fclose` faz o flush final, e é ali que o disco cheio costuma aparecer
     * — o `fwrite` só encheu o buffer da libc. Descartar este retorno é fechar
     * um arquivo truncado dizendo que deu certo. O `fechado` é marcado ANTES
     * de o erro subir: o descritor já foi embora de qualquer jeito, e deixar o
     * objeto "aberto" faria o finalizador do GC fechar de novo. */
    if (!a->fechado && a->f) {
        FILE *f = a->f;
        a->f = NULL; a->fechado = 1;
        errno = 0;
        if (fclose(f) != 0)
            return erro_sistema(vm, errno ? errno : EIO, NULL, NULL);
    }
    *out = MK_NULL();
    return 0;
}

static int cria_pais(const char *caminho);   /* definido mais abaixo */

/* Salva o conteúdo do arquivo num caminho (mesmo contrato dos outros .save():
 * pasta -> deriva o nome do próprio arquivo). Devolve o caminho final. */
static int met_a_save(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "save", 0, 1, n);
    /* `caminho=Null` (o default que a tabela declara) = ausente, como nos
     * vizinhos `=Null`; recusava o próprio default com TypeError */
    if (n == 1 && args[0].t != V_NULL && !EH_STRING(args[0]))
        MERRO(vm, "TypeError", "save() argument 1 must be str, not %s",
              nome_do_tipo_valor(args[0]));
    PSArquivo *a;
    if (arq_exige(vm, alvo, "save", &a) != 0) return -1;
    if (a->f) fflush(a->f);

    const char *destino = (n == 1 && EH_STRING(args[0])) ? COMO_STRING(args[0])->chars : ".";
    struct stat st;
    int eh_pasta = (strcmp(destino, ".") == 0 || strcmp(destino, "..") == 0
                    || (destino[0] && destino[strlen(destino) - 1] == '/')
                    || (stat(destino, &st) == 0 && S_ISDIR(st.st_mode)));
    const char *base = strrchr(a->caminho, '/');
    base = base ? base + 1 : a->caminho;
    char caminho[1024];
    if (eh_pasta) snprintf(caminho, sizeof(caminho), "%.500s/%.400s", destino, base);
    else          snprintf(caminho, sizeof(caminho), "%.1000s", destino);

    /* copia byte-a-byte, só se o destino for outro arquivo */
    char *rpa = realpath(caminho, NULL), *rpo = realpath(a->caminho, NULL);
    int mesmo = (rpa && rpo && strcmp(rpa, rpo) == 0);
    free(rpa); free(rpo);
    if (!mesmo) {
        cria_pais(caminho);
        FILE *src = fopen(a->caminho, "rb");
        if (!src) return erro_sistema(vm, errno, a->caminho, NULL);
        FILE *dst = fopen(caminho, "wb");
        if (!dst) { int e = errno; fclose(src); return erro_sistema(vm, e, caminho, NULL); }
        /* Os TRÊS pontos são conferidos, e cada um pega uma falha diferente:
         * o `fwrite` curto (disco cheio na hora), o `ferror(src)` (leitura que
         * parou por erro e não por fim de arquivo — indistinguíveis pelo
         * `fread`), e o `fclose(dst)` (o flush final). Sem eles, cópia
         * truncada voltava como sucesso, devolvendo o caminho do destino. */
        char buf[8192]; size_t r;
        int e = 0;
        while ((r = fread(buf, 1, sizeof(buf), src)) > 0)
            if (arq_grava(dst, buf, r, &e) != 0) break;
        if (!e && ferror(src)) e = EIO;
        fclose(src);
        errno = 0;
        if (fclose(dst) != 0 && !e) e = errno ? errno : EIO;
        if (e) {
            remove(caminho);   /* não deixa meia cópia no lugar do arquivo bom */
            return erro_sistema(vm, e, NULL, NULL);
        }
    }
    PSString *s = nova_string(vm, caminho, (int)strlen(caminho));
    if (!s) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(s);
    return 0;
}

/* Definidos junto do PoolFile carregado, mais abaixo — valem nos dois. */
static int met_pf_path(VM *vm, Value alvo, Value *args, int n, Value *out);
static int met_pf_move(VM *vm, Value alvo, Value *args, int n, Value *out);
static int met_pf_copy(VM *vm, Value alvo, Value *args, int n, Value *out);
static int met_pf_delete(VM *vm, Value alvo, Value *args, int n, Value *out);
static int met_pf_bytes(VM *vm, Value alvo, Value *args, int n, Value *out);

/* Um `PoolFile` aberto por `open()`. Os cinco últimos são os MESMOS métodos
 * do `PoolFile` carregado (`os.loadFile`): o tipo é um só, então o que vale
 * num vale no outro. Ver `pf_caminho`/`pf_exige_fechado`. */
static const MetodoNat METODOS_ARQ[] = {
    { "read", met_a_read, "n=-1" }, { "readline", met_a_readline, NULL },
    { "readlines", met_a_readlines, NULL }, { "write", met_a_write, "conteudo" },
    { "writelines", met_a_writelines, "linhas" }, { "close", met_a_close, NULL },
    { "save", met_a_save, "caminho=Null" },
    { "path", met_pf_path, NULL }, { "move", met_pf_move, "destino" },
    { "copy", met_pf_copy, "destino" }, { "delete", met_pf_delete, NULL },
    { "bytes", met_pf_bytes, NULL },
};

static int nativa_open(VM *vm, Value *args, int n, Value *out)
{
    if (n < 1 || n > 3) return erro_aridade(vm, "open", 1, 3, n);
    if (!EH_STRING(args[0])) BERRO(vm, "TypeError", "open() argument 1 must be str, not %s",
                                  nome_do_tipo_valor(args[0]));
    const char *modo = "r";
    if (n >= 2) {
        if (!EH_STRING(args[1])) BERRO(vm, "TypeError", "open() argument 2 must be str, not %s",
                                      nome_do_tipo_valor(args[1]));
        modo = COMO_STRING(args[1])->chars;
    }
    /* Valida o modo antes de abrir — senão um modo inválido ("Rb", "wz")
     * caía no fopen e virava o enganoso "arquivo nao encontrado". Mensagem
     * casa com o interp ("valor inválido: invalid mode: '...'"). */
    {
        int prim = 0, tb = 0, seen[128] = {0};
        for (const char *m = modo; *m; m++) {
            unsigned char ch = (unsigned char)*m;
            if (ch >= 128 || !strchr("xrwabt+", (int)*m) || seen[ch])
                BERRO(vm, "ValueError", "invalid mode: '%s'", modo);
            seen[ch] = 1;
            if (*m == 'r' || *m == 'w' || *m == 'a' || *m == 'x') prim++;
            if (*m == 't' || *m == 'b') tb++;
        }
        /* Sao DUAS frases aqui, e a diferenca nao e cosmetica: com
         * modo demais ("rw") sai minusculo e sem a parte do "plus"; sem
         * nenhum ("", "+") e a frase longa, com maiuscula. */
        if (prim > 1)
            BERRO(vm, "ValueError", "must have exactly one of create/read/write/append mode");
        if (prim == 0)
            BERRO(vm, "ValueError", "Must have exactly one of "
                  "create/read/write/append mode and at most one plus");
        if (tb > 1)
            BERRO(vm, "ValueError", "can't have text and binary mode at once");
    }
    /* fopen do C não entende 't'; tira (modo texto já é o padrão) */
    char cfmodo[8]; int ci = 0;
    for (const char *m = modo; *m && ci < 7; m++) if (*m != 't') cfmodo[ci++] = *m;
    cfmodo[ci] = '\0';

    /* o 3º argumento é `encoding` no interpretador; aqui tudo é UTF-8 e o
     * valor é aceito e ignorado, pra o mesmo `.ps` rodar nos dois */
    PSString *cam = COMO_STRING(args[0]);
    /* O fopen("r") do Linux ABRE um diretório sem reclamar; só o read()
     * depois falha, e falhava calado (devolvia ""). Barra aqui. */
    {
        struct stat st;
        if (stat(cam->chars, &st) == 0 && S_ISDIR(st.st_mode))
            return erro_sistema(vm, EISDIR, cam->chars, NULL);
    }
    FILE *f = fopen(cam->chars, cfmodo);
    if (!f) return erro_sistema(vm, errno, cam->chars, NULL);

    PSArquivo *a = calloc(1, sizeof(PSArquivo));
    if (!a) { fclose(f); BERRO(vm, "MemoryError", "sem memoria"); }
    a->obj.type = OBJ_ARQUIVO; a->obj.marked = 0;
    a->obj.next = vm->objetos; vm->objetos = (Obj *)a;
    a->f = f;
    a->fechado = 0;
    a->binario = strchr(modo, 'b') != NULL;
    snprintf(a->caminho, sizeof(a->caminho), "%s", cam->chars);
    vm->alocado += sizeof(PSArquivo);
    *out = MK_OBJ(a);
    return 0;
}


/* ── bytes ──────────────────────────────────────────────────────────────── */
static PSString *novo_bytes(VM *vm, const char *dados, int n)
{
    PSString *b = malloc(sizeof(PSString) + (size_t)n + 1);
    if (!b) return NULL;
    b->obj.type = OBJ_BYTES; b->obj.marked = 0;
    b->obj.next = vm->objetos; vm->objetos = (Obj *)b;
    b->len = n;
    memcpy(b->chars, dados, (size_t)n);
    b->chars[n] = '\0';
    b->hash = hash_str(b->chars, n);
    vm->alocado += sizeof(PSString) + (size_t)n + 1;
    return b;
}

/* ── codecs de encode()/decode() ─────────────────────────────────────────
 * Antes o argumento `encoding` era ACEITO E IGNORADO: `"café".encode("latin-1")`
 * devolvia UTF-8 e `b.decode("naoexiste")` passava batido. Agora o nome é
 * resolvido de verdade e o que não dá pra representar vira erro (ou some /
 * vira '?' se o `errors` pedir). */
enum { CODEC_UTF8, CODEC_LATIN1, CODEC_ASCII, CODEC_UTF16LE, CODEC_UTF16BE, CODEC_UTF32LE, CODEC_UTF32BE };

/* Normaliza o nome: caixa e os separadores `-`/`_`/espaço não contam. */
static int codec_de_nome(const char *nome, int len)
{
    char n[32];
    int j = 0;
    for (int i = 0; i < len && j < (int)sizeof(n) - 1; i++) {
        char c = nome[i];
        if (c == '-' || c == '_' || c == ' ') continue;
        n[j++] = (char)((c >= 'A' && c <= 'Z') ? c + 32 : c);
    }
    n[j] = '\0';
    if (!strcmp(n, "utf8") || !strcmp(n, "u8") || !strcmp(n, "utf")) return CODEC_UTF8;
    if (!strcmp(n, "latin1") || !strcmp(n, "iso88591") || !strcmp(n, "l1")
        || !strcmp(n, "latin") || !strcmp(n, "8859") || !strcmp(n, "cp819")) return CODEC_LATIN1;
    if (!strcmp(n, "ascii") || !strcmp(n, "usascii") || !strcmp(n, "646")) return CODEC_ASCII;
    if (!strcmp(n, "utf16le") || !strcmp(n, "utf16")) return CODEC_UTF16LE;
    if (!strcmp(n, "utf16be")) return CODEC_UTF16BE;
    if (!strcmp(n, "utf32le") || !strcmp(n, "utf32")) return CODEC_UTF32LE;
    if (!strcmp(n, "utf32be")) return CODEC_UTF32BE;
    return -1;
}

enum { ERRO_STRICT, ERRO_IGNORE, ERRO_REPLACE };

static int politica_erro(const char *nome, int len)
{
    if (len == 6 && !memcmp(nome, "strict", 6))  return ERRO_STRICT;
    if (len == 6 && !memcmp(nome, "ignore", 6))  return ERRO_IGNORE;
    if (len == 7 && !memcmp(nome, "replace", 7)) return ERRO_REPLACE;
    return -1;
}

/* Lê os argumentos comuns de encode()/decode(): (encoding, errors). */
static int codec_args(VM *vm, Value *args, int n, const char *quem, int *codec, int *pol)
{
    *codec = CODEC_UTF8; *pol = ERRO_STRICT;
    if (n > 2) { snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
                 return erro_aridade(vm, quem, 0, 2, n); }
    if (n >= 1 && args[0].t != V_NULL) {
        if (!EH_STRING(args[0])) { snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
            snprintf(vm->erro, sizeof(vm->erro), "%s() argument 'encoding' must be str, not %s",
                     quem, nome_do_tipo_valor(args[0])); return -1; }
        PSString *e = COMO_STRING(args[0]);
        *codec = codec_de_nome(e->chars, e->len);
        if (*codec < 0) { snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "LookupError");
            snprintf(vm->erro, sizeof(vm->erro), "unknown encoding: %s", e->chars); return -1; }
    }
    if (n >= 2 && args[1].t != V_NULL) {
        if (!EH_STRING(args[1])) { snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
            snprintf(vm->erro, sizeof(vm->erro), "%s() argument 'errors' must be str, not %s",
                     quem, nome_do_tipo_valor(args[1])); return -1; }
        PSString *e = COMO_STRING(args[1]);
        *pol = politica_erro(e->chars, e->len);
        if (*pol < 0) { snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "LookupError");
            snprintf(vm->erro, sizeof(vm->erro), "unknown error handler name '%s'", e->chars);
            return -1; }
    }
    return 0;
}

/* Decodifica um caractere UTF-8 VALIDANDO (sequência curta, continuação
 * errada, overlong, surrogate, acima de U+10FFFF). -1 se inválido. */
static int utf8_le_estrito(const unsigned char *b, int len, int i, uint32_t *cp)
{
    if (i >= len) return -1;
    unsigned char c = b[i];
    int k;
    uint32_t v;
    if (c < 0x80)            { *cp = c; return 1; }
    else if ((c & 0xE0) == 0xC0) { k = 2; v = c & 0x1F; }
    else if ((c & 0xF0) == 0xE0) { k = 3; v = c & 0x0F; }
    else if ((c & 0xF8) == 0xF0) { k = 4; v = c & 0x07; }
    else return -1;                              /* 0x80-0xBF solto ou 0xF8+ */
    if (i + k > len) return -1;
    for (int t = 1; t < k; t++) {
        if ((b[i + t] & 0xC0) != 0x80) return -1;
        v = (v << 6) | (uint32_t)(b[i + t] & 0x3F);
    }
    if ((k == 2 && v < 0x80) || (k == 3 && v < 0x800) || (k == 4 && v < 0x10000))
        return -1;                               /* overlong */
    if (v >= 0xD800 && v <= 0xDFFF) return -1;   /* surrogate solto */
    if (v > 0x10FFFF) return -1;
    *cp = v;
    return k;
}

static int codec_por_16(int codec) { return codec == CODEC_UTF16LE || codec == CODEC_UTF16BE; }
static int codec_por_32(int codec) { return codec == CODEC_UTF32LE || codec == CODEC_UTF32BE; }

/* O nome que vai na mensagem do codec: `'ascii' codec can't ...`.
 * Nao e o nome que o usuario escreveu (`"utf16"`), e o canonico do codec. */
static const char *nome_do_codec(int c)
{
    switch (c) {
        case CODEC_LATIN1:  return "latin-1";
        case CODEC_ASCII:   return "ascii";
        case CODEC_UTF16LE: return "utf-16-le";
        case CODEC_UTF16BE: return "utf-16-be";
        case CODEC_UTF32LE: return "utf-32-le";
        case CODEC_UTF32BE: return "utf-32-be";
        default:            return "utf-8";
    }
}

/* POR QUE o UTF-8 falhou, na frase padrao de cada motivo. O `utf8_le_estrito` so devolve
 * -1; sem esta classificacao a mensagem teria que chutar um dos tres motivos,
 * e chutar errado e trocar um portugues honesto por um ingles mentiroso. */
static const char *utf8_porque(const unsigned char *b, int len, int i)
{
    unsigned char c = b[i];
    if (c < 0xC2 || c > 0xF4) return "invalid start byte";
    int n = c < 0xE0 ? 2 : (c < 0xF0 ? 3 : 4);
    for (int j = 1; j < n; j++) {
        unsigned char lo = 0x80, hi = 0xBF;
        if (j == 1) {
            if (c == 0xE0)      lo = 0xA0;   /* overlong */
            else if (c == 0xED) hi = 0x9F;   /* surrogate */
            else if (c == 0xF0) lo = 0x90;   /* overlong */
            else if (c == 0xF4) hi = 0x8F;   /* acima de U+10FFFF */
        }
        if (i + j >= len) return "unexpected end of data";
        if (b[i + j] < lo || b[i + j] > hi) return "invalid continuation byte";
    }
    return "invalid start byte";
}

static int met_encode(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    int codec, pol;
    if (codec_args(vm, args, n, "encode", &codec, &pol) != 0) return -1;
    PSString *s = COMO_STRING(alvo);
    if (codec == CODEC_UTF8) {          /* a linguagem já é UTF-8: cópia crua */
        PSString *b = novo_bytes(vm, s->chars, s->len);
        if (!b) MERRO(vm, "MemoryError", "sem memoria");
        *out = MK_OBJ(b);
        return 0;
    }
    SBUF_AUTO sb = {0};
    for (int i = 0; i < s->len; ) {
        uint32_t cp;
        int k = utf8_le(s->chars, s->len, i, &cp);
        if (!k) break;
        i += k;
        uint32_t teto = codec == CODEC_ASCII ? 0x80 : (codec == CODEC_LATIN1 ? 0x100 : 0x110000);
        if (cp >= teto) {
            if (pol == ERRO_IGNORE) continue;
            if (pol == ERRO_REPLACE) cp = '?';
            else {
                /* Os caracteres SEGUIDOS que nao cabem viram uma
                 * faixa (`characters in position 1-2`); o caractere so e citado
                 * quando e um so. A posicao e em CARACTERES, nao em bytes. */
                int ini = utf8_conta(s->chars, i - k), corre = 1;
                for (int j = i; j < s->len; ) {
                    uint32_t c2;
                    int k2 = utf8_le(s->chars, s->len, j, &c2);
                    if (!k2 || c2 < teto) break;
                    corre++; j += k2;
                }
                if (corre > 1)
                    MERRO(vm, "UnicodeEncodeError",
                          "'%s' codec can't encode characters in position %d-%d: "
                          "ordinal not in range(%u)",
                          nome_do_codec(codec), ini, ini + corre - 1, (unsigned)teto);
                char esc[16];
                if (cp < 0x100)        snprintf(esc, sizeof(esc), "\\x%02x", (unsigned)cp);
                else if (cp < 0x10000) snprintf(esc, sizeof(esc), "\\u%04x", (unsigned)cp);
                else                   snprintf(esc, sizeof(esc), "\\U%08x", (unsigned)cp);
                MERRO(vm, "UnicodeEncodeError",
                      "'%s' codec can't encode character '%s' in position %d: "
                      "ordinal not in range(%u)",
                      nome_do_codec(codec), esc, ini, (unsigned)teto);
            }
        }
        char buf[4];
        int nb;
        if (codec_por_16(codec)) {
            if (cp >= 0x10000) {        /* fora do BMP: par de surrogates */
                uint32_t u = cp - 0x10000, hi = 0xD800 + (u >> 10), lo = 0xDC00 + (u & 0x3FF);
                char q[4];
                if (codec == CODEC_UTF16LE) { q[0]=(char)(hi&0xFF); q[1]=(char)(hi>>8); q[2]=(char)(lo&0xFF); q[3]=(char)(lo>>8); }
                else                        { q[0]=(char)(hi>>8); q[1]=(char)(hi&0xFF); q[2]=(char)(lo>>8); q[3]=(char)(lo&0xFF); }
                if (sb_bytes(&sb, q, 4) != 0) { MERRO(vm, "MemoryError", "sem memoria em encode()"); }
                continue;
            }
            if (codec == CODEC_UTF16LE) { buf[0]=(char)(cp&0xFF); buf[1]=(char)((cp>>8)&0xFF); }
            else                        { buf[0]=(char)((cp>>8)&0xFF); buf[1]=(char)(cp&0xFF); }
            nb = 2;
        } else if (codec_por_32(codec)) {
            if (codec == CODEC_UTF32LE) { buf[0]=(char)(cp&0xFF); buf[1]=(char)((cp>>8)&0xFF); buf[2]=(char)((cp>>16)&0xFF); buf[3]=(char)((cp>>24)&0xFF); }
            else                        { buf[0]=(char)((cp>>24)&0xFF); buf[1]=(char)((cp>>16)&0xFF); buf[2]=(char)((cp>>8)&0xFF); buf[3]=(char)(cp&0xFF); }
            nb = 4;
        } else {
            buf[0] = (char)(unsigned char)cp;
            nb = 1;
        }
        if (sb_bytes(&sb, buf, nb) != 0) { MERRO(vm, "MemoryError", "sem memoria em encode()"); }
    }
    PSString *b = novo_bytes(vm, sb.b ? sb.b : "", sb.n);
    if (!b) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(b);
    return 0;
}

static int met_b_decode(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    int codec, pol;
    if (codec_args(vm, args, n, "decode", &codec, &pol) != 0) return -1;
    PSString *b = COMO_BYTES(alvo);
    const unsigned char *p = (const unsigned char *)b->chars;
    SBUF_AUTO sb = {0};
    if (codec == CODEC_UTF8) {
        for (int i = 0; i < b->len; ) {
            uint32_t cp;
            int k = utf8_le_estrito(p, b->len, i, &cp);
            if (k < 0) {
                if (pol == ERRO_STRICT)
                    MERRO(vm, "UnicodeDecodeError",
                          "'%s' codec can't decode byte 0x%02x in position %d: %s",
                          nome_do_codec(codec), p[i], i, utf8_porque(p, b->len, i));
                if (pol == ERRO_REPLACE && sb_cp(&sb, 0xFFFD) != 0)
                    MERRO(vm, "MemoryError", "sem memoria em decode()");
                i++;
                continue;
            }
            if (sb_bytes(&sb, (const char *)p + i, k) != 0) { MERRO(vm, "MemoryError", "sem memoria em decode()"); }
            i += k;
        }
    } else if (codec_por_16(codec) || codec_por_32(codec)) {
        int passo = codec_por_16(codec) ? 2 : 4;
        for (int i = 0; i + passo <= b->len; i += passo) {
            uint32_t cp;
            if (passo == 2)
                cp = codec == CODEC_UTF16LE ? (uint32_t)(p[i] | (p[i+1] << 8))
                                            : (uint32_t)((p[i] << 8) | p[i+1]);
            else
                cp = codec == CODEC_UTF32LE
                     ? ((uint32_t)p[i] | ((uint32_t)p[i+1] << 8) | ((uint32_t)p[i+2] << 16) | ((uint32_t)p[i+3] << 24))
                     : (((uint32_t)p[i] << 24) | ((uint32_t)p[i+1] << 16) | ((uint32_t)p[i+2] << 8) | (uint32_t)p[i+3]);
            if (passo == 2 && cp >= 0xD800 && cp <= 0xDBFF && i + 4 <= b->len) {
                uint32_t lo = codec == CODEC_UTF16LE ? (uint32_t)(p[i+2] | (p[i+3] << 8))
                                                     : (uint32_t)((p[i+2] << 8) | p[i+3]);
                if (lo >= 0xDC00 && lo <= 0xDFFF) {
                    cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    i += 2;
                }
            }
            if (cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
                if (pol == ERRO_STRICT)
                {
                    const char *porque =
                        codec_por_16(codec)
                            ? (cp >= 0xD800 && cp <= 0xDBFF && i + 4 > b->len
                                   ? "unexpected end of data" : "illegal UTF-16 surrogate")
                            : (cp > 0x10FFFF
                                   ? "code point not in range(0x110000)"
                                   : "code point in surrogate code point range(0xd800, 0xe000)");
                    MERRO(vm, "UnicodeDecodeError",
                          "'%s' codec can't decode bytes in position %d-%d: %s",
                          nome_do_codec(codec), i, i + passo - 1, porque);
                }
                if (pol == ERRO_IGNORE) continue;
                cp = 0xFFFD;
            }
            if (sb_cp(&sb, cp) != 0) { MERRO(vm, "MemoryError", "sem memoria em decode()"); }
        }
        if (b->len % passo != 0 && pol == ERRO_STRICT) {
            int resto = b->len - b->len % passo;
            MERRO(vm, "UnicodeDecodeError",
                  "'%s' codec can't decode byte 0x%02x in position %d: truncated data",
                  nome_do_codec(codec), p[resto], resto);
        }
    } else {
        /* latin-1 casa 1 byte = 1 codepoint (nunca falha); ascii recusa >127 */
        for (int i = 0; i < b->len; i++) {
            if (codec == CODEC_ASCII && p[i] >= 0x80) {
                if (pol == ERRO_STRICT)
                    MERRO(vm, "UnicodeDecodeError",
                          "'%s' codec can't decode byte 0x%02x in position %d: "
                          "ordinal not in range(128)", nome_do_codec(codec), p[i], i);
                if (pol == ERRO_IGNORE) continue;
                if (sb_cp(&sb, 0xFFFD) != 0) { MERRO(vm, "MemoryError", "sem memoria em decode()"); }
                continue;
            }
            if (sb_cp(&sb, p[i]) != 0) { MERRO(vm, "MemoryError", "sem memoria em decode()"); }
        }
    }
    return devolve_sbuf(vm, &sb, out);
}

/* `b.len()` — quantidade de BYTES.
 *
 * Conta byte, não codepoint, e isso é o ponto: `"ção".encode().len()` é 5,
 * enquanto `"ção".len()` é 3. Bytes não sabem o que é caractere; quem decide
 * isso é o `decode()`. O método tem que devolver EXATAMENTE o que o builtin
 * `len(b)` devolve — dois números diferentes pra mesma pergunta seria pior que
 * não ter o método.
 *
 * POR QUE ELE PASSOU A EXISTIR: `bytes` era o único tipo embutido sem `.len()`
 * (str, list, dict e tup têm). Quem escreve `pedaco.len()` depois de usar o
 * mesmo em str tomava "membro inexistente" em tempo de execução — e num `try`
 * isso vira falha silenciosa. Custou seis testes de protocolo cru reprovando
 * com a causa invisível em `teste/jinker_roda.ps`. */
static int met_b_len(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "len", 0, 0, n);
    *out = MK_INT(COMO_BYTES(alvo)->len);
    return 0;
}

/* `b.hex()`, `b.hex(sep)`, `b.hex(sep, n_por_grupo)`.
 *
 * O separador entra a cada `n` bytes. `n` POSITIVO agrupa da direita pra
 * esquerda e NEGATIVO da esquerda pra direita — a regra
 * existe porque número em hexadecimal se lê do fim (`hex("_", 4)` de um MAC ou
 * de um inteiro dá os grupos alinhados pelo dígito menos significativo). */
static int met_b_hex(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 2) return erro_aridade(vm, "hex", 0, 2, n);
    PSString *b = COMO_BYTES(alvo);
    char sep = 0;
    if (n >= 1 && args[0].t != V_NULL) {
        if (!EH_STRING(args[0]) && !EH_BYTES(args[0]))
            MERRO(vm, "TypeError", "sep must be str or bytes, not %s",
                  nome_do_tipo_valor(args[0]));
        /* str e bytes têm o mesmo cabeçalho PSString; o que muda é o obj.type */
        PSString *sp = (PSString *)args[0].as.obj;
        if (sp->len != 1) MERRO(vm, "ValueError", "sep must be length 1.");
        sep = sp->chars[0];
    }
    int64_t grupo = 1;
    if (n == 2 && args[1].t != V_NULL) {
        if (args[1].t != V_INT)
            MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[1]));
        grupo = args[1].as.i;
    }
    if (!sep) grupo = 0;                 /* sem separador, não há o que agrupar */
    SBUF_AUTO sb = {0};
    for (int i = 0; i < b->len; i++) {
        if (grupo > 0 && i > 0 && (b->len - i) % grupo == 0) {
            if (sb_bytes(&sb, &sep, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
        } else if (grupo < 0 && i > 0 && i % (-grupo) == 0) {
            if (sb_bytes(&sb, &sep, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
        }
        char par[3];
        snprintf(par, sizeof(par), "%02x", (unsigned char)b->chars[i]);
        if (sb_bytes(&sb, par, 2) != 0) { MERRO(vm, "MemoryError", "sem memoria"); }
    }
    return devolve_sbuf(vm, &sb, out);
}

/* ── bytes: a superfície completa ────────────────────────────────────────
 *
 * POR QUE ISTO EXISTE: `bytes` tinha três métodos — `decode`, `hex` e `len`.
 * Faltava tudo o que serve pra CONFERIR o conteúdo: `find`, `startswith`,
 * `split`, `count`, `in`. O efeito prático apareceu escrevendo o teste do
 * vazamento do jinker: pra provar que a resposta não tinha byte NUL foi
 * preciso converter tudo pra hexadecimal e varrer a string em passos de dois,
 * porque `\x00 in resposta` não existia. Conferência que precisa de rodeio é
 * conferência que ninguém escreve.
 *
 * Método por método, incluindo as
 * diferenças que `bytes` tem em relação ao `str` e que é fácil errar copiando:
 *
 *   - `upper`/`lower`/`title` mexem só no ASCII. `b"\xc0".lower()` é `b"\xc0"`.
 *   - `splitlines` quebra em `\n`, `\r` e `\r\n` e MAIS NADA — o mesmo que
 *     o `str` (`met_splitlines`); `\x0b`/`\x0c` ficam dentro da linha nos dois.
 *   - `find`/`count`/`index` aceitam um INTEIRO (0..255) além de bytes.
 *   - `strip(chars)` é CONJUNTO de bytes, não prefixo.
 *
 * As mensagens de erro são as frases padrão de cada caso, colhidas
 * rodando cada um — não reescritas.
 */

/* Bytes prontos pra devolver. O `(dados && n > 0) ? dados : ""` é porque
 * `memcpy(NULL, 0)` é comportamento indefinido, mesmo copiando zero byte.
 *
 * Esta função já existia mais abaixo, servindo o módulo `bytes`; subiu pra cá
 * porque os métodos precisam dela antes. Ordem dos argumentos preservada — dois
 * helpers iguais com ordens diferentes é armadilha. */
static int by_devolve(VM *vm, Value *out, const char *dados, int n)
{
    PSString *b = novo_bytes(vm, (dados && n > 0) ? dados : "", n);
    if (!b) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(b);
    return 0;
}

static int by_devolve_sbuf(VM *vm, SBuf *s, Value *out)
{
    PSString *r = novo_bytes(vm, s->b ? s->b : "", s->n);
    free(s->b);
    s->b = NULL; s->n = 0; s->cap = 0;
    if (!r) MERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(r);
    return 0;
}

/* O alvo, sempre. */
#define BY_EU(alvo, p, n) \
    const unsigned char *p = (const unsigned char *)COMO_BYTES(alvo)->chars; \
    int n = COMO_BYTES(alvo)->len

/* Argumento "bytes-like". */
static int by_like(VM *vm, Value v, const unsigned char **p, int *n)
{
    if (!EH_BYTES(v))
        MERRO(vm, "TypeError", "a bytes-like object is required, not '%s'",
              nome_do_tipo_valor(v));
    PSString *b = COMO_BYTES(v);
    *p = (const unsigned char *)b->chars;
    *n = b->len;
    return 0;
}

/* Agulha de `find`/`rfind`/`index`/`rindex`/`count`: bytes OU inteiro 0..255.
 * `um` é onde o byte solto fica guardado — o chamador passa um char da pilha
 * dele, porque o ponteiro devolvido tem que sobreviver à volta. */
static int by_agulha(VM *vm, Value v, const unsigned char **p, int *n,
                     unsigned char *um)
{
    if (EH_BYTES(v)) {
        PSString *b = COMO_BYTES(v);
        *p = (const unsigned char *)b->chars;
        *n = b->len;
        return 0;
    }
    if (v.t == V_INT || (v.t == V_OBJ && v.as.obj->type == OBJ_BIGINT)) {
        /* bigint nunca cabe num byte: mesmo erro do int fora de 0..255 */
        if (v.t != V_INT || v.as.i < 0 || v.as.i > 255)
            MERRO(vm, "ValueError", "byte must be in range(0, 256)");
        *um = (unsigned char)v.as.i;
        *p = um;
        *n = 1;
        return 0;
    }
    MERRO(vm, "TypeError",
          "argument should be integer or bytes-like object, not '%s'",
          nome_do_tipo_valor(v));
}

/* `inicio`/`fim` do jeito de fatia: negativo conta do fim, estouro grampeia.
 * Aqui é ÍNDICE DE BYTE direto — sem a conversão de codepoint que o `str`
 * precisa fazer, e é justamente essa a diferença entre os dois tipos. */
static int by_faixa(VM *vm, int total, Value *args, int n, int *b0, int *b1)
{
    int64_t i0 = 0, i1 = total;
    if (n >= 2 && args[1].t != V_NULL) {
        if (args[1].t != V_INT)
            MERRO(vm, "TypeError",
                  "slice indices must be integers or None"
                  " or have an __index__ method");
        i0 = args[1].as.i;
        if (i0 < 0) i0 += total;
        if (i0 < 0) i0 = 0;
        if (i0 > total) i0 = total;
    }
    if (n >= 3 && args[2].t != V_NULL) {
        if (args[2].t != V_INT)
            MERRO(vm, "TypeError",
                  "slice indices must be integers or None"
                  " or have an __index__ method");
        i1 = args[2].as.i;
        if (i1 < 0) i1 += total;
        if (i1 < 0) i1 = 0;
        if (i1 > total) i1 = total;
    }
    *b0 = (int)i0;
    *b1 = (int)i1;
    return 0;
}

/* ASCII e só ASCII: caixa em `bytes` não toca byte >= 0x80. */
static int by_up(int c)   { return (c >= 'a' && c <= 'z') ? c - 32 : c; }
static int by_low(int c)  { return (c >= 'A' && c <= 'Z') ? c + 32 : c; }
static int by_eh_up(int c)  { return c >= 'A' && c <= 'Z'; }
static int by_eh_low(int c) { return c >= 'a' && c <= 'z'; }
static int by_eh_alpha(int c) { return by_eh_up(c) || by_eh_low(c); }
static int by_eh_dig(int c) { return c >= '0' && c <= '9'; }
static int by_eh_ws(int c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f';
}

static int by_acha(const unsigned char *s, int slen,
                   const unsigned char *ag, int alen, int de)
{
    if (alen == 0) return de <= slen ? de : -1;
    for (int i = de; i + alen <= slen; i++)
        if (memcmp(s + i, ag, (size_t)alen) == 0) return i;
    return -1;
}

static int by_racha(const unsigned char *s, int slen,
                    const unsigned char *ag, int alen)
{
    if (alen == 0) return slen;
    for (int i = slen - alen; i >= 0; i--)
        if (memcmp(s + i, ag, (size_t)alen) == 0) return i;
    return -1;
}

/* ── busca ──────────────────────────────────────────────────────────────── */

static int by_busca(VM *vm, Value alvo, Value *args, int n, Value *out,
                    const char *quem, int reverso, int levanta)
{
    if (n < 1 || n > 3) return erro_aridade(vm, quem, 1, 3, n);
    BY_EU(alvo, s, slen);
    unsigned char um;
    const unsigned char *ag;
    int alen;
    if (by_agulha(vm, args[0], &ag, &alen, &um) != 0) return -1;
    int b0 = 0, b1 = slen;
    if (by_faixa(vm, slen, args, n, &b0, &b1) != 0) return -1;
    int achou = -1;
    if (b1 >= b0) {
        achou = reverso ? by_racha(s + b0, b1 - b0, ag, alen)
                        : by_acha(s + b0, b1 - b0, ag, alen, 0);
        if (achou >= 0) achou += b0;
    }
    if (achou < 0) {
        /* `index`/`rindex` levantam, e a frase do bytes NÃO é a do str:
         * "subsection not found", não "substring not found" */
        if (levanta) MERRO(vm, "ValueError", "subsection not found");
        *out = MK_INT(-1);
        return 0;
    }
    *out = MK_INT(achou);
    return 0;
}

static int met_b_find(VM *v, Value a, Value *g, int n, Value *o)   { return by_busca(v, a, g, n, o, "find", 0, 0); }
static int met_b_rfind(VM *v, Value a, Value *g, int n, Value *o)  { return by_busca(v, a, g, n, o, "rfind", 1, 0); }
static int met_b_index(VM *v, Value a, Value *g, int n, Value *o)  { return by_busca(v, a, g, n, o, "index", 0, 1); }
static int met_b_rindex(VM *v, Value a, Value *g, int n, Value *o) { return by_busca(v, a, g, n, o, "rindex", 1, 1); }

static int met_b_count(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 1 || n > 3) return erro_aridade(vm, "count", 1, 3, n);
    BY_EU(alvo, s, slen);
    unsigned char um;
    const unsigned char *ag;
    int alen;
    if (by_agulha(vm, args[0], &ag, &alen, &um) != 0) return -1;
    int b0 = 0, b1 = slen;
    if (by_faixa(vm, slen, args, n, &b0, &b1) != 0) return -1;
    if (b1 < b0) { *out = MK_INT(0); return 0; }
    int janela = b1 - b0;
    /* agulha vazia: conta as POSIÇÕES, que são len+1 */
    if (alen == 0) { *out = MK_INT(janela + 1); return 0; }
    int64_t c = 0;
    for (int i = 0; i + alen <= janela; ) {
        if (memcmp(s + b0 + i, ag, (size_t)alen) == 0) { c++; i += alen; }
        else i++;
    }
    *out = MK_INT(c);
    return 0;
}

static int met_b_contains(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "contains", 1);
    BY_EU(alvo, s, slen);
    unsigned char um;
    const unsigned char *ag;
    int alen;
    if (by_agulha(vm, args[0], &ag, &alen, &um) != 0) return -1;
    *out = MK_BOOL(by_acha(s, slen, ag, alen, 0) >= 0);
    return 0;
}

/* `startswith`/`endswith`: bytes, ou tupla/lista de bytes ("bate com qualquer
 * uma"), com `inicio`/`fim` opcionais. */
static int by_borda(VM *vm, Value alvo, Value *args, int n, Value *out,
                    const char *quem, int fim)
{
    if (n < 1 || n > 3) return erro_aridade(vm, quem, 1, 3, n);
    BY_EU(alvo, s, slen);
    int b0 = 0, b1 = slen;
    if (by_faixa(vm, slen, args, n, &b0, &b1) != 0) return -1;
    if (b1 < b0) b1 = b0;
    int janela = b1 - b0;

    Value *opcoes = &args[0];
    int nopc = 1;
    if (EH_SEQ(args[0])) {
        PSList *l = COMO_LIST(args[0]);   /* tupla e lista têm o mesmo cabeçalho */
        opcoes = l->itens;
        nopc = l->len;
    }
    for (int i = 0; i < nopc; i++) {
        if (!EH_BYTES(opcoes[i]))
            MERRO(vm, "TypeError",
                  "%s first arg must be bytes or a tuple of bytes, not %s",
                  quem, nome_do_tipo_valor(opcoes[i]));
        PSString *p = COMO_BYTES(opcoes[i]);
        if (p->len > janela) continue;
        const unsigned char *base = fim ? s + b1 - p->len : s + b0;
        if (memcmp(base, p->chars, (size_t)p->len) == 0) { *out = MK_BOOL(1); return 0; }
    }
    *out = MK_BOOL(0);
    return 0;
}

static int met_b_startswith(VM *v, Value a, Value *g, int n, Value *o) { return by_borda(v, a, g, n, o, "startswith", 0); }
static int met_b_endswith(VM *v, Value a, Value *g, int n, Value *o)   { return by_borda(v, a, g, n, o, "endswith", 1); }

/* ── caixa ──────────────────────────────────────────────────────────────── */

static int by_mapa(VM *vm, Value alvo, Value *out, const char *quem, int n, int modo)
{
    if (n != 0) return erro_aridade(vm, quem, 0, 0, n);
    BY_EU(alvo, s, slen);
    SBUF_AUTO b = {0};
    int anterior_cased = 0;
    for (int i = 0; i < slen; i++) {
        int c = s[i];
        switch (modo) {
            case 0: c = by_up(c); break;                     /* upper */
            case 1: c = by_low(c); break;                    /* lower */
            case 2: c = by_eh_up(c) ? by_low(c) : by_up(c); break;  /* swapcase */
            case 3: c = i == 0 ? by_up(c) : by_low(c); break;       /* capitalize */
            case 4:                                          /* title */
                c = anterior_cased ? by_low(c) : by_up(c);
                anterior_cased = by_eh_alpha(s[i]);
                break;
        }
        char ch = (char)c;
        if (sb_bytes(&b, &ch, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
    }
    return by_devolve_sbuf(vm, &b, out);
}

static int met_b_upper(VM *v, Value a, Value *g, int n, Value *o)      { (void)g; return by_mapa(v, a, o, "upper", n, 0); }
static int met_b_lower(VM *v, Value a, Value *g, int n, Value *o)      { (void)g; return by_mapa(v, a, o, "lower", n, 1); }
static int met_b_swapcase(VM *v, Value a, Value *g, int n, Value *o)   { (void)g; return by_mapa(v, a, o, "swapcase", n, 2); }
static int met_b_capitalize(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_mapa(v, a, o, "capitalize", n, 3); }
static int met_b_title(VM *v, Value a, Value *g, int n, Value *o)      { (void)g; return by_mapa(v, a, o, "title", n, 4); }

/* ── predicados ─────────────────────────────────────────────────────────── */

/* Vazio é FALSO em todos, menos no `isascii` — é o tipo
 * de detalhe que só aparece quando alguém passa uma resposta vazia. */
static int by_pred(VM *vm, Value alvo, Value *out, const char *quem, int n, int qual)
{
    if (n != 0) return erro_aridade(vm, quem, 0, 0, n);
    BY_EU(alvo, s, slen);
    if (qual == 7) {                       /* isascii: vazio é True */
        for (int i = 0; i < slen; i++) if (s[i] > 0x7f) { *out = MK_BOOL(0); return 0; }
        *out = MK_BOOL(1);
        return 0;
    }
    if (slen == 0) { *out = MK_BOOL(0); return 0; }
    int viu_cased = 0, ok = 1, anterior_cased = 0;
    for (int i = 0; i < slen && ok; i++) {
        int c = s[i];
        switch (qual) {
            case 0: ok = by_eh_alpha(c); break;                     /* isalpha */
            case 1: ok = by_eh_dig(c); break;                       /* isdigit */
            case 2: ok = by_eh_alpha(c) || by_eh_dig(c); break;     /* isalnum */
            case 3: ok = by_eh_ws(c); break;                        /* isspace */
            case 4:                                                 /* isupper */
                if (by_eh_low(c)) ok = 0;
                if (by_eh_alpha(c)) viu_cased = 1;
                break;
            case 5:                                                 /* islower */
                if (by_eh_up(c)) ok = 0;
                if (by_eh_alpha(c)) viu_cased = 1;
                break;
            case 6:                                                 /* istitle */
                if (by_eh_alpha(c)) {
                    if (anterior_cased) { if (by_eh_up(c)) ok = 0; }
                    else                { if (by_eh_low(c)) ok = 0; }
                    viu_cased = 1;
                }
                anterior_cased = by_eh_alpha(c);
                break;
        }
    }
    if (qual >= 4 && qual <= 6 && !viu_cased) ok = 0;   /* sem letra, é falso */
    *out = MK_BOOL(ok);
    return 0;
}

static int met_b_isalpha(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "isalpha", n, 0); }
static int met_b_isdigit(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "isdigit", n, 1); }
static int met_b_isalnum(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "isalnum", n, 2); }
static int met_b_isspace(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "isspace", n, 3); }
static int met_b_isupper(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "isupper", n, 4); }
static int met_b_islower(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "islower", n, 5); }
static int met_b_istitle(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "istitle", n, 6); }
static int met_b_isascii(VM *v, Value a, Value *g, int n, Value *o) { (void)g; return by_pred(v, a, o, "isascii", n, 7); }

/* ── aparar ─────────────────────────────────────────────────────────────── */

/* `chars` é CONJUNTO de bytes, não prefixo — `b"xyaXbyx".strip(b"xy")` é
 * `b"aXb"`. Sem argumento, o conjunto é o branco ASCII. */
static int by_apara(VM *vm, Value alvo, Value *args, int n, Value *out,
                    const char *quem, int esq, int dir)
{
    if (n > 1) return erro_aridade(vm, quem, 0, 1, n);
    BY_EU(alvo, s, slen);
    const unsigned char *set = NULL;
    int nset = 0;
    if (n == 1 && args[0].t != V_NULL) {
        if (by_like(vm, args[0], &set, &nset) != 0) return -1;
    }
    int a = 0, b = slen;
    if (esq) {
        while (a < b) {
            int c = s[a];
            int bate = set ? (memchr(set, c, (size_t)nset) != NULL) : by_eh_ws(c);
            if (!bate) break;
            a++;
        }
    }
    if (dir) {
        while (b > a) {
            int c = s[b - 1];
            int bate = set ? (memchr(set, c, (size_t)nset) != NULL) : by_eh_ws(c);
            if (!bate) break;
            b--;
        }
    }
    return by_devolve(vm, out, (const char *)s + a, b - a);
}

static int met_b_strip(VM *v, Value a, Value *g, int n, Value *o)  { return by_apara(v, a, g, n, o, "strip", 1, 1); }
static int met_b_lstrip(VM *v, Value a, Value *g, int n, Value *o) { return by_apara(v, a, g, n, o, "lstrip", 1, 0); }
static int met_b_rstrip(VM *v, Value a, Value *g, int n, Value *o) { return by_apara(v, a, g, n, o, "rstrip", 0, 1); }

static int met_b_removeprefix(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "removeprefix", 1);
    BY_EU(alvo, s, slen);
    const unsigned char *p;
    int np;
    if (by_like(vm, args[0], &p, &np) != 0) return -1;
    if (np <= slen && np > 0 && memcmp(s, p, (size_t)np) == 0)
        return by_devolve(vm, out, (const char *)s + np, slen - np);
    return by_devolve(vm, out, (const char *)s, slen);
}

static int met_b_removesuffix(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "removesuffix", 1);
    BY_EU(alvo, s, slen);
    const unsigned char *p;
    int np;
    if (by_like(vm, args[0], &p, &np) != 0) return -1;
    if (np <= slen && np > 0 && memcmp(s + slen - np, p, (size_t)np) == 0)
        return by_devolve(vm, out, (const char *)s, slen - np);
    return by_devolve(vm, out, (const char *)s, slen);
}

/* ── partir e juntar ────────────────────────────────────────────────────── */

/* Empurra um pedaço na lista. Devolve -1 SEM mexer no erro da VM quando o
 * chamador ainda precisa tirar a raiz da pilha antes de voltar. */
static int by_push(VM *vm, PSList *l, const unsigned char *p, int n)
{
    PSString *b = novo_bytes(vm, n > 0 ? (const char *)p : "", n);
    if (!b) return -1;
    if (l->len >= l->cap && cresce_lista(vm, l) != 0) return -1;
    l->itens[l->len++] = MK_OBJ(b);
    return 0;
}

static int by_split(VM *vm, Value alvo, Value *args, int n, Value *out,
                    const char *quem, int reverso)
{
    if (n > 2) return erro_aridade(vm, quem, 0, 2, n);
    BY_EU(alvo, s, slen);
    int64_t maxs = -1;
    if (n >= 2 && args[1].t != V_NULL) {
        if (args[1].t != V_INT)
            MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[1]));
        maxs = args[1].as.i;
    }
    PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
    if (!l) MERRO(vm, "MemoryError", "sem memoria em %s()", quem);
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");

    int rc = 0;
    if (n == 0 || args[0].t == V_NULL) {
        /* sem separador: corta em RUNS de branco e descarta os das pontas */
        if (!reverso) {
            int i = 0, feitos = 0;
            while (i < slen) {
                while (i < slen && by_eh_ws(s[i])) i++;
                if (i >= slen) break;
                if (maxs >= 0 && feitos == maxs) {
                    rc = by_push(vm, l, s + i, slen - i);
                    i = slen;
                    break;
                }
                int j = i;
                while (j < slen && !by_eh_ws(s[j])) j++;
                if ((rc = by_push(vm, l, s + i, j - i)) != 0) break;
                feitos++;
                i = j;
            }
        } else {
            /* de trás pra frente, e no fim a lista é invertida */
            int i = slen, feitos = 0;
            while (i > 0) {
                while (i > 0 && by_eh_ws(s[i - 1])) i--;
                if (i <= 0) break;
                if (maxs >= 0 && feitos == maxs) {
                    rc = by_push(vm, l, s, i);
                    i = 0;
                    break;
                }
                int j = i;
                while (j > 0 && !by_eh_ws(s[j - 1])) j--;
                if ((rc = by_push(vm, l, s + j, i - j)) != 0) break;
                feitos++;
                i = j;
            }
            for (int a = 0, b = l->len - 1; a < b; a++, b--) {
                Value t = l->itens[a]; l->itens[a] = l->itens[b]; l->itens[b] = t;
            }
        }
    } else {
        const unsigned char *sep;
        int nsep;
        if (by_like(vm, args[0], &sep, &nsep) != 0) { vm->sp--; return -1; }
        if (nsep == 0) { vm->sp--; MERRO(vm, "ValueError", "empty separator"); }
        if (!reverso) {
            int i = 0, feitos = 0;
            for (;;) {
                if (maxs >= 0 && feitos == maxs) { rc = by_push(vm, l, s + i, slen - i); break; }
                int k = by_acha(s, slen, sep, nsep, i);
                if (k < 0) { rc = by_push(vm, l, s + i, slen - i); break; }
                if ((rc = by_push(vm, l, s + i, k - i)) != 0) break;
                feitos++;
                i = k + nsep;
            }
        } else {
            int fim = slen, feitos = 0;
            for (;;) {
                if (maxs >= 0 && feitos == maxs) { rc = by_push(vm, l, s, fim); break; }
                int k = by_racha(s, fim, sep, nsep);
                if (k < 0) { rc = by_push(vm, l, s, fim); break; }
                if ((rc = by_push(vm, l, s + k + nsep, fim - k - nsep)) != 0) break;
                feitos++;
                fim = k;
            }
            for (int a = 0, b = l->len - 1; a < b; a++, b--) {
                Value t = l->itens[a]; l->itens[a] = l->itens[b]; l->itens[b] = t;
            }
        }
    }
    vm->sp--;
    if (rc != 0) MERRO(vm, "MemoryError", "sem memoria em %s()", quem);
    *out = MK_OBJ(l);
    return 0;
}

static int met_b_split(VM *v, Value a, Value *g, int n, Value *o)  { return by_split(v, a, g, n, o, "split", 0); }
static int met_b_rsplit(VM *v, Value a, Value *g, int n, Value *o) { return by_split(v, a, g, n, o, "rsplit", 1); }

/* Só `\n`, `\r` e `\r\n` — a MESMA regra do `str` (`met_splitlines`); nenhum
 * dos dois quebra em `\v`, `\f` ou `\x1c`. */
static int met_b_splitlines(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "splitlines", 0, 1, n);
    BY_EU(alvo, s, slen);
    int guarda = n == 1 && val_truthy(&args[0]);
    PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
    if (!l) MERRO(vm, "MemoryError", "sem memoria em splitlines()");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    int rc = 0, i = 0;
    while (i < slen) {
        int ini = i;
        while (i < slen && s[i] != '\n' && s[i] != '\r') i++;
        int fim_texto = i;
        if (i < slen) {
            if (s[i] == '\r' && i + 1 < slen && s[i + 1] == '\n') i += 2;
            else i += 1;
        }
        int fim = guarda ? i : fim_texto;
        if ((rc = by_push(vm, l, s + ini, fim - ini)) != 0) break;
    }
    vm->sp--;
    if (rc != 0) MERRO(vm, "MemoryError", "sem memoria em splitlines()");
    *out = MK_OBJ(l);
    return 0;
}

static int by_parte(VM *vm, Value alvo, Value *args, int n, Value *out,
                    const char *quem, int reverso)
{
    ARGS_MET(vm, quem, 1);
    BY_EU(alvo, s, slen);
    const unsigned char *sep;
    int nsep;
    if (by_like(vm, args[0], &sep, &nsep) != 0) return -1;
    if (nsep == 0) MERRO(vm, "ValueError", "empty separator");
    int k = reverso ? by_racha(s, slen, sep, nsep) : by_acha(s, slen, sep, nsep, 0);

    PSList *t = nova_seq(vm, 3, OBJ_TUPLE);
    if (!t) MERRO(vm, "MemoryError", "sem memoria em %s()", quem);
    t->len = 0;
    if (fixa_raiz(vm, MK_OBJ(t)) != 0) MERRO(vm, "RuntimeError", "estouro da pilha");
    Value a = MK_NULL(), b = MK_NULL(), c = MK_NULL();
    int rc = 0;
    if (k < 0) {
        /* não achou: `partition` põe tudo na PRIMEIRA, `rpartition` na ÚLTIMA */
        if (reverso) {
            rc = by_devolve(vm, &a, "", 0);
            if (!rc) rc = by_devolve(vm, &b, "", 0);
            if (!rc) rc = by_devolve(vm, &c, (const char *)s, slen);
        } else {
            rc = by_devolve(vm, &a, (const char *)s, slen);
            if (!rc) rc = by_devolve(vm, &b, "", 0);
            if (!rc) rc = by_devolve(vm, &c, "", 0);
        }
    } else {
        rc = by_devolve(vm, &a, (const char *)s, k);
        if (!rc) rc = by_devolve(vm, &b, (const char *)sep, nsep);
        if (!rc) rc = by_devolve(vm, &c, (const char *)s + k + nsep, slen - k - nsep);
    }
    vm->sp--;
    if (rc != 0) return -1;
    t->itens[0] = a; t->itens[1] = b; t->itens[2] = c;
    t->len = 3;
    *out = MK_OBJ(t);
    return 0;
}

static int met_b_partition(VM *v, Value a, Value *g, int n, Value *o)  { return by_parte(v, a, g, n, o, "partition", 0); }
static int met_b_rpartition(VM *v, Value a, Value *g, int n, Value *o) { return by_parte(v, a, g, n, o, "rpartition", 1); }

/* `b".".join([...])` — o alvo é o separador.
 *
 * O argumento é QUALQUER iterável, e desde que `bytes` passou a ser iterável
 * ele entra aqui também: `b"".join(b"")` é `b''` (nada pra juntar) e
 * `b"-".join(b"abc")` é TypeError, porque iterar bytes dá INTEIROS e inteiro
 * não é bytes-like. Os dois casos saíram da matriz do oráculo: com a lista
 * como único iterável aceito, o primeiro levantava "can only join an
 * iterable" onde o certo é devolver vazio. */
static int met_b_join(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "join", 1);
    BY_EU(alvo, sep, nsep);
    int quantos = iteravel_tam(&args[0]);
    if (quantos < 0 || EH_DICT(args[0]))
        MERRO(vm, "TypeError", "join() argument 1 must be list, tup, str or bytes, not %s",
              nome_do_tipo_valor(args[0]));
    SBUF_AUTO b = {0};
    for (int i = 0; i < quantos; i++) {
        Value item;
        if (iteravel_item(vm, &args[0], i, &item) != 0)
            MERRO(vm, "MemoryError", "sem memoria em join()");
        if (!EH_BYTES(item))
            MERRO(vm, "TypeError",
                  "sequence item %d: expected a bytes-like object, %s found",
                  i, nome_do_tipo_valor(item));
        if (i > 0 && nsep > 0 && sb_bytes(&b, (const char *)sep, nsep) != 0)
            MERRO(vm, "MemoryError", "sem memoria");
        PSString *p = COMO_BYTES(item);
        if (p->len > 0 && sb_bytes(&b, p->chars, p->len) != 0)
            MERRO(vm, "MemoryError", "sem memoria");
    }
    return by_devolve_sbuf(vm, &b, out);
}

/* ── trocar ─────────────────────────────────────────────────────────────── */

static int met_b_replace(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 2 || n > 3) return erro_aridade(vm, "replace", 2, 3, n);
    BY_EU(alvo, s, slen);
    const unsigned char *velho, *novo;
    int nv, nn;
    if (by_like(vm, args[0], &velho, &nv) != 0) return -1;
    if (by_like(vm, args[1], &novo, &nn) != 0) return -1;
    int64_t conta = -1;
    if (n == 3 && args[2].t != V_NULL) {
        if (args[2].t != V_INT)
            MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[2]));
        conta = args[2].as.i;
    }
    SBUF_AUTO b = {0};
    int64_t feitas = 0;
    int i = 0;
    /* agulha VAZIA: a troca entra entre cada byte e nas duas pontas */
    if (nv == 0) {
        for (;;) {
            if (conta < 0 || feitas < conta) {
                if (nn > 0 && sb_bytes(&b, (const char *)novo, nn) != 0)
                    MERRO(vm, "MemoryError", "sem memoria");
                feitas++;
            }
            if (i >= slen) break;
            if (sb_bytes(&b, (const char *)s + i, 1) != 0)
                MERRO(vm, "MemoryError", "sem memoria");
            i++;
        }
        return by_devolve_sbuf(vm, &b, out);
    }
    while (i < slen) {
        if ((conta < 0 || feitas < conta) && i + nv <= slen
                && memcmp(s + i, velho, (size_t)nv) == 0) {
            if (nn > 0 && sb_bytes(&b, (const char *)novo, nn) != 0)
                MERRO(vm, "MemoryError", "sem memoria");
            i += nv;
            feitas++;
            continue;
        }
        if (sb_bytes(&b, (const char *)s + i, 1) != 0)
            MERRO(vm, "MemoryError", "sem memoria");
        i++;
    }
    return by_devolve_sbuf(vm, &b, out);
}

/* ── preencher ──────────────────────────────────────────────────────────── */

static int by_larg(VM *vm, Value v, int64_t *w)
{
    if (v.t != V_INT)
        MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
              nome_do_tipo_valor(v));
    *w = v.as.i;
    if (*w > PS_STR_MAX) *w = PS_STR_MAX;   /* largura absurda não come a RAM */
    return 0;
}

static int by_enche(VM *vm, Value v, const char *quem, unsigned char *ch)
{
    if (!EH_BYTES(v) || COMO_BYTES(v)->len != 1)
        MERRO(vm, "TypeError",
              "%s() argument 2 must be a byte string of length 1, not %s",
              quem, nome_do_tipo_valor(v));
    *ch = (unsigned char)COMO_BYTES(v)->chars[0];
    return 0;
}

static int by_just(VM *vm, Value alvo, Value *args, int n, Value *out,
                   const char *quem, int lado)
{
    if (n < 1 || n > 2) return erro_aridade(vm, quem, 1, 2, n);
    BY_EU(alvo, s, slen);
    int64_t w;
    if (by_larg(vm, args[0], &w) != 0) return -1;
    unsigned char ch = ' ';
    if (n == 2 && by_enche(vm, args[1], quem, &ch) != 0) return -1;
    if (w <= slen) return by_devolve(vm, out, (const char *)s, slen);
    int falta = (int)(w - slen);
    /* `center`: com sobra ímpar o byte a mais vai na ESQUERDA quando
     * a largura também é ímpar — `b"ab".center(7,b"*")` é `b"***ab**"`, não
     * `b"**ab***"`. É `marg/2 + (marg & width & 1)`, a mesma fórmula do
     * `str.center`. */
    int esq = lado == 0 ? 0
            : (lado == 1 ? falta : falta / 2 + (falta & (int)w & 1));
    int dir = falta - esq;
    SBUF_AUTO b = {0};
    for (int i = 0; i < esq; i++)
        if (sb_bytes(&b, (const char *)&ch, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
    if (slen > 0 && sb_bytes(&b, (const char *)s, slen) != 0)
        MERRO(vm, "MemoryError", "sem memoria");
    for (int i = 0; i < dir; i++)
        if (sb_bytes(&b, (const char *)&ch, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
    return by_devolve_sbuf(vm, &b, out);
}

static int met_b_ljust(VM *v, Value a, Value *g, int n, Value *o)  { return by_just(v, a, g, n, o, "ljust", 0); }
static int met_b_rjust(VM *v, Value a, Value *g, int n, Value *o)  { return by_just(v, a, g, n, o, "rjust", 1); }
static int met_b_center(VM *v, Value a, Value *g, int n, Value *o) { return by_just(v, a, g, n, o, "center", 2); }

static int met_b_zfill(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "zfill", 1);
    BY_EU(alvo, s, slen);
    int64_t w;
    if (by_larg(vm, args[0], &w) != 0) return -1;
    if (w <= slen) return by_devolve(vm, out, (const char *)s, slen);
    SBUF_AUTO b = {0};
    /* o sinal fica NA FRENTE dos zeros: `b"-42".zfill(8)` é `b"-0000042"` */
    int i = 0;
    if (slen > 0 && (s[0] == '+' || s[0] == '-')) {
        if (sb_bytes(&b, (const char *)s, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
        i = 1;
    }
    for (int k = 0; k < (int)(w - slen); k++)
        if (sb_bytes(&b, "0", 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
    if (slen - i > 0 && sb_bytes(&b, (const char *)s + i, slen - i) != 0)
        MERRO(vm, "MemoryError", "sem memoria");
    return by_devolve_sbuf(vm, &b, out);
}

static int met_b_expandtabs(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "expandtabs", 0, 1, n);
    BY_EU(alvo, s, slen);
    int64_t tam = 8;
    if (n == 1 && args[0].t != V_NULL) {
        if (args[0].t != V_INT)
            MERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[0]));
        tam = args[0].as.i;
    }
    SBUF_AUTO b = {0};
    int col = 0;
    for (int i = 0; i < slen; i++) {
        if (s[i] == '\t') {
            int quantos = tam > 0 ? (int)(tam - col % tam) : 0;
            for (int k = 0; k < quantos; k++)
                if (sb_bytes(&b, " ", 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
            col += quantos;
            continue;
        }
        if (sb_bytes(&b, (const char *)s + i, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
        if (s[i] == '\n' || s[i] == '\r') col = 0;
        else col++;
    }
    return by_devolve_sbuf(vm, &b, out);
}

/* ── traduzir ───────────────────────────────────────────────────────────── */

static int met_b_maketrans(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)alvo;
    ARGS_MET(vm, "maketrans", 2);
    const unsigned char *de, *para;
    int nde, npara;
    if (by_like(vm, args[0], &de, &nde) != 0) return -1;
    if (by_like(vm, args[1], &para, &npara) != 0) return -1;
    if (nde != npara)
        MERRO(vm, "ValueError", "maketrans arguments must have same length");
    unsigned char tab[256];
    for (int i = 0; i < 256; i++) tab[i] = (unsigned char)i;
    for (int i = 0; i < nde; i++) tab[de[i]] = para[i];
    return by_devolve(vm, out, (const char *)tab, 256);
}

static int met_b_translate(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "translate", 1, 2, n);
    BY_EU(alvo, s, slen);
    const unsigned char *tab = NULL;
    if (args[0].t != V_NULL) {
        int ntab;
        if (by_like(vm, args[0], &tab, &ntab) != 0) return -1;
        if (ntab != 256)
            MERRO(vm, "ValueError", "translation table must be 256 characters long");
    }
    const unsigned char *del = NULL;
    int ndel = 0;
    if (n == 2 && args[1].t != V_NULL) {
        if (by_like(vm, args[1], &del, &ndel) != 0) return -1;
    }
    SBUF_AUTO b = {0};
    for (int i = 0; i < slen; i++) {
        if (del && memchr(del, s[i], (size_t)ndel)) continue;
        char c = (char)(tab ? tab[s[i]] : s[i]);
        if (sb_bytes(&b, &c, 1) != 0) MERRO(vm, "MemoryError", "sem memoria");
    }
    return by_devolve_sbuf(vm, &b, out);
}

