/* ── os ─────────────────────────────────────────────────────────────────── */
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

/* O arquivo é binário? Pergunta ao CONTEÚDO, não a uma lista de extensões.
 *
 * Havia aqui um vetor com doze extensões, e ele mandava em duas coisas: o
 * padrão do `loadFile` e — pior — o que podia ser aberto, porque pedir
 * `modo='rb'` fora da lista era recusado. `.xlsm`, `.7z`, `.tar`, `.wav`,
 * `.odt`, `.parquet` e arquivo sem extensão nenhuma ficavam de fora. Uma
 * lista de convidados escrita à mão nunca termina, e quem chega depois
 * descobre pelo erro.
 *
 * O critério é o mesmo das ferramentas de linha de comando: byte NUL nos
 * primeiros 8 KB. Texto não tem NUL; PNG, ZIP, PDF e planilha têm no
 * cabeçalho. Não é adivinhação de formato, é a única pergunta que separa as
 * duas leituras — e ela vale pra arquivo que ninguém previu.
 *
 * Não conseguir abrir devolve 0 de propósito: quem falha é o `fopen` do
 * caminho de texto logo abaixo, com o errno de verdade, em vez de virar um
 * PoolFile que não existe. */
static int conteudo_binario(const char *caminho)
{
    FILE *f = fopen(caminho, "rb");
    if (!f) return 0;
    char amostra[8192];
    size_t lidos = fread(amostra, 1, sizeof(amostra), f);
    fclose(f);
    return memchr(amostra, '\0', lidos) != NULL;
}

static void minusculo(const char *s, char *saida, size_t cap)
{
    size_t i = 0;
    for (; s[i] && i + 1 < cap; i++)
        saida[i] = (s[i] >= 'A' && s[i] <= 'Z') ? (char)(s[i] + 32) : s[i];
    saida[i] = '\0';
}

static int caminho_abs(const char *rel, char *saida, size_t cap)
{
    if (realpath(rel, saida)) return 0;
    snprintf(saida, cap, "%s", rel);
    return -1;
}

static PSPoolFile *novo_poolfile(VM *vm, const char *caminho)
{
    FILE *f = fopen(caminho, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long tam = ftell(f);
    rewind(f);
    /* `ftell` devolve -1 em FIFO, pipe e dispositivo. O `tam > 0 ? tam : 1`
     * de antes escondia o sinal: o `malloc` era de 1 byte e o `fread` recebia
     * `(size_t)-1` — lia até o EOF ESCREVENDO fora do heap. O `errno` sai
     * pro chamador traduzir com `erro_sistema`, como nos outros caminhos. */
    if (tam < 0) { fclose(f); errno = ESPIPE; return NULL; }
    /* limite físico, não teto: `novo_bytes` recebe `int` */
    if (tam > INT_MAX) { fclose(f); errno = EFBIG; return NULL; }
    char *buf = malloc((size_t)tam + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t lidos = fread(buf, 1, (size_t)tam, f);
    fclose(f);

    PSString *b = novo_bytes(vm, buf, (int)lidos);
    free(buf);
    if (!b) return NULL;

    PSPoolFile *pf = calloc(1, sizeof(PSPoolFile));
    if (!pf) return NULL;
    pf->obj.type = OBJ_POOLFILE; pf->obj.marked = 0;
    pf->obj.next = vm->objetos; vm->objetos = (Obj *)pf;
    char abs[2048];
    caminho_abs(caminho, abs, sizeof(abs));
    pf->caminho = strdup(abs);
    const char *barra = strrchr(abs, '/');
    pf->nome = strdup(barra ? barra + 1 : abs);
    const char *ponto = strrchr(pf->nome ? pf->nome : "", '.');
    char e[64] = "";
    if (ponto) minusculo(ponto, e, sizeof(e));
    pf->ext = strdup(e);
    pf->conteudo = MK_OBJ(b);
    pf->tamanho = (int64_t)lidos;
    vm->alocado += sizeof(PSPoolFile);
    return pf;
}

/* ── métodos do PoolFile ───────────────────────────────────────────────── */
static int cria_pais(const char *caminho)
{
    char tmp[2048];
    snprintf(tmp, sizeof(tmp), "%s", caminho);
    char *barra = strrchr(tmp, '/');
    if (!barra || barra == tmp) return 0;
    *barra = '\0';
    for (char *p = tmp + 1; *p; p++) {
        if (*p != '/') continue;
        *p = '\0';
        mkdir(tmp, 0755);
        *p = '/';
    }
    mkdir(tmp, 0755);
    return 0;
}

/* `culpa` recebe QUAL dos dois caminhos falhou. A mensagem nomeia o arquivo que
 * deu erro, não sempre a origem — sem isto, destino sem permissão sairia
 * apontando a origem, que está perfeita. */
/* Grava tudo e FECHA conferindo. Devolve 0, ou -1 com `errno` no motivo.
 *
 * Existe porque o motor repetia o par `fwrite(...); fclose(f);` sem olhar
 * nenhum dos dois retornos, em varios lugares. Gravacao que falhava era
 * ignorada e a funcao dizia que tinha dado certo — foi assim que
 * `os.move` chegou a APAGAR o arquivo de origem depois de uma copia que nao
 * aconteceu, e que `os.writeFile("/dev/full", ...)` devolvia o caminho com
 * rc=0.
 *
 * O `fclose` importa tanto quanto o `fwrite`: o buffer da libc so vai pro
 * disco no flush, entao ENOSPC costuma aparecer AO FECHAR, nao ao escrever.
 */
static int grava_e_fecha(FILE *f, const void *dados, size_t n)
{
    int err = 0;
    if (n > 0 && fwrite(dados, 1, n, f) != n) err = errno ? errno : EIO;
    if (fclose(f) != 0 && !err) err = errno ? errno : EIO;
    if (err) { errno = err; return -1; }
    return 0;
}

static int copia_arquivo(const char *de, const char *para, const char **culpa)
{
    /* `fopen` de diretório abre no Linux e só falha no `read` — sem este
     * teste, `copy("pasta", "x")` criaria um `x` vazio em silêncio. O `errno`
     * daqui era LIXO da última syscall: agora o caso diz EISDIR, que é o
     * errno certo pra "origem é diretório". */
    struct stat st;
    if (culpa) *culpa = de;
    if (stat(de, &st) != 0) return -1;
    if (!S_ISREG(st.st_mode)) { errno = S_ISDIR(st.st_mode) ? EISDIR : EINVAL; return -1; }
    FILE *a = fopen(de, "rb");
    if (!a) return -1;
    if (culpa) *culpa = para;
    FILE *b = fopen(para, "wb");
    if (!b) { int e = errno; fclose(a); errno = e; return -1; }
    /* A GRAVACAO E CONFERIDA. Sem isto o `fwrite` que falha era ignorado, a
     * funcao devolvia 0 ("copiou") e o `os.move` seguia em frente e dava
     * `unlink` na ORIGEM: perda de dado em silencio, sem erro nenhum.
     * Reproduzido copiando pra /dev/full — o pool dizia que tinha dado certo e
     * o arquivo de origem sumia; o certo e levantar
     * `OSError: [Errno 28] No space left on device` e manter a origem.
     *
     * Os tres pontos que podem falhar, e todos os tres importam:
     *   fread  + ferror  — erro de leitura no meio (EIO)
     *   fwrite curto     — o destino nao aceitou tudo (ENOSPC, EDQUOT)
     *   fclose do destino— e AQUI que o ENOSPC costuma aparecer, porque o
     *                      buffer da libc so vai pro disco no flush
     *
     * `errno` e salvo antes de qualquer fclose de limpeza: fechar o outro
     * arquivo sobrescreveria o motivo real. */
    char buf[8192];
    size_t n;
    int falhou = 0, err = 0;
    while ((n = fread(buf, 1, sizeof(buf), a)) > 0) {
        if (fwrite(buf, 1, n, b) != n) { falhou = 1; err = errno ? errno : EIO; break; }
    }
    if (!falhou && ferror(a)) { falhou = 1; err = errno ? errno : EIO; if (culpa) *culpa = de; }
    fclose(a);
    if (fclose(b) != 0 && !falhou) { falhou = 1; err = errno ? errno : EIO; }
    if (falhou) {
        /* destino incompleto nao fica pra tras fingindo que serve */
        unlink(para);
        errno = err;
        return -1;
    }
    return 0;
}

/* ── TODO ARQUIVO É PoolFile ───────────────────────────────────────────────
 * Existem dois objetos por dentro — o handle aberto (`open()`) e o conteúdo
 * carregado (`os.loadFile`) — mas pra quem escreve `.ps` é UM tipo só:
 * `PoolFile`. Antes o handle se dizia `FileHandle` no `type()`, `Arquivo` no
 * `--metadata`, e não tinha `move`/`copy`/`path`: três nomes e dois conjuntos
 * de método pra mesma ideia. Estes dois ajudantes deixam os métodos de
 * arquivo valerem nos DOIS. */
static const char *pf_caminho(Value v)
{
    if (EH_PFILE(v))   return COMO_PFILE(v)->caminho;
    if (EH_ARQUIVO(v)) return COMO_ARQ(v)->caminho;
    return NULL;
}

/* Operação que mexe no arquivo em disco (mover, apagar) num handle ainda
 * ABERTO: o descritor continuaria escrevendo no lugar antigo. Recusa dizendo
 * o que fazer, em vez de deixar o dado sumir em silêncio. */
static int pf_exige_fechado(VM *vm, Value v, const char *quem)
{
    if (EH_ARQUIVO(v) && !COMO_ARQ(v)->fechado)
        MERRO(vm, "ValueError",
              "%s() num arquivo ainda ABERTO — chame .close() antes (ou saia do `using`)", quem);
    return 0;
}

static int met_pf_move(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "move", 1);
    if (!EH_STRING(args[0])) MERRO(vm, "TypeError", "move() argument 1 must be str, not %s",
                                  nome_do_tipo_valor(args[0]));
    if (pf_exige_fechado(vm, alvo, "move") != 0) return -1;
    if (!EH_PFILE(alvo)) {
        /* handle fechado: move pelo caminho, sem conteúdo em memória */
        const char *orig = pf_caminho(alvo);
        const char *dst = COMO_STRING(args[0])->chars;
        cria_pais(dst);
        if (rename(orig, dst) != 0) {
            const char *culpa = orig;
            if (copia_arquivo(orig, dst, &culpa) != 0) return erro_sistema(vm, errno, culpa, NULL);
            remove(orig);
        }
        snprintf(COMO_ARQ(alvo)->caminho, sizeof(COMO_ARQ(alvo)->caminho), "%s", dst);
        *out = alvo;
        return 0;
    }
    PSPoolFile *f = COMO_PFILE(alvo);
    const char *dest = COMO_STRING(args[0])->chars;
    cria_pais(dest);
    /* rename falha entre sistemas de arquivo; aí copia e apaga */
    if (rename(f->caminho, dest) != 0) {
        const char *culpa = f->caminho;
        if (copia_arquivo(f->caminho, dest, &culpa) != 0)
            return erro_sistema(vm, errno, culpa, NULL);
        unlink(f->caminho);
    }
    PSPoolFile *novo = novo_poolfile(vm, dest);
    if (!novo) return erro_sistema(vm, errno, dest, NULL);
    free(f->caminho);
    f->caminho = strdup(dest);
    *out = MK_OBJ(novo);
    return 0;
}

static int met_pf_copy(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "copy", 1);
    if (!EH_STRING(args[0])) MERRO(vm, "TypeError", "copy() argument 1 must be str, not %s",
                                  nome_do_tipo_valor(args[0]));
    /* Copiar não mexe no original, então vale com o handle aberto — só é
     * preciso escoar o que ainda está no buffer, senão a cópia sai truncada. */
    if (EH_ARQUIVO(alvo) && COMO_ARQ(alvo)->f) fflush(COMO_ARQ(alvo)->f);
    const char *origem = pf_caminho(alvo);
    const char *dest = COMO_STRING(args[0])->chars;
    cria_pais(dest);
    const char *culpa = origem;
    if (copia_arquivo(origem, dest, &culpa) != 0)
        return erro_sistema(vm, errno, culpa, NULL);
    PSPoolFile *novo = novo_poolfile(vm, dest);
    if (!novo) return erro_sistema(vm, errno, dest, NULL);
    *out = MK_OBJ(novo);
    return 0;
}

static int met_pf_delete(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "delete", 0, 0, n);
    if (pf_exige_fechado(vm, alvo, "delete") != 0) return -1;
    unlink(pf_caminho(alvo));            /* já apagado não é erro */
    *out = MK_BOOL(1);
    return 0;
}

static int met_pf_bytes(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "bytes", 0, 0, n);
    if (EH_PFILE(alvo)) { *out = COMO_PFILE(alvo)->conteudo; return 0; }
    /* Handle: o conteúdo não está em memória — lê do disco agora. O `fflush`
     * antes, senão o que ainda está no buffer não entraria nos bytes. */
    PSArquivo *a = COMO_ARQ(alvo);
    if (a->f) fflush(a->f);
    PSPoolFile *lido = novo_poolfile(vm, a->caminho);
    if (!lido) return erro_sistema(vm, errno, a->caminho, NULL);
    *out = lido->conteudo;
    return 0;
}

static int met_pf_save(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    /* save() ou save(path): grava o conteúdo em disco. Sem path, salva na
     * pasta do script em execução com o nome do próprio arquivo. */
    if (n > 1) return erro_aridade(vm, "save", 0, 1, n);
    PSPoolFile *f = COMO_PFILE(alvo);
    char dest[2048];
    if (n == 1 && args[0].t != V_NULL) {   /* Null = ausente, como a tabela declara */
        if (!EH_STRING(args[0])) MERRO(vm, "TypeError", "save() argument 1 must be str, not %s",
                                      nome_do_tipo_valor(args[0]));
        snprintf(dest, sizeof(dest), "%s", COMO_STRING(args[0])->chars);
    } else {
        const char *base = vm->dir_script[0] ? vm->dir_script : ".";
        snprintf(dest, sizeof(dest), "%s/%s", base, f->nome ? f->nome : "arquivo");
    }
    cria_pais(dest);
    FILE *fp = fopen(dest, "wb");
    if (!fp) return erro_sistema(vm, errno, dest, NULL);
    PSString *b = EH_BYTES(f->conteudo) ? COMO_BYTES(f->conteudo) : NULL;
    if (grava_e_fecha(fp, b ? b->chars : "", b ? (size_t)b->len : 0) != 0)
        return erro_sistema(vm, errno, dest, NULL);
    PSPoolFile *novo = novo_poolfile(vm, dest);
    if (!novo) return erro_sistema(vm, errno, dest, NULL);
    free(f->caminho);
    f->caminho = strdup(dest);
    *out = MK_OBJ(novo);
    return 0;
}

static int met_pf_path(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    (void)args;
    if (n != 0) return erro_aridade(vm, "path", 0, 0, n);
    char abs[2048];
    caminho_abs(pf_caminho(alvo), abs, sizeof(abs));
    return devolve_texto(vm, out, abs, (int)strlen(abs));
}

