/* Resolve `alvo.nome`. `.type()` vem primeiro porque vale pra todo valor. */
static int acha_metodo_valor(Value alvo, const char *nome, int *tab, int *idx)
{
    for (int i = 0; i < TAM_TABELA[T_MET_UNIV]; i++)
        if (strcmp(METODOS_UNIV[i].nome, nome) == 0) { *tab = T_MET_UNIV; *idx = i; return 0; }
    int qual;
    if (EH_STRING(alvo) || alvo.t == V_INT || alvo.t == V_FLOAT) qual = T_MET_STR;
    else if (EH_TUPLA(alvo)) qual = T_MET_TUPLA;   /* imutável: só leitura */
    else if (EH_SEQ(alvo))  qual = T_MET_LIST;
    else if (EH_DICT(alvo)) qual = T_MET_DICT;
    else if (EH_ARQUIVO(alvo)) qual = T_MET_ARQ;
    else if (EH_BYTES(alvo))   qual = T_MET_BYTES;
    else if (EH_PFILE(alvo))   qual = T_MET_PFILE;
    else if (EH_SQLCONN(alvo)) qual = T_MET_SQLCONN;
    else if (EH_SQLCUR(alvo))  qual = T_MET_SQLCUR;
    else if (EH_MAILSRV(alvo)) qual = T_MET_MAILSRV;
    else if (EH_MAILMSG(alvo)) qual = T_MET_MAILMSG;
    else if (EH_MAILRD(alvo))  qual = T_MET_MAILRD;
    else if (EH_RESP(alvo))    qual = T_MET_RESP;
    else if (EH_QRFILE(alvo))  qual = T_MET_QRFILE;
    else if (EH_DBCONN(alvo))  qual = T_MET_DBCONN;
    else if (EH_DBCUR(alvo))   qual = T_MET_DBCUR;
    else if (EH_MONGOCONN(alvo)) qual = T_MET_MONGOCONN;
    else if (EH_MONGOCOL(alvo))  qual = T_MET_MONGOCOL;
    else if (EH_JINKER(alvo))  qual = T_MET_JINKER;
    else if (EH_JCORS(alvo))   qual = T_MET_JCORS;
    else if (EH_JREG(alvo))    qual = T_MET_JREG;
    else if (EH_JRESP(alvo))   qual = T_MET_JRESP;
    else if (EH_JPROXY(alvo))  qual = T_MET_JPROXY;
    else if (EH_JUPLOAD(alvo)) qual = T_MET_JUPLOAD;
    else if (EH_JSOCKNS(alvo)) qual = T_MET_JSOCKNS;
    else if (EH_JEMIT(alvo))   qual = T_MET_JEMIT;
    else if (EH_JCHAN(alvo))   qual = T_MET_JCHAN;
    else if (EH_WSCONN(alvo))  qual = T_MET_WSCONN;
    else if (EH_QRBUILD(alvo)) qual = T_MET_QRBUILD;
    else if (EH_QRIMAGE(alvo)) qual = T_MET_QRIMAGE;
    else if (EH_MPFILE(alvo))  qual = T_MET_MPFILE;
    else if (EH_SOCKET(alvo))  qual = T_MET_SOCKET;
    else if (EH_REGEX(alvo))   qual = T_MET_REGEX;
    else return -1;
    for (int i = 0; i < TAM_TABELA[qual]; i++)
        if (strcmp(TABELAS[qual][i].nome, nome) == 0) { *tab = qual; *idx = i; return 0; }
    return -1;
}


/* ── módulos nativos ────────────────────────────────────────────────────── */
/* Membro de módulo tem a mesma assinatura de builtin: não há `self`. */

/* ── json ───────────────────────────────────────────────────────────────── */
/* Serializador: é o mesmo passeio do `valor_para_texto`, mas com as regras do
 * JSON, não as do repr da linguagem — aspas duplas, `null`/`true`/`false`
 * minúsculos, e escape obrigatório. */
static int json_escreve(VM *vm, SBuf *b, const Value *v, int prof, int compacto);

static int json_texto(SBuf *b, const char *s, int len)
{
    if (sb_bytes(b, "\"", 1) != 0) return -1;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        const char *esc = NULL;
        char tmp[8];
        switch (c) {
            case '"':  esc = "\\\""; break;
            case '\\': esc = "\\\\"; break;
            case '\n': esc = "\\n";  break;
            case '\r': esc = "\\r";  break;
            case '\t': esc = "\\t";  break;
            case '\b': esc = "\\b";  break;
            case '\f': esc = "\\f";  break;
            default:
                if (c < 0x20) { snprintf(tmp, sizeof(tmp), "\\u%04x", c); esc = tmp; }
        }
        /* ensure_ascii=False: UTF-8 sai como está, sem virar \uXXXX */
        if (esc) { if (sb_bytes(b, esc, (int)strlen(esc)) != 0) return -1; }
        else     { if (sb_bytes(b, (const char *)&c, 1) != 0) return -1; }
    }
    return sb_bytes(b, "\"", 1);
}

/* `compacto` tira o espaço depois de `,` e `:`. Não é estética: o JWT assina
 * os BYTES do JSON, então um espaço a mais gera token que não valida. Um flag
 * em vez de duas funções porque duas divergiriam na primeira correção. */
static int json_escreve(VM *vm, SBuf *b, const Value *v, int prof, int compacto)
{
    /* profundidade é RecursionError (o comentário do stringify já prometia;
     * só vm->erro era escrito e a rede de baixo virava TypeError) */
    if (prof > 64) {
        snprintf(vm->erro, sizeof(vm->erro), "json aninhado demais");
        snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "RecursionError");
        return -1;
    }
    char tmp[64];
    switch (v->t) {
        case V_NULL: case V_UNSET: return sb_bytes(b, "null", 4);
        case V_BOOL: return v->as.b ? sb_bytes(b, "true", 4) : sb_bytes(b, "false", 5);
        case V_INT:  return sb_bytes(b, tmp, snprintf(tmp, sizeof(tmp), "%lld", (long long)v->as.i));
        case V_FLOAT: return sb_bytes(b, tmp, float_para_texto(tmp, sizeof(tmp), v->as.d));
        case V_OBJ: break;
        default:
            snprintf(vm->erro, sizeof(vm->erro),
                     "Object of type %s is not JSON serializable",
                     nome_do_tipo_valor(*v));
            return -1;
    }
    if (EH_BIGINT(*v)) { char *s = bigint_str(COMO_BIGINT(*v)->v);
                         int rc = s ? sb_bytes(b, s, (int)strlen(s)) : -1; free(s); return rc; }
    if (EH_STRING(*v)) { PSString *s = COMO_STRING(*v); return json_texto(b, s->chars, s->len); }
    if (EH_SEQ(*v)) {
        PSList *l = COMO_LIST(*v);
        if (sb_bytes(b, "[", 1) != 0) return -1;
        for (int i = 0; i < l->len; i++) {
            if (i && sb_bytes(b, compacto ? "," : ", ", compacto ? 1 : 2) != 0) return -1;
            if (json_escreve(vm, b, &l->itens[i], prof + 1, compacto) != 0) return -1;
        }
        return sb_bytes(b, "]", 1);
    }
    if (EH_DICT(*v)) {
        PSDict *d = COMO_DICT(*v);
        if (sb_bytes(b, "{", 1) != 0) return -1;
        int primeiro = 1;
        for (int i = 0; i < d->usados; i++) {
            if (d->entradas[i].estado != 1) continue;
            if (!primeiro && sb_bytes(b, compacto ? "," : ", ", compacto ? 1 : 2) != 0) return -1;
            primeiro = 0;
            /* chave sempre vira texto: JSON não tem chave numérica */
            Value k = d->entradas[i].chave;
            if (EH_STRING(k)) {
                PSString *ks = COMO_STRING(k);
                if (json_texto(b, ks->chars, ks->len) != 0) return -1;
            } else if (k.t == V_BOOL) {
                /* JSON nao tem `True`: chave booleana sai minuscula
                 * (`{true: 1}` -> `{"true": 1}`), como este mesmo
                 * serializador ja escreve um bool em posicao de VALOR. */
                if (json_texto(b, k.as.b ? "true" : "false", k.as.b ? 4 : 5) != 0)
                    return -1;
            } else {
                TXTBUF_AUTO t = {0};
                if (valor_para_texto(&t, &k, 0) != 0) { return -1; }
                int r = json_texto(b, t.b ? t.b : "", t.n);
                if (r != 0) return -1;
            }
            if (sb_bytes(b, compacto ? ":" : ": ", compacto ? 1 : 2) != 0) return -1;
            if (json_escreve(vm, b, &d->entradas[i].valor, prof + 1, compacto) != 0) return -1;
        }
        return sb_bytes(b, "}", 1);
    }
    snprintf(vm->erro, sizeof(vm->erro),
             "Object of type %s is not JSON serializable",
             nome_do_tipo_valor(*v));
    return -1;
}

static int mod_json_stringify(VM *vm, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "stringify", 1, 2, n);
    /* 2º argumento liga o modo compacto: `json.stringify(x, True)` */
    int compacto = (n == 2) && val_truthy(&args[1]);
    SBUF_AUTO b = {0};
    if (json_escreve(vm, &b, &args[0], 0, compacto) != 0) {
        /* O json_escreve ja escolhe o tipo (TypeError no valor que nao serializa,
         * RecursionError na profundidade); o TypeError aqui e so a rede pra quem
         * falhou sem escolher (o sb_bytes sem memoria, por exemplo). */
        if (!vm->erro_tipo[0]) snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
        return -1;
    }
    PSString *r = nova_string(vm, b.b ? b.b : "", b.n);
    if (!r) BERRO(vm, "MemoryError", "sem memoria em stringify()");
    *out = MK_OBJ(r);
    return 0;
}

/* Parser recursivo descendente. `p` anda pelo texto; devolve -1 e preenche
 * vm->erro em qualquer coisa malformada — JSON parcial nunca vira valor. */
typedef struct { const char *s; int n; int i; } JLeitor;

/* Erro de JSON: a mensagem, e ONDE.
 *
 *     Expecting ',' delimiter: line 1 column 8 (char 7)
 *
 * A posição é o que faltava: "json: esperado ',' ou fechamento" num payload de
 * 40 KB não diz nada. Linha e coluna saem do offset contando as quebras — o
 * leitor já carrega o texto inteiro, então é uma varredura só, no caminho de
 * erro. `char` é o offset em BYTES.
 *
 * O tipo é ValueError: o texto tem o tipo certo (str), é o conteúdo que não
 * serve.
 */
static int j_erro(VM *vm, const JLeitor *j, int onde, const char *oque)
{
    if (onde > j->n) onde = j->n;
    if (onde < 0)    onde = 0;
    int linha = 1, col = 1;
    for (int k = 0; k < onde; k++) {
        if (j->s[k] == '\n') { linha++; col = 1; }
        else col++;
    }
    snprintf(vm->erro, sizeof(vm->erro), "%s: line %d column %d (char %d)",
             oque, linha, col, onde);
    snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "ValueError");
    return -1;
}

static void j_espaco(JLeitor *j)
{
    while (j->i < j->n && (j->s[j->i] == ' ' || j->s[j->i] == '\t'
                        || j->s[j->i] == '\n' || j->s[j->i] == '\r')) j->i++;
}

static int j_valor(VM *vm, JLeitor *j, Value *out, int prof);

static int j_texto(VM *vm, JLeitor *j, Value *out)
{
    int ini = j->i;      /* a aspa de ABERTURA: e ela que a mensagem aponta em
                          * "Unterminated string starting at" */
    j->i++;                                   /* passa a aspa de abertura */
    SBUF_AUTO b = {0};
    while (j->i < j->n && j->s[j->i] != '"') {
        char c = j->s[j->i];
        if (c == '\\') {
            j->i++;
            if (j->i >= j->n) { return j_erro(vm, j, j->i - 1, "Invalid \\escape"); }
            char e = j->s[j->i++];
            char saida = 0;
            switch (e) {
                case '"': saida = '"';  break;   case '\\': saida = '\\'; break;
                case '/': saida = '/';  break;   case 'n':  saida = '\n'; break;
                case 't': saida = '\t'; break;   case 'r':  saida = '\r'; break;
                case 'b': saida = '\b'; break;   case 'f':  saida = '\f'; break;
                case 'u': {
                    if (j->i + 4 > j->n) { return j_erro(vm, j, j->i - 1, "Invalid \\uXXXX escape"); }
                    uint32_t cp = 0;
                    for (int k = 0; k < 4; k++) {
                        char h = j->s[j->i + k];
                        int d = (h >= '0' && h <= '9') ? h - '0'
                              : (h >= 'a' && h <= 'f') ? h - 'a' + 10
                              : (h >= 'A' && h <= 'F') ? h - 'A' + 10 : -1;
                        if (d < 0) { return j_erro(vm, j, j->i - 1, "Invalid \\uXXXX escape"); }
                        cp = cp * 16 + (uint32_t)d;
                    }
                    j->i += 4;
                    /* Fora do BMP o JSON escreve um PAR de surrogates
                     * (`\ud83d\ude00` = 😀). Cada metade sozinha não é
                     * caractere: emitir as duas dava 6 bytes de lixo. */
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        if (j->i + 6 > j->n || j->s[j->i] != '\\' || j->s[j->i + 1] != 'u')
                            return j_erro(vm, j, j->i - 1, "Invalid \\uXXXX escape");
                        uint32_t lo = 0;
                        for (int k = 0; k < 4; k++) {
                            char h = j->s[j->i + 2 + k];
                            int d = (h >= '0' && h <= '9') ? h - '0'
                                  : (h >= 'a' && h <= 'f') ? h - 'a' + 10
                                  : (h >= 'A' && h <= 'F') ? h - 'A' + 10 : -1;
                            if (d < 0) { return j_erro(vm, j, j->i - 1, "Invalid \\uXXXX escape"); }
                            lo = lo * 16 + (uint32_t)d;
                        }
                        if (lo < 0xDC00 || lo > 0xDFFF)
                            return j_erro(vm, j, j->i - 1, "Invalid \\uXXXX escape");
                        j->i += 6;
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    } else if (cp >= 0xDC00 && cp <= 0xDFFF) {
                        return j_erro(vm, j, j->i - 1, "Invalid \\uXXXX escape");
                    }
                    if (sb_cp(&b, cp) != 0) { BERRO(vm, "MemoryError", "sem memoria"); }
                    continue;
                }
                default: return j_erro(vm, j, j->i - 1, "Invalid \\escape");
            }
            if (sb_bytes(&b, &saida, 1) != 0) { BERRO(vm, "MemoryError", "sem memoria"); }
        } else {
            /* controle cru dentro de string é inválido em JSON estrito, que é
             * o modo do `json.loads` — sem isso o parser aceitaria um texto
             * que o interpretador recusa. */
            if ((unsigned char)c < 0x20) {
                return j_erro(vm, j, j->i, "Invalid control character at");
            }
            if (sb_bytes(&b, &c, 1) != 0) { BERRO(vm, "MemoryError", "sem memoria"); }
            j->i++;
        }
    }
    if (j->i >= j->n) { return j_erro(vm, j, ini, "Unterminated string starting at"); }
    j->i++;                                   /* aspa de fechamento */
    PSString *r = nova_string(vm, b.b ? b.b : "", b.n);
    if (!r) BERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(r);
    return 0;
}

static int j_valor(VM *vm, JLeitor *j, Value *out, int prof)
{
    if (prof > 64) BERRO(vm, "RecursionError", "json aninhado demais");
    j_espaco(j);
    if (j->i >= j->n) return j_erro(vm, j, j->i, "Expecting value");
    char c = j->s[j->i];
    if (c == '"') return j_texto(vm, j, out);
    if (c == '{' || c == '[') {
        int eh_obj = (c == '{');
        j->i++;
        Value cont;
        if (eh_obj) {
            PSDict *d = novo_dict(vm, 4);
            if (!d) BERRO(vm, "MemoryError", "sem memoria");
            cont = MK_OBJ(d);
        } else {
            PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
            if (!l) BERRO(vm, "MemoryError", "sem memoria");
            cont = MK_OBJ(l);
        }
        /* o container fica na pilha enquanto os filhos são construídos:
         * são muitas alocações, e sem raiz o GC leva o pai */
        if (fixa_raiz(vm, cont) != 0) BERRO(vm, "RuntimeError", "estouro da pilha em json");
        j_espaco(j);
        char fecha = eh_obj ? '}' : ']';
        if (j->i < j->n && j->s[j->i] == fecha) { j->i++; vm->sp--; *out = cont; return 0; }
        for (;;) {
            j_espaco(j);
            if (eh_obj) {
                if (j->i >= j->n || j->s[j->i] != '"') { vm->sp--; return j_erro(vm, j, j->i, "Expecting property name enclosed in double quotes"); }
                Value k, v;
                if (j_texto(vm, j, &k) != 0) { vm->sp--; return -1; }
                if (fixa_raiz(vm, k) != 0) { vm->sp--; BERRO(vm, "RuntimeError", "estouro da pilha"); }
                j_espaco(j);
                if (j->i >= j->n || j->s[j->i] != ':') { vm->sp -= 2; return j_erro(vm, j, j->i, "Expecting ':' delimiter"); }
                j->i++;
                if (j_valor(vm, j, &v, prof + 1) != 0) { vm->sp -= 2; return -1; }
                if (dict_set(vm, COMO_DICT(cont), &k, &v) != 0) { vm->sp -= 2; BERRO(vm, "MemoryError", "sem memoria"); }
                vm->sp--;                     /* solta a chave */
            } else {
                Value v;
                if (j_valor(vm, j, &v, prof + 1) != 0) { vm->sp--; return -1; }
                PSList *l = COMO_LIST(cont);
                if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
                l->itens[l->len++] = v;
            }
            j_espaco(j);
            if (j->i < j->n && j->s[j->i] == ',') { j->i++; continue; }
            if (j->i < j->n && j->s[j->i] == fecha) { j->i++; break; }
            vm->sp--;
            return j_erro(vm, j, j->i, "Expecting ',' delimiter");
        }
        vm->sp--;
        *out = cont;
        return 0;
    }
    if (j->n - j->i >= 4 && memcmp(j->s + j->i, "true", 4) == 0)  { j->i += 4; *out = MK_BOOL(1); return 0; }
    if (j->n - j->i >= 5 && memcmp(j->s + j->i, "false", 5) == 0) { j->i += 5; *out = MK_BOOL(0); return 0; }
    if (j->n - j->i >= 4 && memcmp(j->s + j->i, "null", 4) == 0)  { j->i += 4; *out = MK_NULL(); return 0; }
    if (c == '-' || (c >= '0' && c <= '9')) {
        int ini = j->i, flutua = 0;
        if (j->s[j->i] == '-') j->i++;
        while (j->i < j->n && j->s[j->i] >= '0' && j->s[j->i] <= '9') j->i++;
        if (j->i < j->n && j->s[j->i] == '.') { flutua = 1; j->i++;
            while (j->i < j->n && j->s[j->i] >= '0' && j->s[j->i] <= '9') j->i++; }
        if (j->i < j->n && (j->s[j->i] == 'e' || j->s[j->i] == 'E')) { flutua = 1; j->i++;
            if (j->i < j->n && (j->s[j->i] == '+' || j->s[j->i] == '-')) j->i++;
            while (j->i < j->n && j->s[j->i] >= '0' && j->s[j->i] <= '9') j->i++; }
        char buf[512];   /* inteiro de JSON pode ser bem maior que 64 dígitos */
        int len = j->i - ini;
        if (len <= 0 || len >= (int)sizeof(buf)) return j_erro(vm, j, j->i, "Expecting value");
        memcpy(buf, j->s + ini, (size_t)len);
        buf[len] = '\0';
        if (flutua) { *out = MK_FLOAT(strtod(buf, NULL)); return 0; }
        /* `strtoll` SATURA em INT64_MAX quando não cabe: um id grande vindo de
         * uma API virava 9223372036854775807 sem erro nenhum. Vai pro bignum. */
        errno = 0;
        long long li = strtoll(buf, NULL, 10);
        if (errno == ERANGE) {
            mpz_t z; mpz_init(z);
            if (mpz_set_str(z, buf, 10) != 0) {
                mpz_clear(z);
                return j_erro(vm, j, j->i, "Expecting value");
            }
            *out = mk_from_mpz(vm, z);
            mpz_clear(z);
            return 0;
        }
        *out = MK_INT((int64_t)li);
        return 0;
    }
    return j_erro(vm, j, j->i, "Expecting value");
}

static int mod_json_parse(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "parse", 1);
    /* já estruturado passa reto */
    if (EH_DICT(args[0]) || EH_SEQ(args[0])) { *out = args[0]; return 0; }
    if (!EH_STRING(args[0])) BERRO(vm, "TypeError", "parse() argument 1 must be str, not %s",
                                  nome_do_tipo_valor(args[0]));
    PSString *s = COMO_STRING(args[0]);
    JLeitor j = { s->chars, s->len, 0 };
    if (j_valor(vm, &j, out, 0) != 0) return -1;
    j_espaco(&j);
    if (j.i != j.n) return j_erro(vm, &j, j.i, "Extra data");
    return 0;
}

/* ── date ───────────────────────────────────────────────────────────────── */
static int data_formatada(VM *vm, Value *out, const char *fmt)
{
    time_t agora = time(NULL);
    struct tm tmv;
    localtime_r(&agora, &tmv);
    char buf[64];
    size_t k = strftime(buf, sizeof(buf), fmt, &tmv);
    PSString *r = nova_string(vm, buf, (int)k);
    if (!r) BERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(r);
    return 0;
}

static int mod_date_time(VM *v, Value *a, int n, Value *o)     { (void)a; EXIGE_ARGS(v,"time",0);     return data_formatada(v, o, "%H:%M:%S"); }
static int mod_date_today(VM *v, Value *a, int n, Value *o)    { (void)a; EXIGE_ARGS(v,"today",0);    return data_formatada(v, o, "%d/%m/%Y"); }
static int mod_date_datahora(VM *v, Value *a, int n, Value *o) { (void)a; EXIGE_ARGS(v,"datahora",0); return data_formatada(v, o, "%d/%m/%Y %H:%M:%S"); }
/* `now()` é ISO 8601 com espaço no lugar do T */
static int mod_date_now(VM *v, Value *a, int n, Value *o)      { (void)a; EXIGE_ARGS(v,"now",0);      return data_formatada(v, o, "%Y-%m-%d %H:%M:%S"); }

static int mod_date_timestamp(VM *vm, Value *args, int n, Value *out)
{
    (void)args;
    EXIGE_ARGS(vm, "timestamp", 0);
    *out = MK_INT((int64_t)time(NULL));
    return 0;
}

/* `hora(hours, minutes, days)` devolve SEGUNDOS — some com timestamp(). */
static int mod_date_hora(VM *vm, Value *args, int n, Value *out)
{
    if (n > 3) return erro_aridade(vm, "hora", 0, 3, n);
    int64_t v[3] = { 0, 0, 0 };
    for (int i = 0; i < n && i < 3; i++) {
        /* buraco de arg nomeado ausente = 0 (o mapeador preenche com NULL/UNSET) */
        if (args[i].t == V_UNSET || args[i].t == V_NULL) continue;
        if (args[i].t == V_INT)        v[i] = args[i].as.i;
        else if (args[i].t == V_FLOAT) v[i] = (int64_t)args[i].as.d;
        else if (args[i].t == V_BOOL)  v[i] = args[i].as.b ? 1 : 0;
        else BERRO(vm, "TypeError", "'%s' object cannot be interpreted as an integer",
              nome_do_tipo_valor(args[i]));
    }
    *out = MK_INT(v[0] * 3600 + v[1] * 60 + v[2] * 86400);
    return 0;
}



/* TIPO_CHAR, TIPO_PFILE e TIPO_OBJ saíram destes `#define` e entraram no enum
 * lá em cima, junto com os outros — eram três números escritos à mão que
 * tinham que casar com a posição no array de nomes. */

/* Um item casa o `count` se bate no TIPO e, quando há valor, é igual a ele. */
static int count_casa(const Value *item, int64_t tipo, const Value *val, int tem_val);

/* `data == Usuario`: o dict valida contra o model. Campo ausente, tipo
 * errado ou comprimento estourado reprovam; chave extra passa. */
static int model_valida(const PSModel *m, const Value *v)
{
    if (!EH_DICT(*v)) return 0;
    PSDict *d = COMO_DICT(*v);
    for (int32_t i = 0; i < m->ncampos; i++) {
        const PSModelCampo *f = &m->campos[i];
        /* chave pelo nome do campo */
        Value achado = MK_NULL();
        int tem = 0;
        for (int k = 0; k < d->usados && !tem; k++) {
            if (d->entradas[k].estado != 1) continue;
            Value ch = d->entradas[k].chave;
            if (EH_STRING(ch) && strcmp(COMO_STRING(ch)->chars, f->nome) == 0) {
                achado = d->entradas[k].valor;
                tem = 1;
            }
        }
        if (!tem || achado.t == V_NULL) return 0;
        /* tipo: int aceita flo e vice-versa (validação de dado, não de
         * representação — é o que o interpretador faz) */
        if (!model_campo_aceita(f->tipo, &achado)) return 0;
        if (f->length >= 0) {
            if (f->tipo == TIPO_STR) {
                PSString *sv = COMO_STRING(achado);
                if (utf8_conta(sv->chars, sv->len) > f->length) return 0;
            } else if (f->tipo == TIPO_INT) {
                int64_t x = (achado.t == V_INT) ? achado.as.i : (int64_t)achado.as.d;
                if (x < 0) x = -x;
                int dig = 1;
                while (x >= 10) { x /= 10; dig++; }
                if (dig > f->length) return 0;
            }
        }
    }
    return 1;
}

/* A MESMA validação do `==`, dizendo QUAL campo reprovou e POR QUÊ.
 *
 * O `model_valida` devolve 0/1, que basta pro operador e não basta pra uma
 * resposta HTTP: "corpo inválido" manda o cliente adivinhar entre oito campos.
 * Reimplementar a regra aqui faria as duas divergirem no primeiro tipo novo —
 * então esta função percorre a mesma tabela de campos e o `model_valida`
 * continua sendo o dono da decisão; aqui só se acrescenta o PORQUÊ.
 *
 * Devolve 1 quando passa. Quando não, preenche `campo` e `motivo`. */
/* Era um switch repetindo os mesmos nomes da tabela — duas listas pra manter
 * iguais, e o campo de model dizia "?" pros tipos que faltavam nela. */
static const char *model_nome_tipo(int32_t t) { return tipo_nome(t); }

/* O tipo do CAMPO DE MODEL é mais frouxo que o `is`: aqui `int` aceita `flo` e
 * vice-versa, porque model valida DADO que veio de fora (JSON não distingue
 * 1 de 1.0), não representação. A regra estava escrita duas vezes, em dois
 * switches iguais a algumas linhas de distância. */
static int model_campo_aceita(int32_t tipo, const Value *v)
{
    switch (tipo) {
        case TIPO_INT:
        case TIPO_FLO:  return v->t == V_INT || v->t == V_FLOAT;
        case TIPO_LONG: return EH_INTEIRO(*v) || v->t == V_FLOAT;
        case TIPO_STR:
        case TIPO_BOOL:
        case TIPO_LIST:
        case TIPO_DICT:
        case TIPO_TUP:  return valor_eh_tipo(v, tipo);
        default:        return 0;
    }
}

static int model_valida_detalhe(const PSModel *m, const Value *v,
                                char *campo, size_t ccap, char *motivo, size_t mcap)
{
    campo[0] = '\0'; motivo[0] = '\0';
    if (!EH_DICT(*v)) {
        snprintf(motivo, mcap, "o corpo precisa ser um objeto JSON");
        return 0;
    }
    PSDict *d = COMO_DICT(*v);
    for (int32_t i = 0; i < m->ncampos; i++) {
        const PSModelCampo *f = &m->campos[i];
        Value um = MK_NULL();
        int tem = 0;
        for (int k = 0; k < d->usados && !tem; k++) {
            if (d->entradas[k].estado != 1) continue;
            Value ch = d->entradas[k].chave;
            if (EH_STRING(ch) && strcmp(COMO_STRING(ch)->chars, f->nome) == 0) {
                um = d->entradas[k].valor;
                tem = 1;
            }
        }
        snprintf(campo, ccap, "%s", f->nome);
        if (!tem)              { snprintf(motivo, mcap, "faltando"); return 0; }
        if (um.t == V_NULL)    { snprintf(motivo, mcap, "nao pode ser null"); return 0; }

        Value so_esse = *v;
        (void)so_esse;
        int tipo_ok = model_campo_aceita(f->tipo, &um);
        if (!tipo_ok) {
            snprintf(motivo, mcap, "esperava %s, veio %s",
                     model_nome_tipo(f->tipo), nome_do_tipo_valor(um));
            return 0;
        }
        if (f->length >= 0) {
            if (f->tipo == TIPO_STR) {
                PSString *sv = COMO_STRING(um);
                int q = utf8_conta(sv->chars, sv->len);
                if (q > f->length) {
                    snprintf(motivo, mcap, "no maximo %d caracteres, veio %d", f->length, q);
                    return 0;
                }
            } else if (f->tipo == TIPO_INT) {
                int64_t x = (um.t == V_INT) ? um.as.i : (int64_t)um.as.d;
                if (x < 0) x = -x;
                int dig = 1;
                while (x >= 10) { x /= 10; dig++; }
                if (dig > f->length) {
                    snprintf(motivo, mcap, "no maximo %d digitos, veio %d", f->length, dig);
                    return 0;
                }
            }
        }
    }
    campo[0] = '\0';
    return 1;
}

/* ── a tabela: uma linha por tipo, nome e pertinência juntos ───────────────
 *
 * Indexada pelo CÓDIGO do tipo — a mesma ordem do enum, que é a gravada no
 * bytecode. Quem acrescenta um tipo acrescenta UMA linha, e nome e teste
 * nascem casados; antes eram dois códigos distantes que podiam discordar. */
static int aceita_str(const Value *v)   { return EH_STRING(*v); }
static int aceita_int(const Value *v)   { return v->t == V_INT; }   /* bool NÃO conta */
static int aceita_flo(const Value *v)   { return v->t == V_FLOAT; }
static int aceita_bool(const Value *v)  { return v->t == V_BOOL; }
static int aceita_list(const Value *v)  { return EH_LIST(*v); }
static int aceita_dict(const Value *v)  { return EH_DICT(*v); }
static int aceita_tup(const Value *v)   { return EH_TUPLA(*v); }
static int aceita_type(const Value *v)  { return v->t == V_TIPO; }
/* Todo arquivo é PoolFile: o handle do `open()` (OBJ_ARQUIVO) e o carregado
 * pelo `os.loadFile()` (OBJ_POOLFILE) são o MESMO tipo pra linguagem —
 * `type()` responde "PoolFile" nos dois. A tabela tem que dizer o mesmo, ou
 * `f is PoolFile` e `PoolFile f = open(...)` recusam metade dos arquivos. */
static int aceita_pfile(const Value *v) { return EH_PFILE(*v) || EH_ARQUIVO(*v); }
/* `char` é caractere VISÍVEL: string de uma posição que não é branco. */
static int aceita_char(const Value *v)
{
    return EH_STRING(*v)
        && utf8_conta(COMO_STRING(*v)->chars, COMO_STRING(*v)->len) == 1
        && !cp_eh_branco((unsigned char)COMO_STRING(*v)->chars[0]);
}
/* `Object`: qualquer objeto que não é str/list/dict/tup/bytes — instância de
 * classe, servidor, conexão, arquivo, função. `Object app = Jinker(...)`.
 *
 * FUNCT É OBJETO. O comentário já prometia "função" e o teste não entregava:
 * `V_FUNC` e `V_NATIVE` não são `V_OBJ` (o valor carrega o índice do proto,
 * não um ponteiro pro monte), então `Object f = funct(){ … }` era recusado.
 * A incoerência aparecia até dentro da mesma expressão — lambda que CAPTURA
 * vira OBJ_CLOSURE e passava, lambda que não captura não passava. Quem
 * escreve `Object` quer dizer "qualquer coisa que não é escalar nem coleção",
 * e uma funct é exatamente isso: `type()` dela responde "funct" nas seis
 * formas (V_FUNC, V_NATIVE, closure, bound, nativa, método nativo). */
static int aceita_obj(const Value *v)
{
    if (v->t == V_FUNC || v->t == V_NATIVE) return 1;
    return v->t == V_OBJ && !EH_STRING(*v) && !EH_LIST(*v) && !EH_DICT(*v)
        && !EH_TUPLA(*v) && !EH_BYTES(*v);
}
/* `long`: inteiro de qualquer tamanho — cabendo ou não em 64 bits. */
static int aceita_long(const Value *v)  { return EH_INTEIRO(*v); }

static const struct { const char *nome; int (*aceita)(const Value *); } TIPOS[] = {
    { "str",      aceita_str   },
    { "int",      aceita_int   },
    { "flo",      aceita_flo   },
    { "bool",     aceita_bool  },
    { "list",     aceita_list  },
    { "dict",     aceita_dict  },
    { "tup",      aceita_tup   },
    { "type",     aceita_type  },
    { "char",     aceita_char  },
    { "PoolFile", aceita_pfile },
    { "Object",   aceita_obj   },
    { "long",     aceita_long  },
};

static const char *tipo_nome(int64_t t)
{
    if (tipo_eh_excecao(t)) return EXCECOES[t - TIPO_EXC_BASE].nome;
    return (t >= 0 && t < (int64_t)(sizeof(TIPOS) / sizeof(TIPOS[0]))) ? TIPOS[t].nome : "?";
}

/* `x is <tipo>`, campo de model, `count <tipo>` e a coerção de declaração —
 * os quatro perguntam AQUI. */
static int valor_eh_tipo(const Value *v, int64_t tipo)
{
    if (tipo < 0 || tipo >= (int64_t)(sizeof(TIPOS) / sizeof(TIPOS[0]))) return 0;
    return TIPOS[tipo].aceita(v);
}

/* Índice na TIPOS[] a partir do nome canônico, ou -1 se o nome não é um tipo
 * da tabela (aí é nome de Entity ou de objeto nativo). */
static int64_t tipo_indice(const char *nome)
{
    if (!nome) return -1;
    for (size_t i = 0; i < sizeof(TIPOS) / sizeof(TIPOS[0]); i++)
        if (strcmp(TIPOS[i].nome, nome) == 0) return (int64_t)i;
    return -1;
}

/* A classe `c`, ou alguma ancestral dela, chama-se `nome`? */
static int classe_eh(const PSClass *c, const char *nome)
{
    if (!c) return 0;
    if (c->nome && strcmp(c->nome, nome) == 0) return 1;
    for (int32_t i = 0; i < c->npais; i++)
        if (classe_eh(c->pais[i], nome)) return 1;
    return 0;
}

/* O valor serve pro tipo declarado de um parâmetro (`funct f(str nome)`)?
 * Três origens de nome, nesta ordem: a TIPOS[] (str, int, char, PoolFile…),
 * o nome de tipo do próprio valor (Response, PoolCursor, MailMessage…) e a
 * cadeia de Entity — subclasse serve onde a mãe é pedida.
 * Só responde SIM ou NÃO: nada aqui converte valor nenhum. */
static int param_casa_tipo(const Value *v, const char *tipo)
{
    if (!tipo || !*tipo) return 1;              /* parâmetro sem tipo */
    int64_t idx = tipo_indice(tipo);
    if (idx >= 0) return valor_eh_tipo(v, idx);
    if (strcmp(nome_do_tipo_valor(*v), tipo) == 0) return 1;
    if (EH_INST(*v)) return classe_eh(COMO_INST(*v)->classe, tipo);
    return 0;
}

/* Confere os tipos declarados dos parâmetros de uma chamada. `vals[k]` é o
 * valor do parâmetro de índice `base + k` — `base` é 1 quando o `self` foi
 * dropado (@static chamado na Entity) e os posicionais começam no slot 1.
 * Valor UNSET é pulado: ou é o self que ficou vazio, ou é parâmetro que não
 * veio e vai receber o padrão no prólogo.
 *
 * TODO ponto que monta frame chama isto — chamada direta, método, @static,
 * argumento nomeado, gerador, async. Uma checagem que mora em cinco lugares
 * diverge no dia em que um deles for editado sozinho; por isso a regra vive
 * AQUI e lá só tem a chamada. Devolve -1 com vm->erro posto quando um
 * argumento não bate: a linguagem RECUSA, nunca converte. */
static int checa_param_tipos(VM *vm, const Proto *np, const Value *vals, int n, int base)
{
    if (!np->param_tipos) return 0;
    for (int k = 0; k < n; k++) {
        int idx = base + k;
        if (idx < 0 || idx >= np->nparams) continue;
        const char *t = np->param_tipos[idx];
        if (!t) continue;
        const Value *v = &vals[k];
        if (v->t == V_UNSET) continue;
        if (param_casa_tipo(v, t)) continue;
        snprintf(vm->erro, sizeof(vm->erro),
                 "parâmetro %s de %s() esperava %s, recebeu %s",
                 (np->param_nomes && np->param_nomes[idx]) ? np->param_nomes[idx] : "?",
                 np->nome ? np->nome : "?", t, nome_do_tipo_valor(*v));
        snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "AttributedValueError");
        return -1;
    }
    return 0;
}

static int count_casa(const Value *item, int64_t tipo, const Value *val, int tem_val)
{
    int bate;
    if (tipo == TIPO_CHAR)
        bate = EH_STRING(*item) && utf8_conta(COMO_STRING(*item)->chars, COMO_STRING(*item)->len) == 1
            && !cp_eh_branco((unsigned char)COMO_STRING(*item)->chars[0]);
    else
        bate = valor_eh_tipo(item, tipo);
    if (!bate) return 0;
    return tem_val ? val_iguais(item, val) : 1;
}

/* Percorre o container do `count`. `pares` diz se devolve a lista de
 * (indice, item) ou só o total. Dict conta pelos VALORES, com a chave no
 * lugar do índice — é o que o interpretador faz. */
static int count_percorre(VM *vm, Value cont, int64_t tipo, const Value *val, int tem_val,
                          int pares, Value *out)
{
    PSList *lista = NULL;
    int64_t total = 0;
    if (pares) {
        lista = lista_com_cap(vm, 4, OBJ_LIST);
        if (!lista) { snprintf(vm->erro, sizeof(vm->erro), "sem memoria em count"); return -1; }
        if (fixa_raiz(vm, MK_OBJ(lista)) != 0) { snprintf(vm->erro, sizeof(vm->erro), "estouro da pilha"); return -1; }
    }
    /* Null e float não têm o que contar — zero, não erro. Só INT vira texto:
     * `count int in 5.5` é 0 no interpretador, não 2. */
    if (cont.t == V_NULL || cont.t == V_UNSET || cont.t == V_FLOAT
            || cont.t == V_BOOL) {
        if (pares) { vm->sp--; *out = MK_OBJ(lista); } else *out = MK_INT(0);
        return 0;
    }
    /* Container INT: vira texto e conta dígito por dígito. `count int in 555`
     * é 3 — é a definição do interpretador, não um acidente. */
    int cont_era_int = (cont.t == V_INT);
    Value conv = cont;
    if (cont.t == V_INT) {
        TXTBUF_AUTO t = {0};
        if (valor_para_texto(&t, &cont, 0) != 0) {
            if (pares) vm->sp--;
            snprintf(vm->erro, sizeof(vm->erro), "sem memoria em count");
            return -1;
        }
        PSString *txt = nova_string(vm, t.b ? t.b : "", t.n);
        if (!txt) { if (pares) vm->sp--; snprintf(vm->erro, sizeof(vm->erro), "sem memoria"); return -1; }
        conv = MK_OBJ(txt);
    }
    cont = conv;

    /* Texto procurado DENTRO de texto: conta ocorrências da subcadeia, com
     * sobreposição — `count str("aa") in "aaaa"` é 3, não 2. Sem este ramo o
     * laço abaixo compararia caractere por caractere e um alvo de dois ou
     * mais nunca casaria. */
    if (!cont_era_int && EH_STRING(cont) && tipo == TIPO_STR && tem_val
            && EH_STRING(*val)) {
        PSString *palheiro = COMO_STRING(cont), *agulha = COMO_STRING(*val);
        if (agulha->len > 0) {
            int byte_ = 0, idx = 0;
            while (byte_ + agulha->len <= palheiro->len) {
                unsigned int cp;
                int passo = utf8_le(palheiro->chars, palheiro->len, byte_, &cp);
                if (!passo) break;
                if (memcmp(palheiro->chars + byte_, agulha->chars, (size_t)agulha->len) == 0) {
                    total++;
                    if (pares) {
                        PSString *achado = nova_string(vm, agulha->chars, agulha->len);
                        PSList *par = achado ? nova_seq(vm, 2, OBJ_TUPLE) : NULL;
                        if (!par) { vm->sp--; snprintf(vm->erro, sizeof(vm->erro), "sem memoria"); return -1; }
                        par->itens[0] = MK_INT(idx); par->itens[1] = MK_OBJ(achado); par->len = 2;
                        if (lista->len >= lista->cap && cresce_lista(vm, lista) != 0) {
                            vm->sp--; snprintf(vm->erro, sizeof(vm->erro), "sem memoria"); return -1;
                        }
                        lista->itens[lista->len++] = MK_OBJ(par);
                    }
                }
                byte_ += passo;
                idx++;
            }
        }
        if (pares) { vm->sp--; *out = MK_OBJ(lista); } else *out = MK_INT(total);
        return 0;
    }

    int n_itens;
    if (EH_SEQ(cont))         n_itens = COMO_LIST(cont)->len;
    else if (EH_DICT(cont))   n_itens = COMO_DICT(cont)->count;
    else if (EH_STRING(cont)) n_itens = utf8_conta(COMO_STRING(cont)->chars, COMO_STRING(cont)->len);
    else {
        /* Container que não se itera conta ZERO, não é erro — `count` é uma
         * pergunta ("quantos?"), e a resposta pra algo sem itens é nenhum. */
        if (pares) { vm->sp--; *out = MK_OBJ(lista); } else *out = MK_INT(0);
        return 0;
    }

    int byte = 0;                       /* posição em bytes, pro caso string */
    for (int i = 0; i < n_itens; i++) {
        Value item, chave;
        if (EH_SEQ(cont)) {
            item = COMO_LIST(cont)->itens[i];
            chave = MK_INT(i);
        } else if (EH_DICT(cont)) {
            int pos = dict_pos_viva(COMO_DICT(cont), i);
            if (pos < 0) continue;
            item = COMO_DICT(cont)->entradas[pos].valor;
            chave = COMO_DICT(cont)->entradas[pos].chave;
        } else {
            unsigned int cp;
            int u = utf8_le(COMO_STRING(cont)->chars, COMO_STRING(cont)->len, byte, &cp);
            if (!u) break;
            PSString *ch = nova_string(vm, COMO_STRING(cont)->chars + byte, u);
            if (!ch) { if (pares) vm->sp--; snprintf(vm->erro, sizeof(vm->erro), "sem memoria"); return -1; }
            byte += u;
            item = MK_OBJ(ch);
            chave = MK_INT(i);
        }
        /* Dentro de um número, cada caractere é um DÍGITO: casa como `int`
         * e compara pelo valor numérico, não pelo texto. */
        int casou;
        if (cont_era_int && EH_STRING(item)) {
            PSString *d = COMO_STRING(item);
            int eh_dig = d->len == 1 && d->chars[0] >= '0' && d->chars[0] <= '9';
            casou = eh_dig && tipo == TIPO_INT;
            if (casou && tem_val) {
                Value nd = MK_INT(d->chars[0] - '0');
                casou = val_iguais(&nd, val);
            }
        } else {
            casou = count_casa(&item, tipo, val, tem_val);
        }
        if (!casou) continue;
        total++;
        if (!pares) continue;
        PSList *par = nova_seq(vm, 2, OBJ_TUPLE);
        if (!par) { vm->sp--; snprintf(vm->erro, sizeof(vm->erro), "sem memoria"); return -1; }
        par->itens[0] = chave; par->itens[1] = item; par->len = 2;
        if (lista->len >= lista->cap && cresce_lista(vm, lista) != 0) {
            vm->sp--; snprintf(vm->erro, sizeof(vm->erro), "sem memoria"); return -1;
        }
        lista->itens[lista->len++] = MK_OBJ(par);
    }
    if (pares) { vm->sp--; *out = MK_OBJ(lista); }
    else       { *out = MK_INT(total); }
    return 0;
}

/* ── regex ──────────────────────────────────────────────────────────────── */
/* Compila o padrão e devolve erro de linguagem se ele for inválido. */
static PSRegex *rx_compila(VM *vm, Value v, const char *quem)
{
    if (!EH_STRING(v)) {
        snprintf(vm->erro, sizeof(vm->erro), "%s() argument 1 must be str, not %s",
                 quem, nome_do_tipo_valor(v));
        snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "TypeError");
        return NULL;
    }
    PSString *p = COMO_STRING(v);
    char e[256] = {0};
    PSRegex *r = ps_regex_compila(p->chars, p->len, e, sizeof(e));
    if (!r) {
        snprintf(vm->erro, sizeof(vm->erro), "%s", e[0] ? e : "regex invalida");
        /* ValueError: o TIPO do padrão está certo (é str),
         * é o VALOR que não compila. */
        snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "ValueError");
    }
    return r;
}

/* `findall`: sem grupo devolve o casamento inteiro; com UM grupo
 * devolve só ele; com vários, uma tupla por casamento. */
/* NÃO libera o `r`: quem compila é quem libera (o Pattern reusa). */
static int rx_findall(VM *vm, PSRegex *r, const char *s, int len, Value *out)
{
    PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
    if (!l) { BERRO(vm, "MemoryError", "sem memoria"); }
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) { BERRO(vm, "RuntimeError", "estouro da pilha"); }
    int ng = ps_regex_ngrupos(r);
    int de = 0;
    for (;;) {
        RxCaptura cap;
        int achou = ps_regex_busca(r, s, len, de, &cap);
        if (achou < 0) { vm->sp--; BERRO(vm, "RuntimeError", "regex: backtracking demais"); }
        if (!achou) break;
        Value item;
        if (ng == 0) {
            PSString *m = nova_string(vm, s + cap.inicio[0], cap.fim[0] - cap.inicio[0]);
            if (!m) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
            item = MK_OBJ(m);
        } else if (ng == 1) {
            int i0 = cap.inicio[1], i1 = cap.fim[1];
            PSString *m = (i0 < 0) ? nova_string(vm, "", 0) : nova_string(vm, s + i0, i1 - i0);
            if (!m) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
            item = MK_OBJ(m);
        } else {
            PSList *t = nova_seq(vm, ng, OBJ_TUPLE);
            if (!t) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
            t->len = 0;
            item = MK_OBJ(t);
            if (fixa_raiz(vm, item) != 0) { vm->sp--; BERRO(vm, "RuntimeError", "estouro"); }
            for (int g = 1; g <= ng; g++) {
                int i0 = cap.inicio[g], i1 = cap.fim[g];
                PSString *m = (i0 < 0) ? nova_string(vm, "", 0) : nova_string(vm, s + i0, i1 - i0);
                if (!m) { vm->sp -= 2; BERRO(vm, "MemoryError", "sem memoria"); }
                t->itens[g - 1] = MK_OBJ(m);
                t->len = g;
            }
            vm->sp--;
        }
        if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
        l->itens[l->len++] = item;
        /* casamento vazio não pode travar o laço: anda um caractere */
        de = (cap.fim[0] > cap.inicio[0]) ? cap.fim[0] : cap.fim[0] + 1;
        if (de > len) break;
    }
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

/* `\1`..`\9` na substituição viram o grupo correspondente. */
/* Expande o replacement do sub(). O texto de troca é
 * uma mini-linguagem: `\1`, `\g<1>`, `\g<nome>` e os escapes de
 * caractere (`\n`, `\t`, `\\`). Antes só `\1`-`\9` e `\\` eram
 * entendidos: `r"\n"` saía como a barra mais o 'n' literal e `\g<1>` ia cru
 * pro resultado. */
static int rx_expande(SBuf *b, const char *rep, int rlen, const char *s,
                      const RxCaptura *cap, const PSRegex *r, char *erro, int erro_cap)
{
    for (int i = 0; i < rlen; i++) {
        if (rep[i] != '\\' || i + 1 >= rlen) {
            if (sb_bytes(b, rep + i, 1) != 0) return -1;
            continue;
        }
        char e = rep[i + 1];
        int g = -1;
        int p_ref = i + 1;   /* posicao acusada no erro: o digito de `\5`, ou o
                              * inicio do nome em `\g<...>` (ajustado abaixo) */
        if (e >= '0' && e <= '9') {
            /* `\0`..`\9` sao referencia de GRUPO — `\0` e o casamento inteiro,
             * e por isso nunca chega ao escape de caractere la embaixo.
             * `\12` e o grupo 12 quando ele existe (ate 2 digitos). */
            g = e - '0';
            i++;
            if (i + 1 < rlen && rep[i + 1] >= '0' && rep[i + 1] <= '9'
                    && g * 10 + (rep[i + 1] - '0') <= cap->ngrupos) {
                g = g * 10 + (rep[i + 1] - '0');
                i++;
            }
        } else if (e == 'g' && i + 2 < rlen && rep[i + 2] == '<') {
            int j = i + 3;
            while (j < rlen && rep[j] != '>') j++;
            if (j >= rlen) {
                snprintf(erro, (size_t)erro_cap,
                         "missing >, unterminated name at position %d", i + 3);
                return -2;
            }
            int nlen = j - (i + 3);
            const char *nome = rep + i + 3;
            if (nlen <= 0) {
                snprintf(erro, (size_t)erro_cap,
                         "missing group name at position %d", i + 3);
                return -2;
            }
            int so_digito = 1;
            for (int t = 0; t < nlen; t++)
                if (nome[t] < '0' || nome[t] > '9') { so_digito = 0; break; }
            if (so_digito) {
                g = 0;
                for (int t = 0; t < nlen; t++) g = g * 10 + (nome[t] - '0');
            } else {
                g = ps_regex_grupo_por_nome(r, nome, nlen);
                if (g < 0) {
                    /* nome que nao existe: a mensagem nao leva posicao */
                    snprintf(erro, (size_t)erro_cap, "unknown group name '%.*s'",
                             nlen, nome);
                    return -2;
                }
            }
            p_ref = i + 3;   /* o erro aponta o nome, nao a barra */
            i = j;
        } else {
            /* escape de caractere: o mesmo conjunto do literal da linguagem.
             * `\0` NAO esta aqui de proposito: e o grupo 0, tratado acima. */
            char c;
            switch (e) {
                case 'n': c = '\n';  break;
                case 't': c = '\t';  break;
                case 'r': c = '\r';  break;
                case 'f': c = '\f';  break;
                case 'v': c = '\v';  break;
                case 'a': c = '\a';  break;
                case 'b': c = '\b';  break;
                case '\\': c = '\\'; break;
                default:
                    /* desconhecido: mantém os dois bytes — `\%` não é escape,
                     * então a barra fica */
                    if (sb_bytes(b, rep + i, 2) != 0) return -1;
                    i++;
                    continue;
            }
            if (sb_bytes(b, &c, 1) != 0) return -1;
            i++;
            continue;
        }
        if (g > cap->ngrupos) {
            snprintf(erro, (size_t)erro_cap,
                     "invalid group reference %d at position %d", g, p_ref);
            return -2;
        }
        if (cap->inicio[g] >= 0
                && sb_bytes(b, s + cap->inicio[g], cap->fim[g] - cap->inicio[g]) != 0) return -1;
    }
    return 0;
}

/* NÃO libera o `r`: quem compila é quem libera. O Pattern de `regex.compile`
 * reusa o mesmo PSRegex em toda chamada — liberar aqui deixava o objeto com
 * ponteiro solto e o uso seguinte era segfault. */
static int rx_sub(VM *vm, PSRegex *r, const char *s, int len,
                  const char *rep, int rlen, int64_t limite, Value *out)
{
    SBUF_AUTO b = {0};
    int de = 0;
    int64_t feitos = 0;
    while (de <= len) {
        if (limite > 0 && feitos >= limite) break;
        RxCaptura cap;
        int achou = ps_regex_busca(r, s, len, de, &cap);
        if (achou < 0) BERRO(vm, "RuntimeError", "regex: backtracking demais");
        if (!achou) break;
        if (sb_bytes(&b, s + de, cap.inicio[0] - de) != 0) BERRO(vm, "MemoryError", "sem memoria");
        {
            char msg[160] = {0};
            int rc = rx_expande(&b, rep, rlen, s, &cap, r, msg, (int)sizeof(msg));
            /* ValueError: a MESMA classe que `rx_compila` da ao padrao invalido.
             * Grupo inexistente na substituicao saia como TypeError — duas
             * respostas pra "esta regex nao serve", uma em cada funcao. */
            if (rc == -2) BERRO(vm, "ValueError", "%s", msg);
            if (rc != 0)  BERRO(vm, "MemoryError", "sem memoria");
        }
        feitos++;
        if (cap.fim[0] > cap.inicio[0]) {
            de = cap.fim[0];
        } else {
            /* casamento vazio: copia um byte e anda, senão repetiria pra sempre */
            if (cap.fim[0] < len && sb_bytes(&b, s + cap.fim[0], 1) != 0) BERRO(vm, "MemoryError", "sem memoria");
            de = cap.fim[0] + 1;
        }
    }
    if (de < len && sb_bytes(&b, s + de, len - de) != 0) BERRO(vm, "MemoryError", "sem memoria");
    PSString *res = nova_string(vm, b.b ? b.b : "", b.n);
    if (!res) BERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(res);
    return 0;
}

/* `match` e `fullmatch` sao a MESMA funcao (as duas casam a string inteira),
 * mas cada uma assina o proprio nome no erro: com "match" chumbado,
 * `regex.fullmatch("a")` reclamava de `match()`. */
static int regex_match_nome(VM *vm, Value *args, int n, Value *out, const char *quem)
{
    if (n != 2) return erro_aridade(vm, quem, 2, 2, n);
    if (!EH_STRING(args[1])) BERRO(vm, "TypeError", "%s() argument 2 must be str, not %s",
                                  quem, nome_do_tipo_valor(args[1]));
    PSRegex *r = rx_compila(vm, args[0], quem);
    if (!r) return -1;
    PSString *s = COMO_STRING(args[1]);
    RxCaptura cap;
    int v = ps_regex_casa_tudo(r, s->chars, s->len, &cap);
    ps_regex_free(r);
    if (v < 0) BERRO(vm, "RuntimeError", "regex: backtracking demais");
    *out = MK_BOOL(v);
    return 0;
}
static int mod_regex_match(VM *vm, Value *a, int n, Value *o)     { return regex_match_nome(vm, a, n, o, "match"); }
static int mod_regex_fullmatch(VM *vm, Value *a, int n, Value *o) { return regex_match_nome(vm, a, n, o, "fullmatch"); }

static int mod_regex_search(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "search", 2);
    if (!EH_STRING(args[1])) BERRO(vm, "TypeError", "search() argument 2 must be str, not %s",
                                  nome_do_tipo_valor(args[1]));
    PSRegex *r = rx_compila(vm, args[0], "search");
    if (!r) return -1;
    PSString *s = COMO_STRING(args[1]);
    RxCaptura cap;
    int v = ps_regex_busca(r, s->chars, s->len, 0, &cap);
    ps_regex_free(r);
    if (v < 0) BERRO(vm, "RuntimeError", "regex: backtracking demais");
    *out = MK_BOOL(v);
    return 0;
}

static int mod_regex_findall(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "findall", 2);
    if (!EH_STRING(args[1])) BERRO(vm, "TypeError", "findall() argument 2 must be str, not %s",
                                  nome_do_tipo_valor(args[1]));
    PSRegex *r = rx_compila(vm, args[0], "findall");
    if (!r) return -1;
    PSString *s = COMO_STRING(args[1]);
    int rc = rx_findall(vm, r, s->chars, s->len, out);
    ps_regex_free(r);      /* quem compila, libera */
    return rc;
}

static int mod_regex_sub(VM *vm, Value *args, int n, Value *out)
{
    if (n < 3 || n > 4) return erro_aridade(vm, "sub", 3, 4, n);
    if (!EH_STRING(args[1]) || !EH_STRING(args[2]))
        BERRO(vm, "TypeError", "sub() argument %d must be str, not %s",
              EH_STRING(args[1]) ? 3 : 2,
              nome_do_tipo_valor(EH_STRING(args[1]) ? args[2] : args[1]));
    int64_t limite = 0;
    if (n == 4) {
        if (args[3].t != V_INT)
            BERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[3]));
        limite = args[3].as.i;
    }
    PSRegex *r = rx_compila(vm, args[0], "sub");
    if (!r) return -1;
    PSString *rep = COMO_STRING(args[1]), *s = COMO_STRING(args[2]);
    int rc = rx_sub(vm, r, s->chars, s->len, rep->chars, rep->len, limite, out);
    ps_regex_free(r);      /* quem compila, libera */
    return rc;
}

/* corpo do split, compartilhado pelo módulo e pelo Pattern compilado (que NÃO
 * pode liberar o `r` — ele vive no objeto). */
static int rx_split(VM *vm, PSRegex *r, const char *src, int slen, int64_t maxsplit, Value *out)
{
    PSList *l = lista_com_cap(vm, 4, OBJ_LIST);
    if (!l) BERRO(vm, "MemoryError", "sem memoria");
    if (fixa_raiz(vm, MK_OBJ(l)) != 0) BERRO(vm, "RuntimeError", "estouro");
    int de = 0, ini_campo = 0;
    int64_t cortes = 0;
    while (de <= slen) {
        RxCaptura cap;
        int achou = ps_regex_busca(r, src, slen, de, &cap);
        if (achou < 0) { vm->sp--; BERRO(vm, "RuntimeError", "regex: backtracking demais"); }
        if (!achou) break;
        if (maxsplit > 0 && cortes >= maxsplit) break;
        cortes++;
        PSString *campo = nova_string(vm, src + ini_campo, cap.inicio[0] - ini_campo);
        if (!campo) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
        if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
        l->itens[l->len++] = MK_OBJ(campo);
        /* Grupos de captura do separador ENTRAM no resultado, como no `re`:
         * `split(r"(,)", "a,b")` dá ['a', ',', 'b']. Antes sumiam. */
        for (int g = 1; g <= cap.ngrupos; g++) {
            Value v;
            if (cap.inicio[g] < 0) v = MK_NULL();
            else {
                PSString *gs = nova_string(vm, src + cap.inicio[g], cap.fim[g] - cap.inicio[g]);
                if (!gs) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
                v = MK_OBJ(gs);
            }
            if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
            l->itens[l->len++] = v;
        }
        if (cap.fim[0] == cap.inicio[0]) {
            /* Separador VAZIO divide também: `split("", "abc")`
             * dá ['', 'a', 'b', 'c', '']. Antes a VM pulava e devolvia ['abc'].
             * O campo seguinte começa aqui e a busca anda um byte, senão o
             * mesmo ponto casaria pra sempre. */
            ini_campo = cap.fim[0];
            de = cap.fim[0] + 1;
        } else {
            ini_campo = de = cap.fim[0];
        }
    }
    PSString *ultimo = nova_string(vm, src + ini_campo, slen - ini_campo);
    if (!ultimo) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
    if (l->len >= l->cap && cresce_lista(vm, l) != 0) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
    l->itens[l->len++] = MK_OBJ(ultimo);
    vm->sp--;
    *out = MK_OBJ(l);
    return 0;
}

static int mod_regex_split(VM *vm, Value *args, int n, Value *out)
{
    /* `maxsplit` já estava anunciado na assinatura do módulo (e na doc), mas o
     * código só aceitava 2 argumentos: passar o 3º dava "espera 2". */
    if (n < 2 || n > 3) return erro_aridade(vm, "split", 2, 3, n);
    if (!EH_STRING(args[1])) BERRO(vm, "TypeError", "split() argument 2 must be str, not %s",
                                  nome_do_tipo_valor(args[1]));
    int64_t maxsplit = 0;
    if (n == 3) {
        if (args[2].t != V_INT)
            BERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[2]));
        maxsplit = args[2].as.i;
    }
    PSRegex *r = rx_compila(vm, args[0], "split");
    if (!r) return -1;
    PSString *s = COMO_STRING(args[1]);
    int rc = rx_split(vm, r, s->chars, s->len, maxsplit, out);
    ps_regex_free(r);
    return rc;
}

/* ── regex.compile(): o padrão COMPILADO como objeto (o `re.Pattern`) ──────
 * As funções do módulo compilam e jogam fora a cada chamada; aqui o PSRegex
 * fica no objeto e é reusado — o ganho é num laço. Os métodos são os mesmos
 * do módulo, sem repetir o padrão. `.pattern` é campo (sem parênteses). */

static int rx_obj_str(VM *vm, Value alvo, Value *args, int n, const char *quem,
                      PSRegex **r, PSString **s)
{
    if (n != 1) return erro_aridade(vm, quem, 1, 1, n);
    if (!EH_STRING(args[0]))
        MERRO(vm, "TypeError", "%s() argument 1 must be str, not %s",
              quem, nome_do_tipo_valor(args[0]));
    *r = COMO_REGEX(alvo)->rx;
    *s = COMO_STRING(args[0]);
    return 0;
}

static int met_rx_match(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    PSRegex *r; PSString *s;
    if (rx_obj_str(vm, alvo, args, n, "match", &r, &s) != 0) return -1;
    RxCaptura cap;
    int v = ps_regex_casa_tudo(r, s->chars, s->len, &cap);
    if (v < 0) MERRO(vm, "RuntimeError", "regex: backtracking demais");
    *out = MK_BOOL(v);
    return 0;
}

static int met_rx_search(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    PSRegex *r; PSString *s;
    if (rx_obj_str(vm, alvo, args, n, "search", &r, &s) != 0) return -1;
    RxCaptura cap;
    int v = ps_regex_busca(r, s->chars, s->len, 0, &cap);
    if (v < 0) MERRO(vm, "RuntimeError", "regex: backtracking demais");
    *out = MK_BOOL(v);
    return 0;
}

static int met_rx_findall(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    PSRegex *r; PSString *s;
    if (rx_obj_str(vm, alvo, args, n, "findall", &r, &s) != 0) return -1;
    return rx_findall(vm, r, s->chars, s->len, out);
}

static int met_rx_split(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    PSRegex *r; PSString *s;
    /* `n < 1` FALTAVA, e nao era so mensagem: sem ele, `p.split()` caia no
     * `rx_obj_str(..., 1, ...)` logo abaixo — que recebe o literal 1 no lugar
     * do `n` real, entao a guarda `n != 1` de la nunca disparava — e lia
     * `args[0]` FORA DO ARRAY. Leitura fora de limites, com resultado
     * dependendo do lixo que estivesse na pilha: com o receptor numa variavel
     * saia `TypeError: argument 1 must be str, not Null`, e inline
     * (`regex.compile("a").split()`) saia `['', '']` calado. Duas respostas
     * pra mesma chamada, nenhuma delas de verdade. */
    if (n < 1 || n > 2) return erro_aridade(vm, "split", 1, 2, n);
    /* O maxsplit era VALIDADO e depois ignorado — `p.split(s, 1)` cortava tudo. */
    int64_t maxsplit = 0;
    if (n == 2) {
        if (args[1].t != V_INT)
            MERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[1]));
        maxsplit = args[1].as.i;
    }
    if (rx_obj_str(vm, alvo, args, 1, "split", &r, &s) != 0) return -1;
    return rx_split(vm, r, s->chars, s->len, maxsplit, out);
}

static int met_rx_sub(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n < 2 || n > 3) return erro_aridade(vm, "sub", 2, 3, n);
    /* diz QUAL argumento veio errado — a mensagem tinha "argument 1" fixo e
     * imprimia o tipo do 1º mesmo quando o errado era o 2º */
    if (!EH_STRING(args[0]) || !EH_STRING(args[1]))
        MERRO(vm, "TypeError", "sub() argument %d must be str, not %s",
                  EH_STRING(args[0]) ? 2 : 1,
                  nome_do_tipo_valor(EH_STRING(args[0]) ? args[1] : args[0]));
    int64_t limite = 0;
    if (n == 3) {
        if (args[2].t != V_INT)
            MERRO(vm, "TypeError",
                  "'%s' object cannot be interpreted as an integer",
                  nome_do_tipo_valor(args[2]));
        limite = args[2].as.i;
    }
    PSString *rep = COMO_STRING(args[0]), *s = COMO_STRING(args[1]);
    return rx_sub(vm, COMO_REGEX(alvo)->rx, s->chars, s->len,
                  rep->chars, rep->len, limite, out);
}

static int mod_regex_compile(VM *vm, Value *args, int n, Value *out)
{
    /* um argumento so: o 2º era aceito e IGNORADO em silencio */
    EXIGE_ARGS(vm, "compile", 1);
    PSRegex *r = rx_compila(vm, args[0], "compile");
    if (!r) return -1;
    PSString *p = COMO_STRING(args[0]);
    PSRegexObj *o = calloc(1, sizeof(PSRegexObj));
    char *pat = malloc((size_t)p->len + 1);
    if (!o || !pat) { free(o); free(pat); ps_regex_free(r); BERRO(vm, "MemoryError", "sem memoria"); }
    memcpy(pat, p->chars, (size_t)p->len); pat[p->len] = '\0';
    o->obj.type = OBJ_REGEX; o->obj.marked = 0;
    o->obj.next = vm->objetos; vm->objetos = (Obj *)o;
    o->rx = r; o->pat = pat; o->npat = p->len;
    vm->alocado += sizeof(PSRegexObj) + (size_t)p->len + 1;
    *out = MK_OBJ(o);
    return 0;
}

static int mod_regex_escape(VM *vm, Value *args, int n, Value *out)
{
    EXIGE_ARGS(vm, "escape", 1);
    if (!EH_STRING(args[0])) BERRO(vm, "TypeError", "escape() argument 1 must be str, not %s",
                                  nome_do_tipo_valor(args[0]));
    PSString *s = COMO_STRING(args[0]);
    SBUF_AUTO b = {0};
    for (int i = 0; i < s->len; i++) {
        unsigned char c = (unsigned char)s->chars[i];
        /* o `re.escape` moderno só escapa o que é especial; alfanumérico,
         * '_' e byte alto passam intactos */
        int alfa = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                || (c >= '0' && c <= '9') || c == '_' || c >= 0x80;
        if (!alfa && sb_bytes(&b, "\\", 1) != 0) { BERRO(vm, "MemoryError", "sem memoria"); }
        if (sb_bytes(&b, s->chars + i, 1) != 0) { BERRO(vm, "MemoryError", "sem memoria"); }
    }
    PSString *r = nova_string(vm, b.b ? b.b : "", b.n);
    if (!r) BERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(r);
    return 0;
}

/* Métodos de string que usam regex — mesma semântica do módulo, com o
 * assunto vindo do alvo em vez do argumento. */
static int met_match(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "match", 1);
    Value a[2] = { args[0], alvo };
    return mod_regex_match(vm, a, 2, out);
}

static int met_findall(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "findall", 1);
    Value a[2] = { args[0], alvo };
    return mod_regex_findall(vm, a, 2, out);
}

static int met_sub(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    ARGS_MET(vm, "sub", 2);
    Value a[3] = { args[0], args[1], alvo };
    return mod_regex_sub(vm, a, 3, out);
}

/* Sem `flags`: nenhuma funcao o lia — a tabela anunciava um parametro que
 * chamado por nome dava "unexpected keyword" e por posicao dava aridade
 * errada. Caixa e modo vao no padrao, `(?i)`, `(?m)`, `(?s)`. */
static const MembroMod MOD_REGEX[] = {
    { "compile", mod_regex_compile, 0, "pattern" },
    { "match", mod_regex_match, 0, "pattern,string" },
    { "fullmatch", mod_regex_fullmatch, 0, "pattern,string" },
    { "search", mod_regex_search, 0, "pattern,string" },
    { "findall", mod_regex_findall, 0, "pattern,string" },
    { "sub", mod_regex_sub, 0, "pattern,repl,string,count" },
    { "split", mod_regex_split, 0, "pattern,string,maxsplit" },
    { "escape", mod_regex_escape, 0, "pattern" },
};

/* `"{...}".get_json()` / `.get(chave)`: a string carrega o próprio JSON.
 * Texto que não é JSON devolve Null em vez de estourar — o método existe pra
 * ler resposta de rede, onde corpo inválido é rotina. */
static int met_get_json(VM *vm, Value alvo, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "get_json", 0, 1, n);
    Value um[1] = { alvo };
    Value dados;
    char erro_antes[sizeof(vm->erro)];
    memcpy(erro_antes, vm->erro, sizeof(erro_antes));
    if (mod_json_parse(vm, um, 1, &dados) != 0) {
        memcpy(vm->erro, erro_antes, sizeof(erro_antes));
        vm->erro_tipo[0] = '\0';
        *out = MK_NULL();
        return 0;
    }
    if (n == 0) { *out = dados; return 0; }
    if (!EH_DICT(dados)) { *out = MK_NULL(); return 0; }
    if (dict_get(COMO_DICT(dados), &args[0], out) != 0) *out = MK_NULL();
    return 0;
}

static const MembroMod MOD_JSON[] = {
    { "parse", mod_json_parse, 0, "text" }, { "stringify", mod_json_stringify, 0, "value" },
};
