    PSString *a, *b;
    if (os_str(vm, args[0], "rename", &a) != 0 || os_str(vm, args[1], "rename", &b) != 0) return -1;
    if (rename(a->chars, b->chars) != 0)
        return erro_sistema(vm, errno, a->chars, b->chars);
