extern char **environ;

static int mod_os_environ(VM *vm, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "environ", 0, 1, n);
    if (n == 1 && args[0].t != V_NULL) {
        PSString *k;
        if (os_str(vm, args[0], "environ", &k) != 0) return -1;
        const char *v = getenv(k->chars);
        if (!v) { *out = MK_NULL(); return 0; }
        return devolve_texto(vm, out, v, (int)strlen(v));
    }
    PSDict *d = novo_dict(vm, 32);
    if (!d) BERRO(vm, "MemoryError", "sem memoria");
    *out = MK_OBJ(d);
    if (fixa_raiz(vm, *out) != 0) BERRO(vm, "RuntimeError", "estouro da pilha");
    for (char **e = environ; *e; e++) {
        const char *igual = strchr(*e, '=');
        if (!igual) continue;
        PSString *k = nova_string(vm, *e, (int)(igual - *e));
        PSString *v = k ? nova_string(vm, igual + 1, (int)strlen(igual + 1)) : NULL;
        if (!k || !v) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
        Value kv = MK_OBJ(k), vv = MK_OBJ(v);
        if (dict_set(vm, d, &kv, &vv) != 0) { vm->sp--; BERRO(vm, "MemoryError", "sem memoria"); }
    }
    vm->sp--;
    return 0;
}

static int mod_os_getenv(VM *vm, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "getenv", 1, 2, n);
    PSString *k;
    if (os_str(vm, args[0], "getenv", &k) != 0) return -1;
    /* carrega o .env antes — variável de arquivo tem
     * que estar visível sem o usuário chamar `dotenv.load()` na mão */
    Value ignora;
    mod_dotenv_load(vm, NULL, 0, &ignora);
    const char *v = getenv(k->chars);
    if (!v) { *out = (n == 2) ? args[1] : MK_NULL(); return 0; }
    return devolve_texto(vm, out, v, (int)strlen(v));
}

static int mod_os_warn(VM *vm, Value *args, int n, Value *out)
{
    if (n > 2) return erro_aridade(vm, "warn", 0, 2, n);
    static const struct { const char *nome, *cod; } CORES[] = {
        {"red","\033[91m"},{"green","\033[92m"},{"yellow","\033[93m"},
        {"blue","\033[94m"},{"magenta","\033[95m"},{"cyan","\033[96m"},{"white","\033[97m"},
    };
    const char *cod = "\033[93m";               /* amarelo é o padrão */
    if (n == 2 && EH_STRING(args[1])) {
        char c[32];
        minusculo(COMO_STRING(args[1])->chars, c, sizeof(c));
        for (size_t i = 0; i < sizeof(CORES)/sizeof(CORES[0]); i++)
            if (!strcmp(c, CORES[i].nome)) { cod = CORES[i].cod; break; }
    }
    TXTBUF_AUTO t = {0};
    if (n >= 1 && valor_para_texto(&t, &args[0], 0) != 0) { BERRO(vm, "MemoryError", "sem memoria"); }
    /* AVISO vai pro STDERR, que e o que a doc promete e o que faz sentido:
     * saia no stdout e ele se mistura ao resultado do programa — quem faz
     * `pool x.ps > saida.txt` levava o aviso junto pro arquivo. */
    fprintf(stderr, "%s%.*s\033[0m\n", cod, t.n, t.b ? t.b : "");
    fflush(stderr);
    *out = MK_NULL();
    return 0;
}

/* IP local: abre um UDP pro 8.8.8.8 e pergunta que endereço o sistema
 * escolheu. Não manda pacote — só resolve a rota. */
static int mod_os_ipmach(VM *vm, Value *args, int n, Value *out)
{
    (void)args;
    EXIGE_ARGS(vm, "ipmach", 0);
    char ip[64] = "127.0.0.1";
    int s2 = socket(AF_INET, SOCK_DGRAM, 0);
    if (s2 >= 0) {
        struct sockaddr_in alvo;
        memset(&alvo, 0, sizeof(alvo));
        alvo.sin_family = AF_INET;
        alvo.sin_port = htons(80);
        alvo.sin_addr.s_addr = inet_addr("8.8.8.8");
        if (connect(s2, (struct sockaddr *)&alvo, sizeof(alvo)) == 0) {
            struct sockaddr_in meu;
            socklen_t tam = sizeof(meu);
            if (getsockname(s2, (struct sockaddr *)&meu, &tam) == 0)
                snprintf(ip, sizeof(ip), "%s", inet_ntoa(meu.sin_addr));
        }
        close(s2);
    }
    printf("\033[94m[info] IP da sua máquina: %s\033[0m\n", ip);
    fflush(stdout);
    return devolve_texto(vm, out, ip, (int)strlen(ip));
}

/* Se o `execvp` falhar (programa inexistente), o filho manda o errno pelo
 * exec-error pipe (FD_CLOEXEC: exec bem-sucedido fecha o cano e o pai lê 0
 * bytes). Espelha o FileNotFoundError que o subprocess do os_lib levanta —
 * `os.run(["nao_existe"])` erra IOError nos dois motores, não devolve Null. */
static int checa_exec_erro(VM *vm, int rfd, const char *prog)
{
    int err = 0;
    ssize_t r = read(rfd, &err, sizeof(err));
    close(rfd);
    if (r == (ssize_t)sizeof(err) && err != 0) {
        /* o texto vira o `[Errno N] ...` padrao; o TIPO fica `IOError` porque
         * docs/os/run/run.md:73 fixa ("`os.run` **levanta `IOError`**") e o
         * exemplo de la e um `catch (IOError e)` */
        erro_sistema(vm, err, prog ? prog : "", NULL);
        snprintf(vm->erro_tipo, sizeof(vm->erro_tipo), "IOError");
        return -1;
    }
    return 0;
}

/* Lê tudo que o processo escreveu. `stdout` vazio cai pro `stderr`: comando
 * que falhou tem a mensagem lá, e devolver vazio esconderia o motivo. */
static int roda_processo(VM *vm, const char *cmd_sh, char *const *argv_,
                         int capturar, Value *out)
{
    /* exec-error pipe: o child escreve errno aqui se o exec falhar */
    int ep[2];
    if (pipe(ep) != 0) BERRO(vm, "RuntimeError", "sem pipe");
    fcntl(ep[0], F_SETFD, FD_CLOEXEC);
    fcntl(ep[1], F_SETFD, FD_CLOEXEC);

    if (!capturar) {
        pid_t pid = fork();
        if (pid < 0) { close(ep[0]); close(ep[1]); BERRO(vm, "RuntimeError", "nao consegui criar processo"); }
        if (pid == 0) {
            close(ep[0]);
            if (cmd_sh) execl("/bin/sh", "sh", "-c", cmd_sh, (char *)NULL);
            else        execvp(argv_[0], argv_);
            int err = errno;
            if (write(ep[1], &err, sizeof(err)) < 0) { /* filho sai a seguir; nada a tratar */ }
            _exit(127);
        }
        close(ep[1]);
        if (checa_exec_erro(vm, ep[0], cmd_sh ? NULL : argv_[0]) != 0) {
            int st; waitpid(pid, &st, 0);
            return -1;
        }
        int st;
        waitpid(pid, &st, 0);
        *out = MK_NULL();
        return 0;
    }

    int po[2], pe[2];
    if (pipe(po) != 0) { close(ep[0]); close(ep[1]); BERRO(vm, "RuntimeError", "sem pipe"); }
    if (pipe(pe) != 0) { close(ep[0]); close(ep[1]); close(po[0]); close(po[1]); BERRO(vm, "RuntimeError", "sem pipe"); }
    pid_t pid = fork();
    if (pid < 0) { close(ep[0]); close(ep[1]); close(po[0]); close(po[1]); close(pe[0]); close(pe[1]);
                   BERRO(vm, "RuntimeError", "nao consegui criar processo"); }
    if (pid == 0) {
        close(ep[0]);
        dup2(po[1], 1); dup2(pe[1], 2);
        close(po[0]); close(po[1]); close(pe[0]); close(pe[1]);
        if (cmd_sh) execl("/bin/sh", "sh", "-c", cmd_sh, (char *)NULL);
        else        execvp(argv_[0], argv_);
        int err = errno;
        if (write(ep[1], &err, sizeof(err)) < 0) { /* filho sai a seguir; nada a tratar */ }
        _exit(127);
    }
    close(po[1]); close(pe[1]); close(ep[1]);
    if (checa_exec_erro(vm, ep[0], cmd_sh ? NULL : argv_[0]) != 0) {
        close(po[0]); close(pe[0]);
        int st; waitpid(pid, &st, 0);
        return -1;
    }
    SBUF_AUTO so = {0};
    SBUF_AUTO se = {0};
    char buf[65536];

    /* OS DOIS CANOS AO MESMO TEMPO, com poll().
     *
     * Antes era `while(read(stdout))` até o fim e SÓ DEPOIS o stderr. O cano
     * tem 64 KB: um comando que escreve mais que isso no stderr antes de o
     * stdout acabar trava o filho na escrita, o filho nunca fecha o stdout, e
     * o pai fica esperando para sempre. Não é lentidão, é impasse — medido:
     * 200 KB no stderr e o `pool` pendurou até o timeout matar.
     *
     * E o TETO: os dois buffers cresciam sem limite, então a saída inteira do
     * comando virava RSS do processo. Instalar um pacote grande derrubava a
     * máquina por falta de memória. Passando do teto, o erro diz o que fazer
     * em vez de o sistema matar o processo. */
    int fds[2] = { po[0], pe[0] };
    SBuf *destino[2] = { &so, &se };
    int vivos = 2;
    int estourou = 0;
    while (vivos > 0 && !estourou) {
        struct pollfd pf[2];
        int np = 0, idx[2];
        for (int k = 0; k < 2; k++)
            if (fds[k] >= 0) { pf[np].fd = fds[k]; pf[np].events = POLLIN; pf[np].revents = 0; idx[np] = k; np++; }
        if (np == 0) break;
        if (poll(pf, (nfds_t)np, -1) < 0) { if (errno == EINTR) continue; break; }
        for (int j = 0; j < np; j++) {
            if (!(pf[j].revents & (POLLIN | POLLHUP | POLLERR))) continue;
            int k = idx[j];
            ssize_t r = read(fds[k], buf, sizeof(buf));
            if (r > 0) {
                if (sb_bytes(destino[k], buf, (int)r) != 0) { estourou = 1; break; }
            } else if (r == 0 || (r < 0 && errno != EINTR)) {
                close(fds[k]); fds[k] = -1; vivos--;
            }
        }
    }
    /* Falta de memória de verdade: continua DRENANDO e jogando fora, senão o
     * filho fica travado na escrita e o waitpid abaixo nunca volta —
     * trocaríamos um impasse por outro. */
    if (estourou)
        for (int k = 0; k < 2; k++)
            while (fds[k] >= 0) {
                ssize_t r = read(fds[k], buf, sizeof(buf));
                if (r > 0) continue;
                if (r < 0 && errno == EINTR) continue;
                close(fds[k]); fds[k] = -1; vivos--;
            }
    for (int k = 0; k < 2; k++) if (fds[k] >= 0) close(fds[k]);
    int st;
    waitpid(pid, &st, 0);
    if (estourou) BERRO(vm, "MemoryError", "sem memoria");

    SBuf *escolhido = &so;
    int fim = so.n;
    while (fim > 0 && (so.b[fim-1] == '\n' || so.b[fim-1] == ' ' || so.b[fim-1] == '\t' || so.b[fim-1] == '\r')) fim--;
    if (fim == 0) {
        escolhido = &se;
        fim = se.n;
        while (fim > 0 && (se.b[fim-1] == '\n' || se.b[fim-1] == ' ' || se.b[fim-1] == '\t' || se.b[fim-1] == '\r')) fim--;
    }
    int ini = 0;
    while (ini < fim && (escolhido->b[ini] == '\n' || escolhido->b[ini] == ' ')) ini++;
    return devolve_texto(vm, out, escolhido->b ? escolhido->b + ini : "", fim - ini);
}

static int mod_os_cmd(VM *vm, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "cmd", 1, 2, n);
    PSString *c;
    if (os_str(vm, args[0], "cmd", &c) != 0) return -1;
    /* COM shell: `;` `|` `$` são interpretados. Dado de usuário aqui é
     * injeção — pra isso existe o `run`, que não passa por shell. */
    return roda_processo(vm, c->chars, NULL, (n == 2) && val_truthy(&args[1]), out);
}

/* Vetor de argumentos do `run` sem teto. Era `char *vetor[64]`: lista com
 * mais de 62 itens saía como erro de ARIDADE ("takes at most 2 arguments
 * (2 given)") e a forma em string truncava calada no mesmo ponto, com a
 * cópia presa em 4096 bytes. */
static int os_run_empurra(char ***v, int *q, int *cap, char *s)
{
    if (*q >= *cap) {
        int nc = *cap ? *cap * 2 : 16;
        char **nv = realloc(*v, (size_t)nc * sizeof(char *));
        if (!nv) return -1;
        *v = nv; *cap = nc;
    }
    (*v)[(*q)++] = s;
    return 0;
}

/* Dispara `vetor` (terminado em NULL, montado por `mod_os_run`). */
static int os_run_dispara(VM *vm, char **vetor, int capturar, Value *out)
{
    /* SEM `capture`: SEGUNDO PLANO. Dispara e volta na hora — e o que separa o
     * `run` do `cmd`; enquanto os dois esperavam, ter os dois nao fazia
     * sentido. Devolve o PID do processo, pra dar pra acompanhar ou matar.
     *
     * Fork DUPLO: o filho do meio sai imediatamente e o neto e adotado pelo
     * init, entao nao vira zumbi nem precisa de waitpid — o programa pode
     * disparar quantos quiser e terminar antes deles. O PID do neto volta pelo
     * cano; sem ele so daria pra devolver o pid do meio, que morre na hora.
     *
     * COM `capture=true` continua esperando: colher a saida exige o fim do
     * processo, e devolver texto vazio "porque e bg" seria mentira.
     */
    if (!capturar) {
        /* Dois canos. O primeiro traz o PID do neto. O segundo existe so pra
         * dizer se o `execvp` deu certo: a ponta de escrita e CLOEXEC, entao o
         * exec bem-sucedido FECHA ela sozinho e o pai le EOF; se o exec falha,
         * o neto escreve o errno antes de morrer. Sem isso, programa que nao
         * existe devolvia um PID e morria calado com 127 — o `IOError` que a
         * doc promete some, e o "rodei" e mentira. A espera aqui e a do exec
         * (microssegundos), nao a do processo: o segundo plano continua. */
        int cano[2], canoerr[2];
        if (pipe(cano) != 0) BERRO(vm, "IOError", "run(): nao consegui criar o cano (%s)", strerror(errno));
        if (pipe(canoerr) != 0) {
            close(cano[0]); close(cano[1]);
            BERRO(vm, "IOError", "run(): nao consegui criar o cano (%s)", strerror(errno));
        }
        fcntl(canoerr[1], F_SETFD, FD_CLOEXEC);
        pid_t meio = fork();
        if (meio < 0) {
            close(cano[0]); close(cano[1]); close(canoerr[0]); close(canoerr[1]);
            BERRO(vm, "IOError", "run(): fork falhou (%s)", strerror(errno));
        }
        if (meio == 0) {
            close(cano[0]); close(canoerr[0]);
            pid_t neto = fork();
            if (neto == 0) {
                close(cano[1]);
                setsid();                 /* solta do terminal de quem chamou */
                execvp(vetor[0], vetor);
                int e = errno;            /* execvp so volta em erro */
                ssize_t ig = write(canoerr[1], &e, sizeof(e));
                (void)ig;
                _exit(127);
            }
            close(canoerr[1]);
            ssize_t ig = write(cano[1], &neto, sizeof(neto));
            (void)ig;
            close(cano[1]);
            _exit(0);
        }
        close(cano[1]); close(canoerr[1]);
        pid_t neto = -1;
        ssize_t lidos = read(cano[0], &neto, sizeof(neto));
        close(cano[0]);
        int erro_exec = 0;
        ssize_t le = read(canoerr[0], &erro_exec, sizeof(erro_exec));
        close(canoerr[0]);
        waitpid(meio, NULL, 0);           /* o do meio morre na hora */
        if (le == (ssize_t)sizeof(erro_exec))
            BERRO(vm, "IOError", "run(): %s: %s", vetor[0], strerror(erro_exec));
        if (lidos != (ssize_t)sizeof(neto) || neto < 0)
            BERRO(vm, "IOError", "run(): nao consegui disparar '%s'", vetor[0]);
        *out = MK_INT((int64_t)neto);
        return 0;
    }
    return roda_processo(vm, NULL, vetor, capturar, out);
}

static int mod_os_run(VM *vm, Value *args, int n, Value *out)
{
    if (n < 1 || n > 2) return erro_aridade(vm, "run", 1, 2, n);
    int capturar = (n == 2) && val_truthy(&args[1]);
    char **vetor = NULL;
    char *copia = NULL;
    int q = 0, cap = 0;

    if (EH_SEQ(args[0])) {
        PSList *l = COMO_LIST(args[0]);
        for (int i = 0; i < l->len; i++) {
            if (!EH_STRING(l->itens[i])) {
                free(vetor);
                BERRO(vm, "TypeError", "run() argument 1 must be list of str, not %s",
                      nome_do_tipo_valor(l->itens[i]));
            }
            if (os_run_empurra(&vetor, &q, &cap, COMO_STRING(l->itens[i])->chars) != 0) {
                free(vetor);
                BERRO(vm, "MemoryError", "sem memoria em run()");
            }
        }
    } else if (EH_STRING(args[0])) {
        /* string é dividida respeitando aspas, SEM interpretar shell */
        PSString *c = COMO_STRING(args[0]);
        copia = malloc((size_t)c->len + 1);
        if (!copia) BERRO(vm, "MemoryError", "sem memoria em run()");
        memcpy(copia, c->chars, (size_t)c->len);
        copia[c->len] = '\0';
        char *p = copia;
        while (*p) {
            while (*p == ' ' || *p == '\t') p++;
            if (!*p) break;
            char aspas = 0;
            if (*p == '"' || *p == '\'') { aspas = *p; p++; }
            if (os_run_empurra(&vetor, &q, &cap, p) != 0) {
                free(vetor); free(copia);
                BERRO(vm, "MemoryError", "sem memoria em run()");
            }
            while (*p && (aspas ? *p != aspas : (*p != ' ' && *p != '\t'))) p++;
            if (*p) { *p = '\0'; p++; }
        }
    } else {
        BERRO(vm, "TypeError", "run() argument 1 must be list or str, not %s",
          nome_do_tipo_valor(args[0]));
    }
    if (q == 0 || os_run_empurra(&vetor, &q, &cap, NULL) != 0) {
        int vazio = (q == 0);
        free(vetor); free(copia);
        if (vazio) BERRO(vm, "TypeError", "run() sem comando");
        BERRO(vm, "MemoryError", "sem memoria em run()");
    }
    int rc = os_run_dispara(vm, vetor, capturar, out);
    free(vetor); free(copia);
    return rc;
}

static int mod_os_code(VM *vm, Value *args, int n, Value *out)
{
    if (n > 1) return erro_aridade(vm, "code", 0, 1, n);
    const char *alvo = ".";
    if (n == 1) {
        PSString *p;
        if (os_str(vm, args[0], "code", &p) != 0) return -1;
        alvo = p->chars;
    }
    static const char *EDITORES[] = {"code","cursor","zed","nano","vim"};
    const char *caminho_env = getenv("PATH");
    for (size_t i = 0; i < sizeof(EDITORES)/sizeof(EDITORES[0]); i++) {
        if (!caminho_env) break;
        char copia[4096];
        snprintf(copia, sizeof(copia), "%s", caminho_env);
        for (char *dir = strtok(copia, ":"); dir; dir = strtok(NULL, ":")) {
            char bin[2048];
            snprintf(bin, sizeof(bin), "%s/%s", dir, EDITORES[i]);
            if (access(bin, X_OK) != 0) continue;
            pid_t pid = fork();
            if (pid == 0) {
                execl(bin, EDITORES[i], alvo, (char *)NULL);
                _exit(127);
            }
            char msg[64];
            int k = snprintf(msg, sizeof(msg), "Abrindo %s...", EDITORES[i]);
            return devolve_texto(vm, out, msg, k);
        }
    }
    return devolve_texto(vm, out, "Nenhum editor encontrado", 24);
}

/* `PoolFile` como VALOR: serve pra `x is PoolFile`. Sem construtor — quem
 * cria é o `loadFile`. */
static int mod_os_poolfile_tipo(VM *vm, Value *args, int n, Value *out)
{
    (void)args; (void)n; (void)vm;
    *out = MK_TIPO(TIPO_PFILE);
    return 0;
}

